def default_polling_settings():
    """Target cadence for one shared automatic job per provider tracker.

    These are request intervals, not a promise that a crowd network will
    produce a fresh location. Provider errors may still activate the existing
    bounded backoff/circuit-breaker paths.
    """
    return {
        "apple": {"interval_min": APPLE_DEFAULT_INTERVAL_MIN, "interval_max": APPLE_DEFAULT_INTERVAL_MAX},
        "google": {"interval_min": GOOGLE_DEFAULT_INTERVAL_MIN, "interval_max": GOOGLE_DEFAULT_INTERVAL_MAX},
        "samsung": {"interval_min": SAMSUNG_DEFAULT_INTERVAL_MIN, "interval_max": SAMSUNG_DEFAULT_INTERVAL_MAX},
        "demand_driven": True,
        "apple_batch_reports_default": True,
        "updated_ts": 0,
    }


def normalize_polling_settings(raw):
    raw = raw if isinstance(raw, dict) else {}
    defaults = default_polling_settings()
    result = {
        "demand_driven": bool(raw.get("demand_driven", True)),
        "apple_batch_reports_default": str(raw.get("apple_batch_reports_default", True)).lower() not in {"false", "0", "off", "no"},
        "updated_ts": max(0, int(raw.get("updated_ts", 0) or 0)),
    }
    bounds = {"apple": (15, 300), "google": (30, 900), "samsung": (20, 600)}
    for provider, (lower, upper) in bounds.items():
        source = raw.get(provider) if isinstance(raw.get(provider), dict) else {}
        fallback = defaults[provider]
        try:
            minimum = max(lower, min(upper, int(source.get("interval_min", fallback["interval_min"]) or fallback["interval_min"])))
        except (TypeError, ValueError):
            minimum = fallback["interval_min"]
        try:
            maximum = max(minimum, min(upper, int(source.get("interval_max", fallback["interval_max"]) or fallback["interval_max"])))
        except (TypeError, ValueError):
            maximum = max(minimum, fallback["interval_max"])
        # The old default window becomes a fixed twenty-second cadence.
        if provider == "apple" and (minimum, maximum) == (20, 30):
            maximum = 20
        result[provider] = {"interval_min": minimum, "interval_max": maximum}
    return result


BACKGROUND_CONTROL_VERSION = 2


def settings_bool(value, default=False):
    """Parse persisted/API booleans without treating the string 'false' as true."""
    if value is None:
        return bool(default)
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value != 0
    normalized = str(value).strip().lower()
    if normalized in {"1", "true", "yes", "on", "enabled", "ja", "an"}:
        return True
    if normalized in {"0", "false", "no", "off", "disabled", "nein", "aus", ""}:
        return False
    return bool(default)


def normalize_background_control(raw):
    """Repair the inverted 14.4.1 switch once and establish one clear setting.

    In 14.4.1 the UI row was labelled 'Automatische Abrufe', but a checked
    switch persisted global_pause=true. Existing files without the v2 marker
    therefore cannot reliably distinguish an intentional pause from the UI
    wiring bug. This one-time migration favors active tracking, which is the
    safe behavior for enabled histories, departure alerts and Recovery Guard.
    A deliberate pause remains available immediately after migration.
    """
    settings = dict(raw) if isinstance(raw, dict) else {}
    try:
        version = int(settings.get("background_control_version", 0) or 0)
    except (TypeError, ValueError):
        version = 0
    legacy_pause = settings_bool(settings.get("global_pause"), False)
    repaired_inverted_switch = version < BACKGROUND_CONTROL_VERSION and legacy_pause
    if version < BACKGROUND_CONTROL_VERSION:
        enabled = True
        if repaired_inverted_switch:
            settings["background_control_repaired_ts"] = int(time.time())
    else:
        enabled = settings_bool(settings.get("background_enabled"), not legacy_pause)
    settings["background_enabled"] = bool(enabled)
    settings["global_pause"] = not bool(enabled)
    settings["background_control_version"] = BACKGROUND_CONTROL_VERSION
    return settings, repaired_inverted_switch


def automatic_polling_enabled():
    settings = state.get("settings", {}) if "state" in globals() else {}
    if not isinstance(settings, dict):
        return True
    if "background_enabled" in settings:
        return settings_bool(settings.get("background_enabled"), True)
    return not settings_bool(settings.get("global_pause"), False)


def provider_poll_window(provider):
    polling = normalize_polling_settings(state.get("settings", {}).get("polling", {})) if "state" in globals() else default_polling_settings()
    row = polling.get(str(provider).lower()) or default_polling_settings().get(str(provider).lower()) or {"interval_min": 30, "interval_max": 30}
    return int(row["interval_min"]), int(row["interval_max"])

