def _path_lock(path):
    key = str(Path(path).resolve())
    with _file_locks_guard:
        lock = _file_locks.get(key)
        if lock is None:
            lock = threading.RLock()
            _file_locks[key] = lock
        return lock


def safe_load_json(path, default, accepted_types=None):
    path = Path(path)
    expected = accepted_types or (type(default),)
    if not path.exists():
        return default
    try:
        with _path_lock(path), open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, expected):
            return data
        raise ValueError(f"Unerwarteter JSON-Wurzeltyp: {type(data).__name__}")
    except Exception as exc:
        # Never silently overwrite a damaged production file. Keep an evidence
        # copy and prefer the last atomically-created .bak generation.
        stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
        corrupt_copy = path.with_name(f"{path.name}.corrupt.{stamp}")
        try:
            if path.exists() and not corrupt_copy.exists():
                shutil.copy2(path, corrupt_copy)
        except OSError:
            pass
        backup = path.with_name(f"{path.name}.bak")
        try:
            if backup.exists():
                with open(backup, "r", encoding="utf-8") as f:
                    restored = json.load(f)
                if isinstance(restored, expected):
                    logger.warning("JSON %s beschädigt; gültige .bak-Generation wird verwendet (%s).", path.name, type(exc).__name__)
                    return restored
        except Exception:
            pass
        logger.error("JSON %s konnte nicht sicher geladen werden (%s). Original bleibt erhalten.", path.name, type(exc).__name__)
        return default


def atomic_write_json(path, data, *, create_backup=True, private=False):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    lock = _path_lock(path)
    with lock:
        fd, tmp_name = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=str(path.parent))
        try:
            if private:
                try:
                    os.fchmod(fd, 0o600)
                except OSError:
                    pass
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, separators=(",", ":"))
                f.flush()
                os.fsync(f.fileno())
            if create_backup and path.exists():
                backup = path.with_name(f"{path.name}.bak")
                try:
                    shutil.copy2(path, backup)
                    if private:
                        os.chmod(backup, 0o600)
                except OSError as exc:
                    logger.debug("Backup für %s konnte nicht geschrieben werden: %s", path.name, exc)
            os.replace(tmp_name, path)
            if private:
                try:
                    os.chmod(path, 0o600)
                except OSError:
                    pass
            try:
                dir_fd = os.open(str(path.parent), os.O_RDONLY)
                try:
                    os.fsync(dir_fd)
                finally:
                    os.close(dir_fd)
            except OSError:
                pass
        finally:
            if os.path.exists(tmp_name):
                try:
                    os.remove(tmp_name)
                except OSError:
                    pass


def atomic_external_json_write(path, writer, *, create_backup=True, private=False):
    """Atomically persist JSON produced by a third-party serializer.

    Some Find My objects own their serialization format. They write into an
    isolated temporary path first so an interrupted write can never truncate
    the last known-good production file.
    """
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with _path_lock(path):
        fd, tmp_name = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=str(path.parent))
        os.close(fd)
        tmp_path = Path(tmp_name)
        try:
            writer(tmp_path)
            if not tmp_path.exists() or tmp_path.stat().st_size <= 0:
                raise ValueError(f"Serializer erzeugte keine Daten für {path.name}")
            # Validate that the serializer actually produced JSON before the
            # old generation is touched. The object schema itself stays owned
            # by the upstream library.
            with open(tmp_path, "r", encoding="utf-8") as f:
                json.load(f)
            try:
                with open(tmp_path, "rb") as f:
                    os.fsync(f.fileno())
            except OSError:
                pass
            if private:
                try:
                    os.chmod(tmp_path, 0o600)
                except OSError:
                    pass
            if create_backup and path.exists():
                backup = path.with_name(f"{path.name}.bak")
                try:
                    shutil.copy2(path, backup)
                    if private:
                        os.chmod(backup, 0o600)
                except OSError as exc:
                    logger.debug("Backup für %s konnte nicht geschrieben werden: %s", path.name, exc)
            os.replace(tmp_path, path)
            if private:
                try:
                    os.chmod(path, 0o600)
                except OSError:
                    pass
            try:
                dir_fd = os.open(str(path.parent), os.O_RDONLY)
                try:
                    os.fsync(dir_fd)
                finally:
                    os.close(dir_fd)
            except OSError:
                pass
        finally:
            try:
                tmp_path.unlink(missing_ok=True)
            except OSError:
                pass


def save_json(filepath, data_key):
    with state_lock:
        snapshot = json.loads(json.dumps(state[data_key], ensure_ascii=False))
    atomic_write_json(filepath, snapshot)
    if data_key == "shared_links":
        prune_guest_grants = globals().get("mcp_prune_all_guest_grants")
        if callable(prune_guest_grants):
            prune_guest_grants()


def canonical_device_name(value):
    clean = secure_filename(str(value or "").strip())[:80]
    if not clean:
        raise ValueError("Bitte einen gültigen Namen für das Objekt angeben.")
    return clean


def load_accessory_json(path):
    errors = []
    classes = [FindMyAccessory]
    if FixedRollingKeyPairAccessory is not None:
        classes.append(FixedRollingKeyPairAccessory)
    for accessory_class in classes:
        try:
            return accessory_class.from_json(path)
        except Exception as exc:
            errors.append(exc)
    raise ValueError("Accessory-Datei wird von der installierten FindMy.py-Version nicht unterstützt.") from errors[-1]


def concrete_tenant_path(path):
    """Resolve a tenant-aware PathLike to the real pathlib.Path it represents.

    FindMy.py intentionally accepts only ``str`` and concrete ``Path`` objects
    in its serializer. TenantScopedPath is an os.PathLike proxy, so passing the
    proxy directly makes upstream from_json/to_json silently skip disk I/O.
    Converting at the library boundary preserves dynamic tenant routing while
    keeping the third-party serializer fully compatible.
    """
    return Path(os.fspath(path))


def persist_apple_account(account, *, create_backup=True):
    if account is None:
        raise ValueError("Apple-Account fehlt.")
    account_path = concrete_tenant_path(ACCOUNT_FILE)
    atomic_external_json_write(
        account_path,
        lambda target: account.to_json(target),
        create_backup=create_backup,
        private=True,
    )
    state["apple_session_restore"] = {
        "status": "persisted",
        "checked_ts": int(time.time()),
        "source": "primary",
        "error_type": "",
    }
    return account_path


def restore_apple_account():
    account_path = concrete_tenant_path(ACCOUNT_FILE)
    status = {"status": "missing", "checked_ts": int(time.time()), "source": "", "error_type": ""}
    if not account_path.is_file():
        state["apple_session_restore"] = status
        return None

    candidates = [("primary", account_path)]
    backup_path = account_path.with_name(account_path.name + ".bak")
    if backup_path.is_file():
        candidates.append(("backup", backup_path))
    last_error = None
    anisette_path = concrete_tenant_path(ANISETTE_LIBS)
    for source, candidate in candidates:
        try:
            account = AppleAccount.from_json(candidate, anisette_libs_path=anisette_path)
            status.update({"status": "loaded", "source": source, "error_type": ""})
            state["apple_session_restore"] = status
            if source == "backup":
                # Repair only the broken primary generation. The valid backup
                # is retained and no existing session is deleted or migrated.
                try:
                    persist_apple_account(account, create_backup=False)
                    state["apple_session_restore"]["source"] = "backup_repaired"
                except Exception as repair_exc:
                    logger.warning("Apple-Sitzungsdatei konnte nicht aus der Sicherung repariert werden (%s).", type(repair_exc).__name__)
            return account
        except Exception as exc:
            last_error = exc
    status.update({"status": "error", "source": "primary", "error_type": type(last_error).__name__ if last_error else "UnknownError"})
    state["apple_session_restore"] = status
    logger.warning("Gespeicherte Apple-Sitzung konnte nicht wiederhergestellt werden (%s).", status["error_type"])
    return None


def client_key():
    return request.remote_addr or "unknown"


def is_unlock_rate_limited(key):
    now = time.time()
    with auth_lock:
        attempts = unlock_attempts[key]
        while attempts and now - attempts[0] > UNLOCK_WINDOW_SECONDS:
            attempts.popleft()
        return len(attempts) >= MAX_UNLOCK_ATTEMPTS


def register_unlock_failure(key):
    with auth_lock:
        unlock_attempts[key].append(time.time())


def clear_unlock_failures(key):
    with auth_lock:
        unlock_attempts.pop(key, None)


def is_share_rate_limited(key):
    now = time.time()
    with auth_lock:
        attempts = share_attempts[key]
        while attempts and now - attempts[0] > UNLOCK_WINDOW_SECONDS:
            attempts.popleft()
        return len(attempts) >= MAX_SHARE_ATTEMPTS


def register_share_failure(key):
    with auth_lock:
        share_attempts[key].append(time.time())


def clear_share_failures(key):
    with auth_lock:
        share_attempts.pop(key, None)


def create_password_record(password):
    salt = secrets.token_bytes(16)
    derived = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, 240000)
    return {"password_hash": derived.hex(), "password_salt": salt.hex()}


def load_app_password_record():
    """Return None when no panel-managed password exists, otherwise its record.

    A present but unreadable record intentionally does not fall back to the old
    environment password. That avoids silently re-enabling a previous password
    after filesystem corruption.
    """
    if not APP_PASSWORD_FILE.exists():
        return None
    record = safe_load_json(APP_PASSWORD_FILE, {}, accepted_types=(dict,))
    return record if isinstance(record, dict) else {}


def verify_app_password(candidate):
    candidate = str(candidate or "")
    tenant_getter = globals().get("current_tenant_id")
    if callable(tenant_getter) and tenant_getter() != "main":
        row_getter = globals().get("user_record")
        verifier = globals().get("verify_user_password")
        row = row_getter(tenant_getter()) if callable(row_getter) else {}
        return bool(callable(verifier) and verifier(row, candidate))
    record = load_app_password_record()
    if record is not None:
        try:
            expected_hash = str(record.get("password_hash") or "")
            salt = bytes.fromhex(str(record.get("password_salt") or ""))
            iterations = max(100000, int(record.get("iterations") or APP_PASSWORD_KDF_ITERATIONS))
            if not expected_hash or len(salt) < 16:
                return False
            calculated = hashlib.pbkdf2_hmac("sha256", candidate.encode("utf-8"), salt, iterations).hex()
            return hmac.compare_digest(calculated, expected_hash)
        except (TypeError, ValueError, OverflowError):
            return False
    if hmac.compare_digest(candidate, str(APP_PASSWORD)):
        return True
    return not os.environ.get("ULTRA_TRACKER_PASSWORD") and hmac.compare_digest(candidate, str(_SETUP_PASSWORD_ALIAS))


def app_password_generation():
    if callable(globals().get("current_password_generation")):
        return current_password_generation()
    record = load_app_password_record()
    if record is None:
        return "legacy"
    return str(record.get("generation") or "invalid")


def app_password_is_default():
    tenant_getter = globals().get("current_tenant_id")
    if callable(tenant_getter) and tenant_getter() != "main":
        row_getter = globals().get("user_record")
        verifier = globals().get("verify_user_password")
        row = row_getter(tenant_getter()) if callable(row_getter) else {}
        # Secondary accounts always have a dedicated PBKDF2 record. Treat a
        # missing/corrupt record as unsafe, and explicitly reject the shipped
        # fallback value if an administrator selected it despite UI guidance.
        if not isinstance(row, dict) or not row.get("password_hash") or not row.get("password_salt"):
            return True
        return bool(callable(verifier) and verifier(row, _FALLBACK_PASSWORD))
    record = load_app_password_record()
    if record is not None:
        return verify_app_password(_FALLBACK_PASSWORD)
    return APP_PASSWORD == _FALLBACK_PASSWORD or (not os.environ.get("ULTRA_TRACKER_PASSWORD") and _SETUP_PASSWORD_ALIAS == _FALLBACK_PASSWORD)


def persist_app_password(password):
    password = str(password or "")
    salt = secrets.token_bytes(24)
    derived = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, APP_PASSWORD_KDF_ITERATIONS)
    record = {
        "version": 1,
        "algorithm": "pbkdf2-sha256",
        "iterations": APP_PASSWORD_KDF_ITERATIONS,
        "password_hash": derived.hex(),
        "password_salt": salt.hex(),
        "generation": secrets.token_urlsafe(24),
        "updated_ts": int(time.time()),
    }
    atomic_write_json(APP_PASSWORD_FILE, record, create_backup=True, private=True)
    return record


def verify_shared_password(link_data, candidate):
    candidate = str(candidate or "")
    expected_hash = link_data.get("password_hash")
    salt_hex = link_data.get("password_salt")
    if expected_hash and salt_hex:
        try:
            calculated = hashlib.pbkdf2_hmac(
                "sha256", candidate.encode("utf-8"), bytes.fromhex(salt_hex), 240000
            ).hex()
            return hmac.compare_digest(calculated, str(expected_hash))
        except (ValueError, TypeError):
            return False
    return hmac.compare_digest(str(link_data.get("password", "")), candidate)


def shared_grant_fingerprint(link_data):
    basis = "|".join([
        str((link_data or {}).get("password_salt") or "legacy"),
        str((link_data or {}).get("password_hash") or (link_data or {}).get("password") or ""),
    ])
    return hmac.new(str(SECRET_KEY).encode("utf-8"), basis.encode("utf-8"), hashlib.sha256).hexdigest()[:32]


def shared_session_authorized(link_id, link_data):
    grants = session.get("shared_grants", {})
    if not isinstance(grants, dict):
        return False
    grant = grants.get(str(link_id))
    if not isinstance(grant, dict) or int(grant.get("expires_ts", 0) or 0) <= int(time.time()):
        return False
    return hmac.compare_digest(str(grant.get("fingerprint") or ""), shared_grant_fingerprint(link_data))


def grant_shared_session(link_id, link_data):
    grants = session.get("shared_grants", {})
    grants = dict(grants) if isinstance(grants, dict) else {}
    now_ts = int(time.time())
    grants = {
        str(key): value
        for key, value in grants.items()
        if isinstance(value, dict) and int(value.get("expires_ts", 0) or 0) > now_ts
    }
    link_expiry = int(float((link_data or {}).get("expires_ts", 0) or 0))
    grant_expiry = now_ts + 12 * 60 * 60
    if link_expiry:
        grant_expiry = min(grant_expiry, link_expiry)
    grants[str(link_id)] = {
        "fingerprint": shared_grant_fingerprint(link_data),
        "expires_ts": grant_expiry,
    }
    if len(grants) > 8:
        grants = dict(sorted(grants.items(), key=lambda item: int(item[1].get("expires_ts", 0)), reverse=True)[:8])
    session["shared_grants"] = grants
    session.permanent = True


def shared_remember_cookie_name(link_id):
    digest = hashlib.sha256(str(link_id).encode("utf-8")).hexdigest()[:20]
    return f"uts_share_{digest}"


def shared_remember_token(link_id, link_data):
    material = f"share-remember-v1|{link_id}|{shared_grant_fingerprint(link_data)}"
    return hmac.new(
        str(SECRET_KEY).encode("utf-8"),
        material.encode("utf-8"),
        hashlib.sha256,
    ).hexdigest()


def shared_remembered_authorized(link_id, link_data):
    if not isinstance(link_data, dict):
        return False
    candidate = request.cookies.get(shared_remember_cookie_name(link_id), "")
    if not candidate:
        return False
    return hmac.compare_digest(str(candidate), shared_remember_token(link_id, link_data))


def shared_access_authorized(link_id, link_data):
    return shared_session_authorized(link_id, link_data) or shared_remembered_authorized(link_id, link_data)


def set_shared_remember_cookie(response, link_id, link_data):
    now_ts = int(time.time())
    link_expiry = int(float((link_data or {}).get("expires_ts", 0) or 0))
    # Browsers may clamp very long cookie lifetimes. The server still checks
    # link activity/expiry and the password fingerprint on every request.
    max_age = 5 * 365 * 24 * 60 * 60
    if link_expiry:
        max_age = max(1, min(max_age, link_expiry - now_ts))
    forwarded_https = str(request.headers.get("X-Forwarded-Proto", "")).split(",", 1)[0].strip().lower() == "https"
    response.set_cookie(
        shared_remember_cookie_name(link_id),
        shared_remember_token(link_id, link_data),
        max_age=max_age,
        httponly=True,
        secure=bool(request.is_secure or forwarded_https),
        samesite="Lax",
        path="/",
    )
    return response


def clear_shared_remember_cookie(response, link_id):
    response.delete_cookie(shared_remember_cookie_name(link_id), path="/")
    return response


DEFAULT_SHARE_PERMISSIONS = {
    "can_locate": True,
    "show_history": False,
    "show_geofences": False,
    "show_transit": False,
    "show_accuracy": True,
    "show_address": True,
    "show_battery": True,
    "show_provider": True,
    "can_navigate": True,
}

DEFAULT_SHARE_PRIVACY = {
    "location_precision": "exact",  # exact | 100m | 500m | city
    "delay_minutes": 0,
    "history_hours": 168,
    "emergency_view": False,
    "watermark": False,
}


def share_bool(value, default=False):
    if value is None:
        return bool(default)
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value != 0
    return str(value).strip().lower() in {"1", "true", "yes", "on", "start"}


def share_permissions(link_data, history_fallback=False):
    raw = link_data.get("permissions", {}) if isinstance(link_data, dict) else {}
    raw = raw if isinstance(raw, dict) else {}
    return {
        "can_locate": share_bool(raw.get("can_locate"), DEFAULT_SHARE_PERMISSIONS["can_locate"]),
        "show_history": share_bool(raw.get("show_history"), history_fallback),
        "show_geofences": share_bool(raw.get("show_geofences"), DEFAULT_SHARE_PERMISSIONS["show_geofences"]),
        "show_transit": share_bool(raw.get("show_transit"), DEFAULT_SHARE_PERMISSIONS["show_transit"]),
        "show_accuracy": share_bool(raw.get("show_accuracy"), DEFAULT_SHARE_PERMISSIONS["show_accuracy"]),
        "show_address": share_bool(raw.get("show_address"), DEFAULT_SHARE_PERMISSIONS["show_address"]),
        "show_battery": share_bool(raw.get("show_battery"), DEFAULT_SHARE_PERMISSIONS["show_battery"]),
        "show_provider": share_bool(raw.get("show_provider"), DEFAULT_SHARE_PERMISSIONS["show_provider"]),
        "can_navigate": share_bool(raw.get("can_navigate"), DEFAULT_SHARE_PERMISSIONS["can_navigate"]),
    }


def share_privacy_config(link_data):
    raw = link_data.get("privacy", {}) if isinstance(link_data, dict) else {}
    raw = raw if isinstance(raw, dict) else {}
    precision = str(raw.get("location_precision") or DEFAULT_SHARE_PRIVACY["location_precision"]).strip().lower()
    if precision not in {"exact", "100m", "500m", "city"}:
        precision = "exact"
    try:
        delay = max(0, min(1440, int(float(raw.get("delay_minutes", 0) or 0))))
    except (TypeError, ValueError):
        delay = 0
    try:
        history_hours = max(1, min(24 * 90, int(float(raw.get("history_hours", 168) or 168))))
    except (TypeError, ValueError):
        history_hours = 168
    return {
        "location_precision": precision,
        "delay_minutes": delay,
        "history_hours": history_hours,
        "emergency_view": share_bool(raw.get("emergency_view"), False),
        "watermark": share_bool(raw.get("watermark"), False),
    }


def share_link_status(link_data):
    if not isinstance(link_data, dict) or not share_bool(link_data.get("active"), False):
        return "inactive"
    expires_ts = int(float(link_data.get("expires_ts", 0) or 0))
    if expires_ts and expires_ts <= int(time.time()):
        return "expired"
    return "active"


def share_expiry_timestamp(value, now_ts=None):
    now_ts = int(now_ts or time.time())
    try:
        hours = int(float(value or 0))
    except (TypeError, ValueError):
        hours = 0
    allowed = (0, 1, 6, 24, 72, 168, 720)
    hours = min(allowed, key=lambda option: abs(option - max(0, hours)))
    return now_ts + hours * 60 * 60 if hours else 0


def _privacy_round_coordinates(lat, lon, precision):
    lat = float(lat); lon = float(lon)
    meters = {"100m": 100.0, "500m": 500.0, "city": 5000.0}.get(precision)
    if not meters:
        return lat, lon, 0.0
    lat_step = meters / 111320.0
    lon_scale = max(0.15, abs(math.cos(math.radians(lat))))
    lon_step = meters / (111320.0 * lon_scale)
    rounded_lat = round(lat / lat_step) * lat_step
    rounded_lon = round(lon / lon_step) * lon_step
    return rounded_lat, rounded_lon, meters


def shared_location_payload(location, permissions, privacy=None):
    if not isinstance(location, dict):
        return None
    public = dict(location)
    privacy = privacy or DEFAULT_SHARE_PRIVACY
    precision = str(privacy.get("location_precision") or "exact")
    if public.get("lat") is not None and public.get("lon") is not None and precision != "exact":
        lat, lon, privacy_acc = _privacy_round_coordinates(public["lat"], public["lon"], precision)
        public["lat"] = round(lat, 7)
        public["lon"] = round(lon, 7)
        public["privacy_precision"] = precision
        if privacy_acc:
            public["acc"] = max(float(public.get("acc", 0) or 0), privacy_acc)
    if not permissions.get("show_accuracy", True):
        public.pop("acc", None)
        public.pop("confidence", None)
    if not permissions.get("show_address", True):
        public.pop("address", None)
    elif precision == "city" and isinstance(public.get("address"), dict):
        address = public["address"]
        public["address"] = {
            "schema_version": address.get("schema_version", 3),
            "label": address.get("locality") or address.get("city_line") or address.get("state") or address.get("country") or "Geteilter Bereich",
            "display_name": address.get("city_line") or address.get("locality") or address.get("state") or address.get("country") or "Geteilter Bereich",
            "locality": address.get("locality", ""),
            "city_line": address.get("city_line", ""),
            "state": address.get("state", ""),
            "country": address.get("country", ""),
            "country_code": address.get("country_code", ""),
            "poi_name": "",
            "poi_type_label": "",
        }
    if not permissions.get("show_battery", True):
        for key in ("bat", "battery", "battery_code", "battery_label"):
            public.pop(key, None)
    if not permissions.get("show_provider", True):
        for key in ("provider", "source", "source_name"):
            public.pop(key, None)
    return public


def require_accessory(name):
    if name not in state["accessories"]:
        return jsonify({"status": "error", "message": "Objekt wurde nicht gefunden."}), 404
    return None


def point_identity(point):
    explicit = point.get("report_id") if isinstance(point, dict) else None
    if explicit:
        return str(explicit)
    basis = "{:.7f}|{:.7f}|{:.3f}|{:.3f}".format(
        float(point.get("lat", 0)), float(point.get("lon", 0)),
        float(point.get("acc", 0) or 0), float(point.get("ts", 0))
    )
    return hashlib.sha256(basis.encode("utf-8")).hexdigest()[:24]


def normalize_point(p):
    try:
        lat = float(p.get("lat"))
        lon = float(p.get("lon"))
        ts = float(p.get("ts"))
        acc = float(p.get("acc", 0) or 0)
        if not all(math.isfinite(value) for value in (lat, lon, ts, acc)) or not (-90 <= lat <= 90 and -180 <= lon <= 180) or ts <= 0:
            return None
        point = {"lat": lat, "lon": lon, "acc": acc, "ts": ts}
        if p.get("received_at") is not None:
            received_at = float(p["received_at"])
            if math.isfinite(received_at) and received_at >= 0:
                point["received_at"] = received_at
        if p.get("confidence") is not None:
            point["confidence"] = int(p.get("confidence"))
        if p.get("status") is not None:
            point["status"] = int(p.get("status"))
        if p.get("source") in {"apple", "google", "samsung"}:
            point["source"] = p.get("source")
        if p.get("provider"):
            point["provider"] = str(p.get("provider"))[:60]
        if p.get("is_own_report") is not None:
            point["is_own_report"] = bool(p.get("is_own_report"))
        if p.get("alt") is not None:
            point["alt"] = float(p.get("alt") or 0)
        if p.get("semantic"):
            point["semantic"] = str(p.get("semantic"))[:180]
        if p.get("batch_id"):
            point["batch_id"] = str(p.get("batch_id"))[:80]
        # Preserve bounded, non-secret observation metadata. Older versions
        # normalized these fields away, so comparison reports and evidence
        # PDFs could show the current battery but not the values observed
        # along the stored route.
        if p.get("battery") is not None:
            point["battery"] = str(p.get("battery"))[:120]
        if p.get("bat") is not None:
            raw_battery = p.get("bat")
            point["bat"] = float(raw_battery) if isinstance(raw_battery, (int, float)) else str(raw_battery)[:80]
        if isinstance(p.get("battery_info"), dict):
            point["battery_info"] = {
                str(key)[:40]: value
                for key, value in p["battery_info"].items()
                if key in {"label", "percent", "level", "status", "updated_ts"} and isinstance(value, (str, int, float, bool, type(None)))
            }
        if isinstance(p.get("address"), dict):
            point["address"] = {
                str(key)[:60]: str(value)[:500]
                for key, value in p["address"].items()
                if value not in (None, "")
            }
        for key in ("method", "nearby", "on_demand"):
            if p.get(key) is not None:
                point[key] = p.get(key) if isinstance(p.get(key), (bool, int, float)) else str(p.get(key))[:120]
        point["report_id"] = point_identity({**point, "report_id": p.get("report_id")})
        return point
    except Exception:
        return None


def prune_points(points, retention_seconds=HISTORY_RETENTION_SECONDS, max_points=SEVEN_HISTORY_LIMIT):
    now = time.time()
    clean = []
    seen = set()
    for p in points or []:
        np = normalize_point(p)
        if not np:
            continue
        if retention_seconds is not None and np["ts"] < now - float(retention_seconds):
            continue
        key = np["report_id"]
        if key in seen:
            continue
        seen.add(key)
        clean.append(np)
    clean.sort(key=lambda x: x["ts"])
    if max_points is not None and int(max_points) > 0:
        return clean[-int(max_points):]
    return clean


def history_policy_ref(provider, tracker_id):
    provider = str(provider or "").strip().lower()
    tracker_id = str(tracker_id or "").strip()
    if provider not in {"apple", "google", "samsung", "fusion"} or not tracker_id:
        raise ValueError("Ungültige Verlaufsreferenz.")
    return f"{provider}:{tracker_id}"


def normalize_history_retention(mode=None, days=None, default_days=7):
    raw_mode = str(mode or "days").strip().lower().replace("-", "_")
    if raw_mode in {"forever", "permanent", "dauerhaft", "never_delete", "unlimited"}:
        return {"mode": "forever", "days": None, "retention_seconds": None, "label": "Dauerhaft"}
    try:
        parsed_days = int(float(days if days is not None else default_days))
    except (TypeError, ValueError):
        parsed_days = int(default_days)
    parsed_days = max(HISTORY_RETENTION_MIN_DAYS, min(HISTORY_RETENTION_MAX_DAYS, parsed_days))
    return {
        "mode": "days",
        "days": parsed_days,
        "retention_seconds": parsed_days * 24 * 60 * 60,
        "label": f"{parsed_days} Tage",
    }


def parse_history_retention_choice(value=None, custom_days=None, default_days=7):
    """Parse API/UI/MCP choices without silently accepting invalid custom input."""
    raw = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    if raw in {"forever", "permanent", "dauerhaft", "never", "never_delete", "unlimited"}:
        return normalize_history_retention("forever", None, default_days)
    preset_map = {
        "7": 7, "7_days": 7, "14": 14, "14_days": 14,
        "30": 30, "30_days": 30, "90": 90, "90_days": 90,
    }
    if raw in preset_map:
        return normalize_history_retention("days", preset_map[raw], default_days)
    if raw == "custom" and custom_days is None:
        raise ValueError("Für Custom-Verlauf ist custom_days erforderlich.")
    if raw in {"", "days", "custom"}:
        candidate = custom_days if custom_days is not None else default_days
    else:
        candidate = custom_days if custom_days is not None else raw.removesuffix("_days")
    try:
        parsed = int(float(candidate))
    except (TypeError, ValueError):
        raise ValueError("Bitte eine gültige Anzahl an Tagen angeben.")
    if not HISTORY_RETENTION_MIN_DAYS <= parsed <= HISTORY_RETENTION_MAX_DAYS:
        raise ValueError(
            f"Custom-Verlauf muss zwischen {HISTORY_RETENTION_MIN_DAYS} und {HISTORY_RETENTION_MAX_DAYS} Tagen liegen."
        )
    return normalize_history_retention("days", parsed, default_days)


def normalize_history_policy_row(raw, enabled_default=False):
    raw = dict(raw) if isinstance(raw, dict) else {}
    retention = normalize_history_retention(raw.get("mode"), raw.get("days"), 7)
    return {
        "enabled": settings_bool(raw.get("enabled"), enabled_default),
        "mode": retention["mode"],
        "days": retention["days"],
        "updated_ts": int(float(raw.get("updated_ts", 0) or 0)),
        "created_ts": int(float(raw.get("created_ts", raw.get("updated_ts", 0)) or 0)),
        **({"migrated_from": str(raw.get("migrated_from"))[:80]} if raw.get("migrated_from") else {}),
    }


def history_legacy_enabled(provider, tracker_id):
    provider, tracker_id = str(provider), str(tracker_id)
    if provider == "apple":
        return bool(state.get("seven_day_enabled", {}).get(tracker_id))
    if provider == "google":
        row = state.get("google_history", {}).get(tracker_id)
        return bool(row.get("enabled")) if isinstance(row, dict) else False
    if provider == "samsung":
        row = state.get("samsung_history", {}).get(tracker_id)
        return bool(row.get("enabled")) if isinstance(row, dict) else False
    return False


def history_direct_policy(provider, tracker_id, include_legacy=True):
    ref = history_policy_ref(provider, tracker_id)
    raw = (state.get("history_retention", {}).get("trackers", {}) or {}).get(ref)
    if isinstance(raw, dict):
        normalized = normalize_history_policy_row(raw, history_legacy_enabled(provider, tracker_id))
    else:
        normalized = normalize_history_policy_row({}, history_legacy_enabled(provider, tracker_id) if include_legacy else False)
    # New/default Apple trackers collect all reports. An explicit pause from
    # set_history_policy remains authoritative; no stored data is rewritten.
    if str(provider) == "apple" and include_legacy and (not isinstance(raw, dict) or raw.get("migrated_from")):
        if normalize_polling_settings(state.get("settings", {}).get("polling", {})).get("apple_batch_reports_default", True):
            normalized["enabled"] = True
    retention = normalize_history_retention(normalized.get("mode"), normalized.get("days"), 7)
    return {
        "tracker_ref": ref,
        "provider": str(provider),
        "tracker_id": str(tracker_id),
        **normalized,
        "retention_seconds": retention["retention_seconds"],
        "label": retention["label"],
        "source": "tracker",
    }


def history_linked_fusion_ids(provider, tracker_id):
    provider, tracker_id = str(provider), str(tracker_id)
    names = set()
    if provider == "apple":
        if tracker_id in state.get("fusion_profiles", {}) or tracker_id in state.get("google_links", {}) or tracker_id in state.get("samsung_links", {}):
            names.add(tracker_id)
    elif provider == "google":
        for apple_name, link in state.get("google_links", {}).items():
            if isinstance(link, dict) and str(link.get("google_id") or "") == tracker_id:
                names.add(str(apple_name))
        for apple_name, profile in state.get("fusion_profiles", {}).items():
            if isinstance(profile, dict) and str(profile.get("google_id") or "") == tracker_id:
                names.add(str(apple_name))
    elif provider == "samsung":
        for apple_name, link in state.get("samsung_links", {}).items():
            if isinstance(link, dict) and str(link.get("samsung_id") or "") == tracker_id:
                names.add(str(apple_name))
        for apple_name, profile in state.get("fusion_profiles", {}).items():
            if isinstance(profile, dict) and str(profile.get("samsung_id") or "") == tracker_id:
                names.add(str(apple_name))
    return sorted(names)


def history_longest_policy(policies, fallback=None):
    usable = [dict(row) for row in policies or [] if isinstance(row, dict)]
    if not usable:
        return dict(fallback or normalize_history_retention("days", 7))
    permanent = next((row for row in usable if row.get("mode") == "forever" or row.get("retention_seconds") is None), None)
    if permanent:
        return permanent
    return max(usable, key=lambda row: int(row.get("retention_seconds", 0) or 0))


def history_share_policy(apple_name):
    policies = []
    for link in state.get("shared_links", {}).values():
        if not isinstance(link, dict) or str(link.get("device") or "") != str(apple_name) or share_link_status(link) != "active":
            continue
        permissions = share_permissions(link, history_fallback=bool(state.get("share_history_enabled", {}).get(apple_name)))
        privacy = share_privacy_config(link)
        if permissions.get("show_history") or int(privacy.get("delay_minutes", 0) or 0) > 0:
            hours = max(1, int(privacy.get("history_hours", 168) or 168))
            days = max(1, int(math.ceil(hours / 24)))
            row = normalize_history_retention("days", days)
            row.update({"enabled": True, "source": "share"})
            policies.append(row)
    return history_longest_policy(policies, {}) if policies else None


def history_capture_policy(provider, tracker_id, include_disabled_direct=False):
    direct = history_direct_policy(provider, tracker_id)
    candidates = []
    if direct.get("enabled") or include_disabled_direct:
        candidates.append(direct)
    linked_fusions = history_linked_fusion_ids(provider, tracker_id)
    for apple_name in linked_fusions:
        fusion = history_direct_policy("fusion", apple_name, include_legacy=False)
        if fusion.get("enabled"):
            fusion["source"] = "fusion"
            candidates.append(fusion)
        profile = state.get("fusion_profiles", {}).get(apple_name, {})
        if isinstance(profile, dict) and profile.get("location_optimization"):
            optimized = normalize_history_retention("days", 7)
            optimized.update({"enabled": True, "source": "fusion_optimization"})
            candidates.append(optimized)
        shared = history_share_policy(apple_name)
        if shared:
            candidates.append(shared)
    if provider == "apple":
        shared = history_share_policy(tracker_id)
        if shared:
            candidates.append(shared)
    if not candidates:
        return {**direct, "capture_enabled": False}
    selected = history_longest_policy(candidates, direct)
    return {
        **selected,
        "tracker_ref": direct["tracker_ref"],
        "provider": str(provider),
        "tracker_id": str(tracker_id),
        "capture_enabled": any(bool(row.get("enabled")) for row in candidates),
        "sources": sorted({str(row.get("source") or "tracker") for row in candidates}),
    }


def history_storage_policy(provider, tracker_id):
    direct = history_direct_policy(provider, tracker_id)
    capture = history_capture_policy(provider, tracker_id, include_disabled_direct=True)
    selected = history_longest_policy([direct, capture], direct)
    return {**direct, **selected, "capture_enabled": bool(capture.get("capture_enabled"))}


def fusion_history_storage_policy(apple_name):
    policies = [history_storage_policy("apple", apple_name), history_direct_policy("fusion", apple_name, include_legacy=False)]
    profile = state.get("fusion_profiles", {}).get(apple_name, {})
    google_link = state.get("google_links", {}).get(apple_name, {})
    samsung_link = state.get("samsung_links", {}).get(apple_name, {})
    google_id = (profile if isinstance(profile, dict) else {}).get("google_id") or (google_link if isinstance(google_link, dict) else {}).get("google_id")
    samsung_id = (profile if isinstance(profile, dict) else {}).get("samsung_id") or (samsung_link if isinstance(samsung_link, dict) else {}).get("samsung_id")
    if google_id:
        policies.append(history_storage_policy("google", google_id))
    if samsung_id:
        policies.append(history_storage_policy("samsung", samsung_id))
    selected = history_longest_policy(policies, normalize_history_retention("days", 7))
    return {**selected, "tracker_ref": f"fusion:{apple_name}"}


def history_policy_max_points(provider, policy):
    if str(provider) == "apple" or policy.get("mode") == "forever" or policy.get("retention_seconds") is None:
        # Keep every unique Apple report within the selected retention window.
        return None
    base = {"apple": SEVEN_HISTORY_LIMIT, "google": GOOGLE_HISTORY_LIMIT, "samsung": SAMSUNG_HISTORY_LIMIT}.get(str(provider), SEVEN_HISTORY_LIMIT)
    interval = {"apple": APPLE_DEFAULT_INTERVAL_MIN, "google": GOOGLE_DEFAULT_INTERVAL_MIN, "samsung": SAMSUNG_DEFAULT_INTERVAL_MIN}.get(str(provider), 30)
    expected = int(float(policy.get("retention_seconds", HISTORY_RETENTION_SECONDS)) / max(1, interval)) + 1000
    return max(int(base), expected)


def history_policy_public(provider, tracker_id):
    direct = history_direct_policy(provider, tracker_id)
    storage = fusion_history_storage_policy(tracker_id) if str(provider) == "fusion" else history_storage_policy(provider, tracker_id)
    capture_enabled = bool(direct.get("enabled")) if str(provider) == "fusion" else bool(storage.get("capture_enabled"))
    return {
        "tracker_ref": direct["tracker_ref"],
        "enabled": bool(direct.get("enabled")),
        "mode": direct.get("mode"),
        "days": direct.get("days"),
        "label": direct.get("label"),
        "retention_seconds": direct.get("retention_seconds"),
        "effective_mode": storage.get("mode"),
        "effective_days": storage.get("days"),
        "effective_label": storage.get("label"),
        "capture_enabled": capture_enabled,
        "updated_ts": int(direct.get("updated_ts", 0) or 0),
        "permanent": direct.get("mode") == "forever",
    }


def migrate_history_retention_policies():
    store = state.get("history_retention")
    if not isinstance(store, dict):
        store = default_history_retention_store()
        state["history_retention"] = store
    trackers = store.get("trackers")
    if not isinstance(trackers, dict):
        trackers = {}
        store["trackers"] = trackers
    normalized = {}
    for ref, raw in trackers.items():
        try:
            provider, tracker_id = str(ref).split(":", 1)
            normalized[history_policy_ref(provider, tracker_id)] = normalize_history_policy_row(raw, history_legacy_enabled(provider, tracker_id))
        except (ValueError, TypeError):
            continue
    now_ts = int(time.time())
    legacy_refs = []
    legacy_refs.extend(("apple", name) for name in set(state.get("seven_day_enabled", {})) | set(state.get("seven_day_history", {})))
    legacy_refs.extend(("google", device_id) for device_id in state.get("google_history", {}))
    legacy_refs.extend(("samsung", device_id) for device_id in state.get("samsung_history", {}))
    for provider, tracker_id in legacy_refs:
        ref = history_policy_ref(provider, tracker_id)
        if ref in normalized:
            continue
        provider_store = state.get(
            {"apple": "seven_day_history", "google": "google_history", "samsung": "samsung_history"}[provider],
            {},
        )
        legacy_store = provider_store.get(tracker_id)
        has_points = bool(legacy_store.get("points")) if isinstance(legacy_store, dict) else bool(legacy_store) if isinstance(legacy_store, list) else False
        enabled = history_legacy_enabled(provider, tracker_id)
        if enabled or has_points:
            normalized[ref] = {
                "enabled": enabled,
                "mode": "days",
                "days": 7,
                "created_ts": now_ts,
                "updated_ts": now_ts,
                "migrated_from": "legacy_7_day_history",
            }
    store["schema"] = 2
    store["trackers"] = normalized
    store.setdefault("last_maintenance_ts", 0)
    store.setdefault("last_maintenance_reason", "never")
    store.setdefault("last_removed_points", 0)
    return store


def set_history_policy(provider, tracker_id, enabled, mode="days", days=7):
    provider, tracker_id = str(provider).lower(), str(tracker_id)
    ref = history_policy_ref(provider, tracker_id)
    retention = normalize_history_retention(mode, days, 7)
    now_ts = int(time.time())
    old = (state.setdefault("history_retention", default_history_retention_store()).setdefault("trackers", {}).get(ref) or {})
    row = {
        "enabled": bool(enabled),
        "mode": retention["mode"],
        "days": retention["days"],
        "created_ts": int(old.get("created_ts", now_ts) or now_ts),
        "updated_ts": now_ts,
    }
    state["history_retention"]["trackers"][ref] = row
    if provider == "apple":
        if enabled:
            state.setdefault("seven_day_enabled", {})[tracker_id] = True
        else:
            state.setdefault("seven_day_enabled", {}).pop(tracker_id, None)
        state.setdefault("seven_day_history", {}).setdefault(tracker_id, {"points": []})
        save_json(SEVEN_ENABLED_FILE, "seven_day_enabled")
        save_json(SEVEN_HISTORY_FILE, "seven_day_history")
    elif provider == "google":
        history_store = state.setdefault("google_history", {}).setdefault(tracker_id, {"points": []})
        history_store["enabled"] = bool(enabled)
        history_store["retention_mode"] = retention["mode"]
        history_store["retention_days"] = retention["days"]
        save_json(GOOGLE_HISTORY_FILE, "google_history")
    elif provider == "samsung":
        history_store = state.setdefault("samsung_history", {}).setdefault(tracker_id, {"points": []})
        history_store["enabled"] = bool(enabled)
        history_store["retention_mode"] = retention["mode"]
        history_store["retention_days"] = retention["days"]
        save_json(SAMSUNG_HISTORY_FILE, "samsung_history")
    save_json(HISTORY_POLICY_FILE, "history_retention")
    with fusion_history_cache_lock:
        fusion_history_cache_store.clear()
    with route_day_cache_lock:
        route_day_cache.clear()
    return history_policy_public(provider, tracker_id)


def history_run_maintenance(reason="scheduled", force=False):
    if not history_maintenance_lock.acquire(blocking=False):
        return {"status": "running", "reason": reason, "removed_points": 0}
    try:
        now_ts = int(time.time())
        last_ts = int(state.get("history_retention", {}).get("last_maintenance_ts", 0) or 0)
        if not force and reason != "startup" and now_ts - last_ts < max(60, HISTORY_MAINTENANCE_SECONDS // 2):
            return {"status": "fresh", "reason": reason, "removed_points": 0, "last_maintenance_ts": last_ts}
        changed_files = set()
        removed = 0
        stores = (
            ("apple", state.get("seven_day_history", {}), SEVEN_HISTORY_FILE, "seven_day_history"),
            ("google", state.get("google_history", {}), GOOGLE_HISTORY_FILE, "google_history"),
            ("samsung", state.get("samsung_history", {}), SAMSUNG_HISTORY_FILE, "samsung_history"),
        )
        for provider, history_map, file_path, state_key in stores:
            for tracker_id, raw_store in list(history_map.items()):
                if isinstance(raw_store, list):
                    raw_store = {"points": raw_store}
                    history_map[tracker_id] = raw_store
                if not isinstance(raw_store, dict):
                    history_map[tracker_id] = {"points": []}
                    changed_files.add((file_path, state_key))
                    continue
                policy = history_storage_policy(provider, tracker_id)
                old_points = raw_store.get("points", []) if isinstance(raw_store.get("points"), list) else []
                new_points = prune_points(old_points, policy.get("retention_seconds"), history_policy_max_points(provider, policy))
                if len(new_points) != len(old_points) or new_points != old_points:
                    removed += max(0, len(old_points) - len(new_points))
                    raw_store["points"] = new_points
                    changed_files.add((file_path, state_key))
        for name, raw_store in list(state.get("shared_history", {}).items()):
            if not isinstance(raw_store, dict):
                raw_store = {"points": raw_store if isinstance(raw_store, list) else []}
                state["shared_history"][name] = raw_store
            share_policy = history_share_policy(name) or normalize_history_retention("days", 7)
            old_points = raw_store.get("points", []) if isinstance(raw_store.get("points"), list) else []
            new_points = prune_points(old_points, share_policy.get("retention_seconds"), SHARED_HISTORY_LIMIT)
            if len(new_points) != len(old_points) or new_points != old_points:
                removed += max(0, len(old_points) - len(new_points))
                raw_store["points"] = new_points
                changed_files.add((SHARED_HIST_FILE, "shared_history"))
        for file_path, state_key in changed_files:
            save_json(file_path, state_key)
        retention_store = state.setdefault("history_retention", default_history_retention_store())
        retention_store.update({
            "last_maintenance_ts": now_ts,
            "last_maintenance_reason": str(reason)[:40],
            "last_removed_points": removed,
        })
        save_json(HISTORY_POLICY_FILE, "history_retention")
        if removed:
            with fusion_history_cache_lock:
                fusion_history_cache_store.clear()
            with route_day_cache_lock:
                route_day_cache.clear()
        logger.info("[HISTORY-MAINTENANCE] %s | %d abgelaufene Standortpunkte entfernt | %d Datei(en) aktualisiert", reason, removed, len(changed_files))
        return {"status": "ok", "reason": reason, "removed_points": removed, "updated_files": len(changed_files), "last_maintenance_ts": now_ts}
    finally:
        history_maintenance_lock.release()


