    state["mcp_oauth"] = safe_load_json(MCP_OAUTH_FILE, default_mcp_oauth_store())
    state["mcp_audit"] = safe_load_json(MCP_AUDIT_FILE, [])
    state["google_devices"] = safe_load_json(GOOGLE_DEVICES_FILE, {})
    state["google_locations"] = safe_load_json(GOOGLE_LOCATIONS_FILE, {})
