# ---------------------------------------------------------------------------
# 16.0 MULTI-USER CORE
# ---------------------------------------------------------------------------
# The original data directory is the owner's tenant. Secondary users receive
# the same proven storage layout below data/users/<id>/data. Context-local
# state and path proxies let all existing provider/history code operate on the
# correct tenant without risky rewrites of the established persistence layer.
_MAIN_DATA_DIR = Path(os.fspath(DATA_DIR)).resolve()
_USERS_ROOT = _MAIN_DATA_DIR / "users"
_USERS_FILE = _MAIN_DATA_DIR / "users.json"
_DELETED_USERS_ROOT = _MAIN_DATA_DIR / "deleted_users"
# 17.0 global identity stores deliberately live outside every tenant proxy.
# They contain only access grants and encrypted authentication material; all
# provider sessions, tracker keys and histories remain in their owner tenant.
_INTERNAL_SHARES_FILE = _MAIN_DATA_DIR / "internal_tracker_shares.json"
_TWO_FACTOR_FILE = _MAIN_DATA_DIR / ".two_factor.json"
_PASSKEYS_FILE = _MAIN_DATA_DIR / ".passkeys.json"
_tenant_id_context = contextvars.ContextVar("uts_tenant_id", default="main")
_MAIN_STATE = state
_tenant_states = {"main": _MAIN_STATE}
_tenant_load_lock = threading.RLock()
_tenant_workers_lock = threading.RLock()
_tenant_worker_threads = {}
_deleted_tenant_ids = set()
_users_lock = threading.RLock()
_public_owner_cache = {}
_public_owner_cache_lock = threading.RLock()
_password_reset_attempts = {}
_password_reset_lock = threading.RLock()
_internal_shares_lock = threading.RLock()
_two_factor_lock = threading.RLock()
_two_factor_pending_lock = threading.RLock()
_two_factor_pending = {}
_two_factor_store_cache = None
_two_factor_store_mtime_ns = None
_passkey_lock = threading.RLock()
_passkey_pending_lock = threading.RLock()
_passkey_pending = {}
_passkey_store_cache = None
_passkey_store_mtime_ns = None


def current_tenant_id():
    value = str(_tenant_id_context.get() or "main")
    return value if re.fullmatch(r"[a-z0-9][a-z0-9_-]{0,63}", value) else "main"


@contextmanager
def tenant_context(tenant_id):
    tenant_id = str(tenant_id or "main")
    token = _tenant_id_context.set(tenant_id)
    try:
        yield tenant_id
    finally:
        _tenant_id_context.reset(token)


def tenant_data_dir(tenant_id=None):
    tenant_id = str(tenant_id or current_tenant_id())
    if tenant_id == "main":
        return _MAIN_DATA_DIR
    if tenant_id in _deleted_tenant_ids:
        raise PermissionError("Benutzer wurde gelöscht.")
    if not re.fullmatch(r"[a-z0-9][a-z0-9_-]{0,63}", tenant_id):
        raise ValueError("Ungültige Benutzer-ID")
    return (_USERS_ROOT / tenant_id / "data").resolve()


class TenantScopedPath(os.PathLike):
    """Path-like view that resolves below the active tenant's data root."""

    __slots__ = ("_relative", "_main")

    def __init__(self, original):
        original = Path(original).resolve()
        self._main = original
        self._relative = original.relative_to(_MAIN_DATA_DIR)

    def resolve_for_tenant(self, tenant_id=None):
        if str(tenant_id or current_tenant_id()) == "main":
            return self._main
        return tenant_data_dir(tenant_id) / self._relative

    def __fspath__(self):
        return os.fspath(self.resolve_for_tenant())

    def __str__(self):
        return str(self.resolve_for_tenant())

    def __repr__(self):
        return f"TenantScopedPath({self._relative!s}, tenant={current_tenant_id()!r})"

    def __truediv__(self, other):
        return self.resolve_for_tenant() / other

    def __rtruediv__(self, other):
        return Path(other) / self.resolve_for_tenant()

    def __eq__(self, other):
        try:
            return self.resolve_for_tenant() == Path(other)
        except (TypeError, ValueError):
            return False

    def __hash__(self):
        return hash(self.resolve_for_tenant())

    def __getattr__(self, name):
        return getattr(self.resolve_for_tenant(), name)


class TenantStateProxy(MutableMapping):
    def _target(self):
        tenant_id = current_tenant_id()
        if tenant_id == "main":
            return _MAIN_STATE
        target = _tenant_states.get(tenant_id)
        if target is None:
            raise RuntimeError("Benutzerkontext wurde nicht geladen.")
        return target

    def __getitem__(self, key):
        return self._target()[key]

    def __setitem__(self, key, value):
        self._target()[key] = value

    def __delitem__(self, key):
        del self._target()[key]

    def __iter__(self):
        return iter(self._target())

    def __len__(self):
        return len(self._target())

    def __repr__(self):
        return repr(self._target())


class TenantDictProxy(MutableMapping):
    """Tenant-local view for caches whose keys may otherwise collide."""

    def __init__(self, main_value):
        self._values = {"main": main_value}
        self._lock = threading.RLock()

    def _target(self):
        tenant_id = current_tenant_id()
        with self._lock:
            return self._values.setdefault(tenant_id, {})

    def drop(self, tenant_id):
        if tenant_id == "main":
            return
        with self._lock:
            self._values.pop(str(tenant_id), None)

    def __getitem__(self, key):
        return self._target()[key]

    def __setitem__(self, key, value):
        self._target()[key] = value

    def __delitem__(self, key):
        del self._target()[key]

    def __iter__(self):
        return iter(self._target())

    def __len__(self):
        return len(self._target())


def normalize_username(value):
    value = unicodedata.normalize("NFKC", str(value or "")).strip().casefold()
    value = re.sub(r"\s+", "-", value)
    if not re.fullmatch(r"[a-z0-9][a-z0-9._-]{2,63}", value):
        raise ValueError("Der Benutzername braucht 3–64 Zeichen (Buchstaben, Zahlen, Punkt, _ oder -).")
    return value


def _load_users_registry():
    raw = safe_load_json(_USERS_FILE, {"schema": 1, "users": {}}, accepted_types=(dict,))
    users = raw.get("users") if isinstance(raw.get("users"), dict) else {}
    owner = users.get("main") if isinstance(users.get("main"), dict) else {}
    owner.update({
        "id": "main",
        "username": str(owner.get("username") or os.environ.get("ULTRA_TRACKER_ADMIN_USERNAME", "admin")).strip().casefold() or "admin",
        "display_name": str(owner.get("display_name") or "Haupt-Admin")[:100],
        "role": "owner",
        "active": True,
        "created_ts": int(owner.get("created_ts", int(time.time())) or int(time.time())),
    })
    users["main"] = owner
    return {"schema": 3, "users": users, "updated_ts": int(raw.get("updated_ts", 0) or 0)}


_users_registry = _load_users_registry()


def save_users_registry():
    with _users_lock:
        _users_registry["schema"] = 3
        _users_registry["updated_ts"] = int(time.time())
        atomic_write_json(_USERS_FILE, _users_registry, create_backup=True, private=True)


try:
    _USERS_ROOT.mkdir(parents=True, exist_ok=True)
    os.chmod(_USERS_ROOT, 0o700)
    save_users_registry()
except OSError as exc:
    logger.warning("Benutzerverwaltung konnte nicht vorbereitet werden: %s", exc)


def user_record(user_id):
    row = _users_registry.get("users", {}).get(str(user_id or ""), {})
    return row if isinstance(row, dict) else {}


def find_user_by_username(username):
    try:
        wanted = normalize_username(username)
    except ValueError:
        return None
    for row in _users_registry.get("users", {}).values():
        if isinstance(row, dict) and str(row.get("username") or "").casefold() == wanted:
            return row
    return None


def user_password_record(password):
    salt = secrets.token_bytes(24)
    digest = hashlib.pbkdf2_hmac("sha256", str(password).encode("utf-8"), salt, APP_PASSWORD_KDF_ITERATIONS)
    return {
        "algorithm": "pbkdf2-sha256",
        "iterations": APP_PASSWORD_KDF_ITERATIONS,
        "password_hash": digest.hex(),
        "password_salt": salt.hex(),
        "generation": secrets.token_urlsafe(24),
        "password_updated_ts": int(time.time()),
    }


def verify_user_password(row, candidate):
    if not isinstance(row, dict) or not row.get("active", True):
        return False
    try:
        salt = bytes.fromhex(str(row.get("password_salt") or ""))
        expected = str(row.get("password_hash") or "")
        iterations = max(100000, int(row.get("iterations") or APP_PASSWORD_KDF_ITERATIONS))
        if len(salt) < 16 or not expected:
            return False
        actual = hashlib.pbkdf2_hmac("sha256", str(candidate or "").encode("utf-8"), salt, iterations).hex()
        return hmac.compare_digest(actual, expected)
    except (TypeError, ValueError, OverflowError):
        return False


# All persistence paths that contain tenant data become context-local. Heavy
# toolchains and shared read-only helper binaries remain installed once.
_TENANT_PATH_EXCLUDES = {
    "BASE_DIR", "GOOGLE_TOOLS_DIR", "GOOGLE_VENV_DIR", "GOOGLE_TOOLS_META_FILE",
    "ANISETTE_LIBS", "WEBPUSH_VAPID_FILE", "TRACKER_LAB_TOOLS_DIR", "TRACKER_LAB_IDF_DIR",
    "TRACKER_LAB_IDF_TOOLS_DIR", "TRACKER_LAB_HOST_VENV_DIR",
    "TRACKER_LAB_IDF_READY_FILE",
}
for _path_name, _path_value in list(globals().items()):
    if _path_name.startswith("_") or _path_name in _TENANT_PATH_EXCLUDES or not isinstance(_path_value, Path):
        continue
    try:
        _path_value.resolve().relative_to(_MAIN_DATA_DIR)
    except (ValueError, OSError):
        continue
    globals()[_path_name] = TenantScopedPath(_path_value)

# Replace the direct state/cache objects only after the owner's original data
# has been loaded. Existing references keep their main values in the proxies.
state = TenantStateProxy()
state_response_cache = TenantDictProxy(state_response_cache)
route_day_cache = TenantDictProxy(route_day_cache)
fusion_history_cache_store = TenantDictProxy(fusion_history_cache_store)
storage_scan_cache = TenantDictProxy(storage_scan_cache)


# New threads inherit the tenant active when they are constructed. This is
# essential for manual locate calls and asynchronous exports started by a user.
_OriginalThread = threading.Thread


class TenantContextThread(_OriginalThread):
    def __init__(self, *args, **kwargs):
        self._tenant_context_snapshot = contextvars.copy_context()
        super().__init__(*args, **kwargs)

    def run(self):
        return self._tenant_context_snapshot.run(super().run)


threading.Thread = TenantContextThread


def _prepare_tenant_directories(tenant_id):
    root = tenant_data_dir(tenant_id)
    for relative in (".", "accessories", "sessions", "google", "google/sessions", "samsung", "samsung/sessions", "backups", "exports", "email_map_cache", "tracker_lab", "tracker_lab/projects", "tracker_lab/builds", "tracker_lab/assets"):
        path = (root / relative).resolve()
        if root not in path.parents and path != root:
            raise ValueError("Unsicherer Benutzerpfad")
        path.mkdir(parents=True, exist_ok=True)
    try:
        os.chmod(root.parent, 0o700)
        os.chmod(root, 0o700)
    except OSError:
        pass


def start_tenant_workers(tenant_id):
    tenant_id = str(tenant_id)
    if tenant_id == "main" or globals().get("_DISABLE_BACKGROUND", True):
        return
    required = ("background_poller", "google_poller", "samsung_poller")
    if not all(callable(globals().get(name)) for name in required):
        return
    with _tenant_workers_lock:
        current = [thread for thread in _tenant_worker_threads.get(tenant_id, []) if thread.is_alive()]
        if current:
            _tenant_worker_threads[tenant_id] = current
            return
        threads = []
        with tenant_context(tenant_id):
            for provider, target_name in (("apple", "background_poller"), ("google", "google_poller"), ("samsung", "samsung_poller")):
                thread = threading.Thread(
                    target=globals()[target_name], daemon=True,
                    name=f"tag-studio-{tenant_id[:12]}-{provider}",
                )
                thread.start()
                threads.append(thread)
        _tenant_worker_threads[tenant_id] = threads


def ensure_tenant_state(tenant_id, start_workers=True):
    tenant_id = str(tenant_id or "main")
    if tenant_id == "main":
        return _MAIN_STATE
    row = user_record(tenant_id)
    if not row or not row.get("active", True):
        raise PermissionError("Benutzer ist nicht aktiv.")
    with _tenant_load_lock:
        if tenant_id not in _tenant_states:
            _prepare_tenant_directories(tenant_id)
            _tenant_states[tenant_id] = copy.deepcopy(_STATE_DEFAULT_TEMPLATE)
            try:
                with tenant_context(tenant_id):
                    load_data()
                    if callable(globals().get("migrate_schema")):
                        migrate_schema()
                    if callable(globals().get("history_run_maintenance")):
                        history_run_maintenance("user_load", force=True)
            except Exception:
                _tenant_states.pop(tenant_id, None)
                raise
    if start_workers:
        start_tenant_workers(tenant_id)
    return _tenant_states[tenant_id]


def tenant_ids(active_only=True):
    result = ["main"]
    for user_id, row in _users_registry.get("users", {}).items():
        if user_id == "main" or not isinstance(row, dict):
            continue
        if active_only and not row.get("active", True):
            continue
        result.append(str(user_id))
    return result


def find_public_token_owner(token, kind="shared"):
    token = str(token or "")
    if not re.fullmatch(r"[A-Za-z0-9_-]{8,256}", token):
        return "main"
    cache_key = (kind, token)
    now = time.time()
    with _public_owner_cache_lock:
        cached = _public_owner_cache.get(cache_key)
        if cached and now - cached[1] < 60:
            return cached[0]
    store_key = "recovery_shares" if kind == "recovery" else "shared_links"
    for tenant_id in tenant_ids(active_only=True):
        try:
            tenant_state = ensure_tenant_state(tenant_id, start_workers=False)
        except Exception:
            continue
        if token in tenant_state.get(store_key, {}):
            with _public_owner_cache_lock:
                _public_owner_cache[cache_key] = (tenant_id, now)
            return tenant_id
    return "main"


def current_user_public():
    user_id = str(session.get("user_id") or current_tenant_id() or "main")
    row = user_record(user_id) or user_record("main")
    public = {
        "id": user_id,
        "username": str(row.get("username") or "admin"),
        "display_name": str(row.get("display_name") or row.get("username") or "Benutzer"),
        "email": str(row.get("email") or ""),
        "role": str(row.get("role") or ("owner" if user_id == "main" else "user")),
        "active": bool(row.get("active", True)),
        "is_main_admin": user_id == "main",
    }
    if callable(globals().get("two_factor_public_status")):
        public["two_factor"] = two_factor_public_status(user_id)
    if callable(globals().get("passkey_public_status")):
        public["passkeys"] = passkey_public_status(user_id)
    return public


def is_main_admin():
    return bool(session.get("app_unlocked")) and str(session.get("user_id") or "main") == "main"


def current_password_generation():
    row = user_record(current_tenant_id()) or {}
    if current_tenant_id() == "main":
        record = load_app_password_record()
        password_generation = "legacy" if record is None else str(record.get("generation") or "invalid")
    else:
        password_generation = str(row.get("generation") or "invalid")
    # A distinct authentication generation lets a 2FA change revoke old
    # browser sessions without rotating or re-hashing the user's password.
    auth_generation = str(row.get("auth_generation") or "legacy-2fa")
    return f"{password_generation}:{auth_generation}"


def invalidate_public_owner_cache():
    with _public_owner_cache_lock:
        _public_owner_cache.clear()


# ---------------------------------------------------------------------------
# 17.0 ENCRYPTED TOTP + INTERNAL USER SHARING STORES
# ---------------------------------------------------------------------------
def _identity_bool(value, default=False):
    """Early bool parser: identity stores load before the wider helpers do."""
    if value is None:
        return bool(default)
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    return str(value).strip().lower() in {"1", "true", "yes", "on", "ja", "aktiv", "enabled"}


def _load_internal_share_store():
    raw = safe_load_json(_INTERNAL_SHARES_FILE, {"schema": 1, "shares": {}}, accepted_types=(dict,))
    shares = raw.get("shares") if isinstance(raw.get("shares"), dict) else {}
    normalized = {}
    for share_id, value in shares.items():
        if not isinstance(value, dict):
            continue
        owner_id = str(value.get("owner_user_id") or "")
        recipient_id = str(value.get("recipient_user_id") or "")
        tracker_ref = str(value.get("tracker_ref") or "")
        if not owner_id or not recipient_id or not tracker_ref or owner_id == recipient_id:
            continue
        permissions = value.get("permissions") if isinstance(value.get("permissions"), dict) else {}
        normalized[str(share_id)] = {
            **value,
            "id": str(value.get("id") or share_id),
            "owner_user_id": owner_id,
            "recipient_user_id": recipient_id,
            "tracker_ref": tracker_ref,
            "active": bool(value.get("active", True)),
            "permissions": {
                "can_locate": _identity_bool(permissions.get("can_locate"), True),
                "show_history": _identity_bool(permissions.get("show_history"), True),
                "show_address": _identity_bool(permissions.get("show_address"), True),
                "show_accuracy": _identity_bool(permissions.get("show_accuracy"), True),
                "show_battery": _identity_bool(permissions.get("show_battery"), True),
            },
            "created_ts": int(value.get("created_ts", 0) or 0),
            "updated_ts": int(value.get("updated_ts", 0) or 0),
        }
    return {"schema": 1, "shares": normalized, "updated_ts": int(raw.get("updated_ts", 0) or 0)}


_internal_share_store = _load_internal_share_store()


def save_internal_share_store():
    with _internal_shares_lock:
        _internal_share_store["schema"] = 1
        _internal_share_store["updated_ts"] = int(time.time())
        atomic_write_json(_INTERNAL_SHARES_FILE, _internal_share_store, create_backup=True, private=True)


def internal_share_permissions(raw=None):
    raw = raw if isinstance(raw, dict) else {}
    return {
        "can_locate": _identity_bool(raw.get("can_locate"), True),
        "show_history": _identity_bool(raw.get("show_history"), True),
        "show_address": _identity_bool(raw.get("show_address"), True),
        "show_accuracy": _identity_bool(raw.get("show_accuracy"), True),
        "show_battery": _identity_bool(raw.get("show_battery"), True),
    }


def internal_share_remove_user(user_id):
    user_id = str(user_id or "")
    removed = []
    with _internal_shares_lock:
        for share_id, row in list(_internal_share_store.get("shares", {}).items()):
            if isinstance(row, dict) and user_id in {str(row.get("owner_user_id") or ""), str(row.get("recipient_user_id") or "")}:
                _internal_share_store["shares"].pop(share_id, None)
                removed.append(share_id)
        if removed:
            save_internal_share_store()
    return removed


def internal_share_remove_tracker(owner_user_id, tracker_ref):
    owner_user_id, tracker_ref = str(owner_user_id or ""), str(tracker_ref or "")
    removed = []
    with _internal_shares_lock:
        for share_id, row in list(_internal_share_store.get("shares", {}).items()):
            if isinstance(row, dict) and str(row.get("owner_user_id") or "") == owner_user_id and hmac.compare_digest(str(row.get("tracker_ref") or ""), tracker_ref):
                _internal_share_store["shares"].pop(share_id, None)
                removed.append(share_id)
        if removed:
            save_internal_share_store()
    return removed


def _two_factor_empty_store():
    return {"schema": 1, "users": {}, "updated_ts": 0}


def load_two_factor_store(force=False):
    """Reload on deletion/change so removing data/.two_factor.json is a real emergency reset."""
    global _two_factor_store_cache, _two_factor_store_mtime_ns
    with _two_factor_lock:
        try:
            current_mtime = _TWO_FACTOR_FILE.stat().st_mtime_ns
        except OSError:
            current_mtime = 0
        if not current_mtime:
            # A deliberately removed active file is the documented emergency
            # reset. Discard the stale recovery generation as well so a later
            # corrupt write can never resurrect an old authenticator secret.
            backup = _TWO_FACTOR_FILE.with_name(f"{_TWO_FACTOR_FILE.name}.bak")
            try:
                backup.unlink(missing_ok=True)
            except OSError:
                pass
            _two_factor_store_cache = _two_factor_empty_store()
            _two_factor_store_mtime_ns = 0
            return _two_factor_store_cache
        if force or _two_factor_store_cache is None or current_mtime != _two_factor_store_mtime_ns:
            raw = safe_load_json(_TWO_FACTOR_FILE, _two_factor_empty_store(), accepted_types=(dict,))
            users = raw.get("users") if isinstance(raw.get("users"), dict) else {}
            _two_factor_store_cache = {"schema": 1, "users": users, "updated_ts": int(raw.get("updated_ts", 0) or 0)}
            _two_factor_store_mtime_ns = current_mtime
        return _two_factor_store_cache


def save_two_factor_store(store=None):
    global _two_factor_store_cache, _two_factor_store_mtime_ns
    with _two_factor_lock:
        payload = store if isinstance(store, dict) else load_two_factor_store()
        payload["schema"] = 1
        payload["updated_ts"] = int(time.time())
        atomic_write_json(_TWO_FACTOR_FILE, payload, create_backup=True, private=True)
        _two_factor_store_cache = payload
        try:
            _two_factor_store_mtime_ns = _TWO_FACTOR_FILE.stat().st_mtime_ns
        except OSError:
            _two_factor_store_mtime_ns = None
        return payload


def two_factor_record(user_id):
    row = load_two_factor_store().get("users", {}).get(str(user_id or ""), {})
    return row if isinstance(row, dict) and row.get("enabled") else None


def two_factor_enabled(user_id):
    return two_factor_record(user_id) is not None


def _two_factor_cipher_key():
    return hashlib.sha256(("uts-totp-aesgcm-v1|" + str(SECRET_KEY)).encode("utf-8")).digest()


def encrypt_two_factor_secret(user_id, value):
    nonce = secrets.token_bytes(12)
    aad = f"uts-totp-v1|{user_id}".encode("utf-8")
    encrypted = AESGCM(_two_factor_cipher_key()).encrypt(nonce, str(value).encode("utf-8"), aad)
    return "v1." + base64.urlsafe_b64encode(nonce + encrypted).decode("ascii").rstrip("=")


def decrypt_two_factor_secret(user_id, value):
    text = str(value or "")
    if not text.startswith("v1."):
        raise ValueError("Unbekanntes Zwei-Faktor-Format")
    encoded = text[3:]
    raw = base64.urlsafe_b64decode(encoded + "=" * (-len(encoded) % 4))
    if len(raw) < 29:
        raise ValueError("Zwei-Faktor-Datensatz ist unvollständig")
    aad = f"uts-totp-v1|{user_id}".encode("utf-8")
    return AESGCM(_two_factor_cipher_key()).decrypt(raw[:12], raw[12:], aad).decode("utf-8")


def generate_totp_secret():
    return base64.b32encode(secrets.token_bytes(20)).decode("ascii").rstrip("=")


def totp_counter(at_time=None, period=30):
    return int(float(time.time() if at_time is None else at_time)) // int(period)


def totp_code_for_secret(secret, at_time=None, digits=6, period=30):
    normalized = re.sub(r"\s+", "", str(secret or "")).upper()
    key = base64.b32decode(normalized + "=" * (-len(normalized) % 8), casefold=True)
    counter = totp_counter(at_time, period)
    digest = hmac.new(key, struct.pack(">Q", counter), hashlib.sha1).digest()
    offset = digest[-1] & 0x0F
    binary = struct.unpack(">I", digest[offset:offset + 4])[0] & 0x7FFFFFFF
    return str(binary % (10 ** int(digits))).zfill(int(digits))


def _recovery_code_key(user_id):
    return hashlib.sha256(("uts-totp-recovery-v1|" + str(SECRET_KEY) + "|" + str(user_id)).encode("utf-8")).digest()


def normalize_recovery_code(value):
    return re.sub(r"[^A-Z0-9]", "", str(value or "").upper())


def recovery_code_digest(user_id, value):
    normalized = normalize_recovery_code(value)
    return hmac.new(_recovery_code_key(user_id), normalized.encode("ascii"), hashlib.sha256).hexdigest()


def generate_recovery_codes(count=10):
    alphabet = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"
    values = []
    for _ in range(max(6, min(16, int(count or 10)))):
        raw = "".join(secrets.choice(alphabet) for _ in range(12))
        values.append(f"{raw[:4]}-{raw[4:8]}-{raw[8:]}")
    return values


def verify_two_factor_code(user_id, candidate, consume=True):
    user_id = str(user_id or "")
    record = two_factor_record(user_id)
    if not record:
        return False, "disabled"
    normalized = normalize_recovery_code(candidate)
    if len(normalized) >= 10:
        wanted = recovery_code_digest(user_id, normalized)
        hashes = list(record.get("recovery_hashes") or [])
        for index, stored in enumerate(hashes):
            if hmac.compare_digest(str(stored), wanted):
                if consume:
                    hashes.pop(index)
                    record["recovery_hashes"] = hashes
                    record["last_used_ts"] = int(time.time())
                    record["last_used_method"] = "recovery"
                    save_two_factor_store()
                return True, "recovery"
        return False, "invalid"
    digits = re.sub(r"\D", "", str(candidate or ""))
    if len(digits) != 6:
        return False, "invalid"
    try:
        secret = decrypt_two_factor_secret(user_id, record.get("secret_enc"))
    except Exception as exc:
        logger.error("TOTP-Geheimnis für %s kann nicht entschlüsselt werden: %s", user_id, exc)
        return False, "corrupt"
    current = totp_counter()
    last_counter = int(record.get("last_counter", -1) or -1)
    for counter in (current, current - 1, current + 1):
        if consume and counter <= last_counter:
            continue
        code = totp_code_for_secret(secret, at_time=counter * 30)
        if hmac.compare_digest(code, digits):
            if consume:
                record["last_counter"] = counter
                record["last_used_ts"] = int(time.time())
                record["last_used_method"] = "totp"
                save_two_factor_store()
            return True, "totp"
    return False, "invalid"


def two_factor_public_status(user_id):
    record = two_factor_record(user_id)
    return {
        "enabled": bool(record),
        "created_ts": int((record or {}).get("created_ts", 0) or 0),
        "updated_ts": int((record or {}).get("updated_ts", 0) or 0),
        "last_used_ts": int((record or {}).get("last_used_ts", 0) or 0),
        "recovery_codes_remaining": len((record or {}).get("recovery_hashes") or []),
        "algorithm": "TOTP · SHA-1 · 6 Stellen · 30 Sekunden",
        "emergency_reset_file": "data/.two_factor.json",
    }


def rotate_user_auth_generation(user_id):
    row = user_record(user_id)
    if not row:
        return ""
    row["auth_generation"] = secrets.token_urlsafe(24)
    row["updated_ts"] = int(time.time())
    save_users_registry()
    return row["auth_generation"]


def remove_two_factor_user(user_id, rotate_generation=True):
    user_id = str(user_id or "")
    removed = False
    store = load_two_factor_store()
    with _two_factor_lock:
        removed = store.setdefault("users", {}).pop(user_id, None) is not None
        if removed:
            if store["users"]:
                save_two_factor_store(store)
                # save_two_factor_store first preserves the previous file as
                # .bak. Replace that generation with the sanitized current
                # set so the removed user's encrypted secret is truly gone.
                try:
                    atomic_write_json(
                        _TWO_FACTOR_FILE.with_name(f"{_TWO_FACTOR_FILE.name}.bak"),
                        store,
                        create_backup=False,
                        private=True,
                    )
                except OSError:
                    pass
            else:
                try:
                    _TWO_FACTOR_FILE.unlink(missing_ok=True)
                    _TWO_FACTOR_FILE.with_name(f"{_TWO_FACTOR_FILE.name}.bak").unlink(missing_ok=True)
                except OSError:
                    save_two_factor_store(store)
                load_two_factor_store(force=True)
    with _two_factor_pending_lock:
        for token, pending in list(_two_factor_pending.items()):
            if str((pending or {}).get("user_id") or "") == user_id:
                _two_factor_pending.pop(token, None)
    if removed and rotate_generation and user_record(user_id):
        rotate_user_auth_generation(user_id)
    return removed


def two_factor_otpauth_uri(user_id, secret):
    row = user_record(user_id)
    username = str(row.get("username") or user_id)
    issuer = "Universal Tag Studio"
    label = urllib.parse.quote(f"{issuer}:{username}", safe="")
    query = urllib.parse.urlencode({"secret": secret, "issuer": issuer, "algorithm": "SHA1", "digits": 6, "period": 30})
    return f"otpauth://totp/{label}?{query}"


def two_factor_qr_svg(uri):
    """Generate the QR locally; never send the TOTP secret to an external QR service."""
    try:
        import qrcode
        image = qrcode.make(uri)
        buffer = io.BytesIO()
        image.save(buffer, format="PNG")
        return buffer.getvalue(), "image/png"
    except Exception:
        try:
            from reportlab.graphics import renderSVG
            from reportlab.graphics.barcode import qr
            from reportlab.graphics.shapes import Drawing
            widget = qr.QrCodeWidget(uri)
            x1, y1, x2, y2 = widget.getBounds()
            width, height = max(1, x2 - x1), max(1, y2 - y1)
            size = 256
            drawing = Drawing(size, size, transform=[size / width, 0, 0, size / height, -x1 * size / width, -y1 * size / height])
            drawing.add(widget)
            return renderSVG.drawToString(drawing), "image/svg+xml"
        except Exception:
            return None, None


def prune_two_factor_pending():
    now = time.time()
    with _two_factor_pending_lock:
        for token, row in list(_two_factor_pending.items()):
            if not isinstance(row, dict) or float(row.get("expires_ts", 0) or 0) <= now:
                _two_factor_pending.pop(token, None)


# ---------------------------------------------------------------------------
# 18.0 PASSKEY / WEBAUTHN IDENTITY STORE
# ---------------------------------------------------------------------------
# Passkeys deliberately live beside the TOTP identity store, outside tenant
# data. Only public credential keys are stored on the server; private passkey
# material never leaves the phone, computer or hardware authenticator.
def _passkey_empty_store():
    return {"schema": 1, "users": {}, "updated_ts": 0}


def _passkey_b64_encode(value):
    return base64.urlsafe_b64encode(bytes(value)).decode("ascii").rstrip("=")


def _passkey_b64_decode(value, maximum=1024 * 1024):
    text = str(value or "").strip()
    if not text or len(text) > int(maximum * 1.5) + 16 or not re.fullmatch(r"[A-Za-z0-9_-]+", text):
        raise ValueError("Ungültige Base64URL-Daten")
    raw = base64.urlsafe_b64decode(text + "=" * (-len(text) % 4))
    if len(raw) > maximum:
        raise ValueError("Passkey-Daten überschreiten das Sicherheitslimit")
    return raw


def _normalize_passkey_store(raw):
    raw = raw if isinstance(raw, dict) else {}
    normalized_users = {}
    users = raw.get("users") if isinstance(raw.get("users"), dict) else {}
    for user_id, value in users.items():
        if not isinstance(value, dict) or not user_record(user_id):
            continue
        handle = str(value.get("user_handle") or "")
        try:
            if len(_passkey_b64_decode(handle, 128)) < 16:
                continue
        except ValueError:
            continue
        normalized_credentials = {}
        credentials = value.get("credentials") if isinstance(value.get("credentials"), dict) else {}
        for credential_id, record in credentials.items():
            if not isinstance(record, dict):
                continue
            credential_id = str(record.get("id") or credential_id)
            public_key = str(record.get("public_key_der") or "")
            try:
                raw_id = _passkey_b64_decode(credential_id, 1024)
                key_der = _passkey_b64_decode(public_key, 8192)
                if len(raw_id) < 16:
                    continue
                loaded_key = serialization.load_der_public_key(key_der)
                if not isinstance(loaded_key, (ec.EllipticCurvePublicKey, rsa.RSAPublicKey)):
                    continue
            except Exception:
                continue
            alg = int(record.get("alg", -7) or -7)
            if alg not in {-7, -257}:
                continue
            transports = [
                str(item)[:32] for item in (record.get("transports") or [])
                if str(item) in {"internal", "hybrid", "usb", "nfc", "ble", "smart-card"}
            ]
            normalized_credentials[credential_id] = {
                **record,
                "id": credential_id,
                "public_key_der": public_key,
                "alg": alg,
                "sign_count": max(0, int(record.get("sign_count", 0) or 0)),
                "label": str(record.get("label") or "Passkey")[:80],
                "transports": list(dict.fromkeys(transports)),
                "created_ts": int(record.get("created_ts", 0) or 0),
                "updated_ts": int(record.get("updated_ts", 0) or 0),
                "last_used_ts": int(record.get("last_used_ts", 0) or 0),
                "aaguid": str(record.get("aaguid") or "")[:36],
                "backed_up": bool(record.get("backed_up", False)),
            }
        normalized_users[str(user_id)] = {
            "user_handle": handle,
            "credentials": normalized_credentials,
            "updated_ts": int(value.get("updated_ts", 0) or 0),
        }
    return {"schema": 1, "users": normalized_users, "updated_ts": int(raw.get("updated_ts", 0) or 0)}


def load_passkey_store(force=False):
    """Reload on change/deletion so removing data/.passkeys.json is an emergency reset."""
    global _passkey_store_cache, _passkey_store_mtime_ns
    with _passkey_lock:
        try:
            current_mtime = _PASSKEYS_FILE.stat().st_mtime_ns
        except OSError:
            current_mtime = 0
        if not current_mtime:
            backup = _PASSKEYS_FILE.with_name(f"{_PASSKEYS_FILE.name}.bak")
            try:
                backup.unlink(missing_ok=True)
            except OSError:
                pass
            _passkey_store_cache = _passkey_empty_store()
            _passkey_store_mtime_ns = 0
            return _passkey_store_cache
        if force or _passkey_store_cache is None or current_mtime != _passkey_store_mtime_ns:
            raw = safe_load_json(_PASSKEYS_FILE, _passkey_empty_store(), accepted_types=(dict,))
            _passkey_store_cache = _normalize_passkey_store(raw)
            _passkey_store_mtime_ns = current_mtime
        return _passkey_store_cache


def save_passkey_store(store=None):
    global _passkey_store_cache, _passkey_store_mtime_ns
    with _passkey_lock:
        payload = _normalize_passkey_store(store if isinstance(store, dict) else load_passkey_store())
        payload["schema"] = 1
        payload["updated_ts"] = int(time.time())
        atomic_write_json(_PASSKEYS_FILE, payload, create_backup=True, private=True)
        _passkey_store_cache = payload
        try:
            _passkey_store_mtime_ns = _PASSKEYS_FILE.stat().st_mtime_ns
        except OSError:
            _passkey_store_mtime_ns = None
        return payload


def passkey_user_record(user_id, create=False):
    user_id = str(user_id or "")
    store = load_passkey_store()
    record = store.setdefault("users", {}).get(user_id)
    if not isinstance(record, dict) and create:
        record = {
            "user_handle": _passkey_b64_encode(secrets.token_bytes(32)),
            "credentials": {},
            "updated_ts": int(time.time()),
        }
        store["users"][user_id] = record
        save_passkey_store(store)
    return record if isinstance(record, dict) else None


def passkey_public_status(user_id):
    record = passkey_user_record(user_id) or {}
    credentials = record.get("credentials") if isinstance(record.get("credentials"), dict) else {}
    rows = []
    for credential in credentials.values():
        if not isinstance(credential, dict):
            continue
        rows.append({
            "id": str(credential.get("id") or ""),
            "label": str(credential.get("label") or "Passkey"),
            "created_ts": int(credential.get("created_ts", 0) or 0),
            "last_used_ts": int(credential.get("last_used_ts", 0) or 0),
            "transports": list(credential.get("transports") or []),
            "backed_up": bool(credential.get("backed_up", False)),
            "algorithm": "ES256" if int(credential.get("alg", -7) or -7) == -7 else "RS256",
        })
    rows.sort(key=lambda item: (item.get("last_used_ts", 0), item.get("created_ts", 0)), reverse=True)
    return {
        "enabled": bool(rows),
        "count": len(rows),
        "credentials": rows,
        "private_keys": "authenticator_only",
        "emergency_reset_file": "data/.passkeys.json",
    }


def remove_passkeys_user(user_id, rotate_generation=True):
    user_id = str(user_id or "")
    store = load_passkey_store()
    with _passkey_lock:
        removed = store.setdefault("users", {}).pop(user_id, None)
        if removed is not None:
            if store["users"]:
                save_passkey_store(store)
                try:
                    atomic_write_json(
                        _PASSKEYS_FILE.with_name(f"{_PASSKEYS_FILE.name}.bak"),
                        store,
                        create_backup=False,
                        private=True,
                    )
                except OSError:
                    pass
            else:
                try:
                    _PASSKEYS_FILE.unlink(missing_ok=True)
                    _PASSKEYS_FILE.with_name(f"{_PASSKEYS_FILE.name}.bak").unlink(missing_ok=True)
                except OSError:
                    save_passkey_store(store)
                load_passkey_store(force=True)
    with _passkey_pending_lock:
        for token, pending in list(_passkey_pending.items()):
            if str((pending or {}).get("user_id") or "") == user_id:
                _passkey_pending.pop(token, None)
    if removed is not None and rotate_generation and user_record(user_id):
        rotate_user_auth_generation(user_id)
    return len((removed or {}).get("credentials", {}) or {}) if isinstance(removed, dict) else 0


def prune_passkey_pending():
    now = time.time()
    with _passkey_pending_lock:
        for token, row in list(_passkey_pending.items()):
            if not isinstance(row, dict) or float(row.get("expires_ts", 0) or 0) <= now:
                _passkey_pending.pop(token, None)


def _passkey_origin(value):
    parsed = urllib.parse.urlsplit(str(value or "").strip())
    if parsed.scheme not in {"https", "http"} or not parsed.hostname or parsed.username or parsed.password:
        raise ValueError("Passkey-Origin ist ungültig")
    if parsed.path not in {"", "/"} or parsed.query or parsed.fragment:
        raise ValueError("Passkey-Origin darf keinen Pfad enthalten")
    host = parsed.hostname.rstrip(".").lower()
    try:
        host = host.encode("idna").decode("ascii")
    except UnicodeError as exc:
        raise ValueError("Passkey-Hostname ist ungültig") from exc
    loopback = host == "localhost"
    try:
        loopback = loopback or ipaddress.ip_address(host).is_loopback
    except ValueError:
        pass
    if parsed.scheme != "https" and not loopback:
        raise ValueError("Passkeys benötigen HTTPS (außer localhost)")
    default_port = 443 if parsed.scheme == "https" else 80
    netloc_host = f"[{host}]" if ":" in host else host
    netloc = netloc_host if parsed.port in {None, default_port} else f"{netloc_host}:{parsed.port}"
    return f"{parsed.scheme}://{netloc}", host


def passkey_request_context():
    configured = os.environ.get("ULTRA_TRACKER_PASSKEY_ORIGIN", "").strip() or PUBLIC_BASE_URL_DEFAULT
    if configured:
        origin, origin_host = _passkey_origin(configured)
    else:
        request_origin = str(request.headers.get("Origin") or "").strip()
        candidate = request_origin or request.host_url
        origin, origin_host = _passkey_origin(candidate)
        request_host = urllib.parse.urlsplit(request.host_url).hostname
        request_host = str(request_host or "").rstrip(".").lower()
        try:
            request_host = request_host.encode("idna").decode("ascii")
        except UnicodeError:
            request_host = ""
        if request_origin and (not request_host or not hmac.compare_digest(origin_host, request_host)):
            raise ValueError("Browser-Origin und Server-Hostname stimmen nicht überein")
    rp_id = str(os.environ.get("ULTRA_TRACKER_PASSKEY_RP_ID", "") or "").strip().rstrip(".").lower()
    if not rp_id:
        rp_id = origin_host
    try:
        rp_id = rp_id.encode("idna").decode("ascii")
    except UnicodeError as exc:
        raise ValueError("Passkey-RP-ID ist ungültig") from exc
    if not re.fullmatch(r"[a-z0-9.-]+|[0-9a-f:]+", rp_id):
        raise ValueError("Passkey-RP-ID ist ungültig")
    if origin_host != rp_id and not origin_host.endswith("." + rp_id):
        raise ValueError("Passkey-RP-ID gehört nicht zum Browser-Origin")
    return {"origin": origin, "rp_id": rp_id}


class _PasskeyCborDecoder:
    """Small, bounded decoder for WebAuthn attestation and COSE key objects."""

    def __init__(self, data):
        self.data = bytes(data)
        self.offset = 0
        if len(self.data) > 1024 * 1024:
            raise ValueError("CBOR-Daten überschreiten das Sicherheitslimit")

    def _read(self, count):
        count = int(count)
        if count < 0 or self.offset + count > len(self.data):
            raise ValueError("CBOR-Daten sind unvollständig")
        value = self.data[self.offset:self.offset + count]
        self.offset += count
        return value

    def _length(self, additional):
        if additional < 24:
            return additional
        widths = {24: 1, 25: 2, 26: 4, 27: 8}
        width = widths.get(additional)
        if width is None:
            raise ValueError("Unbegrenzte oder reservierte CBOR-Länge wird nicht akzeptiert")
        return int.from_bytes(self._read(width), "big")

    def decode(self, depth=0):
        if depth > 18:
            raise ValueError("CBOR-Struktur ist zu tief")
        initial = self._read(1)[0]
        major, additional = initial >> 5, initial & 31
        if major in {0, 1}:
            number = self._length(additional)
            return number if major == 0 else -1 - number
        if major in {2, 3}:
            length = self._length(additional)
            if length > 1024 * 1024:
                raise ValueError("CBOR-Feld ist zu groß")
            raw = self._read(length)
            return raw if major == 2 else raw.decode("utf-8")
        if major == 4:
            length = self._length(additional)
            if length > 4096:
                raise ValueError("CBOR-Liste ist zu groß")
            return [self.decode(depth + 1) for _ in range(length)]
        if major == 5:
            length = self._length(additional)
            if length > 4096:
                raise ValueError("CBOR-Map ist zu groß")
            result = {}
            for _ in range(length):
                key = self.decode(depth + 1)
                value = self.decode(depth + 1)
                if key in result:
                    raise ValueError("Doppelter CBOR-Schlüssel")
                result[key] = value
            return result
        if major == 6:
            self._length(additional)
            return self.decode(depth + 1)
        if major == 7:
            if additional == 20:
                return False
            if additional == 21:
                return True
            if additional in {22, 23}:
                return None
        raise ValueError("Nicht unterstützter CBOR-Datentyp")


def _passkey_decode_cbor(data, require_complete=True):
    decoder = _PasskeyCborDecoder(data)
    value = decoder.decode()
    if require_complete and decoder.offset != len(decoder.data):
        raise ValueError("CBOR-Daten enthalten unerwarteten Anhang")
    return value, decoder.offset


def _passkey_parse_authenticator_data(value, require_attested=False):
    raw = bytes(value)
    if len(raw) < 37:
        raise ValueError("Authenticator-Daten sind unvollständig")
    result = {
        "raw": raw,
        "rp_id_hash": raw[:32],
        "flags": raw[32],
        "sign_count": int.from_bytes(raw[33:37], "big"),
        "credential_id": None,
        "cose_key": None,
        "aaguid": "",
    }
    offset = 37
    if raw[32] & 0x40:
        if len(raw) < offset + 18:
            raise ValueError("Attested-Credential-Daten sind unvollständig")
        aaguid = raw[offset:offset + 16]
        offset += 16
        credential_length = int.from_bytes(raw[offset:offset + 2], "big")
        offset += 2
        if credential_length < 16 or credential_length > 1024 or len(raw) < offset + credential_length:
            raise ValueError("Passkey-ID hat eine ungültige Länge")
        result["credential_id"] = raw[offset:offset + credential_length]
        result["aaguid"] = str(uuid.UUID(bytes=aaguid))
        offset += credential_length
        result["cose_key"], consumed = _passkey_decode_cbor(raw[offset:], require_complete=False)
        offset += consumed
    elif require_attested:
        raise ValueError("Authenticator hat keinen öffentlichen Passkey geliefert")
    return result


def _passkey_public_key_from_cose(cose):
    if not isinstance(cose, dict):
        raise ValueError("COSE-Public-Key fehlt")
    alg = int(cose.get(3, 0) or 0)
    key_type = int(cose.get(1, 0) or 0)
    if alg == -7 and key_type == 2:
        if int(cose.get(-1, 0) or 0) != 1:
            raise ValueError("Nur P-256-Passkeys werden unterstützt")
        x, y = cose.get(-2), cose.get(-3)
        if not isinstance(x, bytes) or not isinstance(y, bytes) or len(x) != 32 or len(y) != 32:
            raise ValueError("EC-Passkey ist unvollständig")
        public_key = ec.EllipticCurvePublicNumbers(
            int.from_bytes(x, "big"), int.from_bytes(y, "big"), ec.SECP256R1()
        ).public_key()
    elif alg == -257 and key_type == 3:
        modulus, exponent = cose.get(-1), cose.get(-2)
        if not isinstance(modulus, bytes) or not isinstance(exponent, bytes):
            raise ValueError("RSA-Passkey ist unvollständig")
        if len(modulus) < 256 or len(modulus) > 1024 or len(exponent) > 8:
            raise ValueError("RSA-Passkey hat unsichere Parameter")
        exponent_int = int.from_bytes(exponent, "big")
        if exponent_int < 3 or exponent_int % 2 == 0:
            raise ValueError("RSA-Exponent ist ungültig")
        public_key = rsa.RSAPublicNumbers(exponent_int, int.from_bytes(modulus, "big")).public_key()
    else:
        raise ValueError("Dieser Passkey-Algorithmus wird nicht unterstützt (ES256/RS256 erforderlich)")
    der = public_key.public_bytes(serialization.Encoding.DER, serialization.PublicFormat.SubjectPublicKeyInfo)
    return alg, der


def _passkey_verify_signature(public_key_der, alg, signature, signed_data):
    key = serialization.load_der_public_key(bytes(public_key_der))
    try:
        if int(alg) == -7 and isinstance(key, ec.EllipticCurvePublicKey):
            key.verify(bytes(signature), bytes(signed_data), ec.ECDSA(hashes.SHA256()))
        elif int(alg) == -257 and isinstance(key, rsa.RSAPublicKey):
            key.verify(bytes(signature), bytes(signed_data), asymmetric_padding.PKCS1v15(), hashes.SHA256())
        else:
            raise ValueError("Passkey-Schlüssel und Algorithmus passen nicht zusammen")
    except InvalidSignature as exc:
        raise ValueError("Passkey-Signatur ist ungültig") from exc


def _passkey_validate_client_data(encoded, pending, ceremony_type):
    raw = _passkey_b64_decode(encoded, 65536)
    try:
        data = json.loads(raw.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError("Passkey-Clientdaten sind ungültig") from exc
    if not isinstance(data, dict) or data.get("type") != ceremony_type:
        raise ValueError("Passkey-Zeremonie stimmt nicht")
    try:
        received_challenge = _passkey_b64_decode(data.get("challenge"), 128)
        expected_challenge = _passkey_b64_decode(pending.get("challenge"), 128)
    except ValueError as exc:
        raise ValueError("Passkey-Challenge ist ungültig") from exc
    if not hmac.compare_digest(received_challenge, expected_challenge):
        raise ValueError("Passkey-Challenge stimmt nicht")
    if not hmac.compare_digest(str(data.get("origin") or ""), str(pending.get("origin") or "")):
        raise ValueError("Passkey-Origin stimmt nicht")
    if data.get("crossOrigin") is True:
        raise ValueError("Cross-Origin-Passkey-Anmeldung wird nicht akzeptiert")
    return raw


def _passkey_find_credential(credential_id):
    credential_id = str(credential_id or "")
    for user_id, user in load_passkey_store().get("users", {}).items():
        credentials = user.get("credentials") if isinstance(user, dict) else {}
        if not isinstance(credentials, dict):
            continue
        for stored_id, record in credentials.items():
            if hmac.compare_digest(str(stored_id), credential_id):
                return str(user_id), user, record
    return None, None, None


