def haversine_distance(lat1, lon1, lat2, lon2):
    R = 6371000
    phi1, phi2 = math.radians(lat1), math.radians(lat2)
    dphi = math.radians(lat2 - lat1)
    dlambda = math.radians(lon2 - lon1)
    a = math.sin(dphi / 2) ** 2 + math.cos(phi1) * math.cos(phi2) * math.sin(dlambda / 2) ** 2
    return 2 * R * math.atan2(math.sqrt(a), math.sqrt(1 - a))


def extract_ts(dt):
    if isinstance(dt, (int, float)):
        return dt / 1000.0 if dt > 1e11 else float(dt)
    return dt.timestamp()


def local_datetime(ts=None):
    if ts is None:
        ts = time.time()
    return datetime.fromtimestamp(float(ts), APP_TIMEZONE)


def local_day_key(ts=None):
    return local_datetime(ts).strftime("%Y-%m-%d")


def local_day_bounds(day):
    parsed = datetime.strptime(str(day), "%Y-%m-%d").replace(tzinfo=APP_TIMEZONE)
    end = parsed + timedelta(days=1)
    return parsed.timestamp(), end.timestamp()


def freshness_thresholds():
    raw = state.get("settings", {}).get("freshness_thresholds", {}) if isinstance(state.get("settings"), dict) else {}
    try:
        fresh = max(60, int(float(raw.get("fresh_seconds", DEFAULT_FRESHNESS_THRESHOLDS["fresh_seconds"]))))
        recent = max(fresh + 60, int(float(raw.get("recent_seconds", DEFAULT_FRESHNESS_THRESHOLDS["recent_seconds"]))))
        stale = max(recent + 60, int(float(raw.get("stale_seconds", DEFAULT_FRESHNESS_THRESHOLDS["stale_seconds"]))))
    except (TypeError, ValueError):
        return dict(DEFAULT_FRESHNESS_THRESHOLDS)
    return {"fresh_seconds": fresh, "recent_seconds": recent, "stale_seconds": stale}


def freshness_payload(ts):
    if not ts:
        return {"key": "unknown", "label": "Nicht geortet", "color": "#8E8E93", "age_seconds": None}
    age = max(0, int(time.time() - float(ts)))
    thresholds = freshness_thresholds()
    if age <= thresholds["fresh_seconds"]:
        key, color, label = "fresh", "#30D158", "Frisch"
    elif age <= thresholds["recent_seconds"]:
        key, color, label = "recent", "#FFD60A", "Mäßig alt"
    elif age <= thresholds["stale_seconds"]:
        key, color, label = "stale", "#FF9F0A", "Veraltet"
    else:
        key, color, label = "very_stale", "#FF453A", "Sehr alt"
    return {"key": key, "label": label, "color": color, "age_seconds": age}


def battery_code_from_status(status):
    try:
        return (int(status) >> 6) & 0b11
    except (TypeError, ValueError):
        return None


def route_point_public(point, include_report_id=False):
    """Serialize a route point without depending on a Flask request context.

    This helper deliberately lives before the 5.0 startup migration. Stored
    Google and Samsung locations are normalized while the module is loading,
    so defining it only beside the later route endpoints caused a NameError on
    installations that already had provider data.
    """
    out = {
        "lat": round(float(point.get("lat", 0)), 7),
        "lon": round(float(point.get("lon", 0)), 7),
        "acc": round(float(point.get("acc", 0) or 0), 1),
        "ts": int(float(point.get("ts", 0) or 0)),
    }
    for key in ("quality", "is_outlier", "confidence", "status", "source", "provider", "is_own_report", "alt", "semantic", "batch_id"):
        if point.get(key) is not None:
            out[key] = point.get(key)
    if point.get("status") is not None and point.get("source") != "google":
        out["bat"] = battery_code_from_status(point.get("status"))
    if include_report_id and point.get("report_id"):
        out["report_id"] = point.get("report_id")
    return out


def location_payload(loc):
    if not loc:
        return None
    battery_code = battery_code_from_status(getattr(loc, "status", None))
    payload = {
        "lat": loc.latitude,
        "lon": loc.longitude,
        "acc": loc.horizontal_accuracy,
        "bat": battery_code,
        "battery": BATTERY_LEVEL_LABELS.get(battery_code, "Unbekannt"),
        "ts": extract_ts(loc.timestamp),
        "source": "apple",
        "provider": "Apple Find My",
    }
    payload["freshness"] = freshness_payload(payload["ts"])
    confidence = getattr(loc, "confidence", None)
    if confidence is not None:
        payload["confidence"] = int(confidence)
    status = getattr(loc, "status", None)
    if status is not None:
        payload["status"] = int(status)
    return payload


def address_cache_key(lat, lon):
    return f"{round(float(lat), 4):.4f},{round(float(lon), 4):.4f}"


def address_from_cached(lat, lon):
    key = address_cache_key(lat, lon)
    item = state.get("address_cache", {}).get(key)
    if not isinstance(item, dict):
        return None
    if float(item.get("cached_ts", 0) or 0) < time.time() - ADDRESS_CACHE_TTL_SECONDS:
        return None
    # Address cache v2 also stores the named OSM place/POI (for example a
    # school, station or shop). Older cache rows are refreshed lazily so guest
    # links gain the richer place card without flushing the whole cache.
    if int(item.get("schema_version", 0) or 0) < 3:
        return None
    return item


def compact_address(raw, query_lat=None, query_lon=None):
    raw = raw if isinstance(raw, dict) else {}
    address = raw.get("address") if isinstance(raw.get("address"), dict) else {}
    namedetails = raw.get("namedetails") if isinstance(raw.get("namedetails"), dict) else {}
    category = str(raw.get("category") or raw.get("class") or "").strip().lower()
    place_type = str(raw.get("type") or raw.get("addresstype") or "").strip().lower()

    road = address.get("road") or address.get("pedestrian") or address.get("footway") or address.get("path") or address.get("square")
    house = address.get("house_number") or address.get("house_name")
    postcode = address.get("postcode")
    locality = address.get("city") or address.get("town") or address.get("village") or address.get("municipality") or address.get("hamlet")
    district = address.get("city_district") or address.get("borough") or address.get("suburb") or address.get("quarter") or address.get("neighbourhood")
    county = address.get("county") or address.get("state_district")
    state_name = address.get("state") or address.get("region")

    # Nominatim returns the closest named OSM object as `name`; for many POIs
    # the same value is also present under the category key in addressdetails.
    category_name = address.get(category) if category else None
    poi_candidates = [
        raw.get("name"), namedetails.get("name:de"), namedetails.get("name"), category_name,
        address.get("amenity"), address.get("shop"), address.get("office"), address.get("tourism"),
        address.get("leisure"), address.get("railway"), address.get("aeroway"), address.get("historic"),
        address.get("club"), address.get("craft"), address.get("emergency"), address.get("healthcare"),
    ]
    poi_name = next((str(value).strip() for value in poi_candidates if value and str(value).strip()), "")
    # Do not repeat a road/street as if it were an institution.
    if poi_name and road and poi_name.casefold() == str(road).strip().casefold():
        poi_name = ""
    poi_distance_m = None
    try:
        if query_lat is not None and query_lon is not None and raw.get("lat") is not None and raw.get("lon") is not None:
            poi_distance_m = round(haversine_distance(float(query_lat), float(query_lon), float(raw.get("lat")), float(raw.get("lon"))), 1)
    except (TypeError, ValueError):
        poi_distance_m = None
    # Nominatim may return a named neighbouring object. A POI farther away
    # than the configured tolerance must never be presented as the exact place.
    if poi_name and poi_distance_m is not None and poi_distance_m > GEOCODER_POI_MAX_DISTANCE_METERS:
        poi_name = ""

    type_labels = {
        "school": "Schule", "kindergarten": "Kindergarten", "college": "Hochschule", "university": "Universität",
        "hospital": "Krankenhaus", "clinic": "Klinik", "doctors": "Arztpraxis", "pharmacy": "Apotheke",
        "station": "Bahnhof", "halt": "Haltestelle", "tram_stop": "Haltestelle", "bus_station": "Busbahnhof",
        "supermarket": "Supermarkt", "convenience": "Geschäft", "mall": "Einkaufszentrum", "department_store": "Kaufhaus",
        "restaurant": "Restaurant", "cafe": "Café", "fast_food": "Gastronomie", "pub": "Gastronomie", "bar": "Bar",
        "hotel": "Hotel", "hostel": "Unterkunft", "museum": "Museum", "library": "Bibliothek", "theatre": "Theater",
        "cinema": "Kino", "park": "Park", "playground": "Spielplatz", "sports_centre": "Sportzentrum",
        "police": "Polizei", "fire_station": "Feuerwehr", "townhall": "Rathaus", "post_office": "Postfiliale",
        "place_of_worship": "Einrichtung", "parking": "Parkplatz", "fuel": "Tankstelle", "charging_station": "Ladestation",
        "house": "Adresse", "building": "Gebäude", "residential": "Wohngebiet",
    }
    poi_type_label = type_labels.get(place_type, "")
    if not poi_type_label:
        poi_type_label = {
            "amenity": "Einrichtung", "shop": "Geschäft", "office": "Büro", "tourism": "Ort",
            "leisure": "Freizeit", "railway": "Bahn", "aeroway": "Flughafen", "historic": "Sehenswürdigkeit",
            "healthcare": "Gesundheit", "building": "Gebäude",
        }.get(category, "Ort" if poi_name else "Adresse")

    street = " ".join(str(v).strip() for v in [road, house] if v and str(v).strip())
    city = " ".join(str(v).strip() for v in [postcode, locality] if v and str(v).strip())
    region = ", ".join(dict.fromkeys(str(v).strip() for v in [district, county, state_name] if v and str(v).strip()))
    address_line = ", ".join(v for v in [street, city] if v)
    label = poi_name or address_line or str(raw.get("display_name") or "Unbekannter Ort").split(",")[0].strip()
    subtitle_parts = []
    if poi_name and address_line:
        subtitle_parts.append(address_line)
    elif not poi_name and street and city:
        subtitle_parts.append(city)
    if region and region not in subtitle_parts:
        subtitle_parts.append(region)
    country = str(address.get("country") or "").strip()
    if country and country not in subtitle_parts:
        subtitle_parts.append(country)

    return {
        "schema_version": 3,
        "label": str(label)[:180],
        "display_name": str(raw.get("display_name") or address_line or label)[:500],
        "poi_name": poi_name[:180],
        "poi_category": category[:80],
        "poi_type": place_type[:100],
        "poi_type_label": str(poi_type_label)[:80],
        "road": str(road or "")[:160],
        "house_number": str(house or "")[:80],
        "street_line": street[:220],
        "postcode": str(postcode or "")[:30],
        "locality": str(locality or "")[:160],
        "district": str(district or "")[:160],
        "county": str(county or "")[:160],
        "state": str(state_name or "")[:160],
        "city_line": city[:220],
        "region_line": region[:260],
        "subtitle": " · ".join(subtitle_parts)[:420],
        "country": country[:120],
        "country_code": str(address.get("country_code") or "").upper()[:4],
        "cached_ts": int(time.time()),
        "source_lat": round(float(raw.get("lat")), 7) if raw.get("lat") is not None else None,
        "source_lon": round(float(raw.get("lon")), 7) if raw.get("lon") is not None else None,
        "poi_distance_m": poi_distance_m,
        "quality": "poi_exact" if poi_name else ("address" if street else "area"),
        "provider": "OpenStreetMap Nominatim",
    }


def reverse_geocode(lat, lon):
    global geocoder_last_call
    cached = address_from_cached(lat, lon)
    if cached:
        return cached, True, 0
    if not GEOCODING_ENABLED or not GEOCODER_URL:
        return None, False, 0
    with geocoder_lock:
        cached = address_from_cached(lat, lon)
        if cached:
            return cached, True, 0
        remaining = GEOCODER_MIN_INTERVAL_SECONDS - (time.monotonic() - geocoder_last_call)
        if remaining > 0:
            return None, False, max(1, int(math.ceil(remaining)))
        query = urllib.parse.urlencode({
            "format": "jsonv2",
            "lat": f"{float(lat):.7f}",
            "lon": f"{float(lon):.7f}",
            "zoom": "18",
            "addressdetails": "1",
            "namedetails": "1",
            "layer": "address,poi",
            "accept-language": "de",
        })
        req = urllib.request.Request(
            f"{GEOCODER_URL}?{query}",
            headers={"User-Agent": GEOCODER_USER_AGENT, "Accept": "application/json"},
        )
        geocoder_last_call = time.monotonic()
        try:
            with urllib.request.urlopen(req, timeout=7) as response:
                raw = json.loads(response.read(1024 * 1024).decode("utf-8"))
            item = compact_address(raw, lat, lon)
            key = address_cache_key(lat, lon)
            state["address_cache"][key] = item
            if len(state["address_cache"]) > 5000:
                oldest = sorted(state["address_cache"].items(), key=lambda pair: pair[1].get("cached_ts", 0))[:500]
                for old_key, _ in oldest:
                    state["address_cache"].pop(old_key, None)
            save_json(ADDRESS_CACHE_FILE, "address_cache")
            return item, False, 0
        except (urllib.error.URLError, urllib.error.HTTPError, TimeoutError, ValueError, json.JSONDecodeError) as exc:
            logger.warning("Adresssuche fehlgeschlagen: %s", exc)
            return None, False, 0


def geocoder_search_places(query, limit=5, country_codes=None):
    """Search the configured Nominatim-compatible service for fence centers."""
    global geocoder_last_call
    query = str(query or "").strip()
    if len(query) < 3:
        raise ValueError("Die Ortssuche benötigt mindestens drei Zeichen.")
    if not GEOCODING_ENABLED or not GEOCODER_SEARCH_URL:
        raise RuntimeError("Die Adresssuche ist auf diesem Server deaktiviert.")
    limit = int_range(limit, 5, 1, 8)
    codes = []
    for value in country_codes or []:
        code = str(value or "").strip().lower()
        if re.fullmatch(r"[a-z]{2}", code) and code not in codes:
            codes.append(code)
    params = {
        "format": "jsonv2",
        "q": query[:300],
        "limit": str(limit),
        "addressdetails": "1",
        "namedetails": "1",
        "accept-language": "de",
    }
    if codes:
        params["countrycodes"] = ",".join(codes[:8])
    with geocoder_lock:
        remaining = GEOCODER_MIN_INTERVAL_SECONDS - (time.monotonic() - geocoder_last_call)
        if remaining > 0:
            time.sleep(min(float(remaining), GEOCODER_MIN_INTERVAL_SECONDS))
        request_url = f"{GEOCODER_SEARCH_URL}?{urllib.parse.urlencode(params)}"
        request_object = urllib.request.Request(
            request_url,
            headers={"User-Agent": GEOCODER_USER_AGENT, "Accept": "application/json"},
        )
        geocoder_last_call = time.monotonic()
        try:
            with urllib.request.urlopen(request_object, timeout=8) as response:
                raw_rows = json.loads(response.read(2 * 1024 * 1024).decode("utf-8"))
        except (urllib.error.URLError, urllib.error.HTTPError, TimeoutError, ValueError, json.JSONDecodeError) as exc:
            logger.warning("Ortssuche fehlgeschlagen: %s", exc)
            raise RuntimeError("Die Ortssuche ist momentan nicht erreichbar.") from exc
    if not isinstance(raw_rows, list):
        raise RuntimeError("Die Ortssuche hat ein ungültiges Ergebnis geliefert.")
    results = []
    cache_changed = False
    for raw in raw_rows[:limit]:
        if not isinstance(raw, dict):
            continue
        try:
            lat, lon = float(raw.get("lat")), float(raw.get("lon"))
        except (TypeError, ValueError):
            continue
        if not -90 <= lat <= 90 or not -180 <= lon <= 180:
            continue
        address = compact_address(raw, lat, lon)
        state.setdefault("address_cache", {})[address_cache_key(lat, lon)] = address
        cache_changed = True
        results.append({
            "latitude": round(lat, 7),
            "longitude": round(lon, 7),
            "display_name": str(raw.get("display_name") or address.get("display_name") or address.get("label") or "Ort")[:500],
            "type": str(raw.get("type") or raw.get("addresstype") or "")[:100],
            "importance": round(float(raw.get("importance", 0) or 0), 6),
            "address": address,
        })
    if cache_changed:
        if len(state["address_cache"]) > 5000:
            oldest = sorted(state["address_cache"].items(), key=lambda pair: pair[1].get("cached_ts", 0))[:500]
            for old_key, _ in oldest:
                state["address_cache"].pop(old_key, None)
        save_json(ADDRESS_CACHE_FILE, "address_cache")
    return results


def update_location_cache(name, loc):
    ts = extract_ts(loc.timestamp)
    prev = state["locations"].get(name)
    if prev and extract_ts(prev.timestamp) > ts:
        return extract_ts(prev.timestamp)
    since = ts
    if prev:
        dist = haversine_distance(prev.latitude, prev.longitude, loc.latitude, loc.longitude)
        if dist < 50:
            since = state["since_ts"].get(name, ts)
    state["since_ts"][name] = since
    state["locations"][name] = loc
    return ts


def report_to_point(report):
    try:
        point = {
            "lat": float(report.latitude),
            "lon": float(report.longitude),
            "acc": float(getattr(report, "horizontal_accuracy", 0) or 0),
            "ts": float(extract_ts(report.timestamp)),
            "source": "apple",
            "provider": "Apple Find My",
        }
        confidence = getattr(report, "confidence", None)
        status = getattr(report, "status", None)
        if confidence is not None:
            point["confidence"] = int(confidence)
        if status is not None:
            point["status"] = int(status)
        payload = getattr(report, "payload", None)
        if payload is not None:
            payload_bytes = payload if isinstance(payload, bytes) else str(payload).encode("utf-8")
            point["report_id"] = hashlib.sha256(payload_bytes).hexdigest()[:24]
        else:
            point["report_id"] = point_identity(point)
        return normalize_point(point)
    except Exception as exc:
        logger.debug("Report konnte nicht als Punkt gelesen werden: %s", exc)
        return None


def merge_unique_report_points(existing_points, report_points, retention_seconds, max_points):
    existing = prune_points(existing_points, retention_seconds, max_points)
    existing_ids = {point_identity(p) for p in existing}
    added = 0
    received_at = time.time()
    cutoff = received_at - float(retention_seconds) if retention_seconds is not None else None
    for raw in report_points:
        point = normalize_point(raw) if isinstance(raw, dict) else None
        if not point or (cutoff is not None and point["ts"] < cutoff):
            continue
        pid = point_identity(point)
        if pid not in existing_ids:
            existing.append({**point, "received_at": received_at})
            existing_ids.add(pid)
            added += 1
    existing.sort(key=lambda point: point["ts"])
    if max_points is not None and int(max_points) > 0:
        existing = existing[-int(max_points):]
    return existing, added


def add_persistent_history_points(name, report_points, persist=True):
    capture_policy = history_capture_policy("apple", name)
    if not capture_policy.get("capture_enabled") and not fusion_profile_optimization_enabled(name):
        return 0
    with state_lock:
        store = state["seven_day_history"].setdefault(name, {"points": []})
        storage_policy = history_storage_policy("apple", name)
        store["points"], added = merge_unique_report_points(
            store.get("points", []), report_points, storage_policy.get("retention_seconds"), history_policy_max_points("apple", storage_policy)
        )
        if persist and added:
            save_json(SEVEN_HISTORY_FILE, "seven_day_history")
    return added


def add_recording_points(name, report_points, now_ts):
    if name not in state["recordings"]:
        return 0
    session_id = state["recordings"][name]
    session_file = SESSIONS_DIR / f"{name}_{session_id}.json"
    session_data = {"id": session_id, "start": session_id, "end": now_ts, "points": []}
    if session_file.exists():
        try:
            with open(session_file, "r", encoding="utf-8") as file:
                session_data = json.load(file)
        except Exception:
            pass
    session_data["points"], added = merge_unique_report_points(session_data.get("points", []), report_points, 365 * 24 * 60 * 60, SESSION_HISTORY_LIMIT)
    session_data["end"] = now_ts
    atomic_write_json(session_file, session_data)
    return added


def add_shared_history_points(name, report_points):
    has_link = any(share_link_status(link) == "active" and link.get("device") == name for link in state["shared_links"].values() if isinstance(link, dict))
    if not has_link or not share_capture_required(name):
        return 0
    store = state["shared_history"].setdefault(name, {"points": []})
    share_policy = history_share_policy(name) or normalize_history_retention("days", 7)
    store["points"], added = merge_unique_report_points(store.get("points", []), report_points, share_policy.get("retention_seconds"), SHARED_HISTORY_LIMIT)
    save_json(SHARED_HIST_FILE, "shared_history")
    return added


def bool_from_any(value, default=False):
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    return str(value).strip().lower() in {"1", "true", "yes", "on", "enabled", "ja"}


def int_range(value, default, minimum, maximum):
    try:
        return max(minimum, min(maximum, int(float(value))))
    except (TypeError, ValueError):
        return default


def float_range(value, default, minimum, maximum):
    try:
        return max(minimum, min(maximum, float(value)))
    except (TypeError, ValueError):
        return default


def normalize_device_scope(value):
    if value is None or value == "":
        return []
    if isinstance(value, str):
        items = [v.strip() for v in value.replace(";", ",").split(",")]
    elif isinstance(value, (list, tuple, set)):
        items = [str(v).strip() for v in value]
    else:
        items = []
    return [canonical_device_name(v) for v in items if v][:80]


def normalize_tracker_ref(value):
    value = str(value or "").strip()
    if ":" not in value:
        # Legacy geofences only stored Apple accessory names.
        value = f"apple:{value}"
    provider, tracker_id = value.split(":", 1)
    provider = provider.strip().lower()
    tracker_id = tracker_id.strip()
    if provider not in {"apple", "google", "samsung", "fusion"} or not tracker_id:
        return ""
    return f"{provider}:{tracker_id[:500]}"


def normalize_tracker_refs(value):
    if value is None or value == "":
        return []
    raw_items = [value] if isinstance(value, str) else list(value) if isinstance(value, (list, tuple, set)) else []
    result = []
    for raw in raw_items:
        ref = normalize_tracker_ref(raw)
        if ref and ref not in result:
            result.append(ref)
    return result[:250]


def geofence_public(g):
    lat = float_range(g.get("lat"), 0, -90, 90)
    lon = float_range(g.get("lon"), 0, -180, 180)
    radius = float_range(g.get("radius", 120), 120, 25, 5000)
    legacy_refs = [f"apple:{value}" for value in normalize_device_scope(g.get("device_ids"))]
    tracker_refs = normalize_tracker_refs(g.get("tracker_refs") or legacy_refs)
    channels = [
        channel for channel in (g.get("channels") or [])
        if channel in {"webpush", "email", "ntfy", "pushover", "gotify", "telegram", "webhook"}
    ]
    return {
        "id": str(g.get("id", "")),
        "label": str(g.get("label", "Ort")).strip()[:80] or "Ort",
        "emoji": str(g.get("emoji", "📍")).strip()[:8] or "📍",
        "type": str(g.get("type", "circle")).strip().lower()[:20] or "circle",
        "lat": lat,
        "lon": lon,
        "radius": radius,
        "hysteresis_m": float_range(g.get("hysteresis_m", max(35, radius * 0.28)), max(35, radius * 0.28), 10, 1000),
        "min_confirmations": int_range(g.get("min_confirmations", 2), 2, 1, 8),
        "max_accuracy_m": float_range(g.get("max_accuracy_m", max(250, radius * 2)), max(250, radius * 2), 25, 10000),
        "tracker_refs": tracker_refs,
        "device_ids": [ref.split(":", 1)[1] for ref in tracker_refs if ref.startswith("apple:")],
        "notify_enter": bool_from_any(g.get("notify_enter"), True),
        "notify_exit": bool_from_any(g.get("notify_exit"), True),
        "notify_initial": bool_from_any(g.get("notify_initial"), False),
        "channels": channels,
        "color": str(g.get("color", "#34C759")).strip()[:24] or "#34C759",
        "enabled": bool_from_any(g.get("enabled"), True),
        "created_ts": float_range(g.get("created_ts", time.time()), time.time(), 0, time.time() + 365 * 24 * 60 * 60),
        "updated_ts": float_range(g.get("updated_ts", g.get("created_ts", time.time())), time.time(), 0, time.time() + 365 * 24 * 60 * 60),
    }


ALERT_CHANNELS = ("webpush", "email", "ntfy", "pushover", "gotify", "telegram", "webhook")


def tracker_ref_parts(tracker_ref):
    normalized = normalize_tracker_ref(tracker_ref)
    return normalized.split(":", 1) if normalized else ("", "")


def tracker_ref_for(provider, tracker_id):
    return normalize_tracker_ref(f"{provider}:{tracker_id}")


def all_tracker_refs():
    refs = [f"apple:{name}" for name in state.get("accessories", {})]
    refs.extend(f"google:{device_id}" for device_id in state.get("google_devices", {}))
    refs.extend(f"samsung:{device_id}" for device_id in state.get("samsung_devices", {}))
    return refs


def fusion_related_tracker_refs(provider, tracker_id):
    """Return every provider reference that represents the same fused object."""
    tracker_ref = tracker_ref_for(provider, tracker_id)
    for apple_name, profile in state.get("fusion_profiles", {}).items():
        if not isinstance(profile, dict):
            continue
        refs = [f"apple:{apple_name}", f"fusion:{apple_name}"]
        if profile.get("google_id"):
            refs.append(f"google:{profile['google_id']}")
        if profile.get("samsung_id"):
            refs.append(f"samsung:{profile['samsung_id']}")
        refs = [normalize_tracker_ref(ref) for ref in refs]
        refs = [ref for ref in refs if ref]
        if tracker_ref in refs:
            return refs
    return [tracker_ref] if tracker_ref else []


def tracker_current_location(tracker_ref):
    provider, tracker_id = tracker_ref_parts(tracker_ref)
    if provider == "apple":
        raw = state.get("locations", {}).get(tracker_id)
        if raw:
            try:
                return location_payload(raw)
            except Exception:
                return normalize_point(raw) if isinstance(raw, dict) else None
    if provider == "google":
        raw = state.get("google_locations", {}).get(tracker_id)
        point = normalize_point(raw) if isinstance(raw, dict) else None
        if point:
            point["source"] = "google"
            point["provider"] = "Google Find Hub"
        return point
    if provider == "samsung":
        raw = state.get("samsung_locations", {}).get(tracker_id)
        point = normalize_point(raw) if isinstance(raw, dict) else None
        if point:
            point["source"] = "samsung"
            point["provider"] = "Samsung SmartThings Find"
        return point
    if provider == "fusion":
        candidates = []
        apple_raw = state.get("locations", {}).get(tracker_id)
        if apple_raw:
            try:
                candidates.append(location_payload(apple_raw))
            except Exception:
                pass
        profile = state.get("fusion_profiles", {}).get(tracker_id, {})
        if isinstance(profile, dict) and profile.get("google_id"):
            point = normalize_point(state.get("google_locations", {}).get(str(profile["google_id"]), {}))
            if point:
                point.update({"source": "google", "provider": "Google Find Hub"})
                candidates.append(point)
        if isinstance(profile, dict) and profile.get("samsung_id"):
            point = normalize_point(state.get("samsung_locations", {}).get(str(profile["samsung_id"]), {}))
            if point:
                point.update({"source": "samsung", "provider": "Samsung SmartThings Find"})
                candidates.append(point)
        return max(candidates, key=lambda item: float(item.get("ts", 0) or 0)) if candidates else None
    return None


def tracker_display_label(tracker_ref):
    provider, tracker_id = tracker_ref_parts(tracker_ref)
    if provider in {"apple", "google", "samsung", "fusion"} and "tracker_details_public" in globals():
        return tracker_details_public(provider, tracker_id).get("name") or tracker_id
    if provider == "apple":
        return state.get("tracker_meta", {}).get(tracker_id, {}).get("name", tracker_id)
    if provider == "google":
        return str(state.get("google_devices", {}).get(tracker_id, {}).get("name") or "Google Tag")
    if provider == "samsung":
        return str(state.get("samsung_devices", {}).get(tracker_id, {}).get("name") or "Galaxy SmartTag")
    return tracker_id or "Tracker"


def geofence_rebuild_runtime(gid, fence=None):
    """Reset one fence and establish a no-spam baseline from known locations."""
    gid = str(gid or "")
    if not gid:
        return 0
    initialized = 0
    scoped_refs = normalize_tracker_refs((fence or {}).get("tracker_refs")) if isinstance(fence, dict) else []
    runtime_store = state.setdefault("notification_runtime", {})
    for tracker_ref in all_tracker_refs():
        runtime = runtime_store.setdefault(tracker_ref, {"geofences": {}})
        runtime.setdefault("geofences", {}).pop(gid, None)
        if not isinstance(fence, dict) or fence.get("notify_initial", False):
            continue
        provider, tracker_id = tracker_ref_parts(tracker_ref)
        related_refs = fusion_related_tracker_refs(provider, tracker_id)
        fusion_scope = any(ref.startswith("fusion:") and ref in scoped_refs for ref in related_refs)
        if scoped_refs and tracker_ref not in scoped_refs and not fusion_scope:
            continue
        location = tracker_current_location(tracker_ref)
        point = normalize_point(location) if isinstance(location, dict) else None
        if not point or float(point.get("acc", 0) or 0) > float(fence.get("max_accuracy_m", 500) or 500):
            continue
        distance = haversine_distance(fence["lat"], fence["lon"], point["lat"], point["lon"])
        runtime["geofences"][gid] = {
            "stable": "inside" if distance <= float(fence.get("radius", 120) or 120) else "outside",
            "pending": None,
            "pending_count": 0,
            "changed_ts": int(time.time()),
            "baseline_report_id": point.get("report_id"),
            "baseline_report_ts": int(float(point.get("ts", 0) or 0)),
        }
        initialized += 1
    return initialized


def create_geofence_record(data):
    """Create a persisted geofence for both the web UI and MCP tools."""
    data = data if isinstance(data, dict) else {}
    if data.get("lat") is None or data.get("lon") is None:
        raise ValueError("Mittelpunkt des Geofences fehlt.")
    try:
        lat, lon = float(data.get("lat")), float(data.get("lon"))
    except (TypeError, ValueError) as exc:
        raise ValueError("Ungültige Koordinaten.") from exc
    if not -90 <= lat <= 90 or not -180 <= lon <= 180:
        raise ValueError("Koordinaten liegen außerhalb des gültigen Bereichs.")
    now_ts = int(time.time())
    gid = "gf_" + secrets.token_urlsafe(9).replace("-", "").replace("_", "")
    fence = geofence_public({
        **data,
        "id": gid,
        "lat": lat,
        "lon": lon,
        "created_ts": now_ts,
        "updated_ts": now_ts,
        "color": data.get("color") or "#34C759",
    })
    with notification_lock:
        state.setdefault("geofences", {})[gid] = fence
        baseline_count = geofence_rebuild_runtime(gid, fence)
        save_json(GEOFENCES_FILE, "geofences")
        save_json(NOTIFICATION_RUNTIME_FILE, "notification_runtime")
    append_notification_event({
        "type": "geofence_created",
        "severity": "info",
        "title": f"Geofence {fence['label']} erstellt",
        "body": f"Radius {round(fence['radius'])} m · {fence['min_confirmations']} Bestätigung(en).",
        "geofence_id": gid,
        "geofence_name": fence["label"],
        "event_key": f"geofence-created:{gid}",
    }, dispatch=False)
    if fence.get("enabled", True):
        wake_polling_for_refs(fence.get("tracker_refs"))
    return fence, baseline_count


def update_geofence_record(gid, data):
    """Patch a geofence without replacing its stable id or creation time."""
    gid = str(gid or "")
    data = data if isinstance(data, dict) else {}
    with notification_lock:
        existing = state.get("geofences", {}).get(gid)
        if not isinstance(existing, dict):
            raise KeyError("Geofence wurde nicht gefunden.")
        merged = {**existing, **data, "id": gid, "created_ts": existing.get("created_ts", time.time()), "updated_ts": int(time.time())}
        if merged.get("lat") is None or merged.get("lon") is None:
            raise ValueError("Mittelpunkt des Geofences fehlt.")
        try:
            lat, lon = float(merged.get("lat")), float(merged.get("lon"))
        except (TypeError, ValueError) as exc:
            raise ValueError("Ungültige Koordinaten.") from exc
        if not -90 <= lat <= 90 or not -180 <= lon <= 180:
            raise ValueError("Koordinaten liegen außerhalb des gültigen Bereichs.")
        merged.update({"lat": lat, "lon": lon})
        fence = geofence_public(merged)
        geometry_keys = ("lat", "lon", "radius", "hysteresis_m", "tracker_refs", "min_confirmations", "max_accuracy_m", "notify_initial")
        geometry_changed = any(fence.get(key) != existing.get(key) for key in geometry_keys)
        state["geofences"][gid] = fence
        baseline_count = geofence_rebuild_runtime(gid, fence) if geometry_changed else 0
        save_json(GEOFENCES_FILE, "geofences")
        if geometry_changed:
            save_json(NOTIFICATION_RUNTIME_FILE, "notification_runtime")
    if fence.get("enabled", True):
        wake_polling_for_refs(fence.get("tracker_refs"))
    return fence, geometry_changed, baseline_count


def delete_geofence_record(gid):
    gid = str(gid or "")
    with notification_lock:
        fence = state.get("geofences", {}).pop(gid, None)
        if not isinstance(fence, dict):
            raise KeyError("Geofence wurde nicht gefunden.")
        geofence_rebuild_runtime(gid, None)
        save_json(GEOFENCES_FILE, "geofences")
        save_json(NOTIFICATION_RUNTIME_FILE, "notification_runtime")
    return fence


