def recovery_default_mode(kind="lost"):
    kind = "stolen" if str(kind).lower() == "stolen" else "lost"
    return {
        "active": False,
        "kind": kind,
        "activated_ts": 0,
        "found_ts": 0,
        "found_note": "",
        "note": "",
        "update_frequency": "balanced",
        "stable_radius_m": 75,
        "stable_min_seconds": 10 * 60,
        "stable_confirmations": 3,
        "movement_threshold_m": 140,
        "significant_move_m": 500,
        "stationary_update_seconds": 2 * 60 * 60,
        "movement_update_seconds": 25 * 60,
        "stale_after_seconds": 2 * 60 * 60,
        "stale_repeat_seconds": 6 * 60 * 60,
        "runtime": {},
    }


def recovery_apply_frequency(mode, frequency):
    frequency = str(frequency or "balanced").lower()
    if frequency not in {"high", "balanced", "low"}:
        raise ValueError("update_frequency muss high, balanced oder low sein.")
    presets = {
        "high": {"stationary_update_seconds": 15 * 60, "movement_update_seconds": 5 * 60, "stale_repeat_seconds": 60 * 60},
        "balanced": {"stationary_update_seconds": 2 * 60 * 60, "movement_update_seconds": 25 * 60, "stale_repeat_seconds": 6 * 60 * 60},
        "low": {"stationary_update_seconds": 6 * 60 * 60, "movement_update_seconds": 90 * 60, "stale_repeat_seconds": 12 * 60 * 60},
    }
    mode.update(presets[frequency])
    mode["update_frequency"] = frequency
    return mode


def normalize_recovery_mode(raw):
    raw = raw if isinstance(raw, dict) else {}
    mode = recovery_default_mode(raw.get("kind", "lost"))
    for key in ["active", "kind", "activated_ts", "found_ts", "found_note", "note", "runtime", "update_frequency"]:
        if key in raw:
            mode[key] = raw[key]
    mode["active"] = bool(mode.get("active"))
    mode["kind"] = "stolen" if str(mode.get("kind")).lower() == "stolen" else "lost"
    mode["update_frequency"] = str(mode.get("update_frequency") or "balanced").lower()
    if mode["update_frequency"] not in {"high", "balanced", "low"}:
        mode["update_frequency"] = "balanced"
    for key, minimum, maximum in [
        ("stable_radius_m", 25, 500),
        ("stable_min_seconds", 120, 6 * 60 * 60),
        ("stable_confirmations", 2, 10),
        ("movement_threshold_m", 50, 5000),
        ("significant_move_m", 100, 10000),
        ("stationary_update_seconds", 15 * 60, 24 * 60 * 60),
        ("movement_update_seconds", 5 * 60, 6 * 60 * 60),
        ("stale_after_seconds", 30 * 60, 24 * 60 * 60),
        ("stale_repeat_seconds", 60 * 60, 48 * 60 * 60),
    ]:
        try:
            mode[key] = max(minimum, min(maximum, int(raw.get(key, mode[key]) or mode[key])))
        except (TypeError, ValueError):
            pass
    if not isinstance(mode.get("runtime"), dict):
        mode["runtime"] = {}
    mode["note"] = str(mode.get("note") or "")[:500]
    mode["found_note"] = str(mode.get("found_note") or "")[:500]
    return mode


def recovery_mode_active(name):
    return bool(normalize_recovery_mode(state.get("recovery_modes", {}).get(name, {})).get("active"))


def recovery_store(name):
    store = state.setdefault("recovery_history", {}).setdefault(name, {"points": [], "events": [], "addresses": {}})
    if not isinstance(store, dict):
        store = {"points": [], "events": [], "addresses": {}}
        state["recovery_history"][name] = store
    if not isinstance(store.get("points"), list):
        store["points"] = []
    if not isinstance(store.get("events"), list):
        store["events"] = []
    if not isinstance(store.get("addresses"), dict):
        store["addresses"] = {}
    return store


def save_recovery_state(history=True, shares=False, access=False):
    atomic_write_json(RECOVERY_MODES_FILE, state.get("recovery_modes", {}))
    if history:
        atomic_write_json(RECOVERY_HISTORY_FILE, state.get("recovery_history", {}))
    if shares:
        atomic_write_json(RECOVERY_SHARES_FILE, state.get("recovery_shares", {}), private=True)
    if access:
        atomic_write_json(RECOVERY_ACCESS_LOG_FILE, state.get("recovery_access_log", []), private=True)


def recovery_kind_label(kind):
    return "Gestohlen" if str(kind).lower() == "stolen" else "Verloren"


def recovery_phase_label(phase):
    return {
        "stationary": "Bleibt wahrscheinlich an einem Ort",
        "moving": "Bewegung erkannt",
        "signal_lost": "Seit längerer Zeit kein neuer Standort",
        "found": "Als gefunden markiert",
        "active": "Recovery Guard aktiv",
    }.get(str(phase or "active"), "Recovery Guard aktiv")


def recovery_point_key(point):
    return f"{round(float(point.get('lat', 0)), 5)}:{round(float(point.get('lon', 0)), 5)}"


def recovery_address_for_point(point, store=None):
    point = normalize_point(point) if isinstance(point, dict) else None
    if not point:
        return None
    store = store or {}
    addresses = store.get("addresses", {}) if isinstance(store, dict) else {}
    cached = addresses.get(recovery_point_key(point)) if isinstance(addresses, dict) else None
    if cached:
        return cached
    return address_from_cached(point["lat"], point["lon"])


def recovery_bearing(lat1, lon1, lat2, lon2):
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dl = math.radians(lon2 - lon1)
    y = math.sin(dl) * math.cos(p2)
    x = math.cos(p1) * math.sin(p2) - math.sin(p1) * math.cos(p2) * math.cos(dl)
    return (math.degrees(math.atan2(y, x)) + 360.0) % 360.0


def recovery_destination(lat, lon, bearing_deg, distance_m):
    radius = 6371000.0
    brng = math.radians(bearing_deg)
    p1 = math.radians(lat)
    l1 = math.radians(lon)
    dr = float(distance_m) / radius
    p2 = math.asin(math.sin(p1) * math.cos(dr) + math.cos(p1) * math.sin(dr) * math.cos(brng))
    l2 = l1 + math.atan2(math.sin(brng) * math.sin(dr) * math.cos(p1), math.cos(dr) - math.sin(p1) * math.sin(p2))
    return math.degrees(p2), ((math.degrees(l2) + 540.0) % 360.0) - 180.0


def recovery_motion_prediction(points):
    pts = [normalize_point(p) for p in (points or [])]
    pts = [p for p in pts if p]
    if len(pts) < 3:
        return None
    pts.sort(key=lambda p: p["ts"])
    latest = pts[-1]
    if time.time() - latest["ts"] > 45 * 60:
        return None
    recent = [p for p in pts[-12:] if latest["ts"] - p["ts"] <= 45 * 60]
    if len(recent) < 3:
        return None
    first = recent[0]
    duration = latest["ts"] - first["ts"]
    if duration < 4 * 60:
        return None
    distance = haversine_distance(first["lat"], first["lon"], latest["lat"], latest["lon"])
    speed_mps = distance / max(1.0, duration)
    if distance < 120 or speed_mps < 0.35 or speed_mps > 55:
        return None
    bearings = []
    speeds = []
    for a, b in zip(recent, recent[1:]):
        dt = b["ts"] - a["ts"]
        if dt <= 20:
            continue
        segment = haversine_distance(a["lat"], a["lon"], b["lat"], b["lon"])
        if segment < 25:
            continue
        bearings.append(recovery_bearing(a["lat"], a["lon"], b["lat"], b["lon"]))
        speeds.append(segment / dt)
    if len(bearings) < 2:
        return None
    # Circular bearing consistency, 1.0 means a very straight recent movement.
    sx = sum(math.sin(math.radians(v)) for v in bearings) / len(bearings)
    cx = sum(math.cos(math.radians(v)) for v in bearings) / len(bearings)
    consistency = min(1.0, math.sqrt(sx * sx + cx * cx))
    bearing = (math.degrees(math.atan2(sx, cx)) + 360.0) % 360.0
    median_speed = median(speeds, speed_mps)
    horizon = 10 * 60
    pred_lat, pred_lon = recovery_destination(latest["lat"], latest["lon"], bearing, median_speed * horizon)
    accuracy_penalty = min(0.55, median([p.get("acc", 80) for p in recent], 80) / 500.0)
    confidence = max(0.1, min(0.85, consistency * 0.8 + min(0.2, len(recent) / 40.0) - accuracy_penalty))
    if confidence < 0.3:
        return None
    return {
        "lat": round(pred_lat, 7),
        "lon": round(pred_lon, 7),
        "bearing": round(bearing, 1),
        "speed_kmh": round(median_speed * 3.6, 1),
        "horizon_minutes": 10,
        "confidence": round(confidence, 2),
        "disclaimer": "Bewegungstrend aus vergangenen Apple-Reports, keine garantierte Vorhersage.",
    }


def recovery_route_distance(points):
    pts = [normalize_point(p) for p in (points or [])]
    pts = [p for p in pts if p]
    pts.sort(key=lambda p: p["ts"])
    if len(pts) < 2:
        return 0.0
    total = 0.0
    previous = pts[0]
    for point in pts[1:]:
        distance = haversine_distance(previous["lat"], previous["lon"], point["lat"], point["lon"])
        dt = max(1.0, point["ts"] - previous["ts"])
        # Ignore implausible Find My jumps rather than inflating the movement profile.
        if distance <= 100000 and distance / dt <= 80:
            total += distance
        # Always advance the comparison point. Otherwise one rejected jump can
        # make every following segment compare against a stale location.
        previous = point
    return total


def recovery_stays_for(name, points=None):
    mode = normalize_recovery_mode(state.get("recovery_modes", {}).get(name, {}))
    store = recovery_store(name)
    points = points if points is not None else store.get("points", [])
    source = list(points)[-50000:]
    _, stays = build_stays(source, cluster_radius=mode["stable_radius_m"], min_duration=mode["stable_min_seconds"])
    return [stay for stay in stays if int(stay.get("count", 0) or 0) >= mode["stable_confirmations"]]


def recovery_current_stay(name, points=None):
    store = recovery_store(name)
    pts = [normalize_point(p) for p in list(points if points is not None else store.get("points", []))]
    pts = [p for p in pts if p]
    if not pts:
        return None
    pts.sort(key=lambda p: p["ts"])
    latest = pts[-1]
    latest_ts = float(latest["ts"])
    mode = normalize_recovery_mode(state.get("recovery_modes", {}).get(name, {}))
    stays = recovery_stays_for(name, pts)
    candidates = []
    for stay in stays:
        if latest_ts - float(stay.get("end", 0) or 0) > 20 * 60:
            continue
        radius = max(
            float(mode.get("stable_radius_m", 75) or 75),
            float(stay.get("medianAccuracy", 0) or 0) * 1.6,
            float(latest.get("acc", 0) or 0) * 1.25,
        )
        distance = haversine_distance(
            float(stay.get("centerLat", latest["lat"])),
            float(stay.get("centerLon", latest["lon"])),
            latest["lat"], latest["lon"],
        )
        if distance <= min(500.0, radius):
            candidates.append(stay)
    return candidates[-1] if candidates else None


def recovery_append_event(name, event_type, title, body, severity="normal", point=None, dispatch=True, dedupe_key=""):
    now_ts = int(time.time())
    mode = normalize_recovery_mode(state.get("recovery_modes", {}).get(name, {}))
    store = recovery_store(name)
    point_payload = event_location_payload(point) if point else None
    event = {
        "id": f"rec_{now_ts}_{secrets.token_hex(5)}",
        "ts": now_ts,
        "type": str(event_type)[:80],
        "title": str(title)[:180],
        "body": str(body)[:700],
        "severity": severity,
        "location": point_payload,
        "kind": mode.get("kind", "lost"),
    }
    if dedupe_key:
        for existing in store.get("events", [])[-80:]:
            if existing.get("dedupe_key") == dedupe_key:
                return existing
        event["dedupe_key"] = dedupe_key
    store.setdefault("events", []).append(event)
    store["events"] = store["events"][-RECOVERY_EVENT_LIMIT:]
    if dispatch:
        tracker_ref = f"apple:{name}"
        tracker_config = normalize_tracker_notification_config(state.get("notification_settings", {}).get("trackers", {}).get(tracker_ref, {}))
        append_notification_event({
            "type": f"recovery_{event_type}",
            "severity": severity,
            "title": title,
            "body": body,
            "tracker_ref": tracker_ref,
            "provider": "apple",
            "tracker_id": name,
            "tracker_name": device_display_name(name),
            "location": point_payload,
            "event_key": f"recovery:{name}:{dedupe_key or event['id']}",
            "requested_channels": tracker_config.get("channels", []),
        }, dispatch=True, dedupe_seconds=60)
    return event


def recovery_capture_points(name, report_points, trigger="sync"):
    with recovery_lock:
        raw_mode = state.setdefault("recovery_modes", {}).get(name, {})
        mode = normalize_recovery_mode(raw_mode)
        state["recovery_modes"][name] = mode
        if not mode.get("active"):
            return 0
        store = recovery_store(name)
        activation_ts = float(mode.get("activated_ts", 0) or 0)
        incoming = [normalize_point(p) for p in (report_points or [])]
        incoming = [p for p in incoming if p and float(p.get("ts", 0) or 0) >= activation_ts - 300]
        if not incoming:
            return 0
        existing = list(store.get("points", []))
        old_latest = max((float(p.get("ts", 0) or 0) for p in existing if isinstance(p, dict)), default=0)
        seen = {point_identity(p) for p in existing if isinstance(p, dict)}
        added = 0
        for point in sorted(incoming, key=lambda p: p["ts"]):
            pid = point_identity(point)
            if pid in seen:
                continue
            point = dict(point)
            point["report_id"] = point.get("report_id") or pid
            existing.append(point)
            seen.add(pid)
            added += 1
        if not added:
            return 0
        existing.sort(key=lambda p: float(p.get("ts", 0) or 0))
        store["points"] = existing[-RECOVERY_HISTORY_LIMIT:]
        points = store["points"]
        latest = points[-1]
        runtime = mode.setdefault("runtime", {})
        now_ts = int(time.time())
        current_stay = recovery_current_stay(name, points)

        if old_latest and float(latest["ts"]) - old_latest >= mode["stale_after_seconds"]:
            recovery_append_event(
                name, "signal_back", f"{device_display_name(name)} ist wieder sichtbar",
                f"Nach längerer Pause ist ein neuer Apple-Standort eingetroffen (±{round(float(latest.get('acc', 0) or 0))} m).",
                "high" if mode["kind"] == "stolen" else "normal", latest,
                dedupe_key=f"signal-back:{int(latest['ts'])}",
            )

        if current_stay:
            stay_id = str(current_stay.get("id") or "")
            previous_stay = str(runtime.get("stable_stay_id") or "")
            runtime["phase"] = "stationary"
            runtime["stable_stay_id"] = stay_id
            runtime["stable_center"] = {"lat": current_stay["centerLat"], "lon": current_stay["centerLon"]}
            runtime["stable_since_ts"] = int(current_stay["start"])
            if stay_id and stay_id != previous_stay:
                duration_min = max(1, int(current_stay.get("duration_seconds", 0) / 60))
                recovery_append_event(
                    name, "stationary_confirmed", f"{device_display_name(name)} bleibt wahrscheinlich hier",
                    f"Mehrere Apple-Reports bestätigen denselben Bereich seit etwa {duration_min} Minuten. Recovery Guard beobachtet weitere Veränderungen.",
                    "high" if mode["kind"] == "stolen" else "normal", latest,
                    dedupe_key=f"stay:{stay_id}",
                )
                runtime["last_stationary_notice_ts"] = now_ts
            elif now_ts - int(runtime.get("last_stationary_notice_ts", 0) or 0) >= mode["stationary_update_seconds"]:
                duration_min = max(1, int((latest["ts"] - current_stay["start"]) / 60))
                recovery_append_event(
                    name, "stationary_update", f"Recovery-Update · {device_display_name(name)}",
                    f"Der Gegenstand liegt weiterhin sehr wahrscheinlich im selben Bereich - inzwischen seit ungefähr {duration_min} Minuten.",
                    "normal", latest,
                    dedupe_key=f"stay-update:{stay_id}:{now_ts // mode['stationary_update_seconds']}",
                )
                runtime["last_stationary_notice_ts"] = now_ts
        else:
            stable_center = runtime.get("stable_center") if isinstance(runtime.get("stable_center"), dict) else None
            recent = points[-3:]
            confirmed_move = False
            if stable_center and len(recent) >= 2:
                outside = []
                for point in recent[-2:]:
                    dynamic = max(mode["movement_threshold_m"], float(point.get("acc", 0) or 0) * 1.8)
                    outside.append(haversine_distance(stable_center["lat"], stable_center["lon"], point["lat"], point["lon"]) >= dynamic)
                confirmed_move = all(outside)
            runtime["phase"] = "moving" if confirmed_move else "active"
            if confirmed_move and runtime.get("stable_stay_id"):
                key = f"move:{runtime.get('stable_stay_id')}:{int(latest['ts']) // 600}"
                last_move_notice = int(runtime.get("last_movement_notice_ts", 0) or 0)
                last_move_location = runtime.get("last_movement_notice_location") if isinstance(runtime.get("last_movement_notice_location"), dict) else None
                moved_since_notice = (
                    haversine_distance(last_move_location["lat"], last_move_location["lon"], latest["lat"], latest["lon"])
                    if last_move_location else mode["significant_move_m"]
                )
                if now_ts - last_move_notice >= mode["movement_update_seconds"] or moved_since_notice >= mode["significant_move_m"]:
                    recovery_append_event(
                        name, "movement", f"Bewegung erkannt · {device_display_name(name)}",
                        f"Der Gegenstand hat den zuvor stabilen Bereich verlassen. Neuer Standort ±{round(float(latest.get('acc', 0) or 0))} m.",
                        "critical" if mode["kind"] == "stolen" else "high", latest,
                        dedupe_key=key,
                    )
                    runtime["last_movement_notice_ts"] = now_ts
                    runtime["last_movement_notice_location"] = {"lat": latest["lat"], "lon": latest["lon"]}
                runtime["stable_stay_id"] = ""

        runtime["last_point_ts"] = int(latest["ts"])
        runtime["last_trigger"] = str(trigger)[:120]
        runtime["prediction"] = recovery_motion_prediction(points[-20:])
        state["recovery_modes"][name] = mode
        save_recovery_state(history=True)
        return added


def recovery_periodic_watchdog():
    now_ts = int(time.time())
    changed = False
    with recovery_lock:
        for name, raw in list(state.get("recovery_modes", {}).items()):
            mode = normalize_recovery_mode(raw)
            state["recovery_modes"][name] = mode
            if not mode.get("active") or name not in state.get("accessories", {}):
                continue
            store = recovery_store(name)
            points = store.get("points", [])
            if not points:
                continue
            latest = max(points, key=lambda p: float(p.get("ts", 0) or 0))
            age = now_ts - int(float(latest.get("ts", 0) or 0))
            runtime = mode.setdefault("runtime", {})
            if age >= mode["stale_after_seconds"]:
                runtime["phase"] = "signal_lost"
                last_notice = int(runtime.get("last_stale_notice_ts", 0) or 0)
                if now_ts - last_notice >= mode["stale_repeat_seconds"]:
                    hours = max(1, round(age / 3600, 1))
                    recovery_append_event(
                        name, "signal_stale", f"Noch kein neuer Standort · {device_display_name(name)}",
                        f"Seit ungefähr {hours} Stunden kam kein neuer Apple-Report. Recovery Guard fragt weiterhin automatisch nach neuen Fundmeldungen.",
                        "high" if mode["kind"] == "stolen" else "normal", latest,
                        dedupe_key=f"stale:{now_ts // mode['stale_repeat_seconds']}",
                    )
                    runtime["last_stale_notice_ts"] = now_ts
                    changed = True
        if changed:
            save_recovery_state(history=True)


def recovery_public_summary(name):
    mode = normalize_recovery_mode(state.get("recovery_modes", {}).get(name, {}))
    store = recovery_store(name) if name in state.get("recovery_history", {}) or mode.get("active") else {"points": [], "events": []}
    points = store.get("points", []) if isinstance(store, dict) else []
    runtime = mode.get("runtime", {}) if isinstance(mode.get("runtime"), dict) else {}
    latest = points[-1] if points else None
    share = next((
        {"id": sid, **link}
        for sid, link in state.get("recovery_shares", {}).items()
        if isinstance(link, dict) and link.get("device") == name and recovery_share_status(link) == "active"
    ), None)
    return {
        "active": bool(mode.get("active")),
        "kind": mode.get("kind", "lost"),
        "kind_label": recovery_kind_label(mode.get("kind")),
        "update_frequency": mode.get("update_frequency", "balanced"),
        "activated_ts": int(mode.get("activated_ts", 0) or 0),
        "found_ts": int(mode.get("found_ts", 0) or 0),
        "phase": "found" if not mode.get("active") and mode.get("found_ts") else runtime.get("phase", "active" if mode.get("active") else "inactive"),
        "phase_label": recovery_phase_label("found" if not mode.get("active") and mode.get("found_ts") else runtime.get("phase", "active")),
        "points": len(points),
        "events": len(store.get("events", [])) if isinstance(store, dict) else 0,
        "last_point_ts": int(float((latest or {}).get("ts", 0) or 0)),
        "has_data": bool(points or mode.get("activated_ts")),
        "share_active": bool(share),
        "share_id": share.get("id") if share else "",
        "share_expires_ts": int(float((share or {}).get("expires_ts", 0) or 0)),
        "prediction": runtime.get("prediction") if mode.get("active") else None,
    }


def recovery_compact_points(points, max_points=6000):
    pts = [normalize_point(p) for p in (points or [])]
    pts = [p for p in pts if p]
    if len(pts) <= max_points:
        return pts
    max_points = max(2, int(max_points or 2))
    # Even sampling used to slice the *first* max_points rows whenever the
    # integer step became one. That silently hid the newest owner reports.
    # Proportional indices preserve both endpoints and the complete time span.
    indexes = [round(index * (len(pts) - 1) / (max_points - 1)) for index in range(max_points)]
    return [pts[index] for index in dict.fromkeys(indexes)]


def recovery_detail_payload(name, include_points=True, max_points=6000):
    mode = normalize_recovery_mode(state.get("recovery_modes", {}).get(name, {}))
    store = recovery_store(name)
    points = list(store.get("points", []))
    stays = recovery_stays_for(name, points)
    latest = points[-1] if points else None
    distance_m = recovery_route_distance(points)
    started = int(mode.get("activated_ts", 0) or (points[0]["ts"] if points else 0) or 0)
    ended = int(mode.get("found_ts", 0) or (points[-1]["ts"] if points else time.time()) or time.time())
    stationary_seconds = sum(max(0, int(stay.get("duration_seconds", 0) or 0)) for stay in stays)
    events = list(store.get("events", []))[-RECOVERY_EVENT_LIMIT:]
    for stay in stays:
        address = recovery_address_for_point({"lat": stay["centerLat"], "lon": stay["centerLon"], "ts": stay["end"], "acc": stay.get("medianAccuracy", 0)}, store)
        if address:
            stay["address"] = address
    latest_address = recovery_address_for_point(latest, store) if latest else None
    share_rows = [
        {"id": sid, "status": recovery_share_status(link), "created_ts": int(link.get("created_ts", 0) or 0), "expires_ts": int(float(link.get("expires_ts", 0) or 0)), "access_count": int(link.get("access_count", 0) or 0), "permissions": recovery_share_permissions(link)}
        for sid, link in state.get("recovery_shares", {}).items()
        if isinstance(link, dict) and link.get("device") == name
    ]
    payload = {
        "status": "ok",
        "device": name,
        "name": device_display_name(name),
        "mode": mode,
        "summary": recovery_public_summary(name),
        "official_provider_lost_mode": False,
        "latest": {**latest, "address": latest_address} if latest else None,
        "stays": stays[-250:],
        "events": events[-500:],
        "shares": share_rows,
        "metrics": {
            "distance_m": round(distance_m, 1),
            "duration_seconds": max(0, ended - started) if started else 0,
            "stationary_seconds": stationary_seconds,
            "moving_seconds": max(0, (ended - started) - stationary_seconds) if started else 0,
            "stay_count": len(stays),
            "point_count": len(points),
            "event_count": len(events),
        },
        "prediction": recovery_motion_prediction(points[-20:]) if mode.get("active") else None,
    }
    if include_points:
        public_points = recovery_compact_points(points, max_points=max_points)
        for point in public_points:
            address = recovery_address_for_point(point, store)
            if address:
                point["address"] = address
        payload["points"] = public_points
        payload["points_sampled"] = len(public_points) < len(points)
        payload["points_total"] = len(points)
    return payload


def recovery_share_status(link):
    if not isinstance(link, dict) or not link.get("active", False):
        return "revoked"
    expires = int(float(link.get("expires_ts", 0) or 0))
    if expires and expires <= int(time.time()):
        return "expired"
    return "active"


def recovery_share_permissions(link):
    raw = link.get("permissions", {}) if isinstance(link, dict) else {}
    raw = raw if isinstance(raw, dict) else {}
    return {
        "show_exact_location": bool(raw.get("show_exact_location", True)),
        "show_timeline": bool(raw.get("show_timeline", True)),
        "show_stays": bool(raw.get("show_stays", True)),
        "show_note": bool(raw.get("show_note", True)),
        "can_refresh": bool(raw.get("can_refresh", False)),
    }


def recovery_share_payload(link_id, link):
    name = str(link.get("device") or "")
    if name not in state.get("accessories", {}):
        return None
    permissions = recovery_share_permissions(link)
    detail = recovery_detail_payload(name, include_points=permissions["show_timeline"], max_points=2500)
    latest = detail.get("latest")
    if latest and not permissions["show_exact_location"]:
        latest = dict(latest)
        latest["lat"] = round(float(latest["lat"]), 3)
        latest["lon"] = round(float(latest["lon"]), 3)
        latest["acc"] = max(150, float(latest.get("acc", 0) or 0))
        latest.pop("address", None)
    points = detail.get("points", []) if permissions["show_timeline"] else []
    if points and not permissions["show_exact_location"]:
        points = [{**p, "lat": round(float(p["lat"]), 3), "lon": round(float(p["lon"]), 3), "acc": max(150, float(p.get("acc", 0) or 0))} for p in points]
    stays = detail.get("stays", []) if permissions["show_stays"] else []
    if stays and not permissions["show_exact_location"]:
        stays = [{**stay, "centerLat": round(float(stay["centerLat"]), 3), "centerLon": round(float(stay["centerLon"]), 3), "radius": max(150, float(stay.get("radius", 0) or 0)), "address": None} for stay in stays]
    prediction = detail.get("prediction")
    if prediction and not permissions["show_exact_location"]:
        prediction = {key: value for key, value in prediction.items() if key not in {"lat", "lon"}}
    return {
        "status": "ok",
        "share_id": link_id,
        "name": detail["name"],
        "kind": detail["summary"]["kind"],
        "kind_label": detail["summary"]["kind_label"],
        "phase": detail["summary"]["phase"],
        "phase_label": detail["summary"]["phase_label"],
        "activated_ts": detail["summary"]["activated_ts"],
        "latest": latest,
        "points": points,
        "stays": stays,
        "events": detail.get("events", [])[-120:] if permissions["show_timeline"] else [],
        "metrics": detail.get("metrics", {}),
        "note": detail.get("mode", {}).get("note", "") if permissions["show_note"] else "",
        "permissions": permissions,
        "expires_ts": int(float(link.get("expires_ts", 0) or 0)),
        "last_locate_ts": int(float(link.get("last_locate_ts", 0) or 0)),
        "prediction": prediction,
    }


def recovery_log_share_access(link_id, action="view"):
    link = state.get("recovery_shares", {}).get(link_id, {})
    if not isinstance(link, dict):
        return
    now_ts = int(time.time())
    link["last_access_ts"] = now_ts
    link["access_count"] = int(link.get("access_count", 0) or 0) + (1 if action == "view" else 0)
    row = {
        "ts": now_ts,
        "link_id": link_id,
        "device": link.get("device"),
        "action": action,
        "ip_hash": hashlib.sha256((str(request.remote_addr or "") + str(SECRET_KEY)).encode("utf-8")).hexdigest()[:16],
    }
    state.setdefault("recovery_access_log", []).append(row)
    state["recovery_access_log"] = state["recovery_access_log"][-RECOVERY_SHARE_ACCESS_LIMIT:]
    save_recovery_state(history=False, shares=True, access=True)


def recovery_resolve_addresses(name, limit=8):
    store = recovery_store(name)
    points = store.get("points", [])
    if not points:
        return 0
    candidates = []
    latest = points[-1]
    candidates.append(latest)
    for stay in reversed(recovery_stays_for(name, points)):
        candidates.append({"lat": stay["centerLat"], "lon": stay["centerLon"], "ts": stay["end"], "acc": stay.get("medianAccuracy", 0)})
        if len(candidates) >= max(1, int(limit)):
            break
    resolved = 0
    for point in candidates:
        key = recovery_point_key(point)
        if store["addresses"].get(key):
            continue
        cached = address_from_cached(point["lat"], point["lon"])
        address = cached
        if not address:
            address, _cached, retry = reverse_geocode(point["lat"], point["lon"])
            if not address and retry:
                time.sleep(min(1.3, max(0.15, retry)))
                address, _cached, _retry = reverse_geocode(point["lat"], point["lon"])
        if address:
            store["addresses"][key] = address
            resolved += 1
        time.sleep(0.05)
    if resolved:
        save_recovery_state(history=True)
    return resolved


def recovery_cleanup_device(name):
    with recovery_lock:
        state.get("recovery_modes", {}).pop(name, None)
        state.get("recovery_history", {}).pop(name, None)
        for sid, link in list(state.get("recovery_shares", {}).items()):
            if isinstance(link, dict) and link.get("device") == name:
                state["recovery_shares"].pop(sid, None)
        state["recovery_access_log"] = [row for row in state.get("recovery_access_log", []) if row.get("device") != name]
        save_recovery_state(history=True, shares=True, access=True)


def build_recovery_pdf(name):
    try:
        from reportlab.lib import colors
        from reportlab.lib.enums import TA_LEFT, TA_RIGHT
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.units import mm
        from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether
    except ImportError as exc:
        raise RuntimeError("Für den PDF-Export fehlt 'reportlab'. Installiere es mit: python3 -m pip install reportlab") from exc

    # Try to enrich the most important places. Failure never blocks the report.
    try:
        recovery_resolve_addresses(name, limit=6)
    except Exception as exc:
        logger.debug("Recovery-PDF Adressanreicherung übersprungen: %s", exc)
    detail = recovery_detail_payload(name, include_points=False)
    mode = detail["mode"]
    summary = detail["summary"]
    metrics = detail["metrics"]
    store = recovery_store(name)
    buffer = io.BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, leftMargin=16*mm, rightMargin=16*mm, topMargin=18*mm, bottomMargin=18*mm, title=f"Recovery Guard - {detail['name']}")
    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(name="RGTitle", parent=styles["Title"], fontName="Helvetica-Bold", fontSize=23, leading=27, textColor=colors.HexColor("#111827"), spaceAfter=6))
    styles.add(ParagraphStyle(name="RGKicker", parent=styles["Normal"], fontName="Helvetica-Bold", fontSize=8, leading=10, textColor=colors.HexColor("#DC2626"), spaceAfter=4))
    styles.add(ParagraphStyle(name="RGH2", parent=styles["Heading2"], fontName="Helvetica-Bold", fontSize=14, leading=18, textColor=colors.HexColor("#111827"), spaceBefore=10, spaceAfter=7))
    styles.add(ParagraphStyle(name="RGBody", parent=styles["BodyText"], fontName="Helvetica", fontSize=9.5, leading=14, textColor=colors.HexColor("#374151")))
    styles.add(ParagraphStyle(name="RGSmall", parent=styles["BodyText"], fontName="Helvetica", fontSize=8, leading=11, textColor=colors.HexColor("#6B7280")))
    styles.add(ParagraphStyle(name="RGRight", parent=styles["RGSmall"], alignment=TA_RIGHT))
    styles.add(ParagraphStyle(name="RGTable", parent=styles["BodyText"], fontName="Helvetica", fontSize=7.6, leading=9.4, textColor=colors.HexColor("#374151"), spaceAfter=0, spaceBefore=0))
    styles.add(ParagraphStyle(name="RGTableHead", parent=styles["RGTable"], fontName="Helvetica-Bold", textColor=colors.white))

    def safe_para(value, style="RGBody"):
        text = html.escape(str(value if value is not None else ""), quote=False).replace("\n", "<br/>")
        return Paragraph(text, styles[style])

    def fmt_ts(ts):
        if not ts:
            return "-"
        try:
            return datetime.fromtimestamp(float(ts), tz=APP_TIMEZONE).strftime("%d.%m.%Y %H:%M:%S")
        except Exception:
            return "-"

    def fmt_dur(seconds):
        seconds = max(0, int(seconds or 0))
        days, rem = divmod(seconds, 86400)
        hours, rem = divmod(rem, 3600)
        minutes = rem // 60
        parts = []
        if days: parts.append(f"{days} T")
        if hours: parts.append(f"{hours} h")
        if minutes or not parts: parts.append(f"{minutes} min")
        return " ".join(parts)

    def addr_text(address, lat=None, lon=None):
        if isinstance(address, dict):
            label = address.get("label") or address.get("display_name") or address.get("poi_name")
            if label:
                return str(label)
        if lat is not None and lon is not None:
            return f"{float(lat):.6f}, {float(lon):.6f}"
        return "Adresse nicht aufgelöst"

    story = []
    story += [Paragraph("RECOVERY GUARD / APPLE FIND MY", styles["RGKicker"]), safe_para(detail["name"], "RGTitle"), Paragraph(f"{summary['kind_label']} · {summary['phase_label']} · Bericht erstellt {fmt_ts(time.time())}", styles["RGBody"]), Spacer(1, 8)]
    status_data = [
        ["Aktiviert", fmt_ts(mode.get("activated_ts")), "Status", summary["phase_label"]],
        ["Letzter Standort", fmt_ts(summary.get("last_point_ts")), "Reports", str(metrics["point_count"])],
        ["Beobachtungsdauer", fmt_dur(metrics["duration_seconds"]), "Erkannte Aufenthalte", str(metrics["stay_count"])],
        ["Strecke (bereinigt)", f"{metrics['distance_m']/1000:.2f} km", "Als gefunden", fmt_ts(mode.get("found_ts")) if mode.get("found_ts") else "Nein"],
    ]
    table = Table(status_data, colWidths=[32*mm, 55*mm, 34*mm, 55*mm])
    table.setStyle(TableStyle([
        ("BACKGROUND", (0,0), (-1,-1), colors.HexColor("#F8FAFC")),
        ("BOX", (0,0), (-1,-1), 0.7, colors.HexColor("#E5E7EB")),
        ("INNERGRID", (0,0), (-1,-1), 0.35, colors.HexColor("#E5E7EB")),
        ("FONTNAME", (0,0), (-1,-1), "Helvetica"),
        ("FONTNAME", (0,0), (0,-1), "Helvetica-Bold"),
        ("FONTNAME", (2,0), (2,-1), "Helvetica-Bold"),
        ("FONTSIZE", (0,0), (-1,-1), 8.5),
        ("TEXTCOLOR", (0,0), (-1,-1), colors.HexColor("#374151")),
        ("VALIGN", (0,0), (-1,-1), "TOP"),
        ("LEFTPADDING", (0,0), (-1,-1), 6), ("RIGHTPADDING", (0,0), (-1,-1), 6),
        ("TOPPADDING", (0,0), (-1,-1), 6), ("BOTTOMPADDING", (0,0), (-1,-1), 6),
    ]))
    story += [table]
    if mode.get("note"):
        story += [Spacer(1, 8), Paragraph("Hinweis des Eigentümers", styles["RGH2"]), safe_para(str(mode.get("note")), "RGBody")]

    latest = detail.get("latest")
    if latest:
        story += [Paragraph("Letzter bestätigter Standort", styles["RGH2"])]
        latest_addr = addr_text(latest.get("address"), latest.get("lat"), latest.get("lon"))
        story += [safe_para(latest_addr, "RGBody"), Paragraph(f"{fmt_ts(latest.get('ts'))} · ±{round(float(latest.get('acc',0) or 0))} m · {latest.get('lat'):.6f}, {latest.get('lon'):.6f}", styles["RGSmall"])]

    prediction = detail.get("prediction")
    if prediction:
        story += [Paragraph("Bewegungstrend", styles["RGH2"]), Paragraph(f"Aktueller Trend: ca. {prediction['speed_kmh']} km/h, Richtung {prediction['bearing']}°. Rechnerischer 10-Minuten-Trendpunkt: {prediction['lat']:.6f}, {prediction['lon']:.6f}. Konfidenz {round(prediction['confidence']*100)} %. {prediction['disclaimer']}", styles["RGBody"])]

    story += [Paragraph("Aufenthaltsorte", styles["RGH2"])]
    stays = detail.get("stays", [])
    if stays:
        rows = [[safe_para("Von - bis", "RGTableHead"), safe_para("Dauer", "RGTableHead"), safe_para("Ort / Adresse", "RGTableHead"), safe_para("Reports", "RGTableHead")]]
        for stay in stays[-120:]:
            address = stay.get("address") or recovery_address_for_point({"lat": stay["centerLat"], "lon": stay["centerLon"], "ts": stay["end"], "acc": stay.get("medianAccuracy",0)}, store)
            rows.append([
                safe_para(f"{fmt_ts(stay['start'])}\n{fmt_ts(stay['end'])}", "RGTable"),
                safe_para(fmt_dur(stay.get("duration_seconds")), "RGTable"),
                safe_para(addr_text(address, stay["centerLat"], stay["centerLon"]), "RGTable"),
                safe_para(str(stay.get("count", 0)), "RGTable"),
            ])
        stay_table = Table(rows, repeatRows=1, colWidths=[43*mm, 25*mm, 89*mm, 18*mm])
        stay_table.setStyle(TableStyle([
            ("BACKGROUND", (0,0), (-1,0), colors.HexColor("#111827")),
            ("TEXTCOLOR", (0,0), (-1,0), colors.white),
            ("FONTNAME", (0,0), (-1,0), "Helvetica-Bold"),
            ("FONTNAME", (0,1), (-1,-1), "Helvetica"),
            ("FONTSIZE", (0,0), (-1,-1), 7.8),
            ("LEADING", (0,0), (-1,-1), 10),
            ("GRID", (0,0), (-1,-1), 0.35, colors.HexColor("#D1D5DB")),
            ("ROWBACKGROUNDS", (0,1), (-1,-1), [colors.white, colors.HexColor("#F9FAFB")]),
            ("VALIGN", (0,0), (-1,-1), "TOP"),
            ("LEFTPADDING", (0,0), (-1,-1), 4), ("RIGHTPADDING", (0,0), (-1,-1), 4),
            ("TOPPADDING", (0,0), (-1,-1), 5), ("BOTTOMPADDING", (0,0), (-1,-1), 5),
        ]))
        story += [stay_table]
    else:
        story += [Paragraph("Noch kein ausreichend langer, mehrfach bestätigter Aufenthaltsort erkannt.", styles["RGBody"])]

    story += [PageBreak(), Paragraph("Recovery-Ereignisprotokoll", styles["RGH2"])]
    events = detail.get("events", [])
    if events:
        event_rows = [[safe_para("Zeit", "RGTableHead"), safe_para("Ereignis", "RGTableHead"), safe_para("Beschreibung", "RGTableHead")]]
        for event in events[-300:]:
            event_rows.append([
                safe_para(fmt_ts(event.get("ts")), "RGTable"),
                safe_para(str(event.get("title") or event.get("type") or "Ereignis"), "RGTable"),
                safe_para(str(event.get("body") or ""), "RGTable"),
            ])
        event_table = Table(event_rows, repeatRows=1, colWidths=[35*mm, 53*mm, 87*mm])
        event_table.setStyle(TableStyle([
            ("BACKGROUND", (0,0), (-1,0), colors.HexColor("#B91C1C")),
            ("TEXTCOLOR", (0,0), (-1,0), colors.white),
            ("FONTNAME", (0,0), (-1,0), "Helvetica-Bold"),
            ("FONTNAME", (0,1), (-1,-1), "Helvetica"),
            ("FONTSIZE", (0,0), (-1,-1), 7.6),
            ("LEADING", (0,0), (-1,-1), 10),
            ("GRID", (0,0), (-1,-1), 0.35, colors.HexColor("#D1D5DB")),
            ("ROWBACKGROUNDS", (0,1), (-1,-1), [colors.white, colors.HexColor("#FFF7F7")]),
            ("VALIGN", (0,0), (-1,-1), "TOP"),
            ("LEFTPADDING", (0,0), (-1,-1), 4), ("RIGHTPADDING", (0,0), (-1,-1), 4),
            ("TOPPADDING", (0,0), (-1,-1), 5), ("BOTTOMPADDING", (0,0), (-1,-1), 5),
        ]))
        story += [event_table]
    else:
        story += [Paragraph("Noch keine Recovery-Ereignisse vorhanden.", styles["RGBody"])]

    story += [Spacer(1, 10), Paragraph("Hinweis", styles["RGH2"]), Paragraph("Dieser Bericht dokumentiert Standortmeldungen, die die lokale Anwendung aus Apple Find My empfangen hat. Zeit, Genauigkeit und Vollständigkeit hängen von verfügbaren Find-My-Reports ab. Bewegungstrends sind statistische Schätzungen aus vergangenen Punkten und keine garantierten Vorhersagen. Der Recovery Guard ist für die Wiederbeschaffung eigener Gegenstände gedacht.", styles["RGSmall"])]

    def footer(canvas, doc_obj):
        canvas.saveState()
        canvas.setStrokeColor(colors.HexColor("#E5E7EB")); canvas.setLineWidth(0.5)
        canvas.line(16*mm, 12*mm, 194*mm, 12*mm)
        canvas.setFont("Helvetica", 7.5); canvas.setFillColor(colors.HexColor("#6B7280"))
        canvas.drawString(16*mm, 7.5*mm, f"Universal Tag Studio {APP_VERSION} · Recovery Guard")
        canvas.drawRightString(194*mm, 7.5*mm, f"Seite {doc_obj.page}")
        canvas.restoreState()

    doc.build(story, onFirstPage=footer, onLaterPages=footer)
    buffer.seek(0)
    return buffer

def needs_full_report_history(name):
    # Always request batches; pausing capture affects storage/scheduling, not
    # how many valid reports a manual provider response can contain.
    return name in state.get("accessories", {})


def process_report_results(named_accessories, results, mode):
    if not results:
        return 0, 0
    if not isinstance(results, dict):
        results = {named_accessories[0][1]: results}
    now_ts = int(time.time())
    total_received = total_added = 0
    for name, accessory in named_accessories:
        if state.get("accessories", {}).get(name) is not accessory:
            continue
        raw = results.get(accessory)
        if raw is None:
            register_report_sync(name, 0, 0, 0, 0, 0, mode)
            continue
        reports = list(raw) if isinstance(raw, (list, tuple, set)) else [raw]
        reports = [report for report in reports if report is not None]
        valid = [(report, report_to_point(report)) for report in reports]
        valid = sorted(((report, point) for report, point in valid if point), key=lambda pair: pair[1]["ts"])
        batch_id = "a-" + uuid.uuid4().hex
        report_points = [{**point, "batch_id": batch_id} for _, point in valid]
        if not valid:
            register_report_sync(name, 0, 0, 0, 0, 0, mode)
            continue
        latest = valid[-1][0]
        latest_ts = update_location_cache(name, latest)
        history_added = add_persistent_history_points(name, report_points, persist=False)
        recording_added = add_recording_points(name, report_points, now_ts)
        shared_added = add_shared_history_points(name, report_points)
        add_points_to_apple_tests(name, report_points)
        recovery_capture_points(name, report_points, mode)
        process_tracker_location_reports("apple", name, report_points, mode)
        save_accessory_state(name, accessory)
        register_report_sync(name, len(report_points), history_added, recording_added, shared_added, latest_ts, mode, report_quality_summary(report_points, history_added))
        total_received += len(report_points)
        total_added += history_added

        logger.info("Report-Sync %s: %d Reports empfangen, %d neue Verlaufspunkte gespeichert (%s)", name, len(report_points), history_added, mode)
    if total_added:
        with state_lock:
            save_json(SEVEN_HISTORY_FILE, "seven_day_history")
    return total_received, total_added


def apple_interval_for(_name=None):
    return provider_poll_window("apple")


def apple_active_reasons(name):
    """Return every reason that shares the single Apple polling job."""
    if name not in state.get("accessories", {}):
        return []
    reasons = []
    if history_direct_policy("apple", name).get("enabled"):
        reasons.append("history")
    if history_direct_policy("fusion", name).get("enabled"):
        reasons.append("fusion_history")
    if name in state.get("recordings", {}):
        reasons.append("session")
    if state.get("share_history_enabled", {}).get(name) or share_capture_required(name):
        reasons.append("shared_history")
    if fusion_profile_optimization_enabled(name):
        reasons.append("fusion_optimization")
    if any(test.get("status") == "active" and test.get("apple_name") == name for test in state.get("google_tests", {}).values()):
        reasons.append("test")
    if any(test.get("status") == "active" and test.get("apple_name") == name for test in state.get("fusion_tests", {}).values()):
        reasons.append("fusion_test")
    if any(test.get("status") == "running" and f"apple:{name}" in [str(target.get("ref") or "") for target in test.get("targets", []) if isinstance(target, dict)] for test in state.get("comparison_tests", {}).values() if isinstance(test, dict)):
        reasons.append("comparison_test")
    if tracker_alert_active(f"apple:{name}"):
        reasons.append("alerts")
    if recovery_mode_active(name):
        reasons.append("recovery")
    return list(dict.fromkeys(reasons))


def apple_schedule_next(name, immediate=False, base_ts=None):
    if not apple_active_reasons(name):
        state.setdefault("apple_next_fetch", {}).pop(name, None)
        return 0
    minimum, maximum = apple_interval_for(name)
    if immediate:
        due = time.time()
    else:
        # Cadence is measured start-to-start. Previously the provider runtime
        # was added on top of the configured 20-30 seconds.
        base = float(base_ts if base_ts is not None else time.time())
        due = max(time.time() + 0.25, base + random.randint(minimum, maximum))
    state.setdefault("apple_next_fetch", {})[name] = due
    return due


def fetch_from_apple(device_names, trigger="manual"):
    named_accessories = [(name, state["accessories"][name]) for name in device_names if name in state["accessories"]]
    if not named_accessories:
        return False
    if not state["account"]:
        polling_note_blocked("apple", "Apple-Account ist nicht angemeldet; aktive Verläufe und Alarme können nicht abgefragt werden.")
        return False
    started_monotonic = time.monotonic()
    started_ts = int(time.time())
    with state_lock:
        # Coalesce all callers (web UI, MCP, history, alerts, geofences and
        # Recovery Guard) onto the already-running request for this tracker.
        named_accessories = [
            (name, accessory) for name, accessory in named_accessories
            if name not in state.setdefault("apple_inflight", set())
        ]
        if not named_accessories:
            return False
        for name, _accessory in named_accessories:
            state.setdefault("apple_inflight", set()).add(name)
            stats = state.setdefault("report_stats", {}).setdefault("devices", {}).setdefault(name, {})
            stats.update({"started_ts": started_ts, "last_trigger": str(trigger)[:120], "last_stage": "requesting", "last_result": "running"})
    poll_started = {
        name: polling_attempt_begin("apple", name, trigger, apple_active_reasons(name))
        for name, _accessory in named_accessories
    }
    history_targets = [(name, obj) for name, obj in named_accessories if needs_full_report_history(name)]
    latest_targets = [(name, obj) for name, obj in named_accessories if not needs_full_report_history(name)]
    with fetch_lock:
        try:
            received_total = stored_total = 0
            if history_targets:
                try:
                    history_result = state["account"].fetch_location_history([obj for _, obj in history_targets])
                    received, stored = process_report_results(history_targets, history_result, "history")
                except (AttributeError, NotImplementedError) as exc:
                    logger.warning("fetch_location_history nicht verfügbar (%s); verwende nur den neuesten Standort.", exc)
                    latest_result = state["account"].fetch_location([obj for _, obj in history_targets])
                    received, stored = process_report_results(history_targets, latest_result, "latest_fallback")
                received_total += received
                stored_total += stored
            if latest_targets:
                latest_result = state["account"].fetch_location([obj for _, obj in latest_targets])
                received, stored = process_report_results(latest_targets, latest_result, "latest_only")
                received_total += received
                stored_total += stored
            batch_mode = "mixed" if history_targets and latest_targets else ("history" if history_targets else "latest_only")
            sync_mode = f"{batch_mode}:{trigger}"
            register_sync_batch(received_total, stored_total, len(named_accessories), sync_mode)
            duration_ms = int((time.monotonic() - started_monotonic) * 1000)
            for name, _accessory in named_accessories:
                if name not in state.get("accessories", {}):
                    continue
                stats = state["report_stats"].setdefault("devices", {}).setdefault(name, {})
                batch_received = int(stats.get("last_received", 0) or 0) if int(stats.get("last_sync_ts", 0) or 0) >= started_ts else 0
                stats.update({
                    "last_sync_ts": int(time.time()),
                    "last_received": batch_received,
                    "last_duration_ms": duration_ms,
                    "last_trigger": str(trigger)[:120],
                    "last_stage": "reports_saved",
                    "last_result": "empty" if batch_received == 0 else "ok",
                    "last_error": "",
                    "last_error_detail": "",
                    "last_success_ts": int(time.time()),
                    "consecutive_failures": 0,
                    "successful_syncs": int(stats.get("successful_syncs", 0) or 0) + 1,
                })
                append_notification_console(
                    "info" if batch_received == 0 else "success",
                    "tracker_sync",
                    f"Apple-Ortung für {device_display_name(name)} abgeschlossen",
                    channel="apple",
                    status="empty" if batch_received == 0 else "success",
                    tracker_ref=f"apple:{name}",
                    operation=trigger,
                    duration_ms=duration_ms,
                    detail=f"{batch_received} Report(s) empfangen · {sync_mode}",
                )
            save_json(REPORT_STATS_FILE, "report_stats")
            state["sync_failures"] = 0
            state["sync_backoff_until"] = 0
            save_account_state()
            logger.info("Report-Sync abgeschlossen [%s]: %d Reports empfangen, %d neue Verlaufspunkte gespeichert", trigger, received_total, stored_total)
            return True
        except Exception as exc:
            state["sync_failures"] = min(8, int(state.get("sync_failures", 0)) + 1)
            delay = min(15 * 60, (2 ** state["sync_failures"]) * 15) + random.randint(0, 15)
            state["sync_backoff_until"] = time.time() + delay
            duration_ms = int((time.monotonic() - started_monotonic) * 1000)
            error_code = type(exc).__name__
            for name, _accessory in named_accessories:
                if name not in state.get("accessories", {}):
                    continue
                stats = state["report_stats"].setdefault("devices", {}).setdefault(name, {})
                stats.update({
                    "last_sync_ts": int(time.time()),
                    "last_duration_ms": duration_ms,
                    "last_trigger": str(trigger)[:120],
                    "last_stage": "provider_error",
                    "last_result": "error",
                    "last_error": error_code[:120],
                    "last_error_detail": str(exc)[:500],
                    "consecutive_failures": int(stats.get("consecutive_failures", 0) or 0) + 1,
                    "failed_syncs": int(stats.get("failed_syncs", 0) or 0) + 1,
                })
                append_notification_console(
                    "error",
                    "tracker_sync",
                    f"Apple-Ortung für {device_display_name(name)} fehlgeschlagen",
                    channel="apple",
                    status="error",
                    tracker_ref=f"apple:{name}",
                    operation=trigger,
                    duration_ms=duration_ms,
                    detail=str(exc),
                )
            save_json(REPORT_STATS_FILE, "report_stats")
            logger.exception("Apple Report-Sync fehlgeschlagen: %s", exc)
            return False
        finally:
            with state_lock:
                for name, _accessory in named_accessories:
                    state.setdefault("apple_inflight", set()).discard(name)
                    if name not in state.get("accessories", {}):
                        continue
                    next_due = apple_schedule_next(name, base_ts=poll_started.get(name, started_ts))
                    stats = state.setdefault("report_stats", {}).setdefault("devices", {}).setdefault(name, {})
                    result = str(stats.get("last_result") or "empty")
                    failed = result == "error"
                    polling_attempt_finish(
                        "apple", name, trigger,
                        "error" if failed else ("empty" if result == "empty" else "success"),
                        reports=0 if failed else int(stats.get("last_received", 0) or 0),
                        new_points=0 if failed else int(stats.get("last_history_added", 0) or 0),
                        next_due=next_due,
                        detail=str(stats.get("last_error_detail") or stats.get("last_stage") or ""),
                    )


def background_poller():
    while True:
        if current_tenant_id() != "main" and not user_record(current_tenant_id()).get("active", False):
            return
        try:
            polling_worker_heartbeat("apple")
            if not automatic_polling_enabled():
                polling_note_blocked("apple", "Die globale Hintergrundortung ist in den Einstellungen pausiert.")
            elif not state.get("account"):
                if any(apple_active_reasons(name) for name in state.get("accessories", {})):
                    polling_note_blocked("apple", "Apple ist nicht angemeldet; aktiver Verlauf/Alarm wartet auf eine gültige Sitzung.")
                else:
                    polling_note_ready("apple")
            elif time.time() < float(state.get("sync_backoff_until", 0) or 0):
                polling_note_blocked("apple", "Apple-Fehlerbremse aktiv; der nächste Versuch erfolgt automatisch nach Ablauf des Backoffs.")
            else:
                polling_note_ready("apple")
                now_ts = time.time()
                due = []
                for name in sorted(state.get("accessories", {})):
                    reasons = apple_active_reasons(name)
                    if not reasons:
                        state.setdefault("apple_next_fetch", {}).pop(name, None)
                        continue
                    if name not in state.setdefault("apple_next_fetch", {}):
                        apple_schedule_next(name, immediate=True)
                    if now_ts >= float(state["apple_next_fetch"].get(name, now_ts + 30)) and name not in state.get("apple_inflight", set()):
                        due.append(name)
                if due:
                    # Keep the scheduler heartbeat alive even if Apple's
                    # upstream request is slow. fetch_lock and apple_inflight
                    # still guarantee one coalesced provider call.
                    if not fetch_lock.locked():
                        logger.info(
                            "Apple Auto-Sync: %d fällige Tracker; Gründe teilen je Tracker genau einen Abruf.",
                            len(due),
                        )
                        threading.Thread(
                            target=fetch_from_apple,
                            args=(due, "auto_unified"),
                            daemon=True,
                            name="apple-locate-auto",
                        ).start()
        except Exception as exc:
            logger.exception("Background-Poller fehlgeschlagen: %s", exc)
            polling_note_blocked("apple", f"Scheduler-Zyklus fehlgeschlagen: {type(exc).__name__}: {exc}", level="error")
        try:
            recovery_periodic_watchdog()
        except Exception as exc:
            logger.warning("Recovery-Guard-Watchdog fehlgeschlagen: %s", exc)
        try:
            inactivity_watchdog()
        except Exception as exc:
            logger.warning("Ortungspausen-Watchdog fehlgeschlagen: %s", exc)
        time.sleep(POLLING_WORKER_TICK_SECONDS)


def polling_public_state():
    config = normalize_polling_settings(state.get("settings", {}).get("polling"))
    now_ts = time.time()
    runtime_snapshot = polling_runtime_public()
    providers = {}
    catalogs = {
        "apple": (state.get("accessories", {}), apple_active_reasons, state.get("apple_next_fetch", {}), state.get("apple_inflight", set())),
        "google": (state.get("google_devices", {}), google_active_reasons, state.get("google_next_fetch", {}), state.get("google_inflight", set())),
        "samsung": (state.get("samsung_devices", {}), samsung_active_reasons, state.get("samsung_next_fetch", {}), state.get("samsung_inflight", set())),
    }
    for provider, (rows, reason_fn, due_store, inflight) in catalogs.items():
        active_rows = []
        for tracker_id in rows:
            reasons = reason_fn(tracker_id)
            if not reasons:
                continue
            due = float(due_store.get(tracker_id, 0) or 0)
            active_rows.append({
                "tracker_id": str(tracker_id),
                "reasons": reasons,
                "next_fetch_ts": int(due),
                "due_in_seconds": max(0, int(due - now_ts)) if due else 0,
                "inflight": tracker_id in inflight,
            })
        runtime_provider = runtime_snapshot.get("providers", {}).get(provider, {})
        providers[provider] = {
            **config[provider],
            "tracker_count": len(rows),
            "active_count": len(active_rows),
            "inflight_count": sum(1 for row in active_rows if row["inflight"]),
            "active": active_rows,
            "worker": runtime_provider,
        }
    return {
        "enabled": automatic_polling_enabled(),
        "demand_driven": bool(config.get("demand_driven", True)),
        "providers": providers,
        "updated_ts": int(config.get("updated_ts", 0) or 0),
        "generated_at": int(now_ts),
        "runtime": runtime_snapshot,
        "guarantee": "Abrufintervall; ein Provider kann denselben letzten Report zurückgeben oder bei Fehlern einen Backoff aktivieren.",
    }


def tracker_polling_public(provider, tracker_id):
    """Describe the one coalesced polling job used by all active features."""
    provider = str(provider or "").lower()
    tracker_id = str(tracker_id or "")
    if provider == "fusion":
        profile = state.get("fusion_profiles", {}).get(tracker_id, {})
        sources = [tracker_polling_public("apple", tracker_id)] if tracker_id in state.get("accessories", {}) else []
        if isinstance(profile, dict) and profile.get("google_id"):
            sources.append(tracker_polling_public("google", profile["google_id"]))
        if isinstance(profile, dict) and profile.get("samsung_id"):
            sources.append(tracker_polling_public("samsung", profile["samsung_id"]))
        return {
            "provider": "fusion", "tracker_id": tracker_id, "shared_job": True,
            "active": any(row.get("active") for row in sources), "sources": sources,
        }
    handlers = {
        "apple": (apple_active_reasons, state.get("apple_next_fetch", {}), state.get("apple_inflight", set())),
        "google": (google_active_reasons, state.get("google_next_fetch", {}), state.get("google_inflight", set())),
        "samsung": (samsung_active_reasons, state.get("samsung_next_fetch", {}), state.get("samsung_inflight", set())),
    }
    if provider not in handlers:
        return {"provider": provider, "tracker_id": tracker_id, "active": False, "shared_job": True}
    reason_fn, due_store, inflight = handlers[provider]
    reasons = reason_fn(tracker_id)
    minimum, maximum = polling_effective_interval(provider, tracker_id)
    due = float(due_store.get(tracker_id, 0) or 0)
    runtime_tracker = (
        state.get("polling_runtime", {}).get("providers", {}).get(provider, {}).get("trackers", {}).get(tracker_id, {})
    )
    return {
        "provider": provider, "tracker_id": tracker_id, "active": bool(reasons),
        "reasons": reasons, "interval_min": minimum, "interval_max": maximum,
        "next_fetch_ts": int(due), "due_in_seconds": max(0, int(due - time.time())) if due else 0,
        "inflight": tracker_id in inflight, "shared_job": True,
        "runtime": dict(runtime_tracker) if isinstance(runtime_tracker, dict) else {},
        "deduplication": "history, alerts, geofences, fusion and recovery share this provider request",
    }


