def clamp_int(value, default, minimum, maximum):
    try:
        parsed = int(value)
    except (TypeError, ValueError):
        parsed = default
    return max(minimum, min(maximum, parsed))


def normalize_route_points(points, retention_seconds=None, max_points=None):
    now = time.time()
    clean = []
    seen = set()
    for p in points or []:
        np = normalize_point(p)
        if not np:
            continue
        if retention_seconds is not None and np["ts"] < now - retention_seconds:
            continue
        pid = np["report_id"]
        if pid in seen:
            continue
        seen.add(pid)
        clean.append(np)
    clean.sort(key=lambda item: item["ts"])
    if max_points:
        clean = clean[-max_points:]
    return clean


def downsample_route_points(points, max_points):
    points = list(points or [])
    if len(points) <= max_points or max_points < 3:
        return points
    keep = [points[0]]
    bucket_count = max_points - 2
    span = (len(points) - 2) / bucket_count
    last_idx = 0
    for bucket in range(bucket_count):
        start = 1 + int(round(bucket * span))
        end = 1 + int(round((bucket + 1) * span))
        end = min(max(end, start + 1), len(points) - 1)
        bucket_points = points[start:end]
        if not bucket_points:
            continue
        anchor = keep[-1]
        scored = []
        for offset, p in enumerate(bucket_points, start):
            scored.append((
                haversine_distance(anchor["lat"], anchor["lon"], p["lat"], p["lon"]),
                p.get("acc", 0),
                p.get("ts", 0),
                offset,
                p,
            ))
        *_, best_idx, best = max(scored)
        if best_idx > last_idx:
            keep.append(best)
            last_idx = best_idx
    if keep[-1] is not points[-1]:
        keep.append(points[-1])
    if len(keep) > max_points:
        stride = (len(keep) - 2) / (max_points - 2)
        reduced = [keep[0]]
        for i in range(max_points - 2):
            reduced.append(keep[1 + int(round(i * stride))])
        reduced.append(keep[-1])
        keep = reduced
    return keep


def route_distance(points):
    total = 0.0
    previous = None
    for point in points or []:
        if point.get("is_outlier"):
            continue
        if previous is not None:
            elapsed = max(1, float(point["ts"]) - float(previous["ts"]))
            distance = haversine_distance(previous["lat"], previous["lon"], point["lat"], point["lon"])
            if distance / elapsed <= 75 and distance <= 100000:
                total += distance
        previous = point
    return total


def route_day_index(points, fill_last_seven=True):
    points = list(points or [])

    def point_token(point):
        if not isinstance(point, dict):
            return (0, "")
        return (
            int(float(point.get("ts", 0) or 0)),
            str(point.get("report_id") or point.get("batch_id") or "")[-24:],
        )

    today_token = local_datetime().date().isoformat() if fill_last_seven else ""
    signature = (
        bool(fill_last_seven),
        today_token,
        len(points),
        point_token(points[0]) if points else (0, ""),
        point_token(points[-1]) if points else (0, ""),
    )
    with route_day_cache_lock:
        cached = route_day_cache.get(signature)
    if cached is not None:
        return [dict(item) for item in cached]

    days = {}
    for p in points:
        ts = int(float(p.get("ts", 0) or 0))
        day = local_day_key(ts)
        entry = days.setdefault(day, {"day": day, "count": 0, "start": ts, "end": ts})
        entry["count"] += 1
        entry["start"] = min(entry["start"], ts)
        entry["end"] = max(entry["end"], ts)
    if fill_last_seven:
        today = local_datetime().date()
        for offset in range(6, -1, -1):
            day = (today - timedelta(days=offset)).isoformat()
            days.setdefault(day, {"day": day, "count": 0, "start": None, "end": None})
    # Keep the familiar empty rows for the latest seven days, but expose every
    # retained day. Older clients can still render the final seven entries;
    # newer clients can navigate 14/30/90/custom/permanent histories.
    result = sorted(days.values(), key=lambda item: item["day"])[-HISTORY_DAY_INDEX_LIMIT:]
    with route_day_cache_lock:
        if len(route_day_cache) >= 512:
            route_day_cache.pop(next(iter(route_day_cache)), None)
        route_day_cache[signature] = tuple(dict(item) for item in result)
    return result


def route_metrics(points, stays):
    accuracy = [float(point.get("acc", 0) or 0) for point in points if float(point.get("acc", 0) or 0) > 0]
    qualities = defaultdict(int)
    sources = defaultdict(int)
    for point in points:
        qualities[str(point.get("quality") or classify_point_quality(point))] += 1
        sources[str(point.get("source") or "apple")] += 1
    active_start = int(points[0]["ts"]) if points else None
    active_end = int(points[-1]["ts"]) if points else None
    return {
        "reports": len(points),
        "distance_m": round(route_distance(points), 1),
        "stay_seconds": int(sum(max(0, float(stay.get("duration_seconds", 0) or 0)) for stay in stays)),
        "stay_count": len(stays),
        "median_accuracy_m": round(median(accuracy, 0), 1) if accuracy else None,
        "best_accuracy_m": round(min(accuracy), 1) if accuracy else None,
        "good_reports": qualities["good"],
        "weak_reports": qualities["weak"],
        "outlier_reports": qualities["outlier"] + qualities["ignored_jump"] + qualities["bad"],
        "source_counts": dict(sources),
        "active_start": active_start,
        "active_end": active_end,
    }


def route_payload(points, title="Verlauf", retention_seconds=None, default_limit=OPTIMIZED_ROUTE_DEFAULT_POINTS, filter_day=False):
    full_requested = request.args.get("full") in {"1", "true", "yes"}
    compact_requested = request.args.get("compact") in {"1", "true", "yes"}
    include_report_ids = request.args.get("ids") in {"1", "true", "yes"}
    device_memory_hint = request.args.get("device_memory")
    default = min(default_limit, 2200 if compact_requested else default_limit)
    try:
        if device_memory_hint and float(device_memory_hint) <= 4:
            default = min(default, 1800)
    except (TypeError, ValueError):
        pass

    max_points = clamp_int(request.args.get("max"), default, 350, OPTIMIZED_ROUTE_HARD_LIMIT)
    all_normalized = normalize_route_points(points, retention_seconds=retention_seconds)
    day_index = route_day_index(all_normalized, fill_last_seven=filter_day)
    selected_day = None
    normalized = all_normalized
    if filter_day:
        requested_day = str(request.args.get("day") or local_day_key())
        try:
            start_ts, end_ts = local_day_bounds(requested_day)
            selected_day = requested_day
        except ValueError:
            selected_day = local_day_key()
            start_ts, end_ts = local_day_bounds(selected_day)
        normalized = [point for point in all_normalized if start_ts <= point["ts"] < end_ts]
    raw_count = len(normalized)

    if not normalized:
        return {
            "title": title,
            "points": [],
            "stays": [],
            "raw_count": 0,
            "display_count": 0,
            "optimized": False,
            "full_limited": False,
            "max_points": max_points,
            "day_index": day_index,
            "selected_day": selected_day,
            "timezone": APP_TIMEZONE_NAME,
            "metrics": route_metrics([], []),
            "geocoding_enabled": GEOCODING_ENABLED,
            "geocoder_attribution": "Adressen © OpenStreetMap-Mitwirkende",
            "server_route_budget": OPTIMIZED_ROUTE_HARD_LIMIT,
        }

    analysis_source = normalized if raw_count <= 25000 else downsample_route_points(normalized, 25000)
    annotated_source, stays = build_stays(analysis_source, 65, 120)
    display_source = annotated_source if len(annotated_source) <= max_points else downsample_route_points(annotated_source, max_points)
    display_points = [route_point_public(p, include_report_id=include_report_ids) for p in display_source]
    metrics = route_metrics(annotated_source, stays)

    return {
        "title": title,
        "points": display_points,
        "stays": stays[:120],
        "raw_count": raw_count,
        "display_count": len(display_points),
        "optimized": len(display_points) < raw_count,
        "full_limited": bool(full_requested and raw_count > len(display_points)),
        "max_points": max_points,
        "day_index": day_index,
        "selected_day": selected_day,
        "timezone": APP_TIMEZONE_NAME,
        "metrics": metrics,
        "geocoding_enabled": GEOCODING_ENABLED,
        "geocoder_attribution": "Adressen © OpenStreetMap-Mitwirkende",
        "server_route_budget": OPTIMIZED_ROUTE_HARD_LIMIT,
    }


def infer_device_kind(name, meta=None):
    meta = meta or {}
    haystack = f"{name} {meta.get('name', '')} {meta.get('emoji', '')}".lower()
    for key, (label, icon) in DEVICE_KIND_HINTS.items():
        if key in haystack:
            return {"key": key, "label": label, "icon": icon}
    emoji = str(meta.get("emoji", ""))
    if emoji in {"📱", "☎️"}:
        return {"key": "iphone", "label": "iPhone / Gerät", "icon": "📱"}
    if emoji in {"🎧", "🎵"}:
        return {"key": "airpods", "label": "AirPods / Audio", "icon": "🎧"}
    if emoji in {"🔑", "🗝️"}:
        return {"key": "keys", "label": "Schlüssel", "icon": "🔑"}
    if emoji in {"🎒", "👜", "💼"}:
        return {"key": "bag", "label": "Tasche", "icon": "🎒"}
    return {"key": "object", "label": "FindMy-Objekt", "icon": meta.get("emoji", "📍")}


def device_public_summary(name, loc_data=None):
    meta = state["tracker_meta"].get(name, {"name": name, "emoji": "📍"})
    accessory = state["accessories"].get(name)
    stats = state["report_stats"].get("devices", {}).get(name, {})
    status = loc_data.get("status") if isinstance(loc_data, dict) else None
    battery_code = loc_data.get("bat") if isinstance(loc_data, dict) else None
    paired_at = getattr(accessory, "paired_at", None) if accessory else None
    if paired_at is not None:
        try:
            paired_at = paired_at.isoformat()
        except Exception:
            paired_at = str(paired_at)
    interval = getattr(accessory, "interval", None) if accessory else None
    if interval is not None:
        try:
            interval = int(interval.total_seconds())
        except Exception:
            interval = None
    return {
        "kind": infer_device_kind(name, meta),
        "class": accessory.__class__.__name__ if accessory else "FindMyAccessory",
        "model": getattr(accessory, "model", None) if accessory else None,
        "serial_number": getattr(accessory, "serial_number", None) if accessory else None,
        "group_identifier": getattr(accessory, "group_identifier", None) if accessory else None,
        "identifier": getattr(accessory, "identifier", None) if accessory else None,
        "paired_at": paired_at,
        "key_interval_seconds": interval,
        "battery_code": battery_code,
        "battery_label": BATTERY_LEVEL_LABELS.get(battery_code, "Unbekannt"),
        "status_hex": f"0x{int(status):02X}" if status is not None else None,
        "confidence": loc_data.get("confidence") if isinstance(loc_data, dict) else None,
        "freshness": freshness_payload(loc_data.get("ts") if isinstance(loc_data, dict) else None),
        "last_report_ts": stats.get("last_report_ts"),
        "last_sync_ts": stats.get("last_sync_ts"),
        "last_mode": stats.get("mode"),
        "total_reports": int(stats.get("total_received", 0) or 0),
        "total_history_points": int(stats.get("total_history_added", 0) or 0),
        "capabilities": [
            "Standort-Reports entschlüsseln",
            "Statusbyte / Akku anzeigen",
            "Standortverlauf mit individueller Aufbewahrung darstellen",
            "Direktnavigation zur Position",
            "Geräte-Metadaten auswerten",
            "Aufenthaltscluster und Adressen analysieren",
        ],
    }


def google_health_probe_worker():
    if not google_setup_lock.acquire(blocking=False):
        google_health_cache["checking"] = False
        return
    try:
        google_health_cache["checking"] = True
        google_dependency_status(force=True)
    finally:
        google_health_cache["checking"] = False
        google_setup_lock.release()


def google_runtime_status():
    tools_path = google_tools_path()
    has_secrets = bool(google_load_secrets())
    source_key = str(tools_path or "")
    checked = (
        google_health_cache.get("source") == source_key
        and google_health_cache.get("python") == google_python_path()
        and time.time() - float(google_health_cache.get("checked_ts", 0) or 0) < 60
    )
    if tools_path and has_secrets and not checked and not google_health_cache.get("checking"):
        google_health_cache["checking"] = True
        threading.Thread(target=google_health_probe_worker, daemon=True).start()
    if checked:
        ready = bool(google_health_cache.get("ready"))
        error = str(google_health_cache.get("error") or "")
    else:
        ready = False
        error = "checking" if tools_path and has_secrets else ("secrets_missing" if tools_path else "tools_missing")
    return {
        "tools_installed": bool(tools_path),
        "tools_path_mode": "configured" if tools_path and tools_path != GOOGLE_TOOLS_DIR else "managed",
        "secrets_uploaded": has_secrets,
        "username": google_masked_username(),
        "ready": ready,
        "checking": bool(google_health_cache.get("checking")),
        "error": error,
        "repository": GOOGLE_TOOLS_REPOSITORY,
        "repository_url": f"https://github.com/{GOOGLE_TOOLS_REPOSITORY}",
        "commit": GOOGLE_TOOLS_COMMIT,
        "tools_meta": google_tools_metadata(),
        "tools_current": google_managed_tools_current(tools_path),
        "python_isolated": str(google_python_path()).startswith(str(GOOGLE_VENV_DIR)),
        "setup": dict(state.get("google_setup", {})),
        "guardian": {
            **dict(state.get("google_auth", {})),
            "secret": google_secret_summary(),
            "auto_repair_enabled": bool(state.get("google_settings", {}).get("auto_repair", GOOGLE_AUTO_REPAIR_DEFAULT)),
            "background_tracking": bool(state.get("google_settings", {}).get("background_tracking", GOOGLE_BACKGROUND_TRACKING_DEFAULT)),
            "adaptive_polling": bool(state.get("google_settings", {}).get("adaptive_polling", GOOGLE_ADAPTIVE_POLLING_DEFAULT)),
            "interactive_reauth_supported": False,
        },
    }


def google_session_summaries(device_id):
    sessions = []
    prefix = google_device_safe_id(device_id)
    for session_file in GOOGLE_SESSIONS_DIR.glob(f"{prefix}_*.json"):
        try:
            with open(session_file, "r", encoding="utf-8") as file:
                data = json.load(file)
            if data.get("device_id") != device_id:
                continue
            sessions.append({
                "id": int(data.get("id") or 0),
                "start": int(data.get("start") or 0),
                "end": int(data.get("end") or data.get("start") or 0),
                "reports": len(data.get("points", [])),
            })
        except Exception:
            continue
    sessions.sort(key=lambda item: item["start"], reverse=True)
    return sessions


def fusion_profile_source_ids(apple_name, raw_profile=None):
    """Resolve provider IDs from both current links and durable fusion profiles.

    Older installations can contain a valid fusion profile after a link file was
    migrated or rebuilt. Reading both stores keeps those existing data sets
    usable without silently rewriting them.
    """
    profile = raw_profile if isinstance(raw_profile, dict) else state.get("fusion_profiles", {}).get(apple_name, {})
    profile = profile if isinstance(profile, dict) else {}
    google_link = google_link_for_apple(apple_name)
    samsung_link = samsung_link_for_apple(apple_name)
    google_id = (google_link or {}).get("google_id") or profile.get("google_id")
    samsung_id = (samsung_link or {}).get("samsung_id") or profile.get("samsung_id")
    if google_id not in state.get("google_devices", {}):
        google_id = None
    if samsung_id not in state.get("samsung_devices", {}):
        samsung_id = None
    return google_id, samsung_id


def fusion_locations(apple_name, apple_location):
    google_id, samsung_id = fusion_profile_source_ids(apple_name)
    google_link = google_link_for_apple(apple_name) or ({"google_id": google_id} if google_id else None)
    samsung_link = samsung_link_for_apple(apple_name) or ({"samsung_id": samsung_id} if samsung_id else None)
    google_location = google_public_location(state.get("google_locations", {}).get(google_id)) if google_id else None
    samsung_location = samsung_public_location(state.get("samsung_locations", {}).get(samsung_id)) if samsung_id else None
    candidates = [location for location in [apple_location, google_location, samsung_location] if location]
    latest = max(candidates, key=lambda item: float(item.get("ts", 0) or 0)) if candidates else None
    if latest:
        latest = dict(latest)
        latest["fusion"] = bool(google_link or samsung_link)
        latest["fusion_level"] = 3 if google_link and samsung_link else (2 if google_link or samsung_link else 1)
    return latest, apple_location, google_location, samsung_location, google_link, samsung_link


def fusion_history_points(apple_name, raw_profile=None):
    apple_raw = state["seven_day_history"].get(apple_name, {"points": []}).get("points", [])
    google_id, samsung_id = fusion_profile_source_ids(apple_name, raw_profile)
    google_raw = state["google_history"].get(google_id, {"points": []}).get("points", []) if google_id else []
    samsung_raw = state["samsung_history"].get(samsung_id, {"points": []}).get("points", []) if samsung_id else []

    def source_signature(points):
        def token(point):
            if not isinstance(point, dict):
                return (0, "")
            return (
                int(float(point.get("ts", 0) or 0)),
                str(point.get("report_id") or point.get("batch_id") or "")[-24:],
            )
        return (
            len(points),
            token(points[0]) if points else (0, ""),
            token(points[-1]) if points else (0, ""),
        )

    storage_policy = fusion_history_storage_policy(apple_name)
    signature = (
        str(google_id or ""),
        str(samsung_id or ""),
        storage_policy.get("mode"),
        storage_policy.get("days"),
        storage_policy.get("updated_ts"),
        source_signature(apple_raw),
        source_signature(google_raw),
        source_signature(samsung_raw),
        local_datetime().date().isoformat(),
    )
    with fusion_history_cache_lock:
        cached = fusion_history_cache_store.get(apple_name)
        if cached and cached.get("signature") == signature:
            return cached["points"]

    apple_points = [
        {**point, "source": point.get("source") or "apple", "provider": point.get("provider") or "Apple Find My"}
        for point in apple_raw
    ]
    google_points = [
        {**point, "source": "google", "provider": "Google Find Hub"}
        for point in google_raw
    ] if google_id else []
    samsung_points = [
        {**point, "source": "samsung", "provider": "Samsung SmartThings Find"}
        for point in samsung_raw
    ] if samsung_id else []
    points = normalize_route_points(
        apple_points + google_points + samsung_points,
        retention_seconds=storage_policy.get("retention_seconds"),
        max_points=history_policy_max_points("apple", storage_policy),
    )
    with fusion_history_cache_lock:
        if len(fusion_history_cache_store) >= 256 and apple_name not in fusion_history_cache_store:
            fusion_history_cache_store.pop(next(iter(fusion_history_cache_store)), None)
        fusion_history_cache_store[apple_name] = {"signature": signature, "points": points}
    return points


FUSION_OPTIMIZATION_WINDOW_SECONDS = 20 * 60
FUSION_OPTIMIZATION_MAX_ACCURACY_METERS = 180
FUSION_OPTIMIZATION_MAX_CLUSTER_METERS = 120
FUSION_OPTIMIZATION_REPORTS_PER_SOURCE = 6


def fusion_profile_source_locations(apple_name, raw_profile=None):
    """Return the latest unmodified provider locations for one fusion."""
    locations = {}
    apple_object = state.get("locations", {}).get(apple_name)
    if apple_object:
        apple_location = location_payload(apple_object)
        cached = address_from_cached(apple_location["lat"], apple_location["lon"])
        if cached:
            apple_location["address"] = cached
        locations["apple"] = apple_location
    google_id, samsung_id = fusion_profile_source_ids(apple_name, raw_profile)
    if google_id:
        google_location = google_public_location(state.get("google_locations", {}).get(google_id))
        if google_location:
            locations["google"] = google_location
    if samsung_id:
        samsung_location = samsung_public_location(state.get("samsung_locations", {}).get(samsung_id))
        if samsung_location:
            locations["samsung"] = samsung_location
    return locations


def fusion_profile_provider_names(apple_name, raw_profile=None):
    providers = ["apple"]
    google_id, samsung_id = fusion_profile_source_ids(apple_name, raw_profile)
    if google_id:
        providers.append("google")
    if samsung_id:
        providers.append("samsung")
    return providers


def fusion_profile_timeline_points(apple_name, history_points=None, raw_profile=None):
    """Combine stored history with the latest snapshot of every provider."""
    points = list(history_points if history_points is not None else fusion_history_points(apple_name, raw_profile))
    for source, raw_location in fusion_profile_source_locations(apple_name, raw_profile).items():
        current = normalize_point({**raw_location, "source": source})
        if not current:
            continue
        duplicate = any(
            point.get("source") == source
            and abs(float(point.get("ts", 0) or 0) - current["ts"]) <= 2
            and haversine_distance(point["lat"], point["lon"], current["lat"], current["lon"]) <= 3
            for point in points
        )
        if not duplicate:
            points.append(current)
    storage_policy = fusion_history_storage_policy(apple_name)
    return normalize_route_points(
        points,
        retention_seconds=storage_policy.get("retention_seconds"),
        max_points=history_policy_max_points("apple", storage_policy),
    )


def fusion_optimization_metadata(enabled, status, message, **extra):
    return {
        "enabled": bool(enabled),
        "active": status == "active",
        "status": status,
        "message": message,
        "window_seconds": FUSION_OPTIMIZATION_WINDOW_SECONDS,
        "quality_gate": "strict",
        **extra,
    }


def fusion_profile_display_location(apple_name, enabled=False, history_points=None, raw_profile=None):
    """Build a conservative, display-only fusion location.

    Raw provider reports remain untouched. A derived center is exposed only
    when recent, good reports from every configured network form a compact
    cluster around the newest report and materially tighten its accuracy.
    """
    source_locations = fusion_profile_source_locations(apple_name, raw_profile)
    required_sources = fusion_profile_provider_names(apple_name, raw_profile)
    candidates_now = [location for location in source_locations.values() if location]
    raw_location = max(candidates_now, key=lambda item: float(item.get("ts", 0) or 0)) if candidates_now else None
    if raw_location:
        raw_location = dict(raw_location)
        raw_location["fusion"] = True
        raw_location["fusion_level"] = len(required_sources)
        raw_location["latest_source"] = raw_location.get("source") or "apple"
        raw_location["optimized"] = False

    if not enabled:
        return raw_location, raw_location, source_locations, fusion_optimization_metadata(
            False,
            "disabled",
            "Standortoptimierung ist ausgeschaltet.",
            required_sources=required_sources,
        )
    if not raw_location:
        return None, None, source_locations, fusion_optimization_metadata(
            True,
            "no_location",
            "Noch kein Netzwerk hat einen Standort geliefert.",
            required_sources=required_sources,
        )

    raw_accuracy = float(raw_location.get("acc", 0) or 0)
    if raw_accuracy <= 0 or classify_point_quality(raw_location) != "good":
        return raw_location, raw_location, source_locations, fusion_optimization_metadata(
            True,
            "latest_not_eligible",
            "Der neueste Report ist für eine sichere Bündelung nicht genau genug.",
            required_sources=required_sources,
            latest_source=raw_location.get("latest_source"),
            raw_accuracy_m=round(raw_accuracy, 1) if raw_accuracy > 0 else None,
        )

    newest_ts = float(raw_location.get("ts", 0) or 0)
    history = list(history_points if history_points is not None else fusion_history_points(apple_name, raw_profile))
    combined = normalize_route_points(
        [*history, *source_locations.values()],
        retention_seconds=FUSION_OPTIMIZATION_WINDOW_SECONDS + 180,
    )
    recent = [
        point
        for point in combined
        if newest_ts - FUSION_OPTIMIZATION_WINDOW_SECONDS <= float(point.get("ts", 0) or 0) <= newest_ts + 90
        and 0 < float(point.get("acc", 0) or 0) <= FUSION_OPTIMIZATION_MAX_ACCURACY_METERS
        and classify_point_quality(point) == "good"
        and point.get("source") in required_sources
    ]
    capped = []
    for source in required_sources:
        source_points = sorted(
            (point for point in recent if point.get("source") == source),
            key=lambda item: float(item.get("ts", 0) or 0),
        )
        capped.extend(source_points[-FUSION_OPTIMIZATION_REPORTS_PER_SOURCE:])
    recent = sorted(capped, key=lambda item: float(item.get("ts", 0) or 0))
    available_sources = sorted({point.get("source") for point in recent if point.get("source")})
    minimum_reports = max(3, len(required_sources))
    if len(recent) < minimum_reports or any(source not in available_sources for source in required_sources):
        return raw_location, raw_location, source_locations, fusion_optimization_metadata(
            True,
            "waiting_for_networks",
            "Es fehlen noch zeitnahe, gute Reports aus allen Netzen.",
            required_sources=required_sources,
            available_sources=available_sources,
            reports_considered=len(recent),
            latest_source=raw_location.get("latest_source"),
            raw_accuracy_m=round(raw_accuracy, 1),
        )

    median_accuracy = median([point.get("acc") for point in recent], raw_accuracy)
    cluster_limit = min(
        FUSION_OPTIMIZATION_MAX_CLUSTER_METERS,
        max(25.0, median_accuracy * 1.55),
    )
    clusters = []
    for seed in recent:
        if haversine_distance(seed["lat"], seed["lon"], raw_location["lat"], raw_location["lon"]) > cluster_limit:
            continue
        members = [
            point
            for point in recent
            if haversine_distance(seed["lat"], seed["lon"], point["lat"], point["lon"]) <= cluster_limit
        ]
        if len(members) < minimum_reports:
            continue
        if any(source not in {point.get("source") for point in members} for source in required_sources):
            continue
        first_center = weighted_center(members)
        members = [
            point
            for point in members
            if haversine_distance(first_center[0], first_center[1], point["lat"], point["lon"]) <= cluster_limit
        ]
        if len(members) < minimum_reports:
            continue
        member_sources = {point.get("source") for point in members}
        if any(source not in member_sources for source in required_sources):
            continue
        if haversine_distance(first_center[0], first_center[1], raw_location["lat"], raw_location["lon"]) > cluster_limit:
            continue
        preliminary_distances = [
            haversine_distance(first_center[0], first_center[1], point["lat"], point["lon"])
            for point in members
        ]
        clusters.append((
            len(member_sources),
            len(members),
            max(float(point.get("ts", 0) or 0) for point in members),
            -float(percentile(preliminary_distances, 0.8, cluster_limit) or cluster_limit),
            members,
        ))
    if not clusters:
        return raw_location, raw_location, source_locations, fusion_optimization_metadata(
            True,
            "spread_too_wide",
            "Die aktuellen Reports liegen noch nicht eng genug beieinander.",
            required_sources=required_sources,
            available_sources=available_sources,
            reports_considered=len(recent),
            cluster_limit_m=round(cluster_limit, 1),
            latest_source=raw_location.get("latest_source"),
            raw_accuracy_m=round(raw_accuracy, 1),
        )

    members = max(clusters, key=lambda item: item[:4])[-1]
    source_aggregates = []
    source_report_counts = {}
    for source in required_sources:
        points = [point for point in members if point.get("source") == source]
        source_report_counts[source] = len(points)
        center_lat, center_lon = weighted_center(points)
        source_accuracy = median([point.get("acc") for point in points], raw_accuracy)
        source_accuracy = max(5.0, source_accuracy / math.sqrt(min(len(points), 4)))
        source_aggregates.append({
            "lat": center_lat,
            "lon": center_lon,
            "acc": source_accuracy,
            "source": source,
            "confidence": 3,
        })
    center_lat, center_lon = weighted_center(source_aggregates)
    distances = [
        haversine_distance(center_lat, center_lon, point["lat"], point["lon"])
        for point in members
    ]
    aggregate_distances = [
        haversine_distance(center_lat, center_lon, point["lat"], point["lon"])
        for point in source_aggregates
    ]
    inverse_variance = sum(1.0 / (max(5.0, float(point["acc"])) ** 2) for point in source_aggregates)
    combined_uncertainty = math.sqrt(1.0 / inverse_variance) if inverse_variance else raw_accuracy
    spread = max(
        float(percentile(distances, 0.8, 0) or 0),
        float(percentile(aggregate_distances, 1.0, 0) or 0),
    )
    optimized_accuracy = max(5.0, combined_uncertainty, spread)
    improvement = 1.0 - (optimized_accuracy / raw_accuracy) if raw_accuracy else 0
    if optimized_accuracy >= raw_accuracy * 0.9:
        return raw_location, raw_location, source_locations, fusion_optimization_metadata(
            True,
            "no_material_gain",
            "Die Bündelung wäre aktuell nicht genauer als der neueste Einzelreport.",
            required_sources=required_sources,
            available_sources=available_sources,
            reports_considered=len(recent),
            reports_used=len(members),
            source_report_counts=source_report_counts,
            spread_m=round(spread, 1),
            raw_accuracy_m=round(raw_accuracy, 1),
            candidate_accuracy_m=round(optimized_accuracy, 1),
            latest_source=raw_location.get("latest_source"),
        )

    optimized = dict(raw_location)
    optimized.update({
        "lat": round(center_lat, 7),
        "lon": round(center_lon, 7),
        "acc": round(optimized_accuracy, 1),
        "source": "fusion",
        "provider": "Fusion-Standortoptimierung",
        "latest_source": raw_location.get("latest_source"),
        "optimized": True,
        "optimization_reports": len(members),
        "optimization_sources": required_sources,
        "raw_accuracy_m": round(raw_accuracy, 1),
    })
    cached = address_from_cached(optimized["lat"], optimized["lon"])
    if cached:
        optimized["address"] = cached
    elif raw_location.get("address") and haversine_distance(
        optimized["lat"], optimized["lon"], raw_location["lat"], raw_location["lon"]
    ) <= max(30, raw_accuracy):
        optimized["address"] = raw_location["address"]
    optimized["freshness"] = freshness_payload(optimized.get("ts"))
    confidence_percent = max(70, min(97, round(92 - (spread / max(cluster_limit, 1)) * 18 + min(len(members), 9))))
    metadata = fusion_optimization_metadata(
        True,
        "active",
        "Mehrere gute, zeitnahe Reports aller Netze wurden sicher gebündelt.",
        required_sources=required_sources,
        available_sources=available_sources,
        reports_considered=len(recent),
        reports_used=len(members),
        source_report_counts=source_report_counts,
        spread_m=round(spread, 1),
        cluster_limit_m=round(cluster_limit, 1),
        raw_accuracy_m=round(raw_accuracy, 1),
        optimized_accuracy_m=round(optimized_accuracy, 1),
        improvement_percent=round(max(0, improvement) * 100, 1),
        confidence_percent=confidence_percent,
        latest_source=raw_location.get("latest_source"),
    )
    return optimized, raw_location, source_locations, metadata


FUSION_PROVIDER_LABELS = {
    "apple": "Apple Find My",
    "google": "Google Find Hub",
    "samsung": "Samsung SmartThings Find",
}


def fusion_test_provider_points(test, provider):
    return normalize_route_points(test.get(f"{provider}_points", []), retention_seconds=None)


def fusion_test_consistency(provider_points, other_points):
    """Median distance to the nearest-in-time report from another provider.

    The devices are expected to move together. Comparing only reports no more
    than ten minutes apart avoids treating the whole travelled route as one
    static location while keeping the calculation fast for long-running tests.
    """
    if not provider_points or not other_points:
        return None
    other_points = sorted(other_points, key=lambda point: float(point.get("ts", 0) or 0))
    other_times = [float(point.get("ts", 0) or 0) for point in other_points]
    stride = max(1, math.ceil(len(provider_points) / 800))
    distances = []
    for point in provider_points[::stride]:
        timestamp = float(point.get("ts", 0) or 0)
        index = bisect_left(other_times, timestamp)
        candidates = []
        if index < len(other_points):
            candidates.append(other_points[index])
        if index:
            candidates.append(other_points[index - 1])
        if not candidates:
            continue
        nearest = min(candidates, key=lambda item: abs(float(item.get("ts", 0) or 0) - timestamp))
        if abs(float(nearest.get("ts", 0) or 0) - timestamp) > 600:
            continue
        distance = haversine_distance(point["lat"], point["lon"], nearest["lat"], nearest["lon"])
        if math.isfinite(distance) and distance <= 100000:
            distances.append(distance)
    return round(median(distances, 0), 1) if distances else None


def fusion_test_winner(metrics, field, lower_is_better=False):
    candidates = {
        provider: values.get(field)
        for provider, values in metrics.items()
        if values.get(field) is not None
    }
    if not candidates:
        return "none"
    target = min(candidates.values()) if lower_is_better else max(candidates.values())
    winners = [provider for provider, value in candidates.items() if value == target]
    return winners[0] if len(winners) == 1 else "tie"


def fusion_test_public(test):
    configured = ["apple"]
    if test.get("google_id"):
        configured.append("google")
    if test.get("samsung_id"):
        configured.append("samsung")
    points_by_provider = {
        provider: fusion_test_provider_points(test, provider)
        for provider in configured
    }
    duration_end = (
        int(time.time())
        if test.get("status") == "active"
        else int(test.get("end") or test.get("updated_ts") or test.get("start") or 0)
    )
    start = int(test.get("start") or duration_end)
    duration_seconds = max(0, duration_end - start)
    metrics = {}
    for provider, points in points_by_provider.items():
        accuracies = [
            float(point.get("acc", 0) or 0)
            for point in points
            if float(point.get("acc", 0) or 0) > 0
        ]
        all_intervals = [
            float(points[index]["ts"]) - float(points[index - 1]["ts"])
            for index in range(1, len(points))
            if 0 < float(points[index]["ts"]) - float(points[index - 1]["ts"])
        ]
        intervals = [interval for interval in all_intervals if interval <= 21600]
        other_points = [
            point
            for other_provider, provider_points in points_by_provider.items()
            if other_provider != provider
            for point in provider_points
        ]
        accuracy_median = median(accuracies, None)
        interval_median = median(intervals, None)
        first_report_ts = int(points[0]["ts"]) if points else None
        latest_report_ts = int(points[-1]["ts"]) if points else None
        active_minutes = len({
            int(float(point.get("ts", 0) or 0) // 60)
            for point in points
            if float(point.get("ts", 0) or 0) > 0
        })
        metrics[provider] = {
            "provider": provider,
            "label": FUSION_PROVIDER_LABELS[provider],
            "reports": len(points),
            "median_accuracy_m": round(accuracy_median, 1) if accuracy_median is not None else None,
            "best_accuracy_m": round(min(accuracies), 1) if accuracies else None,
            "p95_accuracy_m": round(percentile(accuracies, 0.95), 1) if accuracies else None,
            "accuracy_jitter_m": round(
                median([abs(value - accuracy_median) for value in accuracies], 0), 1
            ) if accuracies and accuracy_median is not None else None,
            "reports_under_50m": sum(1 for value in accuracies if value <= 50),
            "reports_under_50m_percent": round(
                sum(1 for value in accuracies if value <= 50) / len(accuracies) * 100, 1
            ) if accuracies else None,
            "median_interval_seconds": round(interval_median, 1) if interval_median is not None else None,
            "interval_jitter_seconds": round(
                median([abs(value - interval_median) for value in intervals], 0), 1
            ) if intervals and interval_median is not None else None,
            "max_gap_seconds": round(max(all_intervals), 1) if all_intervals else None,
            "reports_per_hour": round(len(points) / max(1 / 60, duration_seconds / 3600), 2) if duration_seconds else 0,
            "consistency_m": fusion_test_consistency(points, other_points),
            "first_report_ts": first_report_ts,
            "latest_report_ts": latest_report_ts,
            "first_response_seconds": max(0, first_report_ts - start) if first_report_ts else None,
            "freshness_seconds": max(0, duration_end - latest_report_ts) if latest_report_ts else None,
            "active_minutes": active_minutes,
            "coverage_percent": round(
                min(100.0, active_minutes / max(1.0, duration_seconds / 60) * 100), 1
            ) if duration_seconds else 0,
        }

    max_reports = max((item["reports"] for item in metrics.values()), default=0)
    total_reports = sum(item["reports"] for item in metrics.values())
    accuracy_values = [
        item["median_accuracy_m"]
        for item in metrics.values()
        if item["median_accuracy_m"] is not None
    ]
    consistency_values = [
        item["consistency_m"]
        for item in metrics.values()
        if item["consistency_m"] is not None
    ]
    best_accuracy = min(accuracy_values) if accuracy_values else None
    best_consistency = min(consistency_values) if consistency_values else None
    for item in metrics.values():
        item["network_share_percent"] = round(
            item["reports"] / total_reports * 100, 1
        ) if total_reports else 0
        components = []
        if max_reports:
            components.append((item["reports"] / max_reports, 60))
        if best_accuracy is not None and item["median_accuracy_m"] is not None:
            components.append((best_accuracy / max(best_accuracy, item["median_accuracy_m"]), 25))
        if best_consistency is not None and item["consistency_m"] is not None:
            components.append(((best_consistency + 1) / max(best_consistency + 1, item["consistency_m"] + 1), 15))
        weight = sum(component_weight for _, component_weight in components)
        item["score"] = round(sum(value * component_weight for value, component_weight in components) / weight * 100) if weight else 0

    overall_winner = fusion_test_winner(metrics, "score")
    return {
        "id": str(test.get("id") or ""),
        "name": str(test.get("name") or "Fusion Netzwerktest")[:100],
        "apple_name": str(test.get("apple_name") or ""),
        "google_id": str(test.get("google_id") or "") or None,
        "samsung_id": str(test.get("samsung_id") or "") or None,
        "providers": configured,
        "provider_count": len(configured),
        "status": str(test.get("status") or "saved"),
        "start": start,
        "end": int(test.get("end") or 0) if test.get("end") else None,
        "updated_ts": int(test.get("updated_ts") or start),
        "duration_seconds": duration_seconds,
        "interval_min": int(test.get("interval_min") or GOOGLE_DEFAULT_INTERVAL_MIN),
        "interval_max": int(test.get("interval_max") or GOOGLE_DEFAULT_INTERVAL_MAX),
        "polling_model": "provider_unified",
        "polling": {provider: {"interval_min": provider_poll_window(provider)[0], "interval_max": provider_poll_window(provider)[1]} for provider in configured},
        "total_reports": total_reports,
        "metrics": metrics,
        "report_winner": fusion_test_winner(metrics, "reports"),
        "accuracy_winner": fusion_test_winner(metrics, "median_accuracy_m", lower_is_better=True),
        "consistency_winner": fusion_test_winner(metrics, "consistency_m", lower_is_better=True),
        "overall_winner": overall_winner,
        "colocation_confirmed": bool(test.get("colocation_confirmed")),
        "schema": int(test.get("schema") or 3),
    }


def google_test_public(test):
    apple_points = normalize_route_points(test.get("apple_points", []), retention_seconds=None)
    google_points = normalize_route_points(test.get("google_points", []), retention_seconds=None)
    apple_count = len(apple_points)
    google_count = len(google_points)
    if not apple_count and not google_count:
        winner = "none"
    elif apple_count > google_count:
        winner = "apple"
    elif google_count > apple_count:
        winner = "google"
    else:
        winner = "tie"
    apple_acc = [point.get("acc", 0) for point in apple_points if float(point.get("acc", 0) or 0) > 0]
    google_acc = [point.get("acc", 0) for point in google_points if float(point.get("acc", 0) or 0) > 0]
    duration_end = int(test.get("end") or time.time()) if test.get("status") == "active" else int(test.get("end") or test.get("updated_ts") or test.get("start") or 0)
    return {
        "id": str(test.get("id") or ""),
        "name": str(test.get("name") or "Fusion Test")[:100],
        "apple_name": str(test.get("apple_name") or ""),
        "google_id": str(test.get("google_id") or ""),
        "status": str(test.get("status") or "saved"),
        "start": int(test.get("start") or 0),
        "end": int(test.get("end") or 0) if test.get("end") else None,
        "duration_seconds": max(0, duration_end - int(test.get("start") or duration_end)),
        "apple_reports": apple_count,
        "google_reports": google_count,
        "total_reports": apple_count + google_count,
        "winner": winner,
        "apple_median_accuracy": round(median(apple_acc, 0), 1) if apple_acc else None,
        "google_median_accuracy": round(median(google_acc, 0), 1) if google_acc else None,
        "interval_min": int(test.get("interval_min") or GOOGLE_DEFAULT_INTERVAL_MIN),
        "interval_max": int(test.get("interval_max") or GOOGLE_DEFAULT_INTERVAL_MAX),
    }


def google_device_quality(device_id, location, stats):
    now_ts = time.time()
    age = max(0, now_ts - float((location or {}).get("ts", 0) or 0)) if location else None
    recent = [
        event for event in state.get("google_stats", {}).get("recent_events", [])
        if event.get("device_id") == device_id and now_ts - float(event.get("ts", 0) or 0) <= 24 * 60 * 60
    ]
    reports_24h = sum(int(event.get("received", 0) or 0) for event in recent)
    errors_24h = sum(1 for event in recent if event.get("status") == "error")
    syncs_24h = len(recent)
    success_rate = round(100 * (syncs_24h - errors_24h) / syncs_24h) if syncs_24h else None
    if stats.get("last_error"):
        status = "degraded"
        label = "Abruf gestört"
    elif age is None:
        status = "waiting"
        label = "Wartet auf ersten Standort"
    elif age <= 30 * 60:
        status = "excellent"
        label = "Sehr aktuell"
    elif age <= 3 * 60 * 60:
        status = "good"
        label = "Aktuell"
    elif age <= 12 * 60 * 60:
        status = "stale"
        label = "Wenig Finder-Kontakte"
    else:
        status = "old"
        label = "Standort älter"
    return {
        "status": status,
        "label": label,
        "age_seconds": int(age) if age is not None else None,
        "reports_24h": reports_24h,
        "syncs_24h": syncs_24h,
        "errors_24h": errors_24h,
        "success_rate_24h": success_rate,
        "empty_batches": int(stats.get("empty_batches", 0) or 0),
        "consecutive_empty": int(stats.get("consecutive_empty", 0) or 0),
        "consecutive_failures": int(stats.get("consecutive_failures", 0) or 0),
    }


def google_device_public(device_id, device):
    location = google_public_location(state.get("google_locations", {}).get(device_id))
    history_store = state.get("google_history", {}).get(device_id, {"points": [], "enabled": False})
    storage_policy = history_storage_policy("google", device_id)
    history_points = prune_points(
        history_store.get("points", []),
        storage_policy.get("retention_seconds"),
        history_policy_max_points("google", storage_policy),
    )
    if device_id in state.get("google_history", {}):
        state["google_history"][device_id]["points"] = history_points
    minimum, maximum = google_interval_for(device_id)
    link = google_link_for_device(device_id)
    stats = state.get("google_stats", {}).get("devices", {}).get(device_id, {})
    device_settings = state.get("google_settings", {}).get("devices", {}).get(device_id, {})
    return {
        **device,
        "hidden": bool(device_settings.get("hidden", False)),
        "location": location,
        "history_enabled": bool(history_direct_policy("google", device_id).get("enabled")),
        "history_policy": history_policy_public("google", device_id),
        "history_count": len(history_points),
        "history_days": route_day_index(history_points, fill_last_seven=True),
        "is_recording": device_id in state.get("google_recordings", {}),
        "sessions": google_session_summaries(device_id),
        "interval_min": minimum,
        "interval_max": maximum,
        "active_reasons": google_active_reasons(device_id),
        "next_fetch_ts": int(state.get("google_next_fetch", {}).get(device_id, 0) or 0),
        "inflight": device_id in state.get("google_inflight", set()),
        "queued": device_id in state.get("google_pending_fetch", {}),
        "linked_apple": link.get("apple_name") if link else None,
        "report_stats": stats,
        "quality": google_device_quality(device_id, location, stats),
        "battery": (device.get("battery_info") or {}).get("label") or "Nicht vom Google-Upstream bereitgestellt",
        "battery_info": device.get("battery_info") if isinstance(device.get("battery_info"), dict) else None,
        "custom_mcu": bool(device.get("custom_mcu", False)),
    }


