def mcp_tracker_refs_for_model(model):
    refs = []
    for ref in mcp_model_source_refs(model) if isinstance(model, dict) else []:
        normalized = normalize_tracker_ref(ref)
        if normalized and normalized not in refs:
            refs.append(normalized)
    return refs


def mcp_place_catalog(tracker_refs=None, include_saved=True):
    """Build a private place catalog with tracker-scoped geofences."""
    scope = {normalize_tracker_ref(ref) for ref in (tracker_refs or []) if normalize_tracker_ref(ref)}
    rows = []
    for fence in state.get("geofences", {}).values():
        if not isinstance(fence, dict) or fence.get("enabled") is False:
            continue
        fence_refs = {normalize_tracker_ref(ref) for ref in (fence.get("tracker_refs") or []) if normalize_tracker_ref(ref)}
        if scope and fence_refs and not (scope & fence_refs):
            continue
        rows.append({
            "id": str(fence.get("id") or ""),
            "kind": "geofence",
            "label": str(fence.get("label") or "Geofence")[:100],
            "emoji": str(fence.get("emoji") or "📍")[:16],
            "latitude": float(fence.get("lat", 0) or 0),
            "longitude": float(fence.get("lon", 0) or 0),
            "radius_m": max(10.0, float(fence.get("radius", 100) or 100)),
            "tracker_refs": sorted(fence_refs),
            "notify_enter": bool(fence.get("notify_enter")),
            "notify_exit": bool(fence.get("notify_exit")),
        })
    if include_saved:
        for place in state.get("saved_places", {}).values():
            if not isinstance(place, dict):
                continue
            try:
                lat = float(place.get("lat")); lon = float(place.get("lon"))
            except (TypeError, ValueError):
                continue
            rows.append({
                "id": str(place.get("id") or ""),
                "kind": "saved_place",
                "label": str(place.get("label") or "Gespeicherter Ort")[:100],
                "emoji": str(place.get("emoji") or "📍")[:16],
                "latitude": lat,
                "longitude": lon,
                "radius_m": max(10.0, float(place.get("radius", 100) or 100)),
                "tracker_refs": [],
                "note": str(place.get("note") or "")[:240],
            })
    return rows


def mcp_zone_public(zone, include_id=True):
    row = {
        "kind": str(zone.get("kind") or "place"),
        "label": str(zone.get("label") or "Ort")[:100],
        "emoji": str(zone.get("emoji") or "📍")[:16],
        "latitude": round(float(zone.get("latitude", 0) or 0), 7),
        "longitude": round(float(zone.get("longitude", 0) or 0), 7),
        "radius_m": round(float(zone.get("radius_m", 100) or 100), 1),
    }
    if include_id:
        row["id"] = str(zone.get("id") or "")
    if zone.get("note"):
        row["note"] = str(zone.get("note"))[:240]
    return row


def mcp_location_zone_context(location, tracker_refs=None, zones=None, public_guest=False):
    point = normalize_point(location) if isinstance(location, dict) else None
    if not point:
        return {"inside": [], "nearby": [], "nearest": None}
    candidates = zones if isinstance(zones, list) else mcp_place_catalog(tracker_refs)
    assessed = []
    accuracy = max(0.0, float(point.get("acc", 0) or 0))
    for zone in candidates:
        try:
            distance = haversine_distance(point["lat"], point["lon"], float(zone["latitude"]), float(zone["longitude"]))
            radius = max(10.0, float(zone.get("radius_m", 100) or 100))
        except (KeyError, TypeError, ValueError):
            continue
        strict_inside = distance <= radius
        possible_inside = not strict_inside and distance <= radius + min(accuracy, max(25.0, radius * 0.5))
        public_zone = mcp_zone_public(zone, include_id=not public_guest)
        if public_guest:
            for private_key in ("id", "latitude", "longitude", "note"):
                public_zone.pop(private_key, None)
        row = {
            **public_zone,
            "distance_to_center_m": round(distance, 1),
            "distance_to_boundary_m": round(distance - radius, 1),
            "membership": "inside" if strict_inside else ("possibly_inside" if possible_inside else ("nearby" if distance <= radius + 500 else "outside")),
            "strict_inside": strict_inside,
            "accuracy_considered_m": round(accuracy, 1),
        }
        assessed.append(row)
    assessed.sort(key=lambda row: float(row.get("distance_to_boundary_m", 0)))
    inside = [row for row in assessed if row["membership"] in {"inside", "possibly_inside"}]
    nearby = [row for row in assessed if row["membership"] == "nearby"][:3]
    nearest = assessed[0] if assessed else None
    return {
        "inside": inside,
        "nearby": nearby,
        "nearest": nearest,
        "summary": (
            f"Im Bereich {inside[0]['label']}" if inside and inside[0]["membership"] == "inside"
            else (f"Möglicherweise im Bereich {inside[0]['label']} (GPS-Genauigkeit beachten)" if inside else (f"Nächster gespeicherter Ort: {nearest['label']}" if nearest else "Kein gespeicherter Ort"))
        ),
    }


def mcp_resolve_place(reference, tracker_refs=None, zones=None):
    query = mcp_normalize_tracker_text(reference)
    if not query:
        raise MCPToolError("Bitte einen Geofence oder gespeicherten Ort angeben.")
    candidates = zones if isinstance(zones, list) else mcp_place_catalog(tracker_refs)
    ranked = []
    for zone in candidates:
        label = mcp_normalize_tracker_text(zone.get("label"))
        identifier = mcp_normalize_tracker_text(zone.get("id"))
        if query in {label, identifier}:
            score = 1.0
        elif query in label or label in query:
            score = 0.82 + 0.15 * min(len(query), len(label)) / max(1, max(len(query), len(label)))
        else:
            score = difflib.SequenceMatcher(None, query, label).ratio()
        if score >= 0.35:
            ranked.append((score, zone))
    ranked.sort(key=lambda item: (-item[0], str(item[1].get("label") or "").casefold()))
    if not ranked or ranked[0][0] < 0.50:
        suggestions = ", ".join(str(item[1].get("label")) for item in ranked[:5])
        raise MCPToolError(f"Ort ‚{reference}‘ wurde nicht gefunden." + (f" Mögliche Orte: {suggestions}." if suggestions else ""), "not_found")
    if len(ranked) > 1 and ranked[0][0] - ranked[1][0] < 0.12 and ranked[0][0] < 0.95:
        choices = ", ".join(f"{item[1].get('label')} ({item[1].get('kind')})" for item in ranked[:6])
        raise MCPToolError(f"Ortsbezeichnung ist nicht eindeutig: {choices}", "ambiguous")
    return ranked[0][1]


def mcp_visit_segments(points, zone):
    points = sorted((normalize_point(point) for point in points if isinstance(point, dict)), key=lambda point: point["ts"] if point else 0)
    points = [point for point in points if point]
    radius = max(10.0, float(zone.get("radius_m", 100) or 100))
    visits, current = [], None
    previous = None
    for point in points:
        distance = haversine_distance(point["lat"], point["lon"], float(zone["latitude"]), float(zone["longitude"]))
        tolerance = min(max(0.0, float(point.get("acc", 0) or 0)), max(25.0, radius * 0.5))
        inside = distance <= radius + tolerance
        if inside:
            if current is None or point["ts"] - current["last_ts"] > 2 * 60 * 60:
                if current:
                    visits.append(current)
                current = {
                    "first_ts": int(point["ts"]), "last_ts": int(point["ts"]), "report_count": 1,
                    "min_distance_m": distance, "previous_outside_ts": int(previous["ts"]) if previous else None,
                }
            else:
                current["last_ts"] = int(point["ts"])
                current["report_count"] += 1
                current["min_distance_m"] = min(current["min_distance_m"], distance)
        elif current:
            current["next_outside_ts"] = int(point["ts"])
            visits.append(current)
            current = None
        previous = point
    if current:
        visits.append(current)
    result = []
    for index, visit in enumerate(visits, 1):
        duration = max(0, visit["last_ts"] - visit["first_ts"])
        confirmed = visit["report_count"] >= 2 and duration > 0
        result.append({
            "visit_number": index,
            "first_inside_ts": visit["first_ts"],
            "first_inside_local": local_datetime(visit["first_ts"]).isoformat(),
            "last_inside_ts": visit["last_ts"],
            "last_inside_local": local_datetime(visit["last_ts"]).isoformat(),
            "observed_duration_seconds": duration,
            "observed_duration_text": mcp_human_duration(duration),
            "report_count": visit["report_count"],
            "confirmed_visit": confirmed,
            "min_distance_to_center_m": round(visit["min_distance_m"], 1),
            "arrival_window_start_ts": visit.get("previous_outside_ts"),
            "departure_window_end_ts": visit.get("next_outside_ts"),
        })
    return result


def mcp_parse_clock(value):
    text = str(value or "").strip()
    if not text:
        return None
    match = re.fullmatch(r"([01]?\d|2[0-3]):([0-5]\d)", text)
    if not match:
        raise MCPToolError("expected_start muss als lokale Uhrzeit HH:MM angegeben werden.")
    return int(match.group(1)), int(match.group(2))


def mcp_visit_report(points, zone, expected_start="", grace_minutes=0):
    visits = mcp_visit_segments(points, zone)
    per_day = defaultdict(list)
    for visit in visits:
        day = local_datetime(visit["first_inside_ts"]).date().isoformat()
        per_day[day].append(visit)
    expected = mcp_parse_clock(expected_start)
    days = []
    for day, day_visits in sorted(per_day.items()):
        first = min(day_visits, key=lambda row: row["first_inside_ts"])
        schedule = None
        if expected:
            day_date = datetime.strptime(day, "%Y-%m-%d").date()
            scheduled = datetime(day_date.year, day_date.month, day_date.day, expected[0], expected[1], tzinfo=APP_TIMEZONE)
            grace = max(0, min(240, int(grace_minutes or 0)))
            delta = int(first["first_inside_ts"] - scheduled.timestamp())
            schedule = {
                "expected_start_local": scheduled.isoformat(),
                "grace_minutes": grace,
                "observed_first_inside_local": first["first_inside_local"],
                "difference_minutes": round(delta / 60, 1),
                "status": "late" if delta > grace * 60 else ("on_time" if delta >= -6 * 3600 else "early_observation"),
                "late_by_minutes": round(max(0, delta - grace * 60) / 60, 1),
            }
        days.append({
            "date": day,
            "visit_count": len(day_visits),
            "confirmed_visit_count": sum(1 for row in day_visits if row.get("confirmed_visit")),
            "visits": day_visits,
            "schedule_assessment": schedule,
        })
    return {
        "place": mcp_zone_public(zone),
        "visited": bool(visits),
        "visit_count": len(visits),
        "confirmed_visit_count": sum(1 for row in visits if row.get("confirmed_visit")),
        "days": days,
        "interpretation": "Aus Tracker-Meldungen abgeleitete Beobachtung; kein Beweis, dass eine Person tatsächlich ankam oder den Ort verließ.",
    }


def mcp_direction_label(bearing):
    labels = ["Norden", "Nordosten", "Osten", "Südosten", "Süden", "Südwesten", "Westen", "Nordwesten"]
    return labels[int((float(bearing) + 22.5) // 45) % 8]


def mcp_motion_insight(points, privacy=None):
    normalized = [normalize_point(point) for point in points if isinstance(point, dict)]
    normalized = sorted({point_identity(point): point for point in normalized if point}.values(), key=lambda point: point["ts"])
    normalized = [point for point in normalized if not point.get("is_outlier")][-12:]
    result = {
        "prediction_available": False,
        "classification": "insufficient_data",
        "confidence": 0.0,
        "point_count": len(normalized),
        "disclaimer": "Heuristische Bewegungsauswertung aus Crowd-Reports; keine garantierte Route oder Zukunftsposition.",
    }
    if len(normalized) < 3:
        return result
    first, latest = normalized[0], normalized[-1]
    span = max(0.0, latest["ts"] - first["ts"])
    displacement = haversine_distance(first["lat"], first["lon"], latest["lat"], latest["lon"])
    accuracies = [max(0.0, float(point.get("acc", 0) or 0)) for point in normalized]
    median_accuracy = median(accuracies, 0)
    result.update({
        "span_seconds": int(span),
        "displacement_m": round(displacement, 1),
        "median_accuracy_m": round(median_accuracy, 1),
        "latest_ts": int(latest["ts"]),
        "latest_local": local_datetime(latest["ts"]).isoformat(),
    })
    stationary_threshold = max(75.0, median_accuracy * 1.5)
    if span < 120 or displacement <= stationary_threshold:
        result.update({"classification": "stationary_or_unclear", "confidence": 0.65 if span >= 300 else 0.35})
        return result
    segments = []
    for left, right in zip(normalized, normalized[1:]):
        dt = right["ts"] - left["ts"]
        if not 20 <= dt <= 3600:
            continue
        distance = haversine_distance(left["lat"], left["lon"], right["lat"], right["lon"])
        speed = distance / dt
        if speed <= 55:
            segments.append((speed, recovery_bearing(left["lat"], left["lon"], right["lat"], right["lon"]), distance, dt))
    if len(segments) < 2:
        result["classification"] = "movement_detected_no_prediction"
        return result
    speed = median([segment[0] for segment in segments], 0)
    x = sum(math.cos(math.radians(segment[1])) for segment in segments)
    y = sum(math.sin(math.radians(segment[1])) for segment in segments)
    bearing = (math.degrees(math.atan2(y, x)) + 360) % 360
    concentration = math.hypot(x, y) / len(segments)
    age = max(0, time.time() - latest["ts"])
    confidence = max(0.0, min(0.95, 0.25 + 0.35 * concentration + min(0.2, len(segments) * 0.04) + (0.15 if median_accuracy <= 100 else 0) - min(0.35, age / 7200)))
    result.update({
        "classification": "moving",
        "speed_kmh": round(speed * 3.6, 1),
        "bearing_degrees": round(bearing, 1),
        "direction": mcp_direction_label(bearing),
        "direction_consistency": round(concentration, 2),
        "confidence": round(confidence, 2),
    })
    if age > 15 * 60 or median_accuracy > 250 or concentration < 0.58 or speed < 0.35 or confidence < 0.58:
        result["classification"] = "movement_detected_prediction_withheld"
        return result
    estimates = []
    for minutes in (5, 15, 30):
        lat, lon = recovery_destination(latest["lat"], latest["lon"], bearing, speed * minutes * 60)
        if privacy and str(privacy.get("location_precision") or "exact") != "exact":
            lat, lon, _ = _privacy_round_coordinates(lat, lon, str(privacy.get("location_precision")))
        estimates.append({
            "minutes_ahead": minutes,
            "latitude": round(lat, 7),
            "longitude": round(lon, 7),
            "uncertainty_radius_m": round(max(150.0, median_accuracy + minutes * 60 * speed * (1.05 - confidence)), 1),
        })
    result["prediction_available"] = True
    result["estimates"] = estimates
    return result


def mcp_compare_tracker_rows(rows):
    comparisons = []
    for index, left in enumerate(rows):
        for right in rows[index + 1:]:
            left_loc, right_loc = left.get("location"), right.get("location")
            if not left_loc or not right_loc:
                comparisons.append({"left_ref": left.get("ref"), "right_ref": right.get("ref"), "status": "location_missing"})
                continue
            distance = haversine_distance(left_loc["latitude"], left_loc["longitude"], right_loc["latitude"], right_loc["longitude"])
            uncertainty = float(left_loc.get("accuracy_m", 0) or 0) + float(right_loc.get("accuracy_m", 0) or 0)
            time_gap = abs(int(left_loc.get("timestamp", 0) or 0) - int(right_loc.get("timestamp", 0) or 0))
            comparisons.append({
                "left_ref": left.get("ref"), "left_name": left.get("name"),
                "right_ref": right.get("ref"), "right_name": right.get("name"),
                "distance_m": round(distance, 1), "time_gap_seconds": time_gap,
                "combined_accuracy_m": round(uncertainty, 1),
                "likely_same_place": bool(time_gap <= 30 * 60 and distance <= max(100.0, uncertainty)),
                "status": "comparable" if time_gap <= 2 * 3600 else "timestamps_too_far_apart",
            })
    return comparisons


def mcp_guest_entries(grant):
    entries = []
    for link_id in mcp_valid_guest_bindings(grant, prune=True):
        link = state.get("shared_links", {}).get(link_id)
        if share_link_status(link) != "active":
            continue
        name = str(link.get("device") or "")
        if not name:
            continue
        raw_meta = state.get("tracker_meta", {}).get(name, {})
        meta = raw_meta if isinstance(raw_meta, dict) else {}
        google_id, samsung_id = fusion_profile_source_ids(name)
        refs = [f"apple:{name}"]
        if google_id:
            refs.append(f"google:{google_id}")
        if samsung_id:
            refs.append(f"samsung:{samsung_id}")
        entries.append({
            "link_id": link_id,
            "link": link,
            "ref": mcp_guest_ref(link_id),
            "name": str(meta.get("name") or name)[:80],
            "emoji": str(meta.get("emoji") or "📍")[:16],
            "kind": str(meta.get("kind") or "")[:40],
            "device": name,
            "source_refs": refs,
            "permissions": share_permissions(link, history_fallback=bool(state.get("share_history_enabled", {}).get(name))),
            "privacy": share_privacy_config(link),
            "expires_ts": int(float(link.get("expires_ts", 0) or 0)),
            "provider_count": len(refs),
        })
    entries.sort(key=lambda row: row["name"].casefold())
    return entries


def mcp_guest_resolve_entry(grant, reference):
    entries = mcp_guest_entries(grant)
    query_raw = str(reference or "").strip()
    query = mcp_normalize_tracker_text(query_raw)
    if not query:
        if len(entries) == 1:
            return entries[0]
        raise MCPToolError("Bitte einen freigegebenen Tracker angeben.")
    exact = [entry for entry in entries if query_raw.casefold() == entry["ref"].casefold() or query == mcp_normalize_tracker_text(entry["name"])]
    if len(exact) == 1:
        return exact[0]
    ranked = []
    for entry in entries:
        label = mcp_normalize_tracker_text(entry["name"])
        score = difflib.SequenceMatcher(None, query, label).ratio()
        if query in label or label in query:
            score = max(score, 0.82)
        ranked.append((score, entry))
    ranked.sort(key=lambda item: (-item[0], item[1]["name"].casefold()))
    if not ranked or ranked[0][0] < 0.50:
        choices = ", ".join(f"{entry['name']} ({entry['ref']})" for entry in entries)
        raise MCPToolError(f"Freigegebener Tracker wurde nicht gefunden." + (f" Verfügbar: {choices}." if choices else ""), "not_found")
    if len(ranked) > 1 and ranked[0][0] - ranked[1][0] < 0.12:
        choices = ", ".join(f"{entry['name']} ({entry['ref']})" for _, entry in ranked[:8])
        raise MCPToolError(f"Tracker ist nicht eindeutig. Bitte auswählen: {choices}", "ambiguous")
    return ranked[0][1]


def mcp_guest_current_sources(entry):
    raw = shared_current_source_locations(entry["device"])
    raw = delayed_share_source_locations(entry["device"], entry["link"], raw)
    permissions, privacy = entry["permissions"], entry["privacy"]
    public = {}
    for source, location in raw.items():
        if source not in {"apple", "google", "samsung"} or not location:
            continue
        payload = shared_location_payload(location, permissions, privacy)
        if payload:
            payload["source"] = source if permissions.get("show_provider", True) else "tracker"
            payload["provider"] = payload["source"]
            public_key = source if permissions.get("show_provider", True) else "tracker"
            if public_key != "tracker" or public_key not in public or float(payload.get("ts", 0) or 0) > float(public[public_key].get("ts", 0) or 0):
                public[public_key] = payload
    return public


def mcp_guest_entry_row(entry, detailed=False):
    sources = mcp_guest_current_sources(entry)
    location = max(sources.values(), key=lambda row: float(row.get("ts", 0) or 0), default=None)
    clean_location = mcp_clean_location(location)
    row = {
        "ref": entry["ref"],
        "name": entry["name"],
        "emoji": entry["emoji"],
        "kind": entry["kind"],
        # Keep the provider value compatible with the existing ChatGPT map
        # widget without revealing an individual network when the owner hid it.
        "provider": "fusion",
        "provider_count": entry["provider_count"] if entry["permissions"].get("show_provider", True) else 1,
        "location": clean_location,
        "last_seen_ts": int(float((location or {}).get("ts", 0) or 0)),
        "permissions": dict(entry["permissions"]),
        "privacy": dict(entry["privacy"]),
        "expires_ts": entry["expires_ts"],
        "expires_local": local_datetime(entry["expires_ts"]).isoformat() if entry["expires_ts"] else None,
    }
    if detailed:
        row["source_locations"] = {source: mcp_clean_location(value) for source, value in sources.items()}
        row["current_place"] = {
            "last_seen_age_seconds": max(0, int(time.time() - row["last_seen_ts"])) if row["last_seen_ts"] else None,
            "interpretation": "Letzte freigegebene Tracker-Meldung; keine Echtzeit-Anwesenheitsgarantie.",
        }
        if clean_location and entry["permissions"].get("show_geofences"):
            zones = mcp_place_catalog(entry["source_refs"])
            row["current_place"]["geofence_context"] = mcp_location_zone_context(location, entry["source_refs"], zones, public_guest=True)
    return row


def mcp_guest_history_points(entry, arguments):
    if not entry["permissions"].get("show_history"):
        raise MCPToolError("Der Besitzer hat den Verlauf für diesen Freigabelink nicht freigegeben.", "forbidden")
    window = mcp_time_window(arguments or {})
    cutoff = time.time() - int(entry["privacy"].get("history_hours", 168) or 168) * 3600
    delay_cutoff = time.time() - int(entry["privacy"].get("delay_minutes", 0) or 0) * 60
    unique = {}
    for raw in shared_fusion_history_points(entry["device"], entry["link"]):
        point = normalize_point(raw) if isinstance(raw, dict) else None
        if not point or point["ts"] < cutoff or point["ts"] > delay_cutoff:
            continue
        if not window["since_ts"] <= point["ts"] <= window["until_ts"]:
            continue
        public = shared_location_payload({**raw, **point}, entry["permissions"], entry["privacy"])
        public_point = normalize_point(public) if isinstance(public, dict) else None
        if not public_point:
            continue
        public_point["source"] = str(public.get("source") or public.get("provider") or "tracker") if entry["permissions"].get("show_provider", True) else "tracker"
        public_point["provider"] = public_point["source"]
        if isinstance(public.get("address"), dict):
            public_point["address"] = public["address"]
        unique[point_identity(public_point)] = public_point
    return sorted(unique.values(), key=lambda point: point["ts"])


def mcp_guest_history_payload(entry, arguments):
    points = mcp_guest_history_points(entry, arguments)
    min_stay = float_range((arguments or {}).get("min_stay_minutes"), 3, 1, 180)
    analyzed, stays = build_stays(points if len(points) <= 25000 else downsample_route_points(points, 25000), 70, min_stay * 60)
    observations = mcp_observation_clusters(analyzed, stays, int_range((arguments or {}).get("observation_limit"), 20, 1, 50))
    include_points = bool_from_any((arguments or {}).get("include_points"), True)
    limit = int_range((arguments or {}).get("limit"), 250, 1, 2000)
    public_points = []
    if include_points:
        for point in reversed(points[-limit:]):
            location = mcp_clean_location(point)
            if location:
                public_points.append(location)
    return {
        "tracker": mcp_guest_entry_row(entry, False),
        "window": mcp_time_window(arguments or {}),
        "point_count": len(points),
        "points": public_points,
        "stays": [mcp_stay_public(stay) for stay in stays],
        "observations": [mcp_stay_public(row, "single_or_clustered_observation") for row in observations],
        "places": mcp_places_from_stays(stays),
        "route_distance_m": round(route_distance(points), 1),
        "interpretation": "Nur der vom Besitzer freigegebene und gegebenenfalls verzögerte/gerundete Verlauf.",
    }


def mcp_guest_locate(entry, arguments=None):
    if not entry["permissions"].get("can_locate"):
        raise MCPToolError("Der Besitzer hat Live-Aktualisierungen für diesen Link deaktiviert.", "forbidden")
    link = entry["link"]
    now_ts = int(time.time())
    with state_lock:
        last_ts = int(float(link.get("last_locate_ts", 0) or 0))
        remaining = MCP_GUEST_LOCATE_COOLDOWN_SECONDS - (now_ts - last_ts)
        if remaining <= 0:
            link["last_locate_ts"] = now_ts
    if remaining > 0:
        return {"status": "cooldown", "remaining_seconds": remaining, "tracker": mcp_guest_entry_row(entry, True)}
    save_json(LINKS_FILE, "shared_links")
    before = {ref: mcp_location_signature(ref) for ref in entry["source_refs"]}
    providers = []
    apple_name = entry["device"]
    if apple_name in state.get("accessories", {}) and state.get("account"):
        providers.append("apple")
        threading.Thread(target=fetch_from_apple, args=([apple_name], "mcp_guest_live"), daemon=True).start()
    google_id, samsung_id = fusion_profile_source_ids(apple_name)
    if google_id:
        providers.append("google")
        threading.Thread(target=fetch_from_google, args=(google_id, "mcp_guest_live"), daemon=True).start()
    if samsung_id:
        providers.append("samsung")
        threading.Thread(target=fetch_from_samsung, args=(samsung_id, "mcp_guest_live"), daemon=True).start()
    wait_seconds = int_range((arguments or {}).get("wait_seconds"), 35, 0, MCP_LIVE_MAX_WAIT_SECONDS)
    deadline = time.monotonic() + wait_seconds
    changed = False
    while wait_seconds and time.monotonic() < deadline:
        changed = any(mcp_location_signature(ref) != before.get(ref) for ref in entry["source_refs"])
        if changed:
            break
        if providers and not any(mcp_source_inflight(ref) for ref in entry["source_refs"]):
            break
        threading.Event().wait(0.25)
    return {
        "status": "updated" if changed else ("requested" if providers else "provider_unavailable"),
        "providers_requested": providers if entry["permissions"].get("show_provider", True) else (["tracker"] if providers else []),
        "new_report": changed,
        "next_locate_ts": now_ts + MCP_GUEST_LOCATE_COOLDOWN_SECONDS,
        "tracker": mcp_guest_entry_row(entry, True),
    }


def mcp_guest_add_link(grant, arguments):
    if not bool_from_any(arguments.get("confirmed"), False):
        raise MCPToolError("Das Hinzufügen des Freigabelinks benötigt confirmed=true.", "confirmation_required")
    link_id = mcp_parse_share_reference(arguments.get("share_link"))
    link = state.get("shared_links", {}).get(link_id)
    key = f"mcp-add-share:{client_key()}:{hashlib.sha256(link_id.encode('utf-8')).hexdigest()[:12]}"
    if is_share_rate_limited(key):
        raise MCPToolError("Zu viele Fehlversuche. Bitte später erneut versuchen.", "rate_limited")
    if share_link_status(link) != "active" or not verify_shared_password(link or {}, arguments.get("password")):
        register_share_failure(key)
        raise MCPToolError("Freigabelink oder Link-Passwort ist nicht gültig.", "forbidden")
    clear_share_failures(key)
    bindings = dict(mcp_valid_guest_bindings(grant, prune=True))
    if link_id not in bindings and len(bindings) >= MCP_GUEST_LINK_LIMIT:
        raise MCPToolError(f"Maximal {MCP_GUEST_LINK_LIMIT} Freigabelinks pro ChatGPT-Verbindung.", "limit_exceeded")
    bindings[link_id] = mcp_share_binding(link_id, link)
    mcp_update_grant_family(grant, bindings)
    mcp_audit_event("guest_link_added", client_id=grant.get("client_id"), detail=hashlib.sha256(link_id.encode()).hexdigest()[:12])
    return {"status": "ok", "added": mcp_guest_ref(link_id), "trackers": [mcp_guest_entry_row(entry, False) for entry in mcp_guest_entries(grant)]}


def mcp_guest_remove_link(grant, arguments):
    if not bool_from_any(arguments.get("confirmed"), False):
        raise MCPToolError("Das Entfernen des Freigabelinks benötigt confirmed=true.", "confirmation_required")
    entry = mcp_guest_resolve_entry(grant, arguments.get("tracker"))
    bindings = dict(mcp_valid_guest_bindings(grant, prune=True))
    bindings.pop(entry["link_id"], None)
    mcp_update_grant_family(grant, bindings)
    mcp_audit_event("guest_link_removed", client_id=grant.get("client_id"), detail=hashlib.sha256(entry["link_id"].encode()).hexdigest()[:12])
    return {"status": "ok", "removed": entry["ref"], "remaining_count": len(bindings), "reauthorization_required_next_call": not bool(bindings)}


