def mcp_data_quality_row(model):
    now_ts = time.time()
    points = []
    for raw in mcp_raw_history(model):
        point = normalize_point(raw) if isinstance(raw, dict) else None
        if point and point["ts"] >= now_ts - 24 * 3600:
            points.append({**raw, **point})
    location = normalize_point(model.get("location")) if isinstance(model.get("location"), dict) else None
    if location and location["ts"] >= now_ts - 24 * 3600:
        points.append(location)
    points = list({point_identity(point): point for point in points}.values())
    accuracies = [float(point.get("acc", 0) or 0) for point in points if float(point.get("acc", 0) or 0) > 0]
    sources = defaultdict(int)
    for point in points:
        sources[str(point.get("source") or point.get("provider") or model.get("provider") or "unknown")] += 1
    latest = max((point["ts"] for point in points), default=float((model.get("location") or {}).get("ts", 0) or 0))
    score = 0
    score += min(35, len(points) * 3)
    score += 25 if latest and now_ts - latest <= 15 * 60 else (15 if latest and now_ts - latest <= 3600 else 0)
    score += 25 if accuracies and median(accuracies, 99999) <= 100 else (12 if accuracies and median(accuracies, 99999) <= 500 else 0)
    score += min(15, len(sources) * 5)
    return {
        "ref": model.get("ref"), "name": model.get("name"), "provider": model.get("provider"),
        "reports_24h": len(points), "networks_24h": dict(sources),
        "median_accuracy_m": round(median(accuracies, 0), 1) if accuracies else None,
        "latest_report_ts": int(latest or 0),
        "latest_age_seconds": max(0, int(now_ts - latest)) if latest else None,
        "outlier_count": sum(1 for point in points if point.get("is_outlier")),
        "quality_score": max(0, min(100, score)),
        "interpretation": "Technische Reportqualität, keine Aussage über die Qualität des Crowd-Netzes außerhalb der beobachteten Meldungen.",
    }


def mcp_owner_share_status(arguments=None):
    filter_model = mcp_resolve_tracker((arguments or {}).get("tracker")) if (arguments or {}).get("tracker") else None
    filter_devices = set()
    if filter_model:
        filter_devices.add(str(filter_model.get("id") or ""))
        if filter_model.get("provider") == "fusion":
            filter_devices.add(str(filter_model.get("id") or ""))
    guest_bindings = defaultdict(int)
    for row in state.get("mcp_oauth", {}).get("refresh_tokens", {}).values():
        if not isinstance(row, dict) or mcp_grant_principal(row) != "guest":
            continue
        for link_id in mcp_valid_guest_bindings(row):
            guest_bindings[link_id] += 1
    rows = []
    for link_id, link in state.get("shared_links", {}).items():
        if not isinstance(link, dict) or (filter_devices and str(link.get("device") or "") not in filter_devices):
            continue
        meta = state.get("tracker_meta", {}).get(link.get("device"), {})
        rows.append({
            "share_ref": mcp_guest_ref(link_id),
            "tracker_name": str((meta or {}).get("name") or link.get("device") or "Tracker")[:80],
            "status": share_link_status(link),
            "permissions": share_permissions(link, history_fallback=bool(state.get("share_history_enabled", {}).get(link.get("device")))),
            "privacy": share_privacy_config(link),
            "created_ts": int(float(link.get("created_ts", 0) or 0)),
            "expires_ts": int(float(link.get("expires_ts", 0) or 0)),
            "web_access_count": int(link.get("access_count", 0) or 0),
            "mcp_guest_grants": guest_bindings.get(link_id, 0),
        })
    rows.sort(key=lambda row: (row["status"] != "active", -row["created_ts"]))
    return {"shares": rows, "count": len(rows), "active_count": sum(1 for row in rows if row["status"] == "active"), "passwords_exposed": False}


def suite_private_paths():
    return [
        APP_PASSWORD_FILE, MCP_CONFIG_FILE, MCP_OAUTH_FILE, MCP_AUDIT_FILE,
        ACCOUNT_FILE, GOOGLE_SECRETS_FILE, GOOGLE_AUTH_STATE_FILE,
        SAMSUNG_AUTH_FILE, SAMSUNG_PIN_FILE, WEBPUSH_VAPID_FILE,
        AUTOMATION_TOKENS_FILE, DATA_DIR / ".session_secret",
        _USERS_FILE, _TWO_FACTOR_FILE, _PASSKEYS_FILE, _INTERNAL_SHARES_FILE,
    ]


def suite_legacy_leftover_entries(max_age_days=30):
    cutoff = time.time() - max(1, int(max_age_days)) * 86400
    rows = []
    for path in storage_walk_files(DATA_DIR) or ():
        try:
            name = path.name
            stale_corrupt = ".corrupt." in name and path.stat().st_mtime < cutoff
            redundant_backup = name.endswith(".bak") and path.with_name(name[:-4]).exists() and path.stat().st_mtime < cutoff
            legacy_suffix = next((suffix for suffix in (".old", ".legacy", ".disabled") if name.endswith(suffix)), "")
            redundant_legacy = bool(legacy_suffix and path.with_name(name[:-len(legacy_suffix)]).exists() and path.stat().st_mtime < cutoff)
            if not (stale_corrupt or redundant_backup or redundant_legacy):
                continue
            storage_relative_path(path)
            rows.append({"path": path, "relative": storage_relative_path(path).as_posix(), "bytes": int(path.stat().st_size), "modified_ts": int(path.stat().st_mtime)})
        except (OSError, ValueError):
            continue
    return rows


def suite_security_audit():
    permission_findings = []
    for path in suite_private_paths():
        try:
            if path.exists() and path.is_file():
                mode = stat.S_IMODE(path.stat().st_mode)
                if mode & 0o077:
                    permission_findings.append({"file": storage_relative_path(path).as_posix(), "mode": oct(mode), "recommended": "0o600"})
        except (OSError, ValueError):
            continue
    symlinks = []
    for root, dirs, files in os.walk(DATA_DIR, followlinks=False):
        for name in [*dirs, *files]:
            path = Path(root) / name
            try:
                if path.is_symlink():
                    symlinks.append(storage_relative_path(path).as_posix())
            except (OSError, ValueError):
                pass
        if len(symlinks) >= 50:
            break
    secret_key_pattern = re.compile(r"(?:password|passwd|secret|access[_-]?token|refresh[_-]?token|private[_-]?key|authorization)", re.I)
    credential_paths = storage_classification_paths().get("credentials", set())
    possible_secret_files = []
    for path in storage_walk_files(DATA_DIR) or ():
        try:
            relative = storage_relative_path(path).as_posix()
            if relative in credential_paths or path.suffix.lower() != ".json" or path.stat().st_size > 2 * 1024 * 1024:
                continue
            data = safe_load_json(path, None, accepted_types=(dict, list))
            if data is None:
                continue
            keys = set()
            stack = [data]
            while stack and len(keys) < 12:
                value = stack.pop()
                if isinstance(value, dict):
                    for key, child in value.items():
                        if secret_key_pattern.search(str(key)):
                            keys.add(str(key)[:80])
                        if isinstance(child, (dict, list)):
                            stack.append(child)
                elif isinstance(value, list):
                    stack.extend(item for item in value[:100] if isinstance(item, (dict, list)))
            if keys:
                possible_secret_files.append({"file": relative, "key_names_only": sorted(keys)})
        except (OSError, ValueError, TypeError):
            continue
    expired_shares = sum(1 for link in state.get("shared_links", {}).values() if share_link_status(link) in {"expired", "inactive"})
    oauth_store = state.get("mcp_oauth", {})
    now_ts = int(time.time())
    expired_oauth = sum(1 for bucket in ("codes", "access_tokens", "refresh_tokens", "used_refresh_tokens") for row in oauth_store.get(bucket, {}).values() if not isinstance(row, dict) or int(row.get("expires_ts", 0) or 0) <= now_ts)
    leftovers = suite_legacy_leftover_entries()
    status = "warning" if permission_findings or symlinks or possible_secret_files else "ok"
    return {
        "status": status,
        "private_permission_findings": permission_findings,
        "symlinks": symlinks,
        "possible_secret_key_findings": possible_secret_files,
        "expired_share_records": expired_shares,
        "expired_oauth_records": expired_oauth,
        "legacy_leftovers": [{key: row[key] for key in ("relative", "bytes", "modified_ts")} for row in leftovers[:100]],
        "legacy_leftover_bytes": sum(row["bytes"] for row in leftovers),
        "secret_values_returned": False,
        "arbitrary_paths_allowed": False,
        "generated_at": now_ts,
    }


def suite_cleanup_guard_fingerprint(targets, snapshot=None):
    """Bind a cleanup approval to the exact server-side state it previewed."""
    normalized = list(dict.fromkeys(str(target) for target in targets))
    snapshot = snapshot if isinstance(snapshot, dict) else storage_scan_snapshot(force=True)
    catalog = {str(row.get("id")): row for row in snapshot.get("cleanup", []) if isinstance(row, dict)}
    guard = {
        "targets": normalized,
        "catalog": [
            {
                "id": target,
                "bytes": int((catalog.get(target) or {}).get("bytes", 0) or 0),
                "items": int((catalog.get(target) or {}).get("items", 0) or 0),
                "available": bool((catalog.get(target) or {}).get("available", False)),
            }
            for target in normalized
        ],
    }
    if "legacy_leftovers" in normalized:
        guard["legacy"] = [
            (row["relative"], int(row["bytes"]), int(row["modified_ts"]))
            for row in suite_legacy_leftover_entries()
        ]
    if "expired_access" in normalized:
        guard["expired_shares"] = sorted(
            (mcp_guest_ref(link_id), share_link_status(link), int(float((link or {}).get("expires_ts", 0) or 0)))
            for link_id, link in state.get("shared_links", {}).items()
            if share_link_status(link) in {"expired", "inactive"}
        )
        now_ts = int(time.time())
        guard["expired_oauth"] = sorted(
            (bucket, str(key)[:24], int((row or {}).get("expires_ts", 0) or 0))
            for bucket in ("codes", "access_tokens", "refresh_tokens", "used_refresh_tokens")
            for key, row in state.get("mcp_oauth", {}).get(bucket, {}).items()
            if not isinstance(row, dict) or int(row.get("expires_ts", 0) or 0) <= now_ts
        )
    raw = json.dumps(guard, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()


def suite_cleanup_preview(targets):
    targets = list(dict.fromkeys(str(target) for target in targets))
    allowed = set(STORAGE_CLEANUP_TARGETS) | {"expired_access", "legacy_leftovers"}
    if not targets or any(target not in allowed for target in targets):
        raise MCPToolError("Ungültige Bereinigungsauswahl.")
    snapshot = storage_scan_snapshot(force=True)
    catalog = {row["id"]: dict(row) for row in snapshot.get("cleanup", [])}
    audit = suite_security_audit()
    catalog["expired_access"] = {
        "id": "expired_access", "label": "Abgelaufene Zugriffe", "kind": "Sicherheit",
        "description": "Entfernt ausschließlich abgelaufene/inaktive Share- und OAuth-Datensätze; aktive Zugriffe bleiben erhalten.",
        "items": audit["expired_share_records"] + audit["expired_oauth_records"], "bytes": 0, "available": True,
    }
    catalog["legacy_leftovers"] = {
        "id": "legacy_leftovers", "label": "Verwaiste Update-Reste", "kind": "Sicherheit",
        "description": "Entfernt nur alte .corrupt-Dateien sowie redundante .bak-, .old-, .legacy- und .disabled-Kopien, wenn die aktuelle Hauptdatei vorhanden ist.",
        "items": len(audit["legacy_leftovers"]), "bytes": audit["legacy_leftover_bytes"], "available": True,
    }
    selected = [catalog[target] for target in targets if target in catalog]
    payload = {
        "purpose": "suite_cleanup", "targets": targets,
        "guard": suite_cleanup_guard_fingerprint(targets, snapshot),
        "expires_ts": int(time.time()) + MCP_MAINTENANCE_PREVIEW_SECONDS,
        "nonce": secrets.token_urlsafe(12),
    }
    token = mcp_sign_authorization(payload)
    return {
        "status": "preview", "targets": selected,
        "reclaimable_bytes": sum(int(row.get("bytes", 0) or 0) for row in selected),
        "preview_token": token, "expires_ts": payload["expires_ts"],
        "protected_data": ["tracker_keys", "accounts", "active_tokens", "current_history", "settings"],
        "arbitrary_paths_allowed": False,
    }


def suite_cleanup_expired_access():
    now_ts = int(time.time())
    removed_shares = []
    with state_lock:
        for link_id, link in list(state.get("shared_links", {}).items()):
            if share_link_status(link) not in {"expired", "inactive"}:
                continue
            removed_shares.append(link_id)
            state["shared_links"].pop(link_id, None)
            state.get("guest_push_channels", {}).pop(link_id, None)
        if removed_shares:
            save_json(LINKS_FILE, "shared_links")
            atomic_write_json(GUEST_PUSH_FILE, state.get("guest_push_channels", {}), private=True)
    before = sum(len(bucket) for bucket in state.get("mcp_oauth", {}).values() if isinstance(bucket, dict))
    mcp_oauth_cleanup(save=True)
    after = sum(len(bucket) for bucket in state.get("mcp_oauth", {}).values() if isinstance(bucket, dict))
    return {"id": "expired_access", "removed_items": len(removed_shares) + max(0, before - after), "freed_bytes": 0, "message": "Abgelaufene Share- und OAuth-Zugriffe entfernt."}


def suite_cleanup_legacy_leftovers():
    rows = suite_legacy_leftover_entries()
    freed = removed = 0
    for row in rows:
        try:
            freed += storage_remove_entry(row["path"])
            removed += 1
        except FileNotFoundError:
            pass
    return {"id": "legacy_leftovers", "removed_items": removed, "freed_bytes": freed, "message": "Verwaiste Update-Reste entfernt."}


def suite_execute_cleanup(targets, preview_token):
    preview = mcp_unsign_authorization(preview_token)
    normalized = list(dict.fromkeys(str(target) for target in targets))
    if not preview or preview.get("purpose") != "suite_cleanup" or list(preview.get("targets") or []) != normalized:
        raise MCPToolError("Vorschau-Token ist ungültig, abgelaufen oder gehört zu einer anderen Auswahl.", "preview_required")
    if not hmac.compare_digest(str(preview.get("guard") or ""), suite_cleanup_guard_fingerprint(normalized)):
        raise MCPToolError("Der bereinigbare Bestand hat sich seit der Vorschau geändert. Bitte eine neue Vorschau bestätigen.", "preview_stale")
    results, errors = [], []
    if normalized:
        base = storage_run_cleanup(normalized, automatic=False)
        results.extend(base.get("results", [])); errors.extend(base.get("errors", []))
    storage_invalidate_scan()
    total = sum(int(row.get("freed_bytes", 0) or 0) for row in results)
    audit_event("suite_cleanup", ",".join(normalized), f"freed={total}; errors={len(errors)}", "partial" if errors else "ok")
    return {"status": "partial" if errors else "ok", "freed_bytes": total, "results": results, "errors": errors, "security_audit": suite_security_audit()}


def mcp_set_tracker_history(model, enabled, retention_choice=None, custom_days=None):
    provider, tracker_id = str(model.get("provider") or ""), str(model.get("id") or "")
    refs = mcp_tracker_refs_for_model(model)
    if provider not in {"apple", "google", "samsung", "fusion"} or not tracker_id or not refs:
        raise MCPToolError("Für diesen Tracker wurde keine unterstützte Verlaufsquelle gefunden.", "not_found")
    current = history_direct_policy(provider, tracker_id)
    try:
        retention = parse_history_retention_choice(
            retention_choice if retention_choice is not None else current.get("mode"),
            custom_days if custom_days is not None else current.get("days"),
            current.get("days") or 7,
        )
    except ValueError as exc:
        raise MCPToolError(str(exc)) from exc
    policy = set_history_policy(provider, tracker_id, bool(enabled), retention["mode"], retention["days"])
    if enabled:
        wake_polling_for_refs(refs)
    source_policies = []
    for ref in refs:
        source_provider, source_id = ref.split(":", 1)
        source_policies.append(history_policy_public(source_provider, source_id))
    return {
        "tracker": mcp_tracker_row(model, True), "enabled": bool(enabled),
        "policy": policy, "sources": source_policies,
        "existing_points_deleted": False, "points_preserved": True,
    }


def mcp_upsert_saved_place(arguments):
    place_id = str(arguments.get("place_id") or "").strip()
    existing = state.get("saved_places", {}).get(place_id) if place_id else None
    if place_id and not isinstance(existing, dict):
        raise MCPToolError("Gespeicherter Ort wurde nicht gefunden.", "not_found")
    existing = dict(existing or {})
    try:
        lat = float(arguments.get("latitude", existing.get("lat")))
        lon = float(arguments.get("longitude", existing.get("lon")))
        if not (-90 <= lat <= 90 and -180 <= lon <= 180):
            raise ValueError
    except (TypeError, ValueError):
        raise MCPToolError("Gültige latitude und longitude sind erforderlich.")
    label = str(arguments.get("label") or existing.get("label") or "").strip()[:100]
    if not label:
        raise MCPToolError("label darf nicht leer sein.")
    place_id = place_id or secrets.token_urlsafe(8)
    row = {
        **existing, "id": place_id, "label": label,
        "emoji": str(arguments.get("emoji", existing.get("emoji") or "📍"))[:16],
        "lat": round(lat, 7), "lon": round(lon, 7),
        "radius": round(float_range(arguments.get("radius_m", existing.get("radius")), 100, 20, 100000), 1),
        "note": str(arguments.get("note", existing.get("note") or ""))[:240],
        "created_ts": int(existing.get("created_ts", time.time()) or time.time()),
        "updated_ts": int(time.time()),
    }
    state.setdefault("saved_places", {})[place_id] = row
    save_json(SAVED_PLACES_FILE, "saved_places")
    audit_event("place_updated" if existing else "place_created", place_id, label)
    return mcp_zone_public({"id": place_id, "kind": "saved_place", "label": label, "emoji": row["emoji"], "latitude": row["lat"], "longitude": row["lon"], "radius_m": row["radius"], "note": row["note"]})


def mcp_call_tool(name, arguments, grant):
    arguments = arguments if isinstance(arguments, dict) else {}
    if mcp_grant_principal(grant) == "guest":
        return mcp_call_guest_tool(name, arguments, grant)
    if name == "list_tracker_catalog":
        rows = [mcp_tracker_row(row, True) for row in mcp_filter_trackers(arguments)]
        data = {"trackers": rows, "count": len(rows), "provider_refresh": False, "generated_at": int(time.time())}
        return mcp_text_result(data, f"{len(rows)} lokale Katalogeinträge geladen; keine Ortung gestartet.")

    if name == "resolve_tracker_name":
        candidates = mcp_tracker_candidates(arguments.get("query"), arguments.get("limit", 6))
        public = [{key: row[key] for key in ("ref", "name", "provider", "score", "matched_by", "provider_name")} for row in candidates]
        resolved = None
        try:
            resolved = mcp_tracker_row(mcp_resolve_tracker(arguments.get("query")), True)
        except MCPToolError:
            pass
        data = {"query": str(arguments.get("query") or "")[:200], "resolved": resolved, "candidates": public, "provider_refresh": False, "generated_at": int(time.time())}
        sentence = f"Eindeutig als {resolved['name']} ({resolved['ref']}) erkannt; keine Ortung gestartet." if resolved else f"{len(public)} Kandidat(en) gefunden. Bitte vor einer Aktion einen bestätigen."
        return mcp_text_result(data, sentence)

    if name == "list_trackers":
        initial = mcp_filter_trackers(arguments)
        current, refresh, addresses = mcp_live_models(initial, arguments, "mcp_list")
        rows = [mcp_tracker_row(row) for row in current]
        data = {"trackers": rows, "count": len(rows), "generated_at": int(time.time()), "live_refresh": refresh, "address_lookup": addresses}
        return mcp_text_result(data, f"{len(rows)} Tracker geladen. {mcp_refresh_summary_text(refresh)}")

    if name in {"get_tracker", "fetch"}:
        reference = arguments.get("tracker") if name == "get_tracker" else arguments.get("id")
        initial = mcp_resolve_tracker(reference)
        current, refresh, addresses = mcp_live_models([initial], arguments, "mcp_get_tracker")
        model = current[0] if current else initial
        data = {"tracker": mcp_tracker_row(model, True), "generated_at": int(time.time()), "live_refresh": refresh, "address_lookup": addresses}
        return mcp_text_result(data, mcp_tracker_result_sentence(model, refresh))

    if name in {"get_tracker_history", "get_tracker_places"}:
        initial = mcp_resolve_tracker(arguments.get("tracker"))
        current, refresh, latest_addresses = mcp_live_models([initial], arguments, "mcp_history")
        model = current[0] if current else initial
        history_arguments = dict(arguments)
        if name == "get_tracker_places":
            history_arguments["include_points"] = False
        data = mcp_tracker_history(model, history_arguments)
        data["live_refresh"] = refresh
        data["latest_address_lookup"] = latest_addresses
        if name == "get_tracker_places":
            sentence = f"{len(data.get('places', []))} bestätigte Orte und {len(data.get('observed_places', []))} weitere Ortsbeobachtungen für {model.get('name')} ausgewertet."
        else:
            sentence = f"{data['matching_total']} Verlaufspunkte und {len(data.get('stays', []))} bestätigte Aufenthalte für {model.get('name')} ausgewertet."
        return mcp_text_result(data, f"{sentence} {mcp_refresh_summary_text(refresh)}")

    if name == "get_recovery_case":
        initial = mcp_resolve_tracker(arguments.get("tracker"))
        current, refresh, latest_addresses = mcp_live_models([initial], arguments, "mcp_recovery_read")
        model = current[0] if current else initial
        data = mcp_recovery_case(model, bool(arguments.get("include_points")), arguments.get("limit", 300))
        data = mcp_enrich_recovery_addresses(data, arguments)
        data["live_refresh"] = refresh
        data["latest_address_lookup"] = latest_addresses
        summary = data.get("summary") or {}
        return mcp_text_result(data, f"Recovery-Fall für {model.get('name')}: {summary.get('phase_label') or 'nicht aktiv'}. {mcp_refresh_summary_text(refresh)}")

    if name == "get_system_status":
        data = mcp_system_status_data()
        return mcp_text_result(data, data["status"].get("label") or "Systemstatus geladen.")

    if name == "get_polling_status":
        if arguments.get("tracker"):
            model = mcp_resolve_tracker(arguments.get("tracker"))
            data = {"tracker": mcp_tracker_row(model), "polling": tracker_polling_public(model.get("provider"), model.get("id")), "provider_refresh": False, "generated_at": int(time.time())}
            return mcp_text_result(data, f"Ortungsintervall für {model.get('name')} geladen; keine Ortung gestartet.")
        data = {"polling": polling_public_state(), "provider_refresh": False}
        return mcp_text_result(data, "Zentrale Ortungsintervalle und aktive gemeinsame Jobs geladen; keine Ortung gestartet.")

    if name == "get_history_policy":
        model = mcp_resolve_tracker(arguments.get("tracker"))
        sources = []
        for ref in mcp_tracker_refs_for_model(model):
            provider, tracker_id = ref.split(":", 1)
            sources.append(history_policy_public(provider, tracker_id))
        data = {
            "tracker": mcp_tracker_row(model, False),
            "policy": history_policy_public(model.get("provider"), model.get("id")),
            "source_policies": sources,
            "maintenance": {
                key: state.get("history_retention", {}).get(key)
                for key in ("last_maintenance_ts", "last_maintenance_reason", "last_removed_points")
            },
            "provider_refresh": False,
        }
        return mcp_text_result(data, f"Aufbewahrung für {model.get('name')}: {data['policy'].get('label')}; effektiv {data['policy'].get('effective_label')}.")

    if name == "get_transit_status":
        data = transit_public_status()
        return mcp_text_result(data, "Optionale ÖPNV-Quellen und Ausfallstatus geladen; kein externer Abruf ausgeführt.")

    if name == "analyze_tracker_transit":
        initial = mcp_resolve_tracker(arguments.get("tracker"))
        refresh = {"requested": False, "status": "skipped"}
        model = initial
        if bool_from_any(arguments.get("refresh"), False):
            current, refresh, _addresses = mcp_live_models([initial], {**arguments, "resolve_addresses": False}, "mcp_transit")
            model = current[0] if current else initial
        window = mcp_time_window(arguments)
        points = mcp_history_internal_points(model, window)
        data = transit_analyze_points(points, arguments.get("radius_m"), arguments.get("time_tolerance_minutes"), arguments.get("modes"), arguments.get("max_observations"))
        data.update({"tracker": mcp_tracker_row(model, False), "window": window, "live_refresh": refresh})
        return mcp_text_result(data, data.get("answer_hint_de") or f"ÖPNV-Abgleich für {model.get('name')} abgeschlossen.")

    if name == "get_tracker_context":
        initial = mcp_resolve_tracker(arguments.get("tracker"))
        current, refresh, addresses = mcp_live_models([initial], arguments, "mcp_context")
        model = current[0] if current else initial
        row = mcp_tracker_row(model, True)
        location = model.get("location") if isinstance(model.get("location"), dict) else None
        row["geofence_context"] = mcp_location_zone_context(location, mcp_tracker_refs_for_model(model)) if location else {"inside": [], "nearby": [], "nearest": None}
        return mcp_text_result({"tracker": row, "live_refresh": refresh, "address_lookup": addresses}, f"Ortskontext für {model.get('name')} geladen. {row['geofence_context'].get('summary', '')}")

    if name == "compare_trackers":
        references = arguments.get("trackers") if isinstance(arguments.get("trackers"), list) else []
        models, seen = [], set()
        for reference in references[:12]:
            model = mcp_resolve_tracker(reference)
            if model.get("ref") not in seen:
                seen.add(model.get("ref")); models.append(model)
        if len(models) < 2:
            raise MCPToolError("Mindestens zwei unterschiedliche Tracker sind erforderlich.")
        current, refresh, addresses = mcp_live_models(models, arguments, "mcp_compare")
        rows = [mcp_tracker_row(model, False) for model in current]
        data = {"trackers": rows, "comparisons": mcp_compare_tracker_rows(rows), "live_refresh": refresh, "address_lookup": addresses}
        return mcp_text_result(data, f"{len(rows)} Tracker mit {len(data['comparisons'])} Paarvergleich(en) ausgewertet.")

    if name == "check_place_visit":
        initial = mcp_resolve_tracker(arguments.get("tracker"))
        current, refresh, addresses = mcp_live_models([initial], arguments, "mcp_visit")
        model = current[0] if current else initial
        zone = mcp_resolve_place(arguments.get("place"), mcp_tracker_refs_for_model(model))
        points = mcp_history_internal_points(model, mcp_time_window(arguments))
        report = mcp_visit_report(points, zone, arguments.get("expected_start"), arguments.get("grace_minutes", 0))
        report.update({"tracker": mcp_tracker_row(model, False), "live_refresh": refresh, "address_lookup": addresses})
        return mcp_text_result(report, f"Besuchsbeobachtung für {model.get('name')} und {zone.get('label')} abgeschlossen.")

    if name == "get_daily_timeline":
        initial = mcp_resolve_tracker(arguments.get("tracker"))
        current, refresh, addresses = mcp_live_models([initial], arguments, "mcp_daily_timeline")
        model = current[0] if current else initial
        history_args = {**arguments, "period": "today", "include_points": True, "limit": 2000, "observation_limit": 50}
        data = mcp_tracker_history(model, history_args)
        timeline = []
        for stay in data.get("stays", []):
            timeline.append({"type": "confirmed_stay", "ts": stay.get("start_ts"), "end_ts": stay.get("end_ts"), "item": stay})
        for observation in data.get("observed_places", []):
            timeline.append({"type": "observation", "ts": observation.get("start_ts"), "end_ts": observation.get("end_ts"), "item": observation})
        timeline.sort(key=lambda row: int(row.get("ts", 0) or 0))
        data.update({"timeline": timeline, "live_refresh": refresh, "latest_address_lookup": addresses})
        return mcp_text_result(data, f"Tagesablauf für {model.get('name')} enthält {len(timeline)} beobachtete Abschnitte.")

    if name == "get_motion_insight":
        initial = mcp_resolve_tracker(arguments.get("tracker"))
        current, refresh, addresses = mcp_live_models([initial], arguments, "mcp_motion")
        model = current[0] if current else initial
        lookback = int_range(arguments.get("lookback_minutes"), 180, 15, 1440)
        points = mcp_history_internal_points(model, {"since_ts": int(time.time()) - lookback * 60, "until_ts": int(time.time())})
        data = {"tracker": mcp_tracker_row(model, False), "motion": mcp_motion_insight(points), "live_refresh": refresh, "address_lookup": addresses}
        return mcp_text_result(data, f"Bewegungsanalyse für {model.get('name')}: {data['motion'].get('classification')}.")

    if name == "get_fleet_summary":
        data = mcp_owner_fleet_summary(arguments)
        return mcp_text_result(data, f"{data['tracker_count']} Tracker zusammengefasst; {data['with_location']} besitzen einen Standort.")

    if name == "get_provider_login_health":
        data = mcp_provider_login_health()
        return mcp_text_result(data, "Provider-Anmeldungen wurden ohne Offenlegung von Zugangsdaten geprüft.")

    if name == "get_notification_health":
        data = mcp_notification_health_data()
        return mcp_text_result(data, f"Benachrichtigungsstatus geladen; {data['active_push_subscriptions']} aktive Browser-Push-Abonnements.")

    if name == "get_data_quality":
        if arguments.get("tracker"):
            models = [mcp_resolve_tracker(arguments.get("tracker"))]
        else:
            models = mcp_filter_trackers({"provider": "all", "include_hidden": True, "include_archived": True, "limit": 250})
        rows = [mcp_data_quality_row(model) for model in models]
        return mcp_text_result({"trackers": rows, "count": len(rows), "generated_at": int(time.time())}, f"Reportqualität für {len(rows)} Tracker bewertet; keine Ortung gestartet.")

    if name == "list_saved_places":
        query = mcp_normalize_tracker_text(arguments.get("query"))
        rows = [mcp_zone_public(zone) for zone in mcp_place_catalog([], include_saved=True) if zone.get("kind") == "saved_place"]
        if query:
            rows = [row for row in rows if query in mcp_normalize_tracker_text(row.get("label"))]
        return mcp_text_result({"places": rows, "count": len(rows)}, f"{len(rows)} gespeicherte Orte geladen.")

    if name == "list_tracker_groups":
        groups = []
        models = mcp_all_trackers()
        for group in state.get("tracker_groups", {}).values():
            if not isinstance(group, dict):
                continue
            members = [mcp_tracker_row(model, False) for model in models if str(group.get("id")) in (model.get("groups") or [])]
            groups.append({"id": str(group.get("id") or ""), "label": str(group.get("label") or "Gruppe")[:80], "emoji": str(group.get("emoji") or "📁")[:16], "trackers": members, "count": len(members)})
        return mcp_text_result({"groups": groups, "count": len(groups)}, f"{len(groups)} Tracker-Gruppen geladen.")

    if name == "get_share_access_status":
        data = mcp_owner_share_status(arguments)
        return mcp_text_result(data, f"{data['active_count']} aktive Freigabelinks und {sum(row.get('mcp_guest_grants', 0) for row in data['shares'])} Gastverbindungen.")

    if name == "get_security_audit":
        data = suite_security_audit()
        return mcp_text_result(data, f"Sicherheitsprüfung abgeschlossen: {data['status']}; Secret-Werte werden niemals ausgegeben.")

    if name == "preview_suite_cleanup":
        data = suite_cleanup_preview(arguments.get("targets") if isinstance(arguments.get("targets"), list) else [])
        return mcp_text_result(data, f"Bereinigungsvorschau für {len(data['targets'])} feste Kategorien erstellt; noch nichts gelöscht.")

    if name == "render_tracker_map":
        initial = mcp_filter_trackers(arguments)
        current, refresh, addresses = mcp_live_models(initial, arguments, "mcp_map")
        rows = []
        for model in current:
            row = mcp_tracker_row(model, True)
            location = row.get("location")
            if isinstance(location, dict):
                try:
                    latitude, longitude = float(location.get("latitude")), float(location.get("longitude"))
                except (TypeError, ValueError):
                    latitude = longitude = None
                if latitude is not None and longitude is not None and -90 <= latitude <= 90 and -180 <= longitude <= 180:
                    row["location"] = {
                        "lat": round(latitude, 7), "lon": round(longitude, 7),
                        "acc": location.get("accuracy_m"), "ts": location.get("timestamp"),
                        "network": location.get("network"), "provider": location.get("provider"),
                        "battery": location.get("battery"), "address": location.get("address"),
                        "freshness": location.get("freshness"),
                    }
                else:
                    row["location"] = None
            target_alerts = [mcp_found_notification_public(ref) for ref in mcp_notification_target_refs(model)]
            row["found_notification"] = {"enabled": any(item.get("enabled") for item in target_alerts), "sources": target_alerts}
            rows.append(row)
        data = {
            "schema_version": 3,
            "authoritative": True,
            "snapshot_id": mcp_map_snapshot_id(rows),
            "trackers": rows,
            "count": len(rows),
            "location_count": sum(1 for row in rows if isinstance(row.get("location"), dict)),
            "empty_reason": "no_matching_trackers" if not rows else "no_locations" if not any(isinstance(row.get("location"), dict) for row in rows) else "",
            "generated_at": int(time.time()),
            "timezone": APP_TIMEZONE_NAME,
            "live_refresh": refresh,
            "address_lookup": addresses,
            "actions": {
                "refresh": True,
                "found_notifications": bool(mcp_config().get("allow_actions") and ({"alerts:write", MCP_UNIFIED_SCOPE} & set(grant.get("scopes") or []))),
                "fullscreen": True,
            },
        }
        return mcp_text_result(data, f"Interaktive Karte mit {len(rows)} Tracker(n) vorbereitet. {mcp_refresh_summary_text(refresh)}", MCP_MAP_RESOURCE_URI)

    if name == "list_found_notifications":
        data = mcp_found_notifications_status(bool_from_any(arguments.get("active_only"), False))
        return mcp_text_result(data, f"{data['active_count']} Fund-Benachrichtigung(en) sind aktiv.")

    if name == "list_departure_notifications":
        data = mcp_departure_notifications_status(bool_from_any(arguments.get("active_only"), False))
        return mcp_text_result(data, f"{data['active_count']} Wegbewegungsalarm/-alarme sind aktiv.")

    if name == "list_inactivity_notifications":
        data = mcp_inactivity_notifications_status(bool_from_any(arguments.get("active_only"), False))
        return mcp_text_result(data, f"{data['active_count']} Ortungspausen-Alarm/-Alarme sind aktiv.")

    if name == "list_comparison_tests":
        wanted = str(arguments.get("status") or "all")
        rows = [comparison_test_public(test) for test in state.get("comparison_tests", {}).values() if isinstance(test, dict)]
        if wanted != "all":
            rows = [row for row in rows if row.get("status") == wanted]
        rows.sort(key=lambda row: (row.get("status") != "running", -int(row.get("started_ts", 0) or 0)))
        active_count = sum(1 for row in rows if row.get("status") == "running")
        return mcp_text_result({"tests": rows, "count": len(rows), "active_count": active_count}, f"{active_count} Vergleichstest(s) laufen aktuell; insgesamt {len(rows)} Test(s) im Filter.")

    if name == "get_comparison_test":
        test = comparison_resolve_test(arguments.get("test"))
        data = comparison_test_public(test)
        winner = ((data.get("results") or {}).get("winners") or {}).get("overall") or {}
        sentence = f"Vergleich {data.get('name')} ausgewertet."
        if winner.get("name"):
            sentence += f" Gesamtwertung: {winner.get('name')} mit {winner.get('score')} Punkten."
        return mcp_text_result(data, sentence)

    if name == "list_geofences":
        data = mcp_geofences_status(arguments)
        return mcp_text_result(data, f"{data['count']} Geofence(s) geladen; {data['active_count']} davon aktiv.")

    if name == "search_geofence_places":
        data = mcp_search_geofence_places(arguments)
        return mcp_text_result(data, f"{data['count']} passende Orte gefunden. Vor dem Erstellen bitte den gewünschten Kandidaten eindeutig auswählen.")

    if name == "search":
        rows = [mcp_tracker_row(row) for row in mcp_filter_trackers({"query": arguments.get("query"), "include_hidden": True, "include_archived": True, "limit": 50})]
        data = {"results": [{"id": row["ref"], "title": row["name"], "url": f"tracker://{urllib.parse.quote(row['ref'], safe=':')}", "provider": row["provider"], "last_seen_ts": row["last_seen_ts"]} for row in rows]}
        return mcp_text_result(data, f"{len(rows)} passende Tracker gefunden.")

    if name == "locate_trackers":
        mcp_require_action(grant, "trackers:locate", arguments)
        references = arguments.get("trackers")
        if not isinstance(references, list) or not references:
            raise MCPToolError("trackers muss eine nichtleere Liste sein.")
        models, seen = [], set()
        for reference in references[:MCP_LIVE_TRACKER_LIMIT]:
            model = mcp_resolve_tracker(reference)
            if model.get("ref") not in seen:
                seen.add(model.get("ref"))
                models.append(model)
        live_arguments = {**arguments, "refresh": True}
        current, refresh, addresses = mcp_live_models(models, live_arguments, "mcp_explicit_locate")
        data = {"status": refresh.get("status"), "trackers": [mcp_tracker_row(row, True) for row in current], "live_refresh": refresh, "address_lookup": addresses, "generated_at": int(time.time())}
        return mcp_text_result(data, f"Ortung für {len(current)} Tracker abgeschlossen. {mcp_refresh_summary_text(refresh)}")

    if name == "start_tracker_comparison":
        mcp_require_action(grant, "trackers:write", arguments)
        references = list(arguments.get("trackers") or []) if isinstance(arguments.get("trackers"), list) else []
        if arguments.get("fusion"):
            references.append(arguments.get("fusion"))
        data = comparison_start(references, arguments.get("name"), bool_from_any(arguments.get("confirmed"), False), "mcp")
        targets = ", ".join(target.get("name", target.get("ref", "")) for target in data.get("targets", []))
        return mcp_text_result(data, f"Vergleichstest {data.get('name')} läuft jetzt mit {targets}.")

    if name == "finish_tracker_comparison":
        mcp_require_action(grant, "trackers:write", arguments)
        selected = comparison_resolve_test(arguments.get("test"))
        data = comparison_finish(selected.get("id"), bool_from_any(arguments.get("confirmed"), False), "mcp")
        winners = (data.get("results") or {}).get("winners") or {}
        most = winners.get("most_reports") or {}
        overall = winners.get("overall") or {}
        sentence = f"Test {data.get('name')} ist fertig: {data.get('results', {}).get('total_reports', 0)} Meldungen."
        if most.get("name"):
            sentence += f" Am meisten meldete {most.get('name')} ({most.get('reports')} Reports)."
        if overall.get("name"):
            sentence += f" Gesamtwertung: {overall.get('name')} ({overall.get('score')} Punkte)."
        return mcp_text_result(data, sentence)

    if name == "delete_tracker_comparison":
        mcp_require_action(grant, "trackers:write", arguments)
        selected = comparison_resolve_test(arguments.get("test"), running_preferred=False)
        data = comparison_delete(selected.get("id"), bool_from_any(arguments.get("confirmed"), False))
        return mcp_text_result(data, f"Vergleichstest {data.get('name')} wurde gelöscht.")

    if name == "set_inactivity_notification":
        mcp_require_action(grant, "alerts:write", arguments)
        model = mcp_resolve_tracker(arguments.get("tracker"))
        data = mcp_set_inactivity_notification(model, arguments)
        state_text = "aktiviert" if bool_from_any(arguments.get("enabled"), False) else "deaktiviert"
        return mcp_text_result(data, f"Ortungspausen-Alarm für {model.get('name')} wurde {state_text}.")

    if name == "run_system_diagnostics":
        mcp_require_action(grant, "trackers:write", arguments)
        if state.get("diagnostics", {}).get("status") == "running" or diagnostics_lock.locked():
            return mcp_text_result({"status": "running", "report": diagnostics_snapshot()}, "Eine Systemdiagnose läuft bereits.")
        deep = bool_from_any(arguments.get("deep"), False)
        state["diagnostics"] = {"status": "running", "mode": "deep" if deep else "quick", "started_ts": int(time.time()), "finished_ts": 0, "summary": {"ok": 0, "warning": 0, "error": 0, "info": 0}, "checks": []}
        atomic_write_json(DIAGNOSTICS_FILE, state["diagnostics"])
        threading.Thread(target=run_diagnostics_worker, args=(deep,), daemon=True).start()
        return mcp_text_result({"status": "started", "mode": state["diagnostics"]["mode"], "check_again_after_seconds": 5}, f"{state['diagnostics']['mode'].title()}-Diagnose wurde gestartet.")

    if name == "create_server_backup":
        mcp_require_action(grant, "trackers:write", arguments)
        include_history = bool_from_any(arguments.get("include_history"), True)
        file, manifest = create_server_backup(include_history=include_history, include_secrets=False, reason="mcp_confirmed")
        storage_invalidate_scan()
        audit_event("backup_created_mcp", file.name, f"history={include_history}; secrets=false")
        data = {"status": "ok", "backup": {"name": file.name, "size": file.stat().st_size, "created_ts": manifest["created_ts"], "include_history": include_history, "include_secrets": False}}
        return mcp_text_result(data, f"Server-Backup {file.name} wurde ohne Secrets erstellt.")

    if name == "run_suite_cleanup":
        mcp_require_action(grant, "trackers:write", arguments)
        targets = arguments.get("targets") if isinstance(arguments.get("targets"), list) else []
        data = suite_execute_cleanup(targets, arguments.get("preview_token"))
        return mcp_text_result(data, f"Bereinigung abgeschlossen: {data['freed_bytes']} Byte freigegeben, {len(data['errors'])} Fehler.")

    if name == "set_tracker_history":
        mcp_require_action(grant, "trackers:write", arguments)
        model = mcp_resolve_tracker(arguments.get("tracker"))
        data = mcp_set_tracker_history(model, bool_from_any(arguments.get("enabled"), False), arguments.get("retention"), arguments.get("custom_days"))
        return mcp_text_result(data, f"Verlauf für {model.get('name')} wurde {'aktiviert' if data['enabled'] else 'deaktiviert'} ({data['policy'].get('label')}); vorhandene Punkte bleiben erhalten.")

    if name == "upsert_saved_place":
        mcp_require_action(grant, "trackers:write", arguments)
        data = mcp_upsert_saved_place(arguments)
        return mcp_text_result({"status": "ok", "place": data}, f"Gespeicherter Ort {data['label']} wurde gespeichert.")

    if name == "delete_saved_place":
        mcp_require_action(grant, "trackers:write", arguments)
        saved_zones = [zone for zone in mcp_place_catalog([], include_saved=True) if zone.get("kind") == "saved_place"]
        zone = mcp_resolve_place(arguments.get("place"), zones=saved_zones)
        removed = state.get("saved_places", {}).pop(str(zone.get("id") or ""), None)
        if not removed:
            raise MCPToolError("Gespeicherter Ort wurde nicht gefunden.", "not_found")
        save_json(SAVED_PLACES_FILE, "saved_places")
        audit_event("place_deleted_mcp", str(zone.get("id") or ""), str(zone.get("label") or ""))
        return mcp_text_result({"status": "ok", "place": mcp_zone_public(zone)}, f"Gespeicherter Ort {zone.get('label')} wurde gelöscht; Geofences und Verläufe bleiben erhalten.")

    if name == "update_tracker_details":
        mcp_require_action(grant, "trackers:write", arguments)
        model = mcp_resolve_tracker(arguments.get("tracker"))
        data = mcp_update_tracker_details(model, arguments)
        return mcp_text_result(data, f"Tracker {model.get('name')} wurde als {data['details']['name']} gespeichert; ID und Verläufe bleiben unverändert.")

    if name == "set_found_notification":
        mcp_require_action(grant, "alerts:write", arguments)
        model = mcp_resolve_tracker(arguments.get("tracker"))
        channels = arguments.get("channels") if "channels" in arguments else None
        if channels is not None and not isinstance(channels, list):
            raise MCPToolError("channels muss eine Liste unterstützter Benachrichtigungskanäle sein.")
        data = mcp_set_found_notification(model, bool_from_any(arguments.get("enabled"), False), arguments.get("mode", "once"), channels)
        state_text = "aktiviert" if data.get("enabled") else "deaktiviert"
        return mcp_text_result(data, f"Fund-Benachrichtigung für {model.get('name')} wurde {state_text}.")

    if name == "disable_all_found_notifications":
        mcp_require_action(grant, "alerts:write", arguments)
        data = mcp_disable_all_found_notifications()
        sentence = "Es waren bereits keine Fund-Benachrichtigungen aktiv." if data.get("already_disabled") else f"{data.get('disabled_count', 0)} Fund-Benachrichtigung(en) wurden deaktiviert."
        return mcp_text_result(data, sentence)

    if name == "set_departure_notification":
        mcp_require_action(grant, "alerts:write", arguments)
        model = mcp_resolve_tracker(arguments.get("tracker"))
        data = mcp_set_departure_notification(model, arguments)
        if data.get("enabled"):
            anchor = data.get("anchor") or {}
            address = (anchor.get("address") or {}).get("display_name") or (anchor.get("address") or {}).get("label")
            center_text = f" bei {address}" if address else " am aktuellen Standort"
            sentence = f"Wegbewegungsalarm für {model.get('name')} wurde mit {round(float(arguments.get('radius_m', 150) or 150))} m Radius{center_text} aktiviert."
        else:
            sentence = f"Wegbewegungsalarm für {model.get('name')} wurde deaktiviert."
        return mcp_text_result(data, sentence)

    if name == "disable_all_departure_notifications":
        mcp_require_action(grant, "alerts:write", arguments)
        data = mcp_disable_all_departure_notifications()
        sentence = "Es waren bereits keine Wegbewegungsalarme aktiv." if data.get("already_disabled") else f"{data.get('disabled_count', 0)} aktive Alarmquelle(n) wurden deaktiviert."
        return mcp_text_result(data, sentence)

    if name == "create_geofence":
        mcp_require_action(grant, "alerts:write", arguments)
        data = mcp_create_geofence(arguments)
        fence = data.get("geofence") or {}
        return mcp_text_result(data, f"Geofence {fence.get('label')} wurde mit {round(float(fence.get('radius_m', 0) or 0))} m Radius erstellt.")

    if name == "update_geofence":
        mcp_require_action(grant, "alerts:write", arguments)
        data = mcp_update_geofence(arguments)
        fence = data.get("geofence") or {}
        return mcp_text_result(data, f"Geofence {fence.get('label')} wurde aktualisiert.")

    if name == "delete_geofence":
        mcp_require_action(grant, "alerts:write", arguments)
        data = mcp_delete_geofence(arguments)
        fence = data.get("geofence") or {}
        return mcp_text_result(data, f"Geofence {fence.get('label')} wurde gelöscht; Tracker- und Standortdaten bleiben erhalten.")

    if name == "start_recovery_case":
        mcp_require_action(grant, "recovery:write", arguments)
        model = mcp_resolve_tracker(arguments.get("tracker"))
        data = mcp_start_recovery(model, arguments)
        return mcp_text_result(data, f"Recovery Guard für {model.get('name')} ist aktiv.")

    if name == "update_recovery_case":
        mcp_require_action(grant, "recovery:write", arguments)
        model = mcp_resolve_tracker(arguments.get("tracker"))
        data = mcp_update_recovery(model, arguments)
        return mcp_text_result(data, f"Recovery Guard für {model.get('name')} wurde aktualisiert.")

    if name == "mark_recovery_found":
        mcp_require_action(grant, "recovery:write", arguments)
        model = mcp_resolve_tracker(arguments.get("tracker"))
        data = mcp_mark_recovery_found(model, arguments)
        return mcp_text_result(data, f"Recovery-Fall für {model.get('name')} wurde als gefunden abgeschlossen.")

    raise MCPToolError(f"Unbekanntes MCP-Tool: {name}", "method_not_found")


MCP_PROTOCOL_VERSIONS = ("2026-07-28", "2025-11-25", "2025-06-18", "2025-03-26")


def mcp_rpc_error(request_id, code, message, data=None):
    error = {"code": int(code), "message": str(message)[:500]}
    if data is not None:
        error["data"] = data
    return {"jsonrpc": "2.0", "id": request_id, "error": error}


def mcp_rpc_result(request_id, result):
    return {"jsonrpc": "2.0", "id": request_id, "result": result}


@app.route("/mcp", methods=["GET", "POST", "DELETE", "OPTIONS"])
@app.route("/t/<tenant_id>/mcp", methods=["GET", "POST", "DELETE", "OPTIONS"])
def mcp_endpoint(tenant_id=None):
    # ChatGPT can fetch an MCP App template from its isolated browser sandbox.
    # Complete the CORS preflight before OAuth; the following POST still needs
    # the normal bearer grant and is subject to every existing security check.
    if request.method == "OPTIONS":
        if not mcp_origin_allowed():
            return mcp_json_response({"error": "invalid_origin"}, 403)
        return mcp_apply_cors(Response(status=204))
    if not mcp_config().get("enabled"):
        return mcp_json_response({"error": "connector_disabled", "message": "MCP-Connector ist in den Einstellungen deaktiviert."}, 503)
    if not mcp_origin_allowed():
        mcp_audit_event("origin_rejected", status="error", detail="origin_policy")
        return mcp_json_response({"error": "invalid_origin"}, 403)
    if request.method == "GET":
        response = mcp_json_response({"error": "method_not_allowed", "message": "Dieser stateless Streamable-HTTP-Endpunkt verwendet POST."}, 405)
        response.headers["Allow"] = "POST, DELETE"
        return response
    if request.method == "DELETE":
        return mcp_apply_cors(Response(status=204))
    grant, auth_error, token_id = mcp_bearer_grant()
    if not grant:
        return mcp_unauthorized(auth_error)
    if not mcp_rate_limit(f"mcp:{token_id}", 120, 60):
        return mcp_json_response({"error": "rate_limited", "message": "Zu viele MCP-Anfragen."}, 429, {"Retry-After": "60"})
    if request.content_length and request.content_length > 1024 * 1024:
        return mcp_json_response({"error": "request_too_large"}, 413)
    body = request.get_json(silent=True)
    if not isinstance(body, dict) or body.get("jsonrpc") != "2.0":
        return mcp_json_response(mcp_rpc_error(None, -32600, "Invalid Request"), 400)
    request_id = body.get("id")
    method = str(body.get("method") or "")
    params = body.get("params") if isinstance(body.get("params"), dict) else {}
    if request_id is None and method.startswith("notifications/"):
        return mcp_apply_cors(Response(status=202))
    meta = params.get("_meta") if isinstance(params.get("_meta"), dict) else {}
    meta_protocol = str(meta.get("io.modelcontextprotocol/protocolVersion") or "")
    protocol = str(request.headers.get("MCP-Protocol-Version") or meta_protocol or "2025-03-26")
    if meta_protocol and meta_protocol != protocol:
        return mcp_json_response(mcp_rpc_error(request_id, -32600, "MCP protocol metadata/header mismatch"), 400)
    if request.headers.get("Mcp-Method") and request.headers["Mcp-Method"] != method:
        return mcp_json_response(mcp_rpc_error(request_id, -32600, "Mcp-Method mismatch"), 400)
    if method != "initialize" and protocol not in MCP_PROTOCOL_VERSIONS:
        return mcp_json_response(mcp_rpc_error(request_id, -32600, "Unsupported MCP protocol version"), 400)
    try:
        if method == "initialize":
            requested = str(params.get("protocolVersion") or "2025-03-26")
            negotiated = requested if requested in MCP_PROTOCOL_VERSIONS else "2025-11-25"
            guest_mode = mcp_grant_principal(grant) == "guest"
            instructions = (
                "Freigabelink-Modus: Zeige und nutze ausschließlich die durch gültige Share-Links erlaubten Tracker und Felder. "
                "Nutze list_trackers bei unklarem Namen, get_tracker für den letzten freigegebenen Stand, locate_trackers nur bei ausdrücklichem Wunsch und nur wenn der Link dies erlaubt. "
                "Verlauf, Geofence-Namen, Provider, Genauigkeit und Live-Aktualisierung sind unabhängige Linkrechte. Behaupte aus Trackerbeobachtungen nie sicher die Anwesenheit einer Person. "
                "add_shared_link und remove_shared_link benötigen confirmed=true; Admin-, Alarm-, Metadaten-, Recovery- und Systemänderungen sind in diesem Modus gesperrt."
                if guest_mode else
                "Besitzer-Modus: Nutze resolve_tracker_name oder list_tracker_catalog bei unvollständigen oder mehrdeutigen Namen; beide starten keine Ortung. "
                "get_tracker_context berücksichtigt Geofences, check_place_visit bewertet beobachtete Ankunft/Verspätung vorsichtig und get_motion_insight prognostiziert nur bei ausreichender Datenqualität. "
                "Recovery Guard ist eine lokale App-Funktion und kein offizieller Apple-Verloren-Modus. Jede schreibende Aktion benötigt confirmed=true. "
                "Bereinigung darf nur nach preview_suite_cleanup mit passendem Vorschau-Token laufen; beliebige Dateipfade sind nie erlaubt."
            )
            result = {
                "protocolVersion": negotiated,
                "capabilities": {"tools": {"listChanged": False}, "resources": {"subscribe": False, "listChanged": False}},
                "serverInfo": {"name": "universal-tag-studio", "title": "Universal Tag Studio", "version": APP_VERSION},
                "instructions": instructions,
            }
        elif method == "ping":
            result = {}
        elif method == "tools/list":
            result = {"tools": mcp_tools(grant)}
            mcp_audit_event("tools_discovered", client_id=grant.get("client_id"), detail=str(len(result["tools"])))
        elif method == "tools/call":
            tool_name = str(params.get("name") or "")
            tool_arguments = params.get("arguments") if isinstance(params.get("arguments"), dict) else {}
            result = mcp_call_tool(tool_name, tool_arguments, grant)
            config = mcp_config()
            config["last_call_ts"] = int(time.time())
            config["last_error"] = "" if not result.get("isError") else str((result.get("structuredContent") or {}).get("code") or "tool_error")
            mcp_save_config()
            mcp_audit_event("tool_call", "error" if result.get("isError") else "ok", grant.get("client_id"), tool_name)
        elif method == "resources/list":
            result = {"resources": []}
        elif method == "resources/read":
            raise MCPToolError("HTML-Kartenressourcen wurden entfernt. Nutze die Tracker-APIs.", "not_found")
        elif method == "resources/templates/list":
            result = {"resourceTemplates": []}
        elif method == "prompts/list":
            result = {"prompts": []}
        else:
            return mcp_json_response(mcp_rpc_error(request_id, -32601, "Method not found"), 404)
        if protocol == "2026-07-28" and method != "initialize":
            result = {"resultType": "complete", **result}
        response = mcp_json_response(mcp_rpc_result(request_id, result))
        response.headers["MCP-Protocol-Version"] = result.get("protocolVersion", protocol) if isinstance(result, dict) else protocol
        # Stateless transport: do not advertise a session which is never stored.
        return response
    except MCPToolError as exc:
        if method == "tools/call":
            result = mcp_error_result(str(exc), exc.code)
            if exc.code == "insufficient_scope":
                required_scope = "trackers:read"
                tool_name = str(params.get("name") or "")
                if tool_name == "locate_trackers":
                    required_scope = "trackers:locate"
                elif tool_name in {
                    "update_tracker_details", "run_system_diagnostics",
                    "create_server_backup", "run_suite_cleanup",
                    "set_tracker_history", "upsert_saved_place", "delete_saved_place",
                    "start_tracker_comparison", "finish_tracker_comparison", "delete_tracker_comparison",
                }:
                    required_scope = "trackers:write"
                elif tool_name in {
                    "set_found_notification", "disable_all_found_notifications",
                    "set_departure_notification", "disable_all_departure_notifications",
                    "set_inactivity_notification", "create_geofence", "update_geofence", "delete_geofence",
                }:
                    required_scope = "alerts:write"
                elif tool_name in {"start_recovery_case", "update_recovery_case", "mark_recovery_found"}:
                    required_scope = "recovery:write"
                result.setdefault("_meta", {})["mcp/www_authenticate"] = [
                    mcp_bearer_challenge(
                        "insufficient_scope",
                        "Diese Aktion benötigt eine zusätzliche, vom Besitzer bestätigte Berechtigung.",
                        required_scope,
                    )
                ]
            config = mcp_config()
            config["last_call_ts"] = int(time.time())
            config["last_error"] = exc.code
            mcp_save_config()
            mcp_audit_event("tool_call", "error", grant.get("client_id"), str(params.get("name") or ""), exc.code)
            if protocol == "2026-07-28":
                result["resultType"] = "complete"
            return mcp_json_response(mcp_rpc_result(request_id, result))
        return mcp_json_response(mcp_rpc_error(request_id, -32602, str(exc), {"code": exc.code}), 400)
    except Exception as exc:
        logger.exception("MCP-Anfrage fehlgeschlagen: %s", exc)
        mcp_config()["last_error"] = type(exc).__name__
        mcp_save_config()
        mcp_audit_event("rpc_error", "error", grant.get("client_id"), str(params.get("name") or ""), type(exc).__name__)
        return mcp_json_response(mcp_rpc_error(request_id, -32603, "Internal error"), 500)


@app.route("/api/mcp/settings", methods=["GET", "POST", "DELETE"])
def mcp_settings_api():
    if request.method == "GET":
        return jsonify({"status": "ok", "mcp": mcp_public_state(), "audit": list(state.get("mcp_audit", []))[:50], "connections": mcp_connection_rows()})
    if request.method == "DELETE":
        mcp_revoke_grants("owner_revoke", keep_clients=False)
        return jsonify({"status": "ok", "mcp": mcp_public_state()})
    data = request.get_json(silent=True) or {}
    current = dict(mcp_config())
    enabled = bool_from_any(data.get("enabled"), current.get("enabled", False))
    allow_actions = bool_from_any(data.get("allow_actions"), current.get("allow_actions", False))
    allow_shared_access = bool_from_any(data.get("allow_shared_access"), current.get("allow_shared_access", True))
    base_url = normalize_public_base_url(data.get("public_base_url", current.get("public_base_url", "")))
    if data.get("public_base_url") and not base_url:
        return jsonify({"status": "error", "message": "Bitte eine gültige öffentliche HTTP(S)-Basisadresse angeben."}), 400
    if base_url:
        parsed = urllib.parse.urlsplit(base_url)
        host = (parsed.hostname or "").lower()
        local = host in {"localhost", "127.0.0.1", "::1"}
        if parsed.username or parsed.password or parsed.query or parsed.fragment or parsed.path not in {"", "/"}:
            return jsonify({"status": "error", "message": "Die Basisadresse darf keine Zugangsdaten, Parameter oder Unterpfade enthalten."}), 400
        if not local and parsed.scheme != "https":
            return jsonify({"status": "error", "message": "Für ChatGPT ist eine öffentliche HTTPS-Adresse erforderlich."}), 400
    if enabled and not base_url:
        return jsonify({"status": "error", "message": "Zum Aktivieren wird die öffentliche HTTPS-Basisadresse benötigt."}), 400
    if enabled and app_password_is_default():
        return jsonify({"status": "error", "message": "Lege zuerst unter Sicherheit ein eigenes Master-Passwort fest."}), 409
    changed_connection = (
        bool(current.get("enabled")) != enabled
        or str(current.get("public_base_url") or "") != base_url
    )
    disable_shared_access = bool(current.get("allow_shared_access", True)) and not allow_shared_access
    config = mcp_config()
    config.update({"enabled": enabled, "allow_actions": allow_actions, "allow_shared_access": allow_shared_access, "public_base_url": base_url, "updated_ts": int(time.time()), "last_error": ""})
    mcp_save_config()
    if changed_connection:
        mcp_revoke_grants("settings_changed", keep_clients=False)
    elif disable_shared_access:
        mcp_revoke_guest_grants("shared_access_disabled")
    mcp_audit_event("settings_updated", detail=f"enabled={int(enabled)};actions={int(allow_actions)};guests={int(allow_shared_access)}")
    return jsonify({"status": "ok", "mcp": mcp_public_state()})


@app.after_request
def apply_security_headers(response):
    response.headers.setdefault("X-Content-Type-Options", "nosniff")
    response.headers.setdefault("X-Frame-Options", "DENY")
    response.headers.setdefault("Referrer-Policy", "no-referrer")
    response.headers.setdefault("Permissions-Policy", "camera=(), microphone=(), geolocation=(self), bluetooth=(), serial=(self), publickey-credentials-create=(self), publickey-credentials-get=(self)")
    tenant_protocol_path = bool(re.match(r"^/t/[a-z0-9][a-z0-9_-]{0,63}/(?:mcp(?:/|$)|oauth(?:/|$)|\.well-known(?:/|$))", request.path))
    if request.path.startswith("/api/") or request.path == "/mcp" or tenant_protocol_path or request.path.startswith("/oauth/") or request.path.startswith("/.well-known/"):
        response.headers.setdefault("Cache-Control", "no-store")
    return response


@app.errorhandler(413)
def uploaded_file_too_large(_error):
    return jsonify({"status": "error", "message": "Die Datei ist größer als 5 MB."}), 413


def csrf_session_token():
    token = str(session.get("csrf_token") or "")
    if not token:
        token = secrets.token_urlsafe(32)
        session["csrf_token"] = token
    return token


@app.before_request
def select_request_tenant():
    """Bind every request to exactly one isolated tenant before auth/data use."""
    tenant_id = "main"
    g.tenant_route_invalid = False
    tenant_route = re.match(r"^/t/([a-z0-9][a-z0-9_-]{0,63})/(?:mcp(?:/|$)|oauth(?:/|$)|\.well-known(?:/|$))", request.path)
    if tenant_route:
        requested_tenant = tenant_route.group(1)
        row = user_record(requested_tenant)
        if requested_tenant != "main" and row and row.get("active", True):
            tenant_id = requested_tenant
        else:
            g.tenant_route_invalid = True
    elif session.get("app_unlocked"):
        tenant_id = str(session.get("user_id") or "main")
    else:
        path = request.path.rstrip("/")
        shared_match = re.match(r"^/(?:api/)?shared/([^/]+)", path)
        recovery_match = re.match(r"^/(?:api/)?(?:recovery-share|recovery)/([^/]+)", path)
        if shared_match:
            tenant_id = find_public_token_owner(shared_match.group(1), "shared")
        elif recovery_match:
            tenant_id = find_public_token_owner(recovery_match.group(1), "recovery")
    try:
        ensure_tenant_state(tenant_id, start_workers=bool(session.get("app_unlocked")))
    except (PermissionError, OSError, ValueError):
        session.clear()
        if tenant_route:
            g.tenant_route_invalid = True
        tenant_id = "main"
    g.tenant_context_token = _tenant_id_context.set(tenant_id)
    g.tenant_id = tenant_id


@app.teardown_request
def release_request_tenant(_error=None):
    token = getattr(g, "tenant_context_token", None)
    if token is not None:
        try:
            _tenant_id_context.reset(token)
        except (ValueError, RuntimeError):
            pass


@app.before_request
def check_auth():
    if getattr(g, "tenant_route_invalid", False):
        return jsonify({"status": "error", "message": "Dieser Benutzer-Connector ist nicht verfügbar."}), 404
    public_paths = {
        "/favicon.ico",
        "/apple-touch-icon.png",
        "/apple-touch-icon-precomposed.png",
        "/manifest.webmanifest",
        "/icon.svg",
        "/icon-512.png",
        "/sw.js",
        "/health",
        "/mcp",
        "/mcp-icon.png",
        "/.well-known/oauth-protected-resource",
        "/.well-known/oauth-protected-resource/mcp",
        "/.well-known/oauth-authorization-server",
        "/.well-known/openid-configuration",
    }
    tenant_mcp_public = bool(re.match(r"^/t/[a-z0-9][a-z0-9_-]{0,63}/(?:mcp(?:/|$)|oauth(?:/|$)|\.well-known(?:/|$))", request.path))
    if request.path in public_paths or tenant_mcp_public or request.path.startswith("/oauth/") or request.path.startswith("/shared/") or request.path.startswith("/api/shared/") or request.path.startswith("/recovery/") or request.path.startswith("/api/recovery-share/") or request.path.startswith("/api/shortcut/") or request.path.startswith("/api/password-reset/") or request.endpoint in ["index", "unlock", "unlock_two_factor", "mobile_pair_api", "mobile_pair_two_factor_api", "passkey_auth_begin_api", "passkey_auth_finish_api", "static", "favicon", "password_reset_request_api"]:
        return
    if not session.get("app_unlocked"):
        return jsonify({"status": "locked"}), 401
    current_user = user_record(str(session.get("user_id") or "main"))
    if not current_user or not current_user.get("active", True):
        session.clear()
        return jsonify({"status": "locked", "message": "Dieses Benutzerkonto ist deaktiviert oder nicht mehr vorhanden."}), 401
    expected_generation = app_password_generation()
    session_generation = str(session.get("password_generation") or "legacy")
    if not hmac.compare_digest(session_generation, expected_generation):
        # Sessions created by 16.x contained only the password generation.
        # Keep those alive on a no-2FA account during the additive migration.
        legacy_generation = expected_generation.removesuffix(":legacy-2fa")
        if not two_factor_enabled(current_tenant_id()) and hmac.compare_digest(session_generation, legacy_generation):
            session["password_generation"] = expected_generation
        else:
            session.clear()
            return jsonify({"status": "locked", "message": "Anmeldeschutz wurde geändert. Bitte erneut anmelden."}), 401
    if request.method in {"POST", "PUT", "PATCH", "DELETE"}:
        # Service-worker subscription renewal cannot read HttpOnly/session data
        # into JS; the endpoint remains same-origin + master-session protected.
        csrf_exempt = bool(getattr(g, "api_principal", None))
        if not csrf_exempt:
            expected = csrf_session_token()
            provided = str(request.headers.get("X-CSRF-Token") or "")
            if not provided or not hmac.compare_digest(provided, expected):
                return jsonify({"status": "error", "code": "csrf_failed", "message": "Sicherheits-Token fehlt oder ist ungültig."}), 403


