def shared_fusion_history_points(name, link_data=None):
    """Return guest-safe fusion history that survives later link/profile changes.

    The share stores a small provider snapshot when it is created.  We combine
    those provider IDs with the currently linked provider IDs so an existing
    guest link keeps rendering its already collected timeline even if a 2er/3er
    fusion is later changed or dissolved.  This never recreates a removed live
    link and therefore cannot mutate the owner's tracker configuration.
    """
    link_data = link_data if isinstance(link_data, dict) else {}
    snapshot = link_data.get("fusion_snapshot", {})
    snapshot = snapshot if isinstance(snapshot, dict) else {}
    current_google, current_samsung = fusion_profile_source_ids(name)
    google_ids = {str(value) for value in (current_google, snapshot.get("google_id")) if value}
    samsung_ids = {str(value) for value in (current_samsung, snapshot.get("samsung_id")) if value}

    apple_raw = list(state.get("seven_day_history", {}).get(name, {"points": []}).get("points", []))
    apple_raw.extend(state.get("shared_history", {}).get(name, {"points": []}).get("points", []))
    points = [
        {**point, "source": point.get("source") or "apple", "provider": point.get("provider") or "Apple Find My"}
        for point in apple_raw if isinstance(point, dict)
    ]
    for google_id in google_ids:
        points.extend(
            {**point, "source": "google", "provider": "Google Find Hub"}
            for point in state.get("google_history", {}).get(google_id, {"points": []}).get("points", [])
            if isinstance(point, dict)
        )
    for samsung_id in samsung_ids:
        points.extend(
            {**point, "source": "samsung", "provider": "Samsung SmartThings Find"}
            for point in state.get("samsung_history", {}).get(samsung_id, {"points": []}).get("points", [])
            if isinstance(point, dict)
        )
    share_policy = history_share_policy(name)
    fusion_policy = fusion_history_storage_policy(name)
    storage_policy = history_longest_policy([share_policy, fusion_policy])
    return normalize_route_points(
        points,
        retention_seconds=storage_policy.get("retention_seconds"),
        max_points=history_policy_max_points("apple", storage_policy),
    )


def delayed_share_source_locations(name, link_data, current_sources):
    privacy = share_privacy_config(link_data)
    delay_seconds = int(privacy.get("delay_minutes", 0) or 0) * 60
    if delay_seconds <= 0:
        return dict(current_sources or {})
    cutoff = int(time.time()) - delay_seconds
    delayed = {}
    for point in shared_fusion_history_points(name, link_data):
        ts = int(float(point.get("ts", 0) or 0))
        source = str(point.get("source") or "apple")
        if source not in {"apple", "google", "samsung"} or not ts or ts > cutoff:
            continue
        previous = delayed.get(source)
        if previous is None or ts > int(float(previous.get("ts", 0) or 0)):
            public = route_point_public(point)
            public["source"] = source
            public["provider"] = {"apple": "Apple Find My", "google": "Google Find Hub", "samsung": "Samsung SmartThings Find"}.get(source, source)
            cached = address_from_cached(public.get("lat"), public.get("lon"))
            if cached:
                public["address"] = cached
            delayed[source] = public
    # If the current location itself is old enough, it is valid even when a
    # link was created only recently and no separate history row exists yet.
    for source, current in (current_sources or {}).items():
        if not isinstance(current, dict):
            continue
        ts = int(float(current.get("ts", 0) or 0))
        if ts and ts <= cutoff and (source not in delayed or ts > int(float(delayed[source].get("ts", 0) or 0))):
            delayed[source] = dict(current)
    return delayed


def shared_observation_context(name, link_data, location, permissions, privacy):
    """Small, privacy-aware context block for the classic guest view."""
    current = normalize_point(location) if isinstance(location, dict) else None
    if not current:
        return {"report_count": 0, "observed_duration_seconds": 0, "movement": "unknown"}
    if not permissions.get("show_history"):
        # Duration and movement require comparing multiple reports and therefore
        # belong to the history permission, even though this compact block does
        # not return the underlying coordinates.
        return {
            "report_count": 1,
            "observed_duration_seconds": 0,
            "movement": "not_shared",
            "interpretation": "Nur der aktuelle Standort ist freigegeben; Verlaufsableitungen sind verborgen.",
        }
    history_cutoff = time.time() - int(privacy.get("history_hours", 168) or 168) * 3600
    delay_cutoff = time.time() - int(privacy.get("delay_minutes", 0) or 0) * 60
    points = []
    for raw in shared_fusion_history_points(name, link_data):
        point = normalize_point(raw) if isinstance(raw, dict) else None
        if point and history_cutoff <= point["ts"] <= delay_cutoff + 2:
            points.append(point)
    points.append(current)
    points = normalize_route_points(points, retention_seconds=None)
    nearby = [current]
    previous_ts = current["ts"]
    for point in reversed(points[:-1]):
        if previous_ts - point["ts"] > 12 * 60 * 60:
            break
        radius = max(65, min(450, float(current.get("acc", 0) or 0) + float(point.get("acc", 0) or 0) + 30))
        if haversine_distance(current["lat"], current["lon"], point["lat"], point["lon"]) > radius:
            break
        nearby.append(point)
        previous_ts = point["ts"]
    observed_from = min(point["ts"] for point in nearby)
    recent_motion = [point for point in points if point["ts"] >= current["ts"] - 2 * 3600]
    motion = transit_motion_summary(recent_motion)
    context = {
        "observed_from_ts": int(observed_from),
        "observed_until_ts": int(current["ts"]),
        "observed_duration_seconds": max(0, int(current["ts"] - observed_from)),
        "report_count": len(nearby),
        "movement": "moving" if motion.get("moving") else "stationary_or_unclear",
        "median_speed_kmh": motion.get("median_speed_kmh") if motion.get("moving") else None,
        "interpretation": "Aus freigegebenen Meldungen abgeleitet; keine Echtzeit-Anwesenheitsgarantie.",
    }
    if permissions.get("show_geofences"):
        refs = [f"apple:{name}"]
        google_id, samsung_id = fusion_profile_source_ids(name)
        if google_id:
            refs.append(f"google:{google_id}")
        if samsung_id:
            refs.append(f"samsung:{samsung_id}")
        context["geofence_context"] = mcp_location_zone_context(current, refs, mcp_place_catalog(refs), public_guest=True)
    return context


def shared_provider_catalog(name, link_data, profile=None):
    """Describe guest-visible live and historical providers without controls."""
    snapshot = (link_data or {}).get("fusion_snapshot", {})
    snapshot = snapshot if isinstance(snapshot, dict) else {}
    snapshot_labels = snapshot.get("labels", {}) if isinstance(snapshot.get("labels"), dict) else {}
    snapshot_sources = {
        source for source in (snapshot.get("providers") or [])
        if source in {"apple", "google", "samsung"}
    }

    current_google, current_samsung = fusion_profile_source_ids(name)
    live_sources = {"apple"}
    if current_google:
        live_sources.add("google")
    if current_samsung:
        live_sources.add("samsung")
    if isinstance(profile, dict):
        live_sources = {
            source for source in (profile.get("providers") or [])
            if source in {"apple", "google", "samsung"}
        } or live_sources

    visible_sources = live_sources | snapshot_sources
    labels = {
        "apple": device_display_name(name),
        "google": str(state.get("google_devices", {}).get(current_google, {}).get("name") or snapshot_labels.get("google") or "Google Tag") if (current_google or "google" in snapshot_sources) else None,
        "samsung": str(state.get("samsung_devices", {}).get(current_samsung, {}).get("name") or snapshot_labels.get("samsung") or "Galaxy SmartTag") if (current_samsung or "samsung" in snapshot_sources) else None,
    }
    if isinstance(profile, dict):
        labels.update({
            "apple": profile.get("apple_label") or labels["apple"],
            "google": profile.get("google_label") or labels.get("google"),
            "samsung": profile.get("samsung_label") or labels.get("samsung"),
        })
    for source, label in snapshot_labels.items():
        if source in labels and not labels.get(source) and label:
            labels[source] = str(label)

    result = []
    for source in ("apple", "google", "samsung"):
        if source not in visible_sources:
            continue
        result.append({
            "source": source,
            "label": str(labels.get(source) or ({"apple": "Apple Find My", "google": "Google Find Hub", "samsung": "Samsung SmartThings Find"}[source]))[:100],
            "live": source in live_sources,
        })
    return result or [{"source": "apple", "label": device_display_name(name), "live": True}]


def shared_state_revision(link_id, link_data):
    """Build a small, device-scoped ETag for the public guest viewer.

    A guest refresh must not fingerprint every tracker, session and diagnostic
    result in the private console.  Only values that can change this link's
    response participate in the revision.
    """
    name = str((link_data or {}).get("device") or "")

    def stable_location(payload):
        if not isinstance(payload, dict):
            return None
        return {
            key: payload.get(key)
            for key in ("lat", "lon", "acc", "bat", "battery", "ts", "confidence", "status", "source", "provider")
            if payload.get(key) is not None
        }

    with state_lock:
        apple_object = state.get("locations", {}).get(name)
        apple_location = location_payload(apple_object) if apple_object else None
        google_link = google_link_for_apple(name)
        samsung_link = samsung_link_for_apple(name)
        google_id = (google_link or {}).get("google_id")
        samsung_id = (samsung_link or {}).get("samsung_id")
        google_location = google_public_location(state.get("google_locations", {}).get(google_id)) if google_id else None
        samsung_location = samsung_public_location(state.get("samsung_locations", {}).get(samsung_id)) if samsung_id else None
        address_entries = {}
        for location in (apple_location, google_location, samsung_location):
            if not location:
                continue
            key = address_cache_key(location["lat"], location["lon"])
            if key in state.get("address_cache", {}):
                address_entries[key] = state["address_cache"][key]
        signature = {
            "link_id": str(link_id),
            "link": {
                "device": name,
                "active": bool((link_data or {}).get("active")),
                "expires_ts": int(float((link_data or {}).get("expires_ts", 0) or 0)),
                "permissions": share_permissions(
                    link_data or {},
                    history_fallback=bool(state.get("share_history_enabled", {}).get(name)),
                ),
                "privacy": share_privacy_config(link_data or {}),
                "fusion_snapshot": (link_data or {}).get("fusion_snapshot", {}),
                "last_locate_ts": int(float((link_data or {}).get("last_locate_ts", 0) or 0)),
            },
            "meta": state.get("tracker_meta", {}).get(name, {}),
            "locations": {
                "apple": stable_location(apple_location),
                "google": stable_location(google_location),
                "samsung": stable_location(samsung_location),
            },
            "history": {
                "enabled": bool(state.get("share_history_enabled", {}).get(name)),
                "apple": state_history_revision({name: state.get("seven_day_history", {}).get(name, {})}),
                "google": state_history_revision({str(google_id): state.get("google_history", {}).get(google_id, {})}) if google_id else {},
                "samsung": state_history_revision({str(samsung_id): state.get("samsung_history", {}).get(samsung_id, {})}) if samsung_id else {},
                "shared": state_history_revision({name: state.get("shared_history", {}).get(name, {})}),
            },
            "links": {"google": google_link, "samsung": samsung_link},
            "fusion_profile": state.get("fusion_profiles", {}).get(name, {}),
            "report_stats": state.get("report_stats", {}).get("devices", {}).get(name, {}),
            "last_manual_fetch": state.get("last_manual_fetch", {}).get(name, 0),
            "addresses": address_entries,
        }
    encoded = json.dumps(signature, ensure_ascii=False, sort_keys=True, separators=(",", ":"), default=str).encode("utf-8")
    return hashlib.blake2s(encoded, digest_size=16).hexdigest()


def shared_current_source_locations(name):
    """Return only live source coordinates a guest link may already see."""
    loc_obj = state.get("locations", {}).get(name)
    # A freshly imported accessory may legitimately have no Apple report yet.
    # Guest Push can still be armed against linked Google/Samsung sources.
    apple_loc = location_payload(loc_obj) if loc_obj else None
    profile = fusion_profile_public(name)
    if isinstance(profile, dict):
        locations = profile.get("source_locations", {}) or {}
        if apple_loc and not locations.get("apple"):
            locations = {**locations, "apple": apple_loc}
        return {
            source: location
            for source, location in locations.items()
            if source in {"apple", "google", "samsung"} and isinstance(location, dict)
        }
    _fusion, apple_loc, google_loc, samsung_loc, _google_link, _samsung_link = fusion_locations(name, apple_loc)
    return {
        source: location
        for source, location in (("apple", apple_loc), ("google", google_loc), ("samsung", samsung_loc))
        if isinstance(location, dict)
    }


@app.route("/api/recovery-share/<link_id>", methods=["POST"])
def recovery_shared_api(link_id):
    data = request.json or {}
    action = str(data.get("action") or "view")
    link = state.get("recovery_shares", {}).get(link_id)
    status = recovery_share_status(link)
    if status == "expired":
        return jsonify({"error": "Expired", "message": "Diese Recovery-Freigabe ist abgelaufen."}), 410
    if status != "active":
        return jsonify({"error": "Unavailable", "message": "Diese Recovery-Freigabe ist nicht mehr aktiv."}), 404
    grant_id = f"recovery:{link_id}"
    key = f"{client_key()}:{grant_id}"
    authorized = shared_access_authorized(grant_id, link)
    if action == "unlock" and not authorized:
        if is_share_rate_limited(key):
            return jsonify({"error": "Too many attempts", "message": "Zu viele Fehlversuche. Bitte später erneut versuchen."}), 429
        if not verify_shared_password(link, data.get("pw", "")):
            register_share_failure(key)
            return jsonify({"error": "Unauthorized", "message": "Passwort nicht korrekt."}), 401
        clear_share_failures(key)
        grant_shared_session(grant_id, link)
        authorized = True
        response = jsonify({"status": "ok"})
        if share_bool(data.get("remember"), True):
            set_shared_remember_cookie(response, grant_id, link)
        return response
    if not authorized:
        return jsonify({"error": "Unauthorized", "message": "Passwort erforderlich."}), 401
    if action == "locate":
        permissions = recovery_share_permissions(link)
        if not permissions.get("can_refresh"):
            return jsonify({"error": "Forbidden", "message": "Der Eigentümer hat keine Ortungsanfragen für diesen Helferlink freigegeben."}), 403
        now_ts = int(time.time())
        last = int(link.get("last_locate_ts", 0) or 0)
        if now_ts - last < 60:
            return jsonify({"error": "Cooldown", "message": f"Bitte noch {60-(now_ts-last)} Sekunden warten."}), 429
        name = str(link.get("device") or "")
        if name not in state.get("accessories", {}):
            return jsonify({"error": "Unavailable", "message": "Der Apple-Tracker ist nicht mehr verfügbar."}), 404
        link["last_locate_ts"] = now_ts
        save_recovery_state(history=False, shares=True)
        recovery_log_share_access(link_id, "locate")
        threading.Thread(target=fetch_from_apple, args=([name], "recovery_helper"), daemon=True).start()
        return jsonify({"status": "queued", "last_locate_ts": now_ts}), 202
    recovery_log_share_access(link_id, "view")
    payload = recovery_share_payload(link_id, link)
    if not payload:
        return jsonify({"error": "Unavailable", "message": "Der Tracker ist nicht mehr verfügbar."}), 404
    return jsonify(payload)


@app.route("/api/shared/<link_id>", methods=["POST"])
def api_shared_data(link_id):
    data = request.json or {}
    remember_requested = share_bool(data.get("remember"), False)
    key = f"{client_key()}:{link_id}"
    link_data = state["shared_links"].get(link_id)
    link_status = share_link_status(link_data)
    if link_status == "expired":
        return jsonify({"error": "Expired", "message": "Diese Freigabe ist abgelaufen."}), 410
    if link_status != "active":
        return jsonify({"error": "Unavailable", "message": "Diese Freigabe ist nicht mehr aktiv."}), 404
    remembered_authorized = shared_remembered_authorized(link_id, link_data)
    session_authorized = shared_session_authorized(link_id, link_data)
    if not (remembered_authorized or session_authorized):
        if is_share_rate_limited(key):
            return jsonify({"error": "Too many attempts"}), 429
        if not verify_shared_password(link_data, data.get("pw", "")):
            register_share_failure(key)
            return jsonify({"error": "Unauthorized"}), 401
        clear_share_failures(key)
        grant_shared_session(link_id, link_data)
    # A long-lived remembered grant is only minted after a real password
    # verification (unless this browser already owns the valid remember grant).
    if remember_requested and not remembered_authorized:
        if not verify_shared_password(link_data, data.get("pw", "")):
            register_share_failure(key)
            return jsonify({"error": "Unauthorized"}), 401
        clear_share_failures(key)
    shared_revision = shared_state_revision(link_id, link_data)
    if request.if_none_match and request.if_none_match.contains(shared_revision):
        response = Response(status=304)
        response.set_etag(shared_revision)
        if remember_requested:
            set_shared_remember_cookie(response, link_id, link_data)
        return response
    name = link_data["device"]
    permissions = share_permissions(
        link_data,
        history_fallback=bool(state["share_history_enabled"].get(name)),
    )
    loc_obj = state["locations"].get(name)
    apple_loc_dict = location_payload(loc_obj) if loc_obj else None
    if apple_loc_dict:
        cached_address = address_from_cached(apple_loc_dict["lat"], apple_loc_dict["lon"])
        if cached_address:
            apple_loc_dict["address"] = cached_address

    # A current fusion gets the same conservative display location as the
    # owner's Fusion page.  If the fusion was dissolved later, the link
    # deliberately falls back to the still valid Apple tracker instead of
    # breaking or recreating any deleted provider link.
    fusion_profile = fusion_profile_public(name)
    if fusion_profile:
        loc_dict = fusion_profile.get("location")
        source_locations = fusion_profile.get("source_locations", {}) or {}
        google_loc_dict = source_locations.get("google")
        samsung_loc_dict = source_locations.get("samsung")
        apple_loc_dict = source_locations.get("apple") or apple_loc_dict
        google_fusion_link = {"google_id": fusion_profile.get("google_id")} if fusion_profile.get("google_id") else None
        samsung_fusion_link = {"samsung_id": fusion_profile.get("samsung_id")} if fusion_profile.get("samsung_id") else None
        fusion_level = int(fusion_profile.get("provider_count") or 1)
        share_kind = "fusion"
    else:
        loc_dict, apple_loc_dict, google_loc_dict, samsung_loc_dict, google_fusion_link, samsung_fusion_link = fusion_locations(name, apple_loc_dict)
        source_locations = {
            source: location
            for source, location in (("apple", apple_loc_dict), ("google", google_loc_dict), ("samsung", samsung_loc_dict))
            if location
        }
        fusion_level = 3 if google_fusion_link and samsung_fusion_link else (2 if google_fusion_link or samsung_fusion_link else 1)
        share_kind = "fusion" if fusion_level >= 2 else "tracker"

    snapshot = link_data.get("fusion_snapshot", {}) if isinstance(link_data.get("fusion_snapshot", {}), dict) else {}
    if snapshot.get("was_fusion"):
        share_kind = "fusion"
        if not fusion_profile:
            fusion_level = max(fusion_level, int(snapshot.get("provider_count", 0) or 0))
    privacy = share_privacy_config(link_data)
    source_locations = delayed_share_source_locations(name, link_data, source_locations)
    if int(privacy.get("delay_minutes", 0) or 0) > 0:
        loc_dict = max(source_locations.values(), key=lambda row: float(row.get("ts", 0) or 0), default=None)
    provider_catalog = shared_provider_catalog(name, link_data, fusion_profile)
    public_sources = {
        source: shared_location_payload(location, permissions, privacy)
        for source, location in source_locations.items()
        if source in {"apple", "google", "samsung"} and location
    }
    if not permissions.get("show_provider", True):
        # Provider names are a real share permission, not merely a visual
        # preference. Collapse the live sources so inspecting the JSON cannot
        # reveal Apple/Google/Samsung identities either.
        generic_location = shared_location_payload(loc_dict, permissions, privacy)
        public_sources = {"tracker": generic_location} if generic_location else {}
        provider_catalog = [{"source": "tracker", "label": "Tracker", "live": True}]
    raw_meta = state["tracker_meta"].get(name, {"name": name, "emoji": "📍"})
    meta = {
        "name": str(raw_meta.get("name") or name)[:80],
        "emoji": str(raw_meta.get("emoji") or "📍")[:16],
        "kind": str(raw_meta.get("kind") or "")[:40],
    }
    last_shared_locate = int(float(link_data.get("last_locate_ts", 0) or 0))
    public_report_stats = {
        "total_received": int(state.get("report_stats", {}).get("devices", {}).get(name, {}).get("total_received", 0) or 0),
    }
    snapshot_public = link_data.get("fusion_snapshot", {}) if isinstance(link_data.get("fusion_snapshot", {}), dict) else {}
    snapshot_public = {
        "was_fusion": bool(snapshot_public.get("was_fusion")),
        "provider_count": int(snapshot_public.get("provider_count", 0) or 0),
        "providers": [source for source in (snapshot_public.get("providers") or []) if source in {"apple", "google", "samsung"}] if permissions.get("show_provider", True) else [],
    }
    res = {
        "device": name,
        "meta": meta,
        "share_kind": share_kind,
        "location": shared_location_payload(loc_dict, permissions, privacy),
        "source_locations": public_sources,
        "providers": provider_catalog,
        "apple_location": public_sources.get("apple"),
        "google_location": public_sources.get("google"),
        "samsung_location": public_sources.get("samsung"),
        "linked_google": bool(google_fusion_link) if permissions.get("show_provider", True) else False,
        "linked_samsung": bool(samsung_fusion_link) if permissions.get("show_provider", True) else False,
        "fusion_level": fusion_level,
        "fusion_active": bool(fusion_profile),
        "fusion_snapshot": snapshot_public,
        "fusion_optimization": (fusion_profile or {}).get("optimization") if fusion_profile and permissions.get("show_provider", True) else None,
        "last_manual_fetch": state["last_manual_fetch"].get(name, 0),
        "last_shared_locate": last_shared_locate,
        "next_locate_ts": last_shared_locate + 30 if permissions.get("can_locate") else 0,
        "locate_cooldown_seconds": 30,
        "report_stats": public_report_stats,
        "permissions": permissions,
        "privacy": privacy,
        "history_policy": history_policy_public("fusion" if share_kind == "fusion" else "apple", name),
        "observation_context": shared_observation_context(name, link_data, loc_dict, permissions, privacy),
        "freshness_thresholds": freshness_thresholds(),
        "generated_at": int(time.time()),
        "expires_ts": int(float(link_data.get("expires_ts", 0) or 0)),
    }
    if permissions["show_history"] and share_capture_required(name):
        storage_policy = fusion_history_storage_policy(name)
        privacy_retention = int(privacy.get("history_hours", 168) or 168) * 3600
        policy_retention = storage_policy.get("retention_seconds")
        history_retention = privacy_retention if policy_retention is None else min(policy_retention, privacy_retention)
        delay_cutoff = time.time() - int(privacy.get("delay_minutes", 0) or 0) * 60
        pts = []
        for point in shared_fusion_history_points(name, link_data):
            if int(privacy.get("delay_minutes", 0) or 0) > 0 and float(point.get("ts", 0) or 0) > delay_cutoff:
                continue
            shielded = shared_location_payload(point, permissions, privacy)
            if not shielded:
                continue
            if not permissions.get("show_provider", True):
                shielded["source"] = "tracker"
                shielded.pop("provider", None)
            pts.append(shielded)
        res["seven_day_history"] = route_payload(pts, "Geteilter Fusion-Verlauf" if share_kind == "fusion" else "Geteilter Verlauf", retention_seconds=history_retention, default_limit=3600)
        if not permissions.get("show_provider", True):
            for point in res["seven_day_history"].get("points", []):
                point["source"] = "tracker"
                point.pop("provider", None)
    record_share_access(link_id, "ok")
    response = jsonify(res)
    response.set_etag(shared_revision)
    if remember_requested:
        set_shared_remember_cookie(response, link_id, link_data)
    return response


@app.route("/api/shared/<link_id>/address", methods=["POST"])
def api_shared_address(link_id):
    """Resolve a guest-visible live source to a rich cached place/address.

    Coordinates are never accepted from the browser. The requested provider
    must already be a live source of this share, preventing the endpoint from
    becoming a public arbitrary geocoder.
    """
    data = request.json or {}
    key = f"{client_key()}:{link_id}"
    link_data = state.get("shared_links", {}).get(link_id)
    link_status = share_link_status(link_data)
    if link_status == "expired":
        return jsonify({"error": "Expired", "message": "Diese Freigabe ist abgelaufen."}), 410
    if link_status != "active":
        return jsonify({"error": "Unavailable", "message": "Diese Freigabe ist nicht mehr aktiv."}), 404
    if not shared_access_authorized(link_id, link_data):
        if is_share_rate_limited(key):
            return jsonify({"error": "Too many attempts"}), 429
        if not verify_shared_password(link_data, data.get("pw", "")):
            register_share_failure(key)
            return jsonify({"error": "Unauthorized"}), 401
        clear_share_failures(key)
        grant_shared_session(link_id, link_data)

    name = link_data["device"]
    permissions = share_permissions(
        link_data,
        history_fallback=bool(state.get("share_history_enabled", {}).get(name)),
    )
    if not permissions.get("show_address", True):
        return jsonify({"status": "forbidden", "message": "Adressanzeige ist für diesen Link deaktiviert."}), 403

    privacy = share_privacy_config(link_data)
    locations = delayed_share_source_locations(name, link_data, shared_current_source_locations(name))
    requested_source = str(data.get("source") or "").strip().lower()
    hide_provider = not permissions.get("show_provider", True)
    if hide_provider or requested_source not in locations:
        requested_source = max(
            locations,
            key=lambda source: float((locations[source] or {}).get("ts", 0) or 0),
            default="",
        )
    location = locations.get(requested_source)
    if not location:
        return jsonify({"status": "empty", "message": "Für diese Quelle liegt noch kein Live-Standort vor."}), 404
    # Apply the exact same delay and precision policy as the guest map before
    # resolving an address. This prevents the address endpoint from becoming a
    # side channel for a newer or more precise position.
    public_location = shared_location_payload(location, permissions, privacy)
    try:
        lat = float((public_location or {}).get("lat"))
        lon = float((public_location or {}).get("lon"))
        if not -90 <= lat <= 90 or not -180 <= lon <= 180:
            raise ValueError
    except (TypeError, ValueError):
        return jsonify({"status": "error", "message": "Der freigegebene Standort enthält ungültige Koordinaten."}), 422

    address, cached, retry_after = reverse_geocode(lat, lon)
    if retry_after:
        response = jsonify({"status": "retry", "retry_after": retry_after})
        response.status_code = 429
        response.headers["Retry-After"] = str(retry_after)
        return response
    if not address:
        if not GEOCODING_ENABLED:
            return jsonify({"status": "disabled", "message": "Adresssuche ist deaktiviert."}), 503
        return jsonify({"status": "error", "message": "Für diesen Standort konnte keine Adresse ermittelt werden."}), 502
    shielded = shared_location_payload({"lat": lat, "lon": lon, "address": address}, permissions, privacy) or {}
    public_address = shielded.get("address")
    if not public_address:
        return jsonify({"status": "empty", "message": "Für diese Freigabestufe wird keine genauere Adresse angezeigt."}), 404
    return jsonify({
        "status": "ok",
        "source": "tracker" if hide_provider else requested_source,
        "address": public_address,
        "cached": bool(cached),
        "attribution": "Adressdaten © OpenStreetMap-Mitwirkende",
    })


@app.route("/api/shared/<link_id>/locate", methods=["POST"])
def api_shared_locate(link_id):
    data = request.json or {}
    key = f"{client_key()}:{link_id}"
    link_data = state["shared_links"].get(link_id)
    link_status = share_link_status(link_data)
    if link_status == "expired":
        return jsonify({"error": "Expired", "message": "Diese Freigabe ist abgelaufen."}), 410
    if link_status != "active":
        return jsonify({"error": "Unavailable", "message": "Diese Freigabe ist nicht mehr aktiv."}), 404
    if not shared_access_authorized(link_id, link_data):
        if is_share_rate_limited(key):
            return jsonify({"error": "Too many attempts"}), 429
        if not verify_shared_password(link_data, data.get("pw", "")):
            register_share_failure(key)
            return jsonify({"error": "Unauthorized"}), 401
        clear_share_failures(key)
        grant_shared_session(link_id, link_data)
    name = link_data["device"]
    permissions = share_permissions(
        link_data,
        history_fallback=bool(state["share_history_enabled"].get(name)),
    )
    if not permissions["can_locate"]:
        return jsonify({"status": "forbidden", "message": "Der Besitzer hat Live-Aktualisierungen für diesen Link deaktiviert."}), 403
    now = time.time()
    last_fetch = float(link_data.get("last_locate_ts", 0) or 0)
    cooldown = 30
    if now - last_fetch < cooldown:
        return jsonify({
            "status": "cooldown",
            "remaining": max(1, int(math.ceil(cooldown - (now - last_fetch)))),
            "next_locate_ts": int(last_fetch + cooldown),
        }), 429
    link_data["last_locate_ts"] = int(now)
    state["last_manual_fetch"][name] = now
    save_json(LINKS_FILE, "shared_links")
    threading.Thread(target=fetch_from_apple, args=([name],), daemon=True).start()
    google_id, samsung_id = fusion_profile_source_ids(name)
    providers = ["apple"]
    if google_id:
        providers.append("google")
        threading.Thread(target=fetch_from_google, args=(google_id, "shared_manual"), daemon=True).start()
    if samsung_id:
        providers.append("samsung")
        threading.Thread(target=fetch_from_samsung, args=(samsung_id, "shared_manual"), daemon=True).start()
    return jsonify({
        "status": "ok",
        "providers": providers if permissions.get("show_provider", True) else ["tracker"],
        "next_locate_ts": int(now) + cooldown,
        "cooldown_seconds": cooldown,
    })


def authorize_guest_push_request(link_id, data=None):
    link = state.get("shared_links", {}).get(link_id)
    status = share_link_status(link)
    if status != "active":
        state.get("guest_push_channels", {}).pop(link_id, None)
        atomic_write_json(GUEST_PUSH_FILE, state.get("guest_push_channels", {}), private=True)
        return None, (jsonify({"status": "error", "message": "Freigabelink ist abgelaufen oder nicht mehr aktiv."}), 410 if status == "expired" else 404)
    if shared_access_authorized(link_id, link):
        return link, None
    data = data if isinstance(data, dict) else {}
    if data.get("pw") and verify_shared_password(link, data.get("pw")):
        grant_shared_session(link_id, link)
        return link, None
    return None, (jsonify({"status": "error", "message": "Gast-Push benötigt zuerst die Freigabe-Anmeldung."}), 401)






def finish_user_login(row):
    security_bridge = bool(session.get("security_bridge"))
    user_id = str(row.get("id") or "main")
    ensure_tenant_state(user_id, start_workers=True)
    row["last_login_ts"] = int(time.time())
    row["updated_ts"] = int(row.get("updated_ts", 0) or 0) or int(time.time())
    try:
        save_users_registry()
    except OSError:
        pass
    session.clear()
    session.permanent = True
    session["app_unlocked"] = True
    if security_bridge:
        session["security_bridge"] = True
    session["user_id"] = user_id
    session["role"] = str(row.get("role") or ("owner" if user_id == "main" else "user"))
    with tenant_context(user_id):
        session["password_generation"] = app_password_generation()
    session["csrf_token"] = secrets.token_urlsafe(32)
    return {
        "status": "ok",
        "csrf_token": session["csrf_token"],
        "user": {
            "id": user_id,
            "username": str(row.get("username") or "admin"),
            "display_name": str(row.get("display_name") or row.get("username") or "Benutzer"),
            "is_main_admin": user_id == "main",
            "two_factor": two_factor_public_status(user_id),
            "passkeys": passkey_public_status(user_id),
        },
    }


def verify_identity_password(user_id, candidate):
    row = user_record(user_id)
    return verify_app_password(candidate) if str(user_id) == "main" else verify_user_password(row, candidate)


@app.route("/api/unlock", methods=["POST"])
def unlock():
    key = client_key()
    if is_unlock_rate_limited(key):
        return jsonify({"status": "error", "message": "Zu viele Versuche. Bitte später erneut versuchen."}), 429
    data = request.json or {}
    provided = str(data.get("pw", ""))
    username = str(data.get("username") or "").strip()
    owner = user_record("main")
    row = owner if not username else find_user_by_username(username)
    authenticated = False
    if row and str(row.get("id") or "") == "main":
        authenticated = verify_app_password(provided)
    elif row:
        authenticated = verify_user_password(row, provided)
    if authenticated and row and row.get("active", True):
        user_id = str(row.get("id") or "main")
        try:
            ensure_tenant_state(user_id, start_workers=True)
        except Exception as exc:
            logger.exception("Benutzerbereich %s konnte nicht geladen werden: %s", user_id, exc)
            return jsonify({"status": "error", "message": "Der Benutzerbereich konnte nicht sicher geladen werden."}), 500
        clear_unlock_failures(key)
        if two_factor_enabled(user_id):
            session.clear()
            session.permanent = True
            session["pending_two_factor"] = {
                "user_id": user_id,
                "expires_ts": int(time.time()) + 5 * 60,
                "nonce": secrets.token_urlsafe(18),
            }
            return jsonify({
                "status": "two_factor_required",
                "message": "Bitte den Code aus deiner Authenticator-App eingeben.",
                "user": {
                    "username": str(row.get("username") or "admin"),
                    "display_name": str(row.get("display_name") or row.get("username") or "Benutzer"),
                },
                "recovery_available": two_factor_public_status(user_id).get("recovery_codes_remaining", 0) > 0,
            }), 202
        try:
            return jsonify(finish_user_login(row))
        except Exception as exc:
            logger.exception("Benutzerbereich %s konnte beim Login nicht finalisiert werden: %s", user_id, exc)
            return jsonify({"status": "error", "message": "Der Benutzerbereich konnte nicht sicher geladen werden."}), 500
    register_unlock_failure(key)
    return jsonify({"status": "error", "message": "Benutzername oder Passwort ist nicht korrekt."}), 403


@app.route("/api/unlock/2fa", methods=["POST"])
def unlock_two_factor():
    pending = session.get("pending_two_factor") if isinstance(session.get("pending_two_factor"), dict) else {}
    user_id = str(pending.get("user_id") or "")
    key = "2fa-login:" + client_key()
    if is_unlock_rate_limited(key):
        return jsonify({"status": "error", "message": "Zu viele Versuche. Bitte später erneut versuchen."}), 429
    if not user_id or int(pending.get("expires_ts", 0) or 0) <= int(time.time()):
        session.clear()
        return jsonify({"status": "error", "code": "two_factor_expired", "message": "Die Anmeldung ist abgelaufen. Bitte Passwort erneut eingeben."}), 401
    row = user_record(user_id)
    if not row or not row.get("active", True) or not two_factor_enabled(user_id):
        session.clear()
        return jsonify({"status": "error", "message": "Die Zwei-Faktor-Anmeldung ist nicht mehr gültig."}), 401
    code = str((request.get_json(silent=True) or {}).get("code") or "")
    valid, method = verify_two_factor_code(user_id, code, consume=True)
    if not valid:
        register_unlock_failure(key)
        return jsonify({"status": "error", "code": "two_factor_invalid", "message": "Der Zwei-Faktor- oder Wiederherstellungscode ist nicht korrekt."}), 403
    clear_unlock_failures(key)
    try:
        payload = finish_user_login(row)
        payload["two_factor_method"] = method
        return jsonify(payload)
    except Exception as exc:
        logger.exception("Benutzerbereich %s konnte nach 2FA nicht geladen werden: %s", user_id, exc)
        return jsonify({"status": "error", "message": "Der Benutzerbereich konnte nicht sicher geladen werden."}), 500


@app.route("/api/logout", methods=["POST"])
def logout_session():
    session.clear()
    return jsonify({"status": "ok"})


@app.route("/api/security/password", methods=["POST"])
def change_master_password():
    data = request.json or {}
    current = str(data.get("current_password") or "")
    new_password = str(data.get("new_password") or "")
    confirmation = str(data.get("confirm_password") or "")
    user_id = current_tenant_id()
    row = user_record(user_id)
    valid_current = verify_app_password(current) if user_id == "main" else verify_user_password(row, current)
    if not valid_current:
        return jsonify({"status": "error", "message": "Das aktuelle Passwort ist nicht korrekt."}), 403
    if new_password != confirmation:
        return jsonify({"status": "error", "message": "Die beiden neuen Passwörter stimmen nicht überein."}), 400
    if len(new_password) < 10:
        return jsonify({"status": "error", "message": "Das neue Master-Passwort muss mindestens 10 Zeichen lang sein."}), 400
    if len(new_password) > 512:
        return jsonify({"status": "error", "message": "Das neue Master-Passwort ist zu lang."}), 400
    if hmac.compare_digest(current, new_password):
        return jsonify({"status": "error", "message": "Bitte wähle ein anderes Passwort als bisher."}), 400
    try:
        if user_id == "main":
            record = persist_app_password(new_password)
        else:
            with _users_lock:
                row.update(user_password_record(new_password))
                row["updated_ts"] = int(time.time())
                save_users_registry()
            record = row
    except OSError as exc:
        logger.error("Passwort konnte nicht gespeichert werden: %s", exc)
        return jsonify({"status": "error", "message": "Das neue Passwort konnte nicht sicher gespeichert werden."}), 500
    mcp_revoke_owner_grants("master_password_changed")
    # Keep this browser signed in, but invalidate every older browser session.
    session["password_generation"] = app_password_generation()
    session["csrf_token"] = secrets.token_urlsafe(32)
    return jsonify({
        "status": "ok",
        "message": "Passwort geändert. Andere bestehende Sitzungen müssen sich neu anmelden.",
        "csrf_token": session["csrf_token"],
    })


def verify_pending_totp(secret, candidate):
    digits = re.sub(r"\D", "", str(candidate or ""))
    if len(digits) != 6:
        return None
    current = totp_counter()
    for counter in (current, current - 1, current + 1):
        try:
            expected = totp_code_for_secret(secret, at_time=counter * 30)
        except Exception:
            return None
        if hmac.compare_digest(expected, digits):
            return counter
    return None


