@app.route("/api/security/2fa/setup", methods=["POST"])
def two_factor_setup_api():
    data = request.get_json(silent=True) or {}
    user_id = current_tenant_id()
    if not verify_identity_password(user_id, data.get("current_password")):
        return jsonify({"status": "error", "message": "Das aktuelle Passwort ist nicht korrekt."}), 403
    if two_factor_enabled(user_id):
        valid, _method = verify_two_factor_code(user_id, data.get("current_code"), consume=True)
        if not valid:
            return jsonify({"status": "error", "message": "Zum erneuten Einrichten ist ein gültiger Zwei-Faktor- oder Wiederherstellungscode nötig."}), 403
    prune_two_factor_pending()
    secret = generate_totp_secret()
    token = secrets.token_urlsafe(32)
    with _two_factor_pending_lock:
        _two_factor_pending[token] = {
            "user_id": user_id,
            "secret": secret,
            "expires_ts": int(time.time()) + 10 * 60,
        }
    return jsonify({
        "status": "ok",
        "setup_token": token,
        "setup_key": secret,
        "otpauth_uri": two_factor_otpauth_uri(user_id, secret),
        "qr_url": f"/api/security/2fa/setup/qr?token={urllib.parse.quote(token)}",
        "expires_ts": int(time.time()) + 10 * 60,
        "message": "QR-Code scannen und anschließend einen aktuellen sechsstelligen Code bestätigen.",
    })


@app.route("/api/security/2fa/setup/qr", methods=["GET"])
def two_factor_setup_qr_api():
    prune_two_factor_pending()
    token = str(request.args.get("token") or "")
    with _two_factor_pending_lock:
        pending = dict(_two_factor_pending.get(token) or {})
    if not pending or str(pending.get("user_id") or "") != current_tenant_id():
        return jsonify({"status": "error", "message": "Der QR-Code ist ungültig oder abgelaufen."}), 404
    content, mimetype = two_factor_qr_svg(two_factor_otpauth_uri(current_tenant_id(), pending.get("secret")))
    if not content:
        return jsonify({"status": "error", "message": "QR-Code-Bibliothek fehlt. Bitte den Einrichtungsschlüssel verwenden."}), 503
    response = Response(content, mimetype=mimetype)
    response.headers["Cache-Control"] = "no-store"
    response.headers["Content-Security-Policy"] = "default-src 'none'; style-src 'none'; sandbox"
    return response


@app.route("/api/security/2fa/confirm", methods=["POST"])
def two_factor_confirm_api():
    data = request.get_json(silent=True) or {}
    token = str(data.get("setup_token") or "")
    prune_two_factor_pending()
    with _two_factor_pending_lock:
        pending = dict(_two_factor_pending.get(token) or {})
    user_id = current_tenant_id()
    if not pending or str(pending.get("user_id") or "") != user_id:
        return jsonify({"status": "error", "message": "Die Einrichtung ist ungültig oder abgelaufen."}), 404
    counter = verify_pending_totp(pending.get("secret"), data.get("code"))
    if counter is None:
        return jsonify({"status": "error", "message": "Der Authenticator-Code ist nicht korrekt."}), 400
    recovery_codes = generate_recovery_codes(10)
    now_ts = int(time.time())
    store = load_two_factor_store()
    with _two_factor_lock:
        store.setdefault("users", {})[user_id] = {
            "enabled": True,
            "secret_enc": encrypt_two_factor_secret(user_id, pending.get("secret")),
            "recovery_hashes": [recovery_code_digest(user_id, code) for code in recovery_codes],
            "last_counter": int(counter),
            "created_ts": int((two_factor_record(user_id) or {}).get("created_ts", now_ts) or now_ts),
            "updated_ts": now_ts,
            "last_used_ts": 0,
            "last_used_method": "",
        }
        save_two_factor_store(store)
    with _two_factor_pending_lock:
        _two_factor_pending.pop(token, None)
    rotate_user_auth_generation(user_id)
    session["password_generation"] = app_password_generation()
    session["csrf_token"] = secrets.token_urlsafe(32)
    mcp_revoke_owner_grants("two_factor_changed")
    audit_event("two_factor_enabled", user_id, "Authenticator-Zwei-Faktor aktiviert")
    return jsonify({
        "status": "ok",
        "message": "Zwei-Faktor-Schutz ist aktiv. Wiederherstellungscodes werden nur jetzt angezeigt.",
        "two_factor": two_factor_public_status(user_id),
        "recovery_codes": recovery_codes,
        "csrf_token": session["csrf_token"],
    })


@app.route("/api/security/2fa", methods=["DELETE"])
def two_factor_disable_api():
    user_id = current_tenant_id()
    if not two_factor_enabled(user_id):
        return jsonify({"status": "ok", "two_factor": two_factor_public_status(user_id)})
    data = request.get_json(silent=True) or {}
