@app.route("/api/internal-shares", methods=["GET", "POST"])
def internal_shares_api():
    user_id = current_tenant_id()
    if request.method == "GET":
        include_history = bool_from_any(request.args.get("history"), True)
        try:
            return jsonify(internal_share_snapshot_for_user(user_id, include_history=include_history))
        except Exception as exc:
            logger.exception("Interne Freigaben konnten nicht geladen werden: %s", exc)
            return jsonify({"status": "error", "message": "Geteilte Tracker konnten nicht geladen werden."}), 500
    data = request.get_json(silent=True) or {}
    recipient_id = str(data.get("recipient_user_id") or "")
    tracker_ref = str(data.get("tracker_ref") or "").strip()
    recipient = user_record(recipient_id)
    if not recipient or not recipient.get("active", True):
        return jsonify({"status": "error", "message": "Der Empfänger wurde nicht gefunden oder ist deaktiviert."}), 404
    if recipient_id == user_id:
        return jsonify({"status": "error", "message": "Ein Tracker kann nicht mit demselben Benutzer geteilt werden."}), 400
    model = internal_share_exact_model(tracker_ref)
    if not model:
        return jsonify({"status": "error", "message": "Dieser Tracker gehört nicht zum angemeldeten Benutzer."}), 404
    permissions = internal_share_permissions(data.get("permissions"))
    now_ts = int(time.time())
    with _internal_shares_lock:
        duplicate = next((
            row for row in _internal_share_store.setdefault("shares", {}).values()
            if isinstance(row, dict)
            and str(row.get("owner_user_id") or "") == user_id
            and str(row.get("recipient_user_id") or "") == recipient_id
            and hmac.compare_digest(str(row.get("tracker_ref") or ""), tracker_ref)
        ), None)
        if duplicate:
            duplicate.update({
                "active": True,
                "permissions": permissions,
                "label": str(model.get("name") or tracker_ref)[:160],
                "updated_ts": now_ts,
            })
            row = duplicate
            created = False
        else:
            share_id = "ish_" + secrets.token_urlsafe(18)
            row = {
                "id": share_id,
                "owner_user_id": user_id,
                "recipient_user_id": recipient_id,
                "tracker_ref": tracker_ref,
                "label": str(model.get("name") or tracker_ref)[:160],
                "active": True,
                "permissions": permissions,
                "created_ts": now_ts,
                "updated_ts": now_ts,
                "last_locate_ts": 0,
            }
            _internal_share_store["shares"][share_id] = row
            created = True
        save_internal_share_store()
    audit_event("internal_share_created" if created else "internal_share_updated", tracker_ref, f"Empfänger {recipient_id}")
    return jsonify({"status": "ok", "share": internal_share_public(row, user_id, include_history=False)}), (201 if created else 200)


@app.route("/api/internal-shares/<share_id>", methods=["PATCH", "DELETE"])
def internal_share_api(share_id):
    user_id = current_tenant_id()
    with _internal_shares_lock:
        row = _internal_share_store.get("shares", {}).get(share_id)
        if not isinstance(row, dict):
            return jsonify({"status": "error", "message": "Freigabe wurde nicht gefunden."}), 404
        owner_id = str(row.get("owner_user_id") or "")
        recipient_id = str(row.get("recipient_user_id") or "")
        if user_id not in {owner_id, recipient_id}:
            return jsonify({"status": "error", "message": "Kein Zugriff auf diese Freigabe."}), 403
        data = request.get_json(silent=True) or {}
        if request.method == "DELETE":
            if not bool_from_any(data.get("confirmed"), False):
                return jsonify({"status": "confirmation_required", "message": "Das Entfernen der Freigabe muss bestätigt werden."}), 409
            _internal_share_store["shares"].pop(share_id, None)
            save_internal_share_store()
            audit_event("internal_share_removed", str(row.get("tracker_ref") or share_id), f"durch {user_id}")
            return jsonify({"status": "ok", "removed": share_id})
        if user_id != owner_id:
            return jsonify({"status": "error", "message": "Nur der Besitzer darf Freigaberechte ändern."}), 403
        if "active" in data:
            row["active"] = bool_from_any(data.get("active"), True)
        if "permissions" in data:
            row["permissions"] = internal_share_permissions(data.get("permissions"))
        row["updated_ts"] = int(time.time())
        save_internal_share_store()
    return jsonify({"status": "ok", "share": internal_share_public(row, user_id, include_history=False)})


@app.route("/api/internal-shares/<share_id>/locate", methods=["POST"])
def locate_internal_share(share_id):
    user_id = current_tenant_id()
    with _internal_shares_lock:
        row = _internal_share_store.get("shares", {}).get(share_id)
        if not isinstance(row, dict):
            return jsonify({"status": "error", "message": "Freigabe wurde nicht gefunden."}), 404
        owner_id = str(row.get("owner_user_id") or "")
        recipient_id = str(row.get("recipient_user_id") or "")
        if user_id not in {owner_id, recipient_id}:
            return jsonify({"status": "error", "message": "Kein Zugriff auf diese Freigabe."}), 403
        if not row.get("active", True):
            return jsonify({"status": "error", "message": "Die Freigabe ist pausiert."}), 409
        permissions = internal_share_permissions(row.get("permissions"))
        if user_id == recipient_id and not permissions.get("can_locate"):
            return jsonify({"status": "error", "message": "Der Besitzer hat Live-Ortung nicht freigegeben."}), 403
        now_ts = time.time()
        last_locate = float(row.get("last_locate_ts", 0) or 0)
        if now_ts - last_locate < 30:
            return jsonify({"status": "cooldown", "remaining": max(1, int(30 - (now_ts - last_locate)))}), 429
        row["last_locate_ts"] = int(now_ts)
        row["updated_ts"] = int(now_ts)
        save_internal_share_store()
        tracker_ref = str(row.get("tracker_ref") or "")
    owner = user_record(owner_id)
    if not owner or not owner.get("active", True):
        return jsonify({"status": "error", "message": "Der Besitzer ist derzeit nicht verfügbar."}), 409
    with tenant_context(owner_id):
        try:
            ensure_tenant_state(owner_id, start_workers=False)
            if not internal_share_exact_model(tracker_ref):
                return jsonify({"status": "error", "message": "Der freigegebene Tracker existiert nicht mehr."}), 404
        except Exception:
            return jsonify({"status": "error", "message": "Der Besitzerbereich ist derzeit nicht verfügbar."}), 503
    threading.Thread(target=internal_share_locate_worker, args=(owner_id, tracker_ref), daemon=True).start()
    return jsonify({"status": "started", "message": "Ortung wurde im Konto des Besitzers gestartet."}), 202


def password_reset_base_url(tenant_state):
    candidates = [
        (tenant_state.get("notification_settings") or {}).get("public_base_url"),
        (tenant_state.get("mcp_server") or {}).get("public_base_url"),
        request.url_root.rstrip("/"),
    ]
    for raw in candidates:
        value = normalize_public_base_url(raw)
        if not value:
            continue
        parsed = urllib.parse.urlsplit(value)
        if parsed.scheme == "https" or (parsed.scheme == "http" and (parsed.hostname or "").lower() in {"localhost", "127.0.0.1", "::1"}):
            return value.rstrip("/")
    return ""


def password_reset_rate_limited(key):
    now = time.time()
    with _password_reset_lock:
        attempts = [stamp for stamp in _password_reset_attempts.get(key, []) if now - stamp < 900]
        _password_reset_attempts[key] = attempts
        if len(attempts) >= 3:
            return True
        attempts.append(now)
        return False


@app.route("/api/password-reset/request", methods=["POST"])
def password_reset_request_api():
    data = request.get_json(silent=True) or {}
    username = str(data.get("username") or "").strip()
    row = find_user_by_username(username)
    key = f"{client_key()}:{hashlib.sha256(username.casefold().encode('utf-8')).hexdigest()[:12]}"
    if password_reset_rate_limited(key):
        return jsonify({"status": "error", "message": "Zu viele Anfragen. Bitte in 15 Minuten erneut versuchen."}), 429
    # Unknown and inactive accounts intentionally receive the same neutral
    # response so the public form cannot enumerate private user names.
    if not row or not row.get("active", True) or not row.get("email"):
        return jsonify({"status": "accepted", "message": "Falls Konto und E-Mail verfügbar sind, wurde eine Nachricht versendet."}), 202
    tenant_id = str(row.get("id") or "main")
    try:
        tenant_state = ensure_tenant_state(tenant_id, start_workers=False)
        with tenant_context(tenant_id):
            config = (state.get("notification_settings") or {}).get("channels", {}).get("email", {})
            if not notification_channel_configured("email", config):
                return jsonify({"status": "unavailable", "message": "Für dieses Konto ist noch kein funktionierender E-Mail-Provider eingerichtet."}), 503
            base_url = password_reset_base_url(tenant_state)
            if not base_url:
                return jsonify({"status": "unavailable", "message": "Für sichere Reset-Links muss zuerst eine öffentliche HTTPS-Adresse hinterlegt werden."}), 503
            token = secrets.token_urlsafe(48)
            token_hash = hashlib.sha256(token.encode("utf-8")).hexdigest()
            now_ts = int(time.time())
            row["password_reset"] = {"token_hash": token_hash, "created_ts": now_ts, "expires_ts": now_ts + 15 * 60}
            row["updated_ts"] = now_ts
            save_users_registry()
            reset_url = f"{base_url}/#password-reset={urllib.parse.quote(token, safe='')}"
            event = {
                "id": "password-reset-" + secrets.token_hex(8), "type": "password_reset", "severity": "high",
                "title": "Passwort sicher zurücksetzen",
                "body": f"Für {row.get('display_name') or row.get('username')} wurde eine Passwortänderung angefordert. Der Link ist 15 Minuten gültig und kann nur einmal verwendet werden. Falls du das nicht warst, ignoriere diese Nachricht.",
                "tracker_name": str(row.get("display_name") or row.get("username") or "Benutzerkonto"),
                "provider": "Kontosicherheit", "ts": now_ts, "action_url": reset_url,
                "action_label": "Neues Passwort festlegen",
            }
            try:
                send_email_channel(config, event, recipients_override=[row.get("email")])
            except Exception as exc:
                row.pop("password_reset", None)
                save_users_registry()
                config["last_error"] = sanitize_console_text(exc, 180)
                save_json(NOTIFICATION_SETTINGS_FILE, "notification_settings")
                logger.warning("Passwort-Reset-Mail konnte nicht zugestellt werden: %s", sanitize_console_text(exc, 240))
                return jsonify({"status": "unavailable", "message": "Der eingerichtete E-Mail-Provider konnte die Reset-Nachricht nicht zustellen."}), 503
    except Exception as exc:
        logger.warning("Passwort-Reset konnte nicht vorbereitet werden: %s", sanitize_console_text(exc, 240))
        return jsonify({"status": "unavailable", "message": "Passwort-Reset ist derzeit nicht verfügbar."}), 503
    return jsonify({"status": "accepted", "message": "Die Reset-E-Mail wurde versendet. Der Link ist 15 Minuten gültig."}), 202


@app.route("/api/password-reset/confirm", methods=["POST"])
def password_reset_confirm_api():
    data = request.get_json(silent=True) or {}
    token = str(data.get("token") or "")
    password = str(data.get("new_password") or "")
    confirmation = str(data.get("confirm_password") or "")
    if len(token) < 40:
        return jsonify({"status": "error", "message": "Der Reset-Link ist ungültig oder abgelaufen."}), 400
    if password != confirmation:
        return jsonify({"status": "error", "message": "Die beiden Passwörter stimmen nicht überein."}), 400
    if len(password) < 10 or len(password) > 512:
        return jsonify({"status": "error", "message": "Das neue Passwort muss 10–512 Zeichen lang sein."}), 400
    wanted_hash = hashlib.sha256(token.encode("utf-8")).hexdigest()
    matched = None
    now_ts = int(time.time())
    with _users_lock:
        for row in _users_registry.get("users", {}).values():
            reset = row.get("password_reset") if isinstance(row, dict) else None
            if not isinstance(reset, dict) or int(reset.get("expires_ts", 0) or 0) < now_ts:
                continue
            if hmac.compare_digest(str(reset.get("token_hash") or ""), wanted_hash):
                matched = row
                break
    if not matched:
        return jsonify({"status": "error", "message": "Der Reset-Link ist ungültig, abgelaufen oder wurde bereits verwendet."}), 400
    tenant_id = str(matched.get("id") or "main")
    try:
        ensure_tenant_state(tenant_id, start_workers=False)
        with tenant_context(tenant_id):
            if tenant_id == "main":
                record = persist_app_password(password)
                matched["generation"] = str(record.get("generation") or "")
                mcp_revoke_owner_grants("password_reset")
            else:
                matched.update(user_password_record(password))
            matched.pop("password_reset", None)
            matched["updated_ts"] = now_ts
            save_users_registry()
    except Exception as exc:
        logger.error("Passwort-Reset konnte nicht gespeichert werden: %s", sanitize_console_text(exc, 240))
        return jsonify({"status": "error", "message": "Das neue Passwort konnte nicht sicher gespeichert werden."}), 500
    session.clear()
    return jsonify({"status": "ok", "message": "Passwort geändert. Du kannst dich jetzt anmelden."})


