export_jobs_lock = threading.RLock()


def export_address_text(point):
    address = point.get("address") if isinstance(point, dict) else None
    if isinstance(address, dict):
        return str(address.get("display_name") or address.get("label") or address.get("street_line") or "")[:1000]
    return ""


def export_point_properties(point):
    timestamp = int(float(point.get("ts", 0) or 0))
    return {
        "timestamp": timestamp,
        "time_utc": datetime.fromtimestamp(timestamp, tz=timezone.utc).isoformat().replace("+00:00", "Z") if timestamp else "",
        "time_local": local_datetime(timestamp).isoformat() if timestamp else "",
        "network": str(point.get("source") or "unknown"),
        "provider": str(point.get("provider") or point.get("source") or ""),
        "accuracy_m": round(float(point.get("acc", 0) or 0), 1),
        "battery": str(point.get("battery") if point.get("battery") is not None else point.get("bat") if point.get("bat") is not None else ""),
        "report_id": str(point.get("report_id") or point_identity(point))[:180],
        "address": export_address_text(point),
        "is_outlier": bool(point.get("is_outlier", False)),
    }


def serialize_history_export(model, window, points, export_format):
    export_format = str(export_format or "gpx").lower()
    name = str(model.get("name") or model.get("id") or "Tracker")
    if export_format == "csv":
        output = io.StringIO(newline="")
        writer = csv.writer(output, lineterminator="\n")
        writer.writerow(["timestamp", "time_utc", "time_local", "latitude", "longitude", "accuracy_m", "network", "provider", "battery", "address", "report_id", "is_outlier"])
        for point in points:
            props = export_point_properties(point)
            writer.writerow([props["timestamp"], props["time_utc"], props["time_local"], f"{float(point['lat']):.7f}", f"{float(point['lon']):.7f}", props["accuracy_m"], props["network"], props["provider"], props["battery"], props["address"], props["report_id"], int(props["is_outlier"])])
        return output.getvalue().encode("utf-8-sig"), "text/csv; charset=utf-8", "csv"
    if export_format == "geojson":
        features = [{
            "type": "Feature", "id": export_point_properties(point)["report_id"],
            "geometry": {"type": "Point", "coordinates": [round(float(point["lon"]), 7), round(float(point["lat"]), 7)]},
            "properties": export_point_properties(point),
        } for point in points]
        clean_route = [[round(float(point["lon"]), 7), round(float(point["lat"]), 7)] for point in points if not point.get("is_outlier")]
        if len(clean_route) >= 2:
            features.insert(0, {"type": "Feature", "geometry": {"type": "LineString", "coordinates": clean_route}, "properties": {"name": name, "kind": "tracker_history", **window}})
        payload = {"type": "FeatureCollection", "name": name, "properties": {"generator": f"Universal Tag Studio {APP_VERSION}", **window}, "features": features}
        return json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8"), "application/geo+json", "geojson"
    if export_format == "kml":
        xml = lambda value: html.escape(str(value if value is not None else ""), quote=True)
        coordinates = " ".join(f"{float(point['lon']):.7f},{float(point['lat']):.7f},0" for point in points if not point.get("is_outlier"))
        placemarks = []
        for point in points:
            props = export_point_properties(point)
            extended = "".join(f'<Data name="{xml(key)}"><value>{xml(value)}</value></Data>' for key, value in props.items())
            placemarks.append(f'<Placemark><name>{xml(props["time_local"] or name)}</name><description>{xml(props["address"])}</description><ExtendedData>{extended}</ExtendedData><Point><coordinates>{float(point["lon"]):.7f},{float(point["lat"]):.7f},0</coordinates></Point></Placemark>')
        route_placemark = f'<Placemark><name>{xml(name)} · Verlauf</name><Style><LineStyle><color>ffff840a</color><width>5</width></LineStyle></Style><LineString><tessellate>1</tessellate><coordinates>{coordinates}</coordinates></LineString></Placemark>' if sum(1 for point in points if not point.get("is_outlier")) >= 2 else ""
        document = f'''<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>{xml(name)}</name>{route_placemark}{''.join(placemarks)}</Document></kml>'''
        return document.encode("utf-8"), "application/vnd.google-earth.kml+xml", "kml"
    if export_format != "gpx":
        raise ValueError("Format muss GPX, KML, GeoJSON oder CSV sein.")
    xml = lambda value: html.escape(str(value if value is not None else ""), quote=True)
    trackpoints = []
    for point in points:
        props = export_point_properties(point)
        extensions = f'<uts:network>{xml(props["network"])}</uts:network><uts:provider>{xml(props["provider"])}</uts:provider><uts:accuracy_m>{props["accuracy_m"]}</uts:accuracy_m><uts:battery>{xml(props["battery"])}</uts:battery><uts:report_id>{xml(props["report_id"])}</uts:report_id><uts:address>{xml(props["address"])}</uts:address>'
        trackpoints.append(f'<trkpt lat="{float(point["lat"]):.7f}" lon="{float(point["lon"]):.7f}"><time>{xml(props["time_utc"])}</time><hdop>{max(.1, float(props["accuracy_m"]) / 5):.2f}</hdop><extensions>{extensions}</extensions></trkpt>')
    document = f'''<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="Universal Tag Studio {xml(APP_VERSION)}" xmlns="http://www.topografix.com/GPX/1/1" xmlns:uts="https://universal-tag-studio.local/gpx/1"><metadata><name>{xml(name)}</name><time>{datetime.now(timezone.utc).isoformat().replace('+00:00','Z')}</time></metadata><trk><name>{xml(name)} · {xml(window.get("since_local"))} bis {xml(window.get("until_local"))}</name><trkseg>{''.join(trackpoints)}</trkseg></trk></gpx>'''
    return document.encode("utf-8"), "application/gpx+xml", "gpx"


@app.route("/api/exports/history", methods=["GET"])
def history_export_api():
    try:
        model = mcp_resolve_tracker(request.args.get("tracker"))
        window = mcp_time_window({"since_ts": request.args.get("since_ts"), "until_ts": request.args.get("until_ts"), "period": request.args.get("period") or "last_7_days"})
        points = mcp_history_internal_points(model, window)
        if not points:
            return jsonify({"status": "error", "message": "Im gewählten Zeitraum sind keine gespeicherten Standortpunkte vorhanden."}), 404
        content, mimetype, extension = serialize_history_export(model, window, points, request.args.get("format") or "gpx")
    except (MCPToolError, ValueError) as exc:
        return jsonify({"status": "error", "message": str(exc)}), 400
    filename = secure_filename(f"Verlauf_{model.get('name') or model.get('id')}_{local_datetime(window['since_ts']).strftime('%Y-%m-%d')}_{local_datetime(window['until_ts']).strftime('%Y-%m-%d')}.{extension}") or f"tracker-verlauf.{extension}"
    audit_event("history_export", str(model.get("ref") or ""), f"{extension} · {len(points)} Punkte")
    return send_file(io.BytesIO(content), mimetype=mimetype, as_attachment=True, download_name=filename, max_age=0)


