def evidence_job_update(job_id, **changes):
    with export_jobs_lock:
        job = state.setdefault("export_jobs", {}).get(job_id)
        if not isinstance(job, dict):
            return None
        job.update(changes)
        job["updated_ts"] = int(time.time())
        save_export_jobs()
        return job


def evidence_route_map_png(points):
    try:
        from PIL import Image as PILImage, ImageDraw
    except ImportError:
        return None
    route = [point for point in points if not point.get("is_outlier")]
    if not route:
        return None
    if len(route) == 1:
        return email_map_png(route[0])
    width, height = 920, 480
    latitudes = [max(-85.0511, min(85.0511, float(point["lat"]))) for point in route]
    longitudes = [float(point["lon"]) for point in route]
    min_lat, max_lat, min_lon, max_lon = min(latitudes), max(latitudes), min(longitudes), max(longitudes)
    def project(lat, lon, zoom):
        scale = 256 * (2 ** zoom)
        sine = math.sin(math.radians(max(-85.0511, min(85.0511, lat))))
        return ((lon + 180) / 360 * scale, (0.5 - math.log((1 + sine) / (1 - sine)) / (4 * math.pi)) * scale)
    zoom = 3
    for candidate in range(18, 2, -1):
        a, b = project(min_lat, min_lon, candidate), project(max_lat, max_lon, candidate)
        if abs(b[0] - a[0]) <= width - 120 and abs(b[1] - a[1]) <= height - 120:
            zoom = candidate
            break
    center_lat, center_lon = (min_lat + max_lat) / 2, (min_lon + max_lon) / 2
    center_x, center_y = project(center_lat, center_lon, zoom)
    left, top = center_x - width / 2, center_y - height / 2
    x0, y0 = math.floor(left / 256), math.floor(top / 256)
    x1, y1 = math.floor((left + width) / 256), math.floor((top + height) / 256)
    canvas = PILImage.new("RGB", ((x1 - x0 + 1) * 256, (y1 - y0 + 1) * 256), "#edf2f7")
    tile_count = 2 ** zoom
    for tile_y in range(y0, y1 + 1):
        if tile_y < 0 or tile_y >= tile_count:
            continue
        for tile_x in range(x0, x1 + 1):
            wrapped_x = tile_x % tile_count
            tile_cache = EMAIL_MAP_CACHE_DIR / f"tile_{zoom}_{wrapped_x}_{tile_y}.png"
            try:
                if tile_cache.exists() and time.time() - tile_cache.stat().st_mtime < 60 * 86400:
                    tile_bytes = tile_cache.read_bytes()
                else:
                    url = os.environ.get("ULTRA_TRACKER_EMAIL_TILE_URL", "https://tile.openstreetmap.org/{z}/{x}/{y}.png").format(z=zoom, x=wrapped_x, y=tile_y)
                    req = urllib.request.Request(url, headers={"User-Agent": GEOCODER_USER_AGENT, "Accept": "image/png"})
                    with urllib.request.urlopen(req, timeout=6) as response:
                        tile_bytes = response.read(1024 * 1024)
                    EMAIL_MAP_CACHE_DIR.mkdir(parents=True, exist_ok=True)
                    tile_cache.write_bytes(tile_bytes)
                tile = PILImage.open(io.BytesIO(tile_bytes)).convert("RGB")
                canvas.paste(tile, ((tile_x - x0) * 256, (tile_y - y0) * 256))
            except Exception:
                continue
    crop_x, crop_y = int(left - x0 * 256), int(top - y0 * 256)
    canvas = canvas.crop((crop_x, crop_y, crop_x + width, crop_y + height))
    draw = ImageDraw.Draw(canvas, "RGBA")
    sampled = route if len(route) <= 1800 else [route[round(index * (len(route) - 1) / 1799)] for index in range(1800)]
    colors_by_source = {"apple": (28, 29, 34, 220), "google": (66, 133, 244, 225), "samsung": (82, 109, 255, 225), "fusion": (109, 92, 246, 225)}
    for previous, current in zip(sampled, sampled[1:]):
        ax, ay = project(float(previous["lat"]), float(previous["lon"]), zoom); bx, by = project(float(current["lat"]), float(current["lon"]), zoom)
        color = colors_by_source.get(str(current.get("source") or ""), (10, 132, 255, 220))
        draw.line((ax - left, ay - top, bx - left, by - top), fill=(255, 255, 255, 235), width=9)
        draw.line((ax - left, ay - top, bx - left, by - top), fill=color, width=5)
    for point, color in ((sampled[0], (48, 209, 88, 255)), (sampled[-1], (255, 69, 58, 255))):
        px, py = project(float(point["lat"]), float(point["lon"]), zoom);px -= left;py -= top
        draw.ellipse((px-10, py-10, px+10, py+10), fill=(255,255,255,255));draw.ellipse((px-7, py-7, px+7, py+7), fill=color)
    draw.rounded_rectangle((12, height-34, 230, height-9), radius=8, fill=(255,255,255,225));draw.text((20, height-29), "Kartendaten © OpenStreetMap", fill=(55,65,81,255))
    output = io.BytesIO();canvas.save(output, format="PNG", optimize=True);return output.getvalue()


def build_evidence_pdf(path, job, model, window, points, stays):
    try:
        from reportlab.lib import colors
        from reportlab.lib.enums import TA_RIGHT
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.units import mm
        from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, Image as RLImage
    except ImportError as exc:
        raise RuntimeError("Für PDF-Fallakten fehlt reportlab (python3 -m pip install reportlab).") from exc
    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(name="EVTitle", parent=styles["Title"], fontName="Helvetica-Bold", fontSize=24, leading=28, textColor=colors.HexColor("#101828")))
    styles.add(ParagraphStyle(name="EVKicker", parent=styles["Normal"], fontName="Helvetica-Bold", fontSize=8, leading=11, textColor=colors.HexColor("#0A84FF"), spaceAfter=5))
    styles.add(ParagraphStyle(name="EVH2", parent=styles["Heading2"], fontName="Helvetica-Bold", fontSize=14, leading=18, textColor=colors.HexColor("#101828"), spaceBefore=11, spaceAfter=7))
    styles.add(ParagraphStyle(name="EVBody", parent=styles["BodyText"], fontName="Helvetica", fontSize=9.2, leading=13.5, textColor=colors.HexColor("#344054")))
    styles.add(ParagraphStyle(name="EVSmall", parent=styles["BodyText"], fontName="Helvetica", fontSize=7.5, leading=10, textColor=colors.HexColor("#667085")))
    styles.add(ParagraphStyle(name="EVCell", parent=styles["BodyText"], fontName="Helvetica", fontSize=7.1, leading=9, textColor=colors.HexColor("#344054")))
    styles.add(ParagraphStyle(name="EVHead", parent=styles["EVCell"], fontName="Helvetica-Bold", textColor=colors.white))
    safe = lambda value, style="EVBody": Paragraph(html.escape(str(value if value is not None else ""), quote=False).replace("\n", "<br/>"), styles[style])
    fmt = lambda ts: local_datetime(ts).strftime("%d.%m.%Y %H:%M:%S %Z") if ts else "–"
    address = lambda item: export_address_text(item) or f"{float(item.get('lat', item.get('centerLat', 0))):.6f}, {float(item.get('lon', item.get('centerLon', 0))):.6f}"
    networks = {}
    accuracies = []
    battery_values = []
    for point in points:
        source = str(point.get("source") or "unknown");networks[source] = networks.get(source, 0) + 1
        if float(point.get("acc", 0) or 0) > 0:accuracies.append(float(point.get("acc")))
        battery = point.get("battery") if point.get("battery") is not None else point.get("bat")
