def evidence_export_worker(job_id):
    job = state.get("export_jobs", {}).get(job_id)
    if not isinstance(job, dict):
        return
    try:
        evidence_job_update(job_id, status="running", progress=3, stage="Tracker und Zeitraum werden geprüft", error="")
        model = mcp_resolve_tracker(job.get("tracker_ref"))
        window = mcp_time_window({"since_ts": job.get("since_ts"), "until_ts": job.get("until_ts")})
        points = mcp_history_internal_points(model, window)
        if not points:
            raise RuntimeError("Im gewählten Zeitraum sind keine gespeicherten Standortpunkte vorhanden.")
        truncated = len(points) > 20000
        if truncated:
            points = [points[round(index * (len(points)-1) / 19999)] for index in range(20000)]
        evidence_job_update(job_id, progress=10, stage="Standortdaten werden normalisiert", point_count=len(points), truncated=truncated)
        groups = {}
        for point in points:
            key = address_cache_key(point["lat"], point["lon"])
            groups.setdefault(key, {"lat":point["lat"],"lon":point["lon"],"points":[]})["points"].append(point)
        for group in groups.values():
            cached = address_from_cached(group["lat"], group["lon"])
            if cached:
                for point in group["points"]:point["address"] = cached
        unresolved = [group for group in groups.values() if not export_address_text(group["points"][0])]
        limit = int_range(job.get("address_limit"), 80, 0, 300) if job.get("resolve_addresses", True) else 0
        selected = unresolved if len(unresolved)<=limit else [unresolved[round(index*(len(unresolved)-1)/max(1,limit-1))] for index in range(limit)] if limit else []
        resolved = 0;evidence_job_update(job_id, address_total=len(selected), address_resolved=0, progress=12, stage="Adressen werden aufgelöst" if selected else "Gespeicherte Adressen werden übernommen")
        for index, group in enumerate(selected):
            address, _cached, retry_after = reverse_geocode(group["lat"], group["lon"])
            if not address and retry_after:
                time.sleep(min(1.2, max(.1, float(retry_after))));address, _cached, _retry = reverse_geocode(group["lat"], group["lon"])
            if address:
                resolved += 1
                for point in group["points"]:point["address"] = address
            evidence_job_update(job_id, address_resolved=resolved, progress=12+int(46*(index+1)/max(1,len(selected))), stage=f"Adressen {index+1}/{len(selected)}")
        evidence_job_update(job_id, progress=62, stage="Aufenthalte und Kennzahlen werden berechnet")
        _annotated_points, stays = build_stays(points)
        for stay in stays:
            stay["address"] = address_from_cached(stay["centerLat"],stay["centerLon"])
        export_dir = Path(os.fspath(EXPORTS_DIR));export_dir.mkdir(parents=True,exist_ok=True)
        filename = secure_filename(f"Fallakte_{job.get('name') or model.get('name')}_{job_id}.pdf") or f"Fallakte_{job_id}.pdf"
        output = (export_dir / filename).resolve()
        if output.parent != export_dir.resolve():raise RuntimeError("Unsicherer Exportpfad wurde abgelehnt.")
        evidence_job_update(job_id, progress=70, stage="Professionelle PDF-Fallakte wird gesetzt", tracker_name=str(model.get("name") or model.get("id")), filename=filename, stay_count=len(stays))
        digest, networks = build_evidence_pdf(output, state["export_jobs"][job_id], model, window, points, stays)
        evidence_job_update(job_id, status="completed", progress=100, stage="Fallakte ist fertig", finished_ts=int(time.time()), data_sha256=digest, networks=networks, filename=filename)
        audit_event("evidence_export", str(model.get("ref") or ""), f"{filename} · {len(points)} Punkte")
    except Exception as exc:
        logger.exception("PDF-Fallakte %s fehlgeschlagen: %s", job_id, exc)
        evidence_job_update(job_id, status="error", stage="Export fehlgeschlagen", error=sanitize_console_text(exc, 400), finished_ts=int(time.time()))


@app.route("/api/exports/cases", methods=["GET", "POST"])
def evidence_exports_api():
    if request.method == "GET":
        rows = [evidence_job_public(job) for job in state.get("export_jobs", {}).values() if isinstance(job, dict)]
        rows.sort(key=lambda item:int(item.get("created_ts",0) or 0),reverse=True)
        return jsonify({"status":"ok","jobs":rows[:50]})
    data=request.get_json(silent=True) or {}
    try:
        model=mcp_resolve_tracker(data.get("tracker"));window=mcp_time_window({"since_ts":data.get("since_ts"),"until_ts":data.get("until_ts")})
    except MCPToolError as exc:return jsonify({"status":"error","message":str(exc)}),400
    case_name=str(data.get("name") or f"Fallakte {model.get('name')}").strip()[:120] or "Tracker-Fallakte"
    job_id="case_"+secrets.token_hex(9);now_ts=int(time.time())
    job={"id":job_id,"status":"queued","progress":0,"stage":"Wartet auf Verarbeitung","name":case_name,"tracker_ref":str(model.get("ref") or ""),"tracker_name":str(model.get("name") or ""),"since_ts":window["since_ts"],"until_ts":window["until_ts"],"resolve_addresses":bool_from_any(data.get("resolve_addresses"),True),"address_limit":int_range(data.get("address_limit"),80,0,300),"created_ts":now_ts,"updated_ts":now_ts,"error":""}
    with export_jobs_lock:state.setdefault("export_jobs",{})[job_id]=job;save_export_jobs()
    threading.Thread(target=evidence_export_worker,args=(job_id,),daemon=True,name=f"evidence-{job_id}").start()
    return jsonify({"status":"queued","job":evidence_job_public(job)}),202


@app.route("/api/exports/cases/<job_id>", methods=["GET", "DELETE"])
def evidence_export_job_api(job_id):
    job=state.get("export_jobs",{}).get(job_id)
    if not isinstance(job,dict):return jsonify({"status":"error","message":"Exportauftrag wurde nicht gefunden."}),404
    if request.method=="DELETE":
        data=request.get_json(silent=True) or {}
        if not bool_from_any(data.get("confirmed"),False):return jsonify({"status":"confirmation_required","message":"Löschen muss bestätigt werden."}),409
        if job.get("status") in {"queued","running"}:return jsonify({"status":"error","message":"Ein laufender PDF-Export kann nicht gelöscht werden."}),409
        filename=str(job.get("filename") or "")
        if filename:
            export_dir=Path(os.fspath(EXPORTS_DIR)).resolve();target=(export_dir/filename).resolve()
            if target.parent==export_dir:target.unlink(missing_ok=True)
        state["export_jobs"].pop(job_id,None);save_export_jobs();return jsonify({"status":"ok"})
    return jsonify({"status":"ok","job":evidence_job_public(job)})


@app.route("/api/exports/cases/<job_id>/download", methods=["GET"])
def evidence_export_download_api(job_id):
    job=state.get("export_jobs",{}).get(job_id)
    if not isinstance(job,dict) or job.get("status")!="completed":return jsonify({"status":"error","message":"Die Fallakte ist noch nicht fertig."}),409
    export_dir=Path(os.fspath(EXPORTS_DIR)).resolve();target=(export_dir/str(job.get("filename") or "")).resolve()
