    if request.method == "DELETE":
        recovery_cleanup_device(name)
        audit_event("recovery_deleted", name, "Recovery-Guard-Daten gelöscht")
        activity_event("recovery", "Recovery-Guard-Daten gelöscht", tracker_ref=f"apple:{name}")
        return jsonify({"status": "ok"})
    try:
        max_points = max(250, min(12000, int(request.args.get("max", "6000"))))
    except ValueError:
        max_points = 6000
