@app.route("/api/recovery/<name>/share", methods=["POST"])
def recovery_guard_create_share(name):
    missing = require_accessory(name)
    if missing:
        return missing
    data = request.json or {}
    mode = normalize_recovery_mode(state.get("recovery_modes", {}).get(name, {}))
    if not mode.get("activated_ts"):
        return jsonify({"status": "error", "message": "Aktiviere zuerst Recovery Guard für diesen Apple-Tracker."}), 409
    password = str(data.get("password") or "")
    if len(password) < 6:
        return jsonify({"status": "error", "message": "Das Helfer-Passwort muss mindestens 6 Zeichen lang sein."}), 400
    try:
        expires_hours = max(1, min(24 * 30, int(data.get("expires_hours", 24 * 7) or 24 * 7)))
    except (TypeError, ValueError):
        expires_hours = 24 * 7
    permissions = {
        "show_exact_location": bool(data.get("show_exact_location", True)),
        "show_timeline": bool(data.get("show_timeline", True)),
        "show_stays": bool(data.get("show_stays", True)),
        "show_note": bool(data.get("show_note", True)),
        "can_refresh": bool(data.get("can_refresh", False)),
    }
    # One current helper link per tracker keeps revocation simple and predictable.
    for existing in state.get("recovery_shares", {}).values():
        if isinstance(existing, dict) and existing.get("device") == name and recovery_share_status(existing) == "active":
            existing["active"] = False
            existing["revoked_ts"] = int(time.time())
    link_id = secrets.token_urlsafe(24)
    now_ts = int(time.time())
    state["recovery_shares"][link_id] = {
        "device": name,
        "active": True,
        "created_ts": now_ts,
        "expires_ts": now_ts + expires_hours * 3600,
        "last_access_ts": 0,
        "access_count": 0,
        "last_locate_ts": 0,
        "permissions": permissions,
        **create_password_record(password),
    }
    save_recovery_state(history=False, shares=True)
    audit_event("recovery_share_created", link_id, f"{name} · {expires_hours}h")
    activity_event("recovery", "Recovery-Helferlink erstellt", tracker_ref=f"apple:{name}")
    return jsonify({"status": "ok", "link_id": link_id, "path": f"/recovery/{link_id}", "expires_ts": now_ts + expires_hours * 3600, "permissions": permissions})


