@app.route("/api/history7/<name>/start", methods=["POST"])
def start_history7(name):
    missing = require_accessory(name)
    if missing:
        return missing
    current = history_direct_policy("apple", name)
    policy = set_history_policy("apple", name, True, current.get("mode"), current.get("days"))
    if name in state["locations"]:
        loc = state["locations"][name]
        point = report_to_point(loc)
        if point:
            add_persistent_history_points(name, [point])
    threading.Thread(target=fetch_from_apple, args=([name],), daemon=True).start()
    fusion_link = google_link_for_apple(name)
    if fusion_link:
        state["google_next_fetch"][fusion_link["google_id"]] = time.time()
        threading.Thread(target=fetch_from_google, args=(fusion_link["google_id"], "linked_history_start"), daemon=True).start()
    samsung_link = samsung_link_for_apple(name)
    if samsung_link:
        state["samsung_next_fetch"][samsung_link["samsung_id"]] = time.time()
        threading.Thread(target=fetch_from_samsung, args=(samsung_link["samsung_id"], "linked_history_start"), daemon=True).start()
    return jsonify({"status": "ok", "policy": policy})


