@app.route("/api/history7/<name>", methods=["GET"])
def get_history7(name):
    missing = require_accessory(name)
    if missing:
        return missing
    points = fusion_history_points(name)
    requested_sources = {
        value.strip().lower()
        for value in str(request.args.get("sources") or "").split(",")
        if value.strip().lower() in {"apple", "google", "samsung"}
    }
    if requested_sources:
        points = [point for point in points if str(point.get("source") or "apple").lower() in requested_sources]
    storage_policy = fusion_history_storage_policy(name)
    retention_seconds = storage_policy.get("retention_seconds")
    normalized = normalize_route_points(points, retention_seconds=retention_seconds)
    payload = route_payload(normalized, "Tagesverlauf", retention_seconds=retention_seconds, filter_day=True)
    payload.update({"id": "seven_day", "start": normalized[0]["ts"] if normalized else int(time.time()), "end": normalized[-1]["ts"] if normalized else int(time.time())})
    return jsonify(payload)


def validate_history_tracker_reference(provider, tracker_id):
    provider, tracker_id = str(provider).lower(), str(tracker_id)
    if provider == "fusion":
        if tracker_id in state.get("accessories", {}) and (
            tracker_id in state.get("fusion_profiles", {})
            or tracker_id in state.get("google_links", {})
            or tracker_id in state.get("samsung_links", {})
        ):
            return None
        return jsonify({"status": "error", "message": "Fusion-Tracker wurde nicht gefunden."}), 404
    return validate_tracker_reference(provider, tracker_id)


def wake_history_tracker(provider, tracker_id, trigger="history_policy"):
    """Wake only already configured provider jobs; policy changes never block the request."""
    refs = [(str(provider), str(tracker_id))]
    if provider == "fusion":
        refs = [("apple", tracker_id)]
        google_id, samsung_id = fusion_profile_source_ids(tracker_id)
        if google_id:
            refs.append(("google", google_id))
        if samsung_id:
            refs.append(("samsung", samsung_id))
    for source, source_id in refs:
        if source == "apple" and source_id in state.get("accessories", {}):
            state.setdefault("apple_next_fetch", {})[source_id] = time.time()
            threading.Thread(target=fetch_from_apple, args=([source_id], trigger), daemon=True).start()
        elif source == "google" and source_id in state.get("google_devices", {}):
            state.setdefault("google_next_fetch", {})[source_id] = time.time()
            threading.Thread(target=fetch_from_google, args=(source_id, trigger), daemon=True).start()
        elif source == "samsung" and source_id in state.get("samsung_devices", {}):
            state.setdefault("samsung_next_fetch", {})[source_id] = time.time()
            threading.Thread(target=fetch_from_samsung, args=(source_id, trigger), daemon=True).start()


@app.route("/api/history/policy/<provider>/<path:tracker_id>", methods=["GET", "POST"])
def history_policy_route(provider, tracker_id):
    provider = str(provider).lower()
    missing = validate_history_tracker_reference(provider, tracker_id)
    if missing:
        return missing
    if request.method == "GET":
        return jsonify({"status": "ok", "policy": history_policy_public(provider, tracker_id)})
    data = request.json or {}
    current = history_direct_policy(provider, tracker_id)
    try:
        retention_choice = data.get("retention", data.get("mode")) if ("retention" in data or "mode" in data) else current.get("mode")
        retention_days = data.get("custom_days", data.get("days")) if ("custom_days" in data or "days" in data) else current.get("days")
        retention = parse_history_retention_choice(
            retention_choice,
            retention_days,
            current.get("days") or 7,
        )
    except ValueError as exc:
        return jsonify({"status": "error", "message": str(exc)}), 400
    enabled = bool_from_any(data.get("enabled"), current.get("enabled", False))
    policy = set_history_policy(provider, tracker_id, enabled, retention["mode"], retention["days"])
    if enabled:
        wake_history_tracker(provider, tracker_id)
    elif provider == "google" and not google_active_reasons(tracker_id):
        state.get("google_next_fetch", {}).pop(tracker_id, None)
    elif provider == "samsung" and not samsung_active_reasons(tracker_id):
        state.get("samsung_next_fetch", {}).pop(tracker_id, None)
    activity_event("history_policy", "Standortverlauf aktualisiert", policy.get("label", ""), provider=provider, tracker_ref=f"{provider}:{tracker_id}")
    return jsonify({"status": "ok", "policy": policy, "points_preserved": True})


