@app.route("/api/google/secrets", methods=["POST"])
def upload_google_secrets():
    uploaded = request.files.get("file")
    if uploaded is None or not str(uploaded.filename or "").lower().endswith(".json"):
        return jsonify({"status": "error", "message": "Bitte eine gültige secrets.json auswählen."}), 400
    try:
        raw = uploaded.stream.read(1024 * 1024 + 1)
        if len(raw) > 1024 * 1024:
            return jsonify({"status": "error", "message": "Die Secrets-Datei ist unerwartet groß."}), 400
        data = json.loads(raw)
        valid, message = google_validate_secrets(data)
        if not valid:
            return jsonify({"status": "error", "message": message}), 400
        google_store_secrets(data, source="web-upload", merge=False)
        google_sync_secrets_to_tools()
        google_health_cache["checked_ts"] = 0
        threading.Thread(target=google_prepare_worker, daemon=True).start()
        return jsonify({"status": "ok", "message": "Secrets wurden sicher hinterlegt und werden geprüft."})
    except (UnicodeDecodeError, json.JSONDecodeError):
        return jsonify({"status": "error", "message": "Die Datei enthält kein gültiges JSON."}), 400
    except Exception as exc:
        logger.warning("Google-Secrets konnten nicht gespeichert werden: %s", type(exc).__name__)
        return jsonify({"status": "error", "message": "Die Secrets-Datei konnte nicht gespeichert werden."}), 500


@app.route("/api/google/secrets", methods=["DELETE"])
def delete_google_secrets():
    try:
        if GOOGLE_SECRETS_FILE.exists():
            GOOGLE_SECRETS_FILE.unlink()
        tools_path = google_tools_path()
        if tools_path and (tools_path / "Auth" / "secrets.json").exists():
            (tools_path / "Auth" / "secrets.json").unlink()
        state["google_next_fetch"].clear()
        state["google_inflight"].clear()
        state.setdefault("google_inflight_since", {}).clear()
        state.setdefault("google_pending_fetch", {}).clear()
        state["google_auth"] = {
            "status": "disconnected", "last_check_ts": int(time.time()), "last_success_ts": 0,
            "last_failure_ts": 0, "last_error_code": "", "last_error": "", "repairing": False,
            "last_repair_ts": 0, "last_repair_success_ts": 0, "repair_attempts": 0,
            "automatic_repairs": 0, "secret_refreshes": 0, "secret_fingerprint": "",
            "reauth_required": False, "repair_queued": False,
        }
        google_auth_save()
        google_health_cache["checked_ts"] = 0
        return jsonify({"status": "ok"})
    except OSError:
        return jsonify({"status": "error", "message": "Die Secrets-Datei konnte nicht entfernt werden."}), 500


@app.route("/api/google/tools", methods=["POST"])
def upload_google_tools():
    uploaded = request.files.get("file")
    if uploaded is None or not str(uploaded.filename or "").lower().endswith((".zip", ".zip(1)")):
        return jsonify({"status": "error", "message": "Bitte das GoogleFindMyTools-ZIP auswählen."}), 400
    fd, temp_name = tempfile.mkstemp(prefix="google_tools_upload_", suffix=".zip", dir=str(GOOGLE_DIR))
    os.close(fd)
    temp_path = Path(temp_name)
    try:
        uploaded.save(temp_path)
        google_install_archive(temp_path)
        google_health_cache["checked_ts"] = 0
        threading.Thread(target=google_prepare_worker, daemon=True).start()
        return jsonify({"status": "ok", "message": "GoogleFindMyTools wurde installiert."})
    except (zipfile.BadZipFile, ValueError) as exc:
        return jsonify({"status": "error", "message": str(exc)}), 400
    except Exception as exc:
        logger.warning("Google-Tool-Bundle konnte nicht installiert werden: %s", type(exc).__name__)
        return jsonify({"status": "error", "message": "Das GoogleFindMyTools-Bundle konnte nicht installiert werden."}), 500
    finally:
        if temp_path.exists():
            temp_path.unlink()


