@app.route("/api/google/settings", methods=["POST"])
def update_google_defaults():
    data = request.json or {}
    current_min, current_max = provider_poll_window("google")
    minimum = int_range(data.get("interval_min"), current_min, 30, 900)
    maximum = int_range(data.get("interval_max"), current_max, minimum, 900)
    polling = normalize_polling_settings(state.get("settings", {}).get("polling"))
    polling["google"] = {"interval_min": minimum, "interval_max": maximum}
    polling["updated_ts"] = int(time.time())
    state.setdefault("settings", {})["polling"] = normalize_polling_settings(polling)
    state["google_settings"]["default_interval_min"] = minimum
    state["google_settings"]["default_interval_max"] = maximum
    if "background_tracking" in data:
        state["google_settings"]["background_tracking"] = bool(data.get("background_tracking"))
    if "adaptive_polling" in data:
        state["google_settings"]["adaptive_polling"] = bool(data.get("adaptive_polling"))
    if "auto_repair" in data:
        state["google_settings"]["auto_repair"] = bool(data.get("auto_repair"))
    save_json(GOOGLE_SETTINGS_FILE, "google_settings")
    save_json(SETTINGS_FILE, "settings")
    if state["google_settings"].get("background_tracking"):
        for index, device_id in enumerate(sorted(state.get("google_devices", {}))):
            state["google_next_fetch"][device_id] = min(
                float(state["google_next_fetch"].get(device_id, time.time() + 60 + index * 15)),
                time.time() + 60 + index * 15,
            )
    return jsonify({
        "status": "ok", "interval_min": minimum, "interval_max": maximum,
        "background_tracking": bool(state["google_settings"].get("background_tracking")),
        "adaptive_polling": bool(state["google_settings"].get("adaptive_polling")),
        "auto_repair": bool(state["google_settings"].get("auto_repair")),
    })


@app.route("/api/google/devices/<path:device_id>/settings", methods=["POST"])
def update_google_device_settings(device_id):
    missing = require_google_device(device_id)
    if missing:
        return missing
    data = request.json or {}
    global_min, global_max = provider_poll_window("google")
    minimum = int_range(data.get("interval_min"), global_min, 30, 3600)
    maximum = int_range(data.get("interval_max"), global_max, minimum, 3600)
    previous = state["google_settings"].setdefault("devices", {}).get(device_id, {})
    state["google_settings"]["devices"][device_id] = {
        **(previous if isinstance(previous, dict) else {}),
        "interval_min": minimum,
        "interval_max": maximum,
        "interval_override_enabled": bool_from_any(data.get("interval_override_enabled"), True),
    }
    save_json(GOOGLE_SETTINGS_FILE, "google_settings")
    if google_active_reasons(device_id):
        state["google_next_fetch"][device_id] = min(float(state["google_next_fetch"].get(device_id, time.time() + maximum)), time.time() + maximum)
    return jsonify({"status": "ok", "interval_min": minimum, "interval_max": maximum})


@app.route("/api/google/devices/<path:device_id>/locate", methods=["POST"])
def locate_google_device(device_id):
    missing = require_google_device(device_id)
    if missing:
        return missing
    runtime = google_runtime_status()
    if not runtime.get("ready"):
        return jsonify({"status": "error", "message": "GoogleFindMyTools ist noch nicht bereit."}), 503
    if google_transport_circuit_open():
        auth = state.setdefault("google_auth", {})
        google_schedule_transport_repair("manual_circuit", device_id)
        state.setdefault("google_pending_fetch", {})[device_id] = "manual_after_transport_repair"
        retry_at = max(time.time() + 12, float(auth.get("transport_circuit_open_until", 0) or 0))
        state.setdefault("google_next_fetch", {})[device_id] = retry_at
        return jsonify({
            "status": "repairing",
            "message": "Der gemeinsame Google-Pushkanal wird einmalig repariert. Dieser Tracker startet danach automatisch.",
            "retry_at": int(retry_at),
        }), 202
    now_ts = time.time()
    last_fetch = float(state["google_last_manual_fetch"].get(device_id, 0) or 0)
    if now_ts - last_fetch < 30:
        return jsonify({"status": "cooldown", "remaining": int(30 - (now_ts - last_fetch))}), 429
    state["google_last_manual_fetch"][device_id] = now_ts
    state.setdefault("google_pending_fetch", {})[device_id] = "manual"
    state["google_next_fetch"][device_id] = now_ts
    if device_id in state.get("google_inflight", set()):
        return jsonify({"status": "running", "message": "Für diesen Google Tag läuft bereits ein Abruf."}), 202
    if google_fetch_lock.locked():
        stats = state.setdefault("google_stats", {}).setdefault("devices", {}).setdefault(device_id, {})
        stats.update({"last_stage": "waiting_for_bridge", "last_result": "queued", "last_trigger": "manual"})
        save_json(GOOGLE_STATS_FILE, "google_stats")
        return jsonify({"status": "queued", "message": "Der Abruf startet automatisch, sobald die Google-Bridge frei ist."}), 202
    threading.Thread(
        target=fetch_from_google,
        args=(device_id, "manual"),
        daemon=True,
        name=f"google-manual-{google_device_safe_id(device_id)[:10]}",
    ).start()
    return jsonify({"status": "started"}), 202


