    if data.get("device_id") != device_id:
        return jsonify({"status": "error", "message": "Google-Session wurde nicht gefunden."}), 404
    payload = route_payload(data.get("points", []), "Google-Session", retention_seconds=None, default_limit=12000)
    payload.update({"id": session_id, "start": data.get("start"), "end": data.get("end"), "device_id": device_id, "source": "google"})
