def comparison_api_error(exc):
    status = {"not_found": 404, "conflict": 409, "ambiguous": 409, "confirmation_required": 409, "invalid_arguments": 400}.get(getattr(exc, "code", ""), 400)
    return jsonify({"status": "error", "code": getattr(exc, "code", "invalid_arguments"), "message": str(exc)}), status


@app.route("/api/comparison-tests", methods=["GET", "POST"])
def comparison_tests_api():
    if request.method == "GET":
        rows = [comparison_test_public(test) for test in state.get("comparison_tests", {}).values() if isinstance(test, dict)]
        rows.sort(key=lambda test: (test.get("status") != "running", -int(test.get("started_ts", 0) or 0)))
        return jsonify({"status": "ok", "active_count": sum(1 for test in rows if test.get("status") == "running"), "tests": rows})
    data = request.get_json(silent=True) or {}
    references = data.get("trackers") or data.get("references") or ([data.get("fusion")] if data.get("fusion") else [])
    try:
        test = comparison_start(references, data.get("name"), bool(data.get("confirmed")), "web")
    except MCPToolError as exc:
        return comparison_api_error(exc)
    return jsonify({"status": "ok", "test": test}), 201


@app.route("/api/comparison-tests/<test_id>", methods=["GET", "DELETE"])
def comparison_test_api(test_id):
    test = state.get("comparison_tests", {}).get(test_id)
    if request.method == "GET":
        if not isinstance(test, dict):
            return jsonify({"status": "error", "message": "Vergleichstest wurde nicht gefunden."}), 404
        return jsonify({"status": "ok", "test": comparison_test_public(test, include_points=bool_from_any(request.args.get("include_points"), False))})
    data = request.get_json(silent=True) or {}
    try:
        result = comparison_delete(test_id, bool(data.get("confirmed")))
    except MCPToolError as exc:
        return comparison_api_error(exc)
    return jsonify({"status": "ok", **result})


@app.route("/api/comparison-tests/<test_id>/finish", methods=["POST"])
def comparison_test_finish_api(test_id):
    data = request.get_json(silent=True) or {}
    try:
        test = comparison_finish(test_id, bool(data.get("confirmed")), "web")
    except MCPToolError as exc:
        return comparison_api_error(exc)
    return jsonify({"status": "ok", "test": test})


@app.route("/api/comparison-tests/<test_id>/refresh", methods=["POST"])
def comparison_test_refresh_api(test_id):
    test = state.get("comparison_tests", {}).get(test_id)
    if not isinstance(test, dict):
        return jsonify({"status": "error", "message": "Vergleichstest wurde nicht gefunden."}), 404
    if test.get("status") != "running":
        return jsonify({"status": "error", "message": "Nur ein laufender Test kann aktualisiert werden."}), 409
    refs = [str(target.get("ref") or "") for target in test.get("targets", []) if isinstance(target, dict)]
    for ref in refs:
        provider, tracker_id = ref.split(":", 1)
        if provider == "apple":
            threading.Thread(target=fetch_from_apple, args=([tracker_id], "comparison_manual"), daemon=True).start()
        elif provider == "google":
            threading.Thread(target=fetch_from_google, args=(tracker_id, "comparison_manual"), daemon=True).start()
        elif provider == "samsung":
            threading.Thread(target=fetch_from_samsung, args=(tracker_id, "comparison_manual"), daemon=True).start()
    return jsonify({"status": "ok", "sources": refs})


@app.route("/api/samsung/auth/start", methods=["POST"])
def start_samsung_auth():
    try:
        login_url = samsung_generate_login_url()
        return jsonify({"status": "ok", "login_url": login_url, "expires_in": 1800})
    except Exception as exc:
        logger.warning("Samsung-Login konnte nicht vorbereitet werden: %s", exc)
        return jsonify({"status": "error", "message": str(exc)}), 502


@app.route("/api/samsung/auth/complete", methods=["POST"])
def complete_samsung_auth():
    data = request.json or {}
    try:
        auth = samsung_complete_login(data.get("redirect_url"))
    except Exception as exc:
        logger.warning("Samsung-Login fehlgeschlagen: %s", exc)
        return jsonify({"status": "error", "message": str(exc)}), 400
    try:
        count = samsung_sync_devices()
        return jsonify({"status": "ok", "login_id": auth.get("login_id"), "devices": count, "setup": state.get("samsung_setup", {}), "debug": state.get("samsung_debug", [])[-40:]})
    except Exception as exc:
        logger.warning("Samsung-Konto verbunden, Geräteliste aber nicht geladen: %s", exc)
        return jsonify({"status": "ok", "login_id": auth.get("login_id"), "devices": 0, "sync_warning": str(exc)})


@app.route("/api/samsung/auth/logout", methods=["POST"])
def logout_samsung_auth():
    state["samsung_auth"] = {}
    state["samsung_devices"] = {}
    state["samsung_locations"] = {}
    state["samsung_next_fetch"].clear()
    state["samsung_find_pin"] = ""
    for file in [SAMSUNG_AUTH_FILE, SAMSUNG_PENDING_FILE, SAMSUNG_PIN_FILE]:
        try:
            file.unlink()
        except OSError:
            pass
    save_json(SAMSUNG_DEVICES_FILE, "samsung_devices")
    save_json(SAMSUNG_LOCATIONS_FILE, "samsung_locations")
    return jsonify({"status": "ok"})


@app.route("/api/samsung/pin", methods=["POST", "DELETE"])
def configure_samsung_pin():
    if request.method == "DELETE":
        state["samsung_find_pin"] = ""
        try:
            SAMSUNG_PIN_FILE.unlink()
        except OSError:
            pass
        return jsonify({"status": "ok", "configured": False})
    data = request.json or {}
    pin = str(data.get("pin") or "").strip()
    if not pin or len(pin) > 128:
        return jsonify({"status": "error", "message": "Bitte einen gültigen Samsung-Find-PIN eingeben."}), 400
    state["samsung_find_pin"] = pin
    if bool(data.get("save", True)):
        samsung_private_save(SAMSUNG_PIN_FILE, {"pin": pin})
    else:
        try:
            SAMSUNG_PIN_FILE.unlink()
        except OSError:
            pass
    for device_id in state.get("samsung_devices", {}):
        state["samsung_next_fetch"][device_id] = time.time()
    return jsonify({"status": "ok", "configured": True})


@app.route("/api/samsung/devices/sync", methods=["POST"])
def sync_samsung_devices_route():
    if not state.get("samsung_auth", {}).get("userauth_token"):
        return jsonify({"status": "error", "message": "Bitte zuerst das Samsung-Konto verbinden."}), 400
    try:
        count = samsung_sync_devices()
        return jsonify({"status": "ok", "devices": count, "setup": state.get("samsung_setup", {}), "debug": state.get("samsung_debug", [])[-40:]})
    except Exception as exc:
        samsung_debug_event("sync_route_error", "Samsung-Geräteabruf ist mit einem Fehler beendet worden.", {"error": str(exc)}, "error")
        return jsonify({"status": "error", "message": str(exc), "setup": state.get("samsung_setup", {}), "debug": state.get("samsung_debug", [])[-40:]}), 502


@app.route("/api/samsung/settings", methods=["POST"])
def update_samsung_defaults():
    data = request.json or {}
    current_min, current_max = provider_poll_window("samsung")
    minimum = int_range(data.get("interval_min"), current_min, 20, 600)
    maximum = int_range(data.get("interval_max"), current_max, minimum, 600)
    polling = normalize_polling_settings(state.get("settings", {}).get("polling"))
    polling["samsung"] = {"interval_min": minimum, "interval_max": maximum}
    polling["updated_ts"] = int(time.time())
    state.setdefault("settings", {})["polling"] = normalize_polling_settings(polling)
    state["samsung_settings"]["default_interval_min"] = minimum
    state["samsung_settings"]["default_interval_max"] = maximum
    save_json(SAMSUNG_SETTINGS_FILE, "samsung_settings")
    save_json(SETTINGS_FILE, "settings")
    return jsonify({"status": "ok", "interval_min": minimum, "interval_max": maximum})


