    if device_id not in state.get("samsung_devices", {}):
        return jsonify({"status": "error", "message": "Samsung SmartTag wurde nicht gefunden."}), 404
    now_ts = time.time()
    last = float(state["samsung_last_manual_fetch"].get(device_id, 0) or 0)
    if now_ts - last < 30:
        return jsonify({"status": "cooldown", "remaining": int(30 - (now_ts - last))}), 429
    state["samsung_last_manual_fetch"][device_id] = now_ts
    threading.Thread(target=fetch_from_samsung, args=(device_id, "manual"), daemon=True).start()
    return jsonify({"status": "started"}), 202


