@app.route("/api/v2/groups/<group_id>", methods=["POST", "DELETE"])
def v2_group(group_id):
    row = state.get("tracker_groups", {}).get(group_id)
    if not row: return jsonify({"status": "error", "message": "Gruppe nicht gefunden."}), 404
    if request.method == "DELETE":
        state["tracker_groups"].pop(group_id, None); save_json(TRACKER_GROUPS_FILE, "tracker_groups")
