@app.route("/api/transit/analyze", methods=["POST"])
def api_transit_analyze():
    data = request.get_json(silent=True) or {}
    reference = str(data.get("tracker") or data.get("tracker_ref") or "").strip()
    if not reference and data.get("provider") and data.get("tracker_id"):
        reference = f"{data.get('provider')}:{data.get('tracker_id')}"
    try:
        model = mcp_resolve_tracker(reference)
        window = mcp_time_window(data)
        points = mcp_history_internal_points(model, window)
        result = transit_analyze_points(
            points,
            radius_m=data.get("radius_m"),
            tolerance_minutes=data.get("time_tolerance_minutes"),
            modes=data.get("modes") if isinstance(data.get("modes"), list) else None,
            max_observations=data.get("max_observations"),
        )
    except MCPToolError as exc:
        return jsonify({"status": "error", "message": str(exc), "code": exc.code}), 400
    except (TypeError, ValueError) as exc:
        return jsonify({"status": "error", "message": str(exc)}), 400
    result.update({
        "tracker": {"ref": model.get("ref"), "name": model.get("name"), "provider": model.get("provider")},
        "window": window,
    })
    activity_event("transit_analysis", "ÖPNV-Abgleich ausgeführt", result.get("status", ""), provider="transit", tracker_ref=str(model.get("ref") or ""))
    return jsonify(result)


