# ---------------------------------------------------------------------------
# 19.0 NATIVE iOS API + APNs BRIDGE
# ---------------------------------------------------------------------------
# The web application and every existing /api route stay intact.  The mobile
# layer is deliberately additive and uses the same authenticated tenant state,
# same provider sessions, same history database and same tracker operations.
# Pairing reuses the hardened Flask login session instead of creating a second
# password/token database.  The iOS app therefore stores no account password.

MOBILE_API_VERSION = "1.0"
MOBILE_API_PREFIX = "/api/mobile/v1"
_APNS_JWT_CACHE = {"token": "", "created_ts": 0, "fingerprint": ""}
_APNS_JWT_LOCK = threading.RLock()


def mobile_json_error(message, status=400, code="invalid_request"):
    return jsonify({"status": "error", "code": code, "message": str(message)}), status


def mobile_user_session_payload():
    return {
        "authenticated": bool(session.get("app_unlocked")),
        "user": current_user_public() if session.get("app_unlocked") else None,
        "csrf_token": csrf_session_token() if session.get("app_unlocked") else "",
        "tenant_id": current_tenant_id() if session.get("app_unlocked") else "",
        "server_time": int(time.time()),
        "timezone": APP_TIMEZONE_NAME,
        "app_name": APP_NAME,
        "app_version": APP_VERSION,
        "mobile_api_version": MOBILE_API_VERSION,
    }


def mobile_api_catalog():
    rows = []
    for rule in app.url_map.iter_rules():
        path = str(rule.rule)
        if not path.startswith("/api/"):
            continue
        methods = sorted(method for method in rule.methods if method not in {"HEAD", "OPTIONS"})
        rows.append({
            "path": path,
            "endpoint": str(rule.endpoint),
            "methods": methods,
            "arguments": sorted(str(value) for value in (rule.arguments or set())),
            "mobile_native": path.startswith(MOBILE_API_PREFIX),
        })
    rows.sort(key=lambda row: (row["path"], ",".join(row["methods"])))
    return rows


def ios_apns_channel_config(create=True):
    settings = state.setdefault("notification_settings", default_notification_settings())
    channels = settings.setdefault("channels", {})
    existing = channels.get("apns")
    if isinstance(existing, dict):
        config = existing
    elif create:
        config = {}
        channels["apns"] = config
    else:
        config = {}
    if create:
        config.setdefault("enabled", True)
        config.setdefault("mirror_events", True)
        config.setdefault("devices", {})
    return config


def ios_apns_devices():
    config = ios_apns_channel_config(True)
    devices = config.setdefault("devices", {})
    if not isinstance(devices, dict):
        devices = {}
        config["devices"] = devices
    return devices


def ios_apns_credentials():
    team_id = str(os.environ.get("ULTRA_TRACKER_APNS_TEAM_ID", "") or "").strip()
    key_id = str(os.environ.get("ULTRA_TRACKER_APNS_KEY_ID", "") or "").strip()
    bundle_id = str(os.environ.get("ULTRA_TRACKER_APNS_BUNDLE_ID", "eu.rjuhas.rjtracker") or "").strip()
    key_text = str(os.environ.get("ULTRA_TRACKER_APNS_P8", "") or "").strip()
    key_file = str(os.environ.get("ULTRA_TRACKER_APNS_P8_FILE", "") or "").strip()
    if not key_text and key_file:
        try:
            key_text = Path(key_file).expanduser().read_text(encoding="utf-8").strip()
        except OSError:
            key_text = ""
    if "\\n" in key_text and "\n" not in key_text:
        key_text = key_text.replace("\\n", "\n")
    production = str(os.environ.get("ULTRA_TRACKER_APNS_PRODUCTION", "0") or "0").strip().lower() in {"1", "true", "yes", "on"}
    return {
        "team_id": team_id,
        "key_id": key_id,
        "bundle_id": bundle_id,
        "private_key": key_text,
        "production": production,
        "host": "https://api.push.apple.com" if production else "https://api.sandbox.push.apple.com",
    }


def ios_apns_status_public():
    config = ios_apns_channel_config(True)
    credentials = ios_apns_credentials()
    devices = ios_apns_devices()
    enabled_devices = [row for row in devices.values() if isinstance(row, dict) and row.get("enabled", True)]
    credential_fields = {
        "team_id": bool(credentials["team_id"]),
        "key_id": bool(credentials["key_id"]),
        "bundle_id": bool(credentials["bundle_id"]),
        "private_key": bool(credentials["private_key"]),
    }
    return {
        "enabled": bool(config.get("enabled", True)),
        "mirror_events": bool(config.get("mirror_events", True)),
        "registered_devices": len(devices),
        "active_devices": len(enabled_devices),
        "server_configured": all(credential_fields.values()),
        "credential_fields": credential_fields,
        "environment": "production" if credentials["production"] else "sandbox",
        "bundle_id": credentials["bundle_id"],
        "requires_apple_push_key": not all(credential_fields.values()),
        "last_registration_ts": max([int(row.get("updated_ts", 0) or 0) for row in enabled_devices] + [0]),
    }


def ios_apns_configured():
    config = ios_apns_channel_config(True)
    if not config.get("enabled", True) or not config.get("mirror_events", True):
        return False
    status = ios_apns_status_public()
    return bool(status["server_configured"] and status["active_devices"] > 0)


def ios_apns_jwt(credentials):
    now_ts = int(time.time())
    fingerprint = hashlib.sha256(
        f"{credentials.get('team_id')}|{credentials.get('key_id')}|{credentials.get('private_key')}".encode("utf-8")
    ).hexdigest()[:24]
    with _APNS_JWT_LOCK:
        if (
            _APNS_JWT_CACHE.get("token")
            and _APNS_JWT_CACHE.get("fingerprint") == fingerprint
            and now_ts - int(_APNS_JWT_CACHE.get("created_ts", 0) or 0) < 45 * 60
        ):
            return _APNS_JWT_CACHE["token"]
        try:
            private_key = serialization.load_pem_private_key(credentials["private_key"].encode("utf-8"), password=None)
        except Exception as exc:
            raise RuntimeError("APNs .p8 Private Key ist ungültig.") from exc
        if not isinstance(private_key, ec.EllipticCurvePrivateKey):
            raise RuntimeError("APNs .p8 muss ein EC-Private-Key sein.")
        header = b64url_encode(json.dumps({"alg": "ES256", "kid": credentials["key_id"]}, separators=(",", ":")).encode("utf-8"))
        claims = b64url_encode(json.dumps({"iss": credentials["team_id"], "iat": now_ts}, separators=(",", ":")).encode("utf-8"))
        signing_input = f"{header}.{claims}".encode("ascii")
        der_signature = private_key.sign(signing_input, ec.ECDSA(hashes.SHA256()))
        r_value, s_value = decode_dss_signature(der_signature)
        raw_signature = r_value.to_bytes(32, "big") + s_value.to_bytes(32, "big")
        token = f"{header}.{claims}.{b64url_encode(raw_signature)}"
        _APNS_JWT_CACHE.update({"token": token, "created_ts": now_ts, "fingerprint": fingerprint})
        return token


def ios_apns_payload(event):
    severity = str(event.get("severity") or "normal").lower()
    interruption = "time-sensitive" if severity in {"critical", "high", "warning"} else "active"
    tracker_ref = str(event.get("tracker_ref") or "")
    location = event.get("location") if isinstance(event.get("location"), dict) else {}
    payload = {
        "aps": {
            "alert": {
                "title": str(event.get("title") or "Universal Tag Studio")[:180],
                "body": str(event.get("body") or "Neues Tracker-Ereignis")[:500],
            },
            "sound": "default",
            "badge": max(1, sum(1 for item in state.get("notification_events", []) if not item.get("acknowledged"))),
            "interruption-level": interruption,
            "thread-id": tracker_ref or str(event.get("type") or "tracker"),
        },
        "event_id": str(event.get("id") or ""),
        "event_type": str(event.get("type") or "system"),
        "tracker_ref": tracker_ref,
        "severity": severity,
        "server_ts": int(event.get("ts", time.time()) or time.time()),
    }
    if location.get("lat") is not None and location.get("lon") is not None:
        payload["location"] = {
            "lat": float(location["lat"]),
            "lon": float(location["lon"]),
            "acc": float(location.get("acc", 0) or 0),
            "ts": int(float(location.get("ts", 0) or 0)),
        }
    return payload


def ios_apns_send_device(device_id, stored, event):
    credentials = ios_apns_credentials()
    if not all(credentials.get(key) for key in ("team_id", "key_id", "bundle_id", "private_key")):
        raise RuntimeError("APNs ist serverseitig noch nicht vollständig konfiguriert.")
    device_token = re.sub(r"[^0-9A-Fa-f]", "", str(stored.get("token") or ""))
    if len(device_token) < 32:
        raise RuntimeError("Ungültiger APNs-Geräte-Token.")
    try:
        import httpx
    except ImportError as exc:
        raise RuntimeError("Für APNs wird httpx mit HTTP/2-Unterstützung benötigt: pip install 'httpx[http2]'.") from exc
    payload = ios_apns_payload(event)
    encoded = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    if len(encoded) > 4096:
        payload.pop("location", None)
        encoded = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).encode("utf-8")
    jwt_token = ios_apns_jwt(credentials)
    url = f"{credentials['host']}/3/device/{device_token}"
    headers = {
        "authorization": f"bearer {jwt_token}",
        "apns-topic": credentials["bundle_id"],
        "apns-push-type": "alert",
        "apns-priority": "10",
        "apns-expiration": "0",
    }
    with httpx.Client(http2=True, timeout=12.0) as client:
        response = client.post(url, headers=headers, content=encoded)
    body = {}
    try:
        body = response.json() if response.content else {}
    except Exception:
        body = {}
    if response.status_code == 200:
        stored["last_success_ts"] = int(time.time())
        stored["last_error"] = ""
        return "sent", "APNs accepted"
    reason = str(body.get("reason") or f"HTTP {response.status_code}")
    if response.status_code == 410 or reason in {"BadDeviceToken", "Unregistered", "DeviceTokenNotForTopic"}:
        stored["enabled"] = False
        stored["last_error"] = reason[:180]
        return "stale", reason
    raise RuntimeError(f"APNs HTTP {response.status_code}: {reason}")


def ios_apns_deliver_event(event):
    devices = ios_apns_devices()
    delivered = failed = stale = 0
    details = []
    changed = False
    for device_id, stored in list(devices.items()):
        if not isinstance(stored, dict) or not stored.get("enabled", True):
            continue
        try:
            status, detail = ios_apns_send_device(device_id, stored, event)
            changed = True
            if status == "sent":
                delivered += 1
            elif status == "stale":
                stale += 1
            details.append({"device_id": device_id, "status": status, "detail": detail[:160]})
        except Exception as exc:
            failed += 1
            changed = True
            stored["last_error"] = sanitize_console_text(exc, 180)
            details.append({"device_id": device_id, "status": "error", "detail": str(exc)[:160]})
    if changed:
        save_json(NOTIFICATION_SETTINGS_FILE, "notification_settings")
    return {"delivered": delivered, "failed": failed, "stale": stale, "details": details}


