@app.route(f"{MOBILE_API_PREFIX}/push", methods=["GET", "POST", "DELETE"])
def mobile_push_api():
    config = ios_apns_channel_config(True)
    devices = ios_apns_devices()
    if request.method == "GET":
        public_devices = [
            {
                "id": device_id,
                "label": str(row.get("label") or "iPhone")[:80],
                "created_ts": int(row.get("created_ts", 0) or 0),
                "updated_ts": int(row.get("updated_ts", 0) or 0),
                "last_success_ts": int(row.get("last_success_ts", 0) or 0),
                "last_error": sanitize_console_text(row.get("last_error"), 160),
                "enabled": bool(row.get("enabled", True)),
                "app_version": str(row.get("app_version") or "")[:40],
                "device_model": str(row.get("device_model") or "")[:80],
            }
            for device_id, row in devices.items() if isinstance(row, dict)
        ]
        return jsonify({"status": "ok", "push": ios_apns_status_public(), "devices": public_devices})
    data = request.get_json(silent=True) or {}
    if request.method == "DELETE":
        device_id = str(data.get("device_id") or "").strip()
        token = re.sub(r"[^0-9A-Fa-f]", "", str(data.get("token") or ""))
        if not device_id and token:
            token_hash = hashlib.sha256(token.lower().encode("ascii")).hexdigest()
            device_id = token_hash[:20]
        removed = devices.pop(device_id, None) if device_id else None
        save_json(NOTIFICATION_SETTINGS_FILE, "notification_settings")
        return jsonify({"status": "ok", "removed": bool(removed), "push": ios_apns_status_public()})
    token = re.sub(r"[^0-9A-Fa-f]", "", str(data.get("token") or ""))
    if len(token) < 32:
        return mobile_json_error("APNs-Geräte-Token ist ungültig.")
    now_ts = int(time.time())
    token_hash = hashlib.sha256(token.lower().encode("ascii")).hexdigest()
    device_id = token_hash[:20]
    previous = devices.get(device_id) if isinstance(devices.get(device_id), dict) else {}
    devices[device_id] = {
        **previous,
        "token": token.lower(),
        "label": str(data.get("label") or previous.get("label") or "iPhone")[:80],
        "app_version": str(data.get("app_version") or "")[:40],
        "device_model": str(data.get("device_model") or "")[:80],
        "system_version": str(data.get("system_version") or "")[:40],
        "created_ts": int(previous.get("created_ts", now_ts) or now_ts),
        "updated_ts": now_ts,
        "last_success_ts": int(previous.get("last_success_ts", 0) or 0),
        "last_error": str(previous.get("last_error") or "")[:180],
        "enabled": True,
    }
    config["enabled"] = True
    config["mirror_events"] = bool_from_any(data.get("mirror_events"), config.get("mirror_events", True))
    save_json(NOTIFICATION_SETTINGS_FILE, "notification_settings")
    audit_event("ios_push_registered", device_id, str(devices[device_id].get("label") or "iPhone"))
    return jsonify({"status": "ok", "device_id": device_id, "push": ios_apns_status_public()}), 201


@app.route(f"{MOBILE_API_PREFIX}/action", methods=["POST"])
def mobile_action_api():
    data = request.get_json(silent=True) or {}
    action = str(data.get("action") or "").strip().lower()
    try:
        if action == "locate":
            model = mcp_resolve_tracker(data.get("tracker"))
            return jsonify({"status": "scheduled", "tracker": mcp_tracker_row(model), "networks": mcp_trigger_locate(model)})
        if action == "set_found_notification":
            model = mcp_resolve_tracker(data.get("tracker"))
            result = mcp_set_found_notification(
                model,
                bool_from_any(data.get("enabled"), False),
                str(data.get("mode") or "once"),
                data.get("channels") if isinstance(data.get("channels"), list) else None,
            )
            return jsonify({"status": "ok", **result})
        if action == "set_departure_notification":
            model = mcp_resolve_tracker(data.get("tracker"))
            result = mcp_set_departure_notification(model, data)
            return jsonify({"status": "ok", **result})
        if action == "set_history":
            model = mcp_resolve_tracker(data.get("tracker"))
            result = mcp_set_tracker_history(model, bool_from_any(data.get("enabled"), True), data.get("retention"), data.get("custom_days"))
            return jsonify({"status": "ok", **result})
        if action == "update_tracker_details":
            model = mcp_resolve_tracker(data.get("tracker"))
            result = mcp_update_tracker_details(model, data)
            return jsonify({"status": "ok", **result})
        if action == "create_geofence":
            return jsonify({"status": "ok", **mcp_create_geofence(data)})
        if action == "update_geofence":
            return jsonify({"status": "ok", **mcp_update_geofence(data)})
        if action == "delete_geofence":
            return jsonify({"status": "ok", **mcp_delete_geofence(data)})
        if action == "upsert_saved_place":
            place = mcp_upsert_saved_place(data)
            return jsonify({"status": "ok", "place": place})
        if action == "delete_saved_place":
            saved_zones = [zone for zone in mcp_place_catalog([], include_saved=True) if zone.get("kind") == "saved_place"]
            zone = mcp_resolve_place(data.get("place"), zones=saved_zones)
            removed = state.get("saved_places", {}).pop(str(zone.get("id") or ""), None)
            if not removed:
                raise MCPToolError("Gespeicherter Ort wurde nicht gefunden.", "not_found")
            save_json(SAVED_PLACES_FILE, "saved_places")
            return jsonify({"status": "ok", "place": mcp_zone_public(zone)})
        if action == "start_recovery":
            model = mcp_resolve_tracker(data.get("tracker"))
            return jsonify({"status": "ok", **mcp_start_recovery(model, data)})
        if action == "mark_recovery_found":
            model = mcp_resolve_tracker(data.get("tracker"))
            return jsonify({"status": "ok", **mcp_mark_recovery_found(model, data)})
        if action == "global_pause":
            paused = bool_from_any(data.get("paused"), False)
            state.setdefault("settings", {})["global_pause"] = paused
            save_json(SETTINGS_FILE, "settings")
            return jsonify({"status": "ok", "paused": paused, "polling": polling_public_state()})
        if action in {"clear_events", "delete_event", "acknowledge_all_events"}:
            with notification_lock:
                events = state.get("notification_events", [])
                if action == "clear_events":
                    remaining = []
                elif action == "delete_event":
                    event_id = str(data.get("event_id") or "")
                    if not event_id:
                        raise MCPToolError("Ereignis-ID fehlt.")
                    remaining = [row for row in events if str(row.get("id")) != event_id]
                else:
                    remaining = [{**row, "acknowledged": True} for row in events]
                # Persist first, so a write failure never clears the live inbox.
                atomic_write_json(NOTIFICATION_EVENTS_FILE, remaining)
                state["notification_events"] = remaining
            return jsonify(status="ok", removed_count=len(events) - len(remaining))
        if action == "acknowledge_event":
            event_id = str(data.get("event_id") or "")
            event = next((item for item in state.get("notification_events", []) if str(item.get("id")) == event_id), None)
            if not event:
                raise MCPToolError("Ereignis wurde nicht gefunden.", "not_found")
            event["acknowledged"] = bool_from_any(data.get("acknowledged"), True)
            atomic_write_json(NOTIFICATION_EVENTS_FILE, state.get("notification_events", []))
            return jsonify({"status": "ok", "event": event})
        return mobile_json_error("Unbekannte Mobile-Aktion.", 404, "unknown_action")
    except MCPToolError as exc:
        return mobile_json_error(str(exc), 404 if exc.code == "not_found" else 400, exc.code)
    except (TypeError, ValueError) as exc:
        return mobile_json_error(str(exc), 400, "invalid_arguments")


