# API Edition 20: client access, scoped automation keys and security-only administration.
_ACCESS_FILE = _MAIN_DATA_DIR / '.client_access.json'
_access_lock = threading.RLock()
_access = safe_load_json(_ACCESS_FILE, {'clients': {}, 'keys': {}}, accepted_types=(dict,))
_access.setdefault('clients', {})
_access.setdefault('keys', {})
_bridge_lock = threading.RLock()
_bridge_pending = {}

def access_save():
    atomic_write_json(_ACCESS_FILE, _access, private=True)

def access_public(row):
    return {k: v for k, v in row.items() if k not in {'hash', 'generation'}}

def access_register_client():
    if not session.get('app_unlocked'):
        return
    client_id = secrets.token_urlsafe(24)
    row = {'id': client_id, 'user_id': str(session.get('user_id') or 'main'),
           'label': str(request.headers.get('X-RJ-Device-Label') or 'API client')[:100],
           'created_ts': int(time.time()), 'last_seen_ts': int(time.time()), 'revoked': False}
    with _access_lock:
        _access['clients'][client_id] = row
        access_save()
    session['client_id'] = client_id

def access_key_scope(path, method):
    # Explicit endpoint families: keys cannot manage users, passwords, backups or credentials.
    if path in {'/api/v3/info', '/api/v3/schema', '/api/mobile/v1/session', '/api/mobile/v1/capabilities', '/api/mobile/v1/trackers', '/api/mobile/v1/tracker', '/api/mobile/v1/history', '/api/mobile/v1/history/stream', '/api/mobile/v1/history/days', '/api/mobile/v1/alerts'} and method == 'GET':
        return 'read'
    if path == '/api/mobile/v1/locate' and method == 'POST':
        return 'locate'
    if path == '/api/mobile/v1/action' and method == 'POST':
        action = (request.get_json(silent=True) or {}).get('action')
        if action == 'locate':
            return 'locate'
        if action in {'update_tracker_details'}:
            return 'manage'
    return None

def access_before_request():
    path = request.path
    g.api_principal = None
    if session.get('app_unlocked') and (session.get('admin_console') or session.get('security_bridge') or session.get('client_id')):
        user_id = str(session.get('user_id') or 'main')
        user = user_record(user_id)
        with tenant_context(user_id):
            generation = app_password_generation()
        if not user or not user.get('active',True) or not hmac.compare_digest(str(session.get('password_generation') or ''), generation):
            session.clear()
            return jsonify(status='error', message='Anmeldung wurde zurückgesetzt.'),401
        client_id = session.get('client_id')
        with _access_lock:
            client = _access['clients'].get(client_id) if client_id else None
            if client_id and (not client or client.get('revoked')):
                session.clear()
                return jsonify(status='error', message='Dieses Gerät wurde abgemeldet.'),401
    # All security bridge routes must implement their own explicit checks.
    if path.startswith('/admin/api/') or path.startswith('/auth/') or path == '/api/v3/auth/exchange':
        if path.startswith('/admin/api/') and path not in {'/admin/api/login', '/admin/api/2fa'}:
            if not session.get('app_unlocked') or str(session.get('user_id')) != 'main':
                return jsonify(status='error', message='Hauptadmin-Anmeldung erforderlich.'), 403
            if request.method not in {'GET','HEAD'} and not hmac.compare_digest(str(request.headers.get('X-CSRF-Token') or ''), str(session.get('csrf_token') or 'missing')):
                return jsonify(status='error', message='CSRF-Token fehlt.'), 403
        return
    if path.startswith('/oauth/') or path.startswith('/.well-known/') or path == '/mcp' or re.match(r'^/t/[a-z0-9_-]+/(oauth/|\.well-known/|mcp$)', path):
        return
    if session.get('admin_console'):
        allowed = {'/', '/admin', '/api/logout', '/api/security/password'}
        if path not in allowed and path != '/api/server/findmy' and not path.startswith('/api/mcp/'):
            return jsonify(status='error', message='Diese Sitzung ist auf die Admin-Oberfläche beschränkt.'), 403
    if session.get('security_bridge'):
        allowed = {'/api/unlock', '/api/unlock/2fa', '/api/passkeys/auth/begin', '/api/passkeys/auth/finish', '/api/security/passkeys/register/begin', '/api/security/passkeys/register/finish'}
        if path not in allowed:
            return jsonify(status='error', message='Diese Sitzung darf nur Passkeys einrichten.'), 403
    authorization = str(request.headers.get('Authorization') or '')
    if path.startswith('/api/') and authorization.startswith('Bearer '):
        token = authorization[7:]
        digest = hashlib.sha256(token.encode()).hexdigest()
        now = int(time.time())
        with _access_lock:
            row = next((x for x in _access['keys'].values() if hmac.compare_digest(str(x.get('hash') or ''), digest)), None)
            if not row or row.get('revoked') or row.get('expires_ts', 0) <= now:
                return jsonify(status='error', message='API-Schlüssel ungültig oder abgelaufen.'), 401
            user_id = str(row['user_id'])
            user = user_record(user_id)
            if not user or not user.get('active', True):
                return jsonify(status='error', message='Konto deaktiviert.'), 401
            with tenant_context(user_id):
                if not hmac.compare_digest(str(row.get('generation')), app_password_generation()):
                    return jsonify(status='error', message='Anmeldeschutz geändert; neuen API-Schlüssel erstellen.'), 401
            scope = access_key_scope(path, request.method)
            if not scope or scope not in row.get('scopes', []):
                return jsonify(status='error', message='API-Schlüssel hat hierfür keine Berechtigung.'), 403
            if not mcp_rate_limit('api-key:' + row['id'], 120, 60):
                return jsonify(status='error', message='Zu viele Anfragen.'), 429
            if now - row.get('last_seen_ts', 0) >= 60:
                row['last_seen_ts'] = now
                access_save()
            g.api_principal = dict(row)
        session.clear()
        session.update(app_unlocked=True, user_id=user_id, password_generation=row['generation'])
    client_id = session.get('client_id')
    if client_id and not g.api_principal:
        with _access_lock:
            row = _access['clients'].get(client_id)
            if not row or row.get('revoked'):
                session.clear()
                return jsonify(status='error', message='Dieses Gerät wurde abgemeldet.'), 401
            if int(time.time()) - row.get('last_seen_ts',0) > 300:
                row['last_seen_ts'] = int(time.time())
                access_save()

app.before_request_funcs.setdefault(None, []).insert(0, access_before_request)
# Security pages implement independent login/auth checks above.
_original_check_auth = check_auth
@app.before_request
def _unused_api_edition_guard():
    return None

def api_edition_check_auth():
    if request.path in {'/', '/admin'} or request.path.startswith('/admin/api/') or request.path.startswith('/auth/') or request.path == '/api/v3/auth/exchange':
        return
    return _original_check_auth()
app.before_request_funcs[None] = [api_edition_check_auth if f is _original_check_auth else f for f in app.before_request_funcs[None]]

@app.after_request
def access_after_request(response):
    if getattr(g, 'api_principal', None):
        session.clear()
        session.modified = False
    elif request.path in {'/api/mobile/v1/pair', '/api/mobile/v1/pair/2fa', '/api/v3/auth/exchange'} and response.status_code < 300 and session.get('app_unlocked'):
        access_register_client()
    if request.path.startswith('/api/') or request.path.startswith('/admin') or request.path.startswith('/auth'):
        response.headers['Cache-Control'] = 'no-store'
    return response

