@app.route('/api/v3/schema')
def api_edition_schema():
    paths = {}
    for row in mobile_api_catalog():
        # Existing APIs include Flask path arguments; convert these to OpenAPI parameters.
        path = re.sub(r'<(?:[^:>]+:)?([^>]+)>', r'{\1}', row['path'])
        for method in row['methods']:
            scope = access_key_scope(row['path'], method) if row['path'] != '/api/mobile/v1/action' else 'manage'
            operation = {'operationId': row['endpoint']+'_'+method.lower(), 'responses': {'200': {'description':'JSON response'}, '401': {'description':'Login required'}, '403': {'description':'Permission denied'}}, 'security': [{'sessionCookie': []}, {'apiKey': []}] if scope else [{'sessionCookie': []}], 'x-api-key-scope':scope,
                         'parameters':[{'in':'path','name':a,'required':True,'schema':{'type':'string'}} for a in row['arguments']]}
            paths.setdefault(path,{})[method.lower()] = operation
    return jsonify(openapi='3.1.0', info={'title':'RJ Tracker API','version':'3.0.0','description':'Session mutations require X-CSRF-Token. API keys permit only explicitly scoped routes. See API-EDITION.md for request examples.'}, paths=paths,
                   components={'securitySchemes': {'sessionCookie':{'type':'apiKey','in':'cookie','name':app.config.get('SESSION_COOKIE_NAME','session')},'apiKey':{'type':'http','scheme':'bearer'}}})

