@app.route('/api/v3/keys', methods=['GET','POST'])
def api_access_keys():
    user_id=current_tenant_id()
    with _access_lock:
        if request.method=='GET':
            return jsonify(status='ok',keys=[access_public(r) for r in _access['keys'].values() if r['user_id']==user_id])
        body=request.get_json(silent=True) or {}
        valid,message=verify_passkey_management_auth(user_id,body)
        if not valid:return jsonify(status='error',message=message),403
        requested=body.get('scopes',['read'])
        if not isinstance(requested,list) or not requested or set(requested)-{'read','locate','manage'}:
            return jsonify(status='error',message='Erlaubte Scopes: read, locate, manage.'),400
        try:days=min(365,max(1,int(body.get('expires_days',90))))
        except (TypeError,ValueError):return jsonify(status='error',message='Ungültige Laufzeit.'),400
        token='rjt_'+secrets.token_urlsafe(40)
        key_id=secrets.token_urlsafe(16)
        row={'id':key_id,'user_id':user_id,'label':str(body.get('label') or 'Skript')[:100],'scopes':sorted(set(requested)), 'hash':hashlib.sha256(token.encode()).hexdigest(),'created_ts':int(time.time()),'expires_ts':int(time.time())+days*86400,'last_seen_ts':0,'revoked':False,'generation':app_password_generation()}
        _access['keys'][key_id]=row
        access_save()
    return jsonify(status='ok',key=access_public(row),token=token,message='Schlüssel wird nur einmal angezeigt.'),201

