@app.route('/api/v3/import',methods=['POST'])
def api_native_import():
    body=request.get_json(silent=True) or {}
    provider=body.get('provider')
    content=body.get('content')
    if not isinstance(content,(dict,list)):return jsonify(status='error',message='JSON-Objekt oder Liste erwartet.'),400
    raw=json.dumps(content,ensure_ascii=False).encode()
    if len(raw)>1024*1024:return jsonify(status='error',message='JSON-Datei maximal 1 MB.'),413
    if provider=='google':
        valid,message=google_validate_secrets(content)
        if not valid:return jsonify(status='error',message=message),400
        google_store_secrets(content,source='ios-import',merge=False)
        google_sync_secrets_to_tools()
        google_health_cache['checked_ts']=0
        threading.Thread(target=google_prepare_worker,daemon=True).start()
        return jsonify(status='ok',message='Google-Zugang importiert; Geräte werden vorbereitet.')
    if provider!='apple':return jsonify(status='error',message='Nur Apple-Tracker und Google-Secrets können importiert werden.'),400
    try:name=canonical_device_name(body.get('name',''))
    except ValueError as exc:return jsonify(status='error',message=str(exc)),400
    dest=ACC_DIR / (name+'.json')
    if dest.exists() and not body.get('replace'):return jsonify(status='error',message='Tracker existiert bereits. Zum Ersetzen ausdrücklich bestätigen.'),409
    fd,tmp=tempfile.mkstemp(suffix='.json',dir=str(ACC_DIR));os.close(fd)
    p=Path(tmp)
    try:
        p.write_bytes(raw)
        accessory=load_accessory_json(p)
        os.chmod(p,0o600)
        os.replace(p,dest)
        load_data()
        state['tracker_meta'].setdefault(name,{'name':str(getattr(accessory,'name','') or name)[:80],'emoji':'📍'})
        save_json(META_FILE,'tracker_meta')
        return jsonify(status='ok',ref='apple:'+name,message='Apple-Tracker importiert.')
    except Exception:
        logger.warning('Native accessory import failed',exc_info=True)
        return jsonify(status='error',message='Ungültige oder nicht unterstützte Apple-Tracker-JSON.'),400
    finally:p.unlink(missing_ok=True)

@app.route('/api/v3/trackers/<provider>/<path:tracker_id>',methods=['DELETE'])
def api_remove_native_tracker(provider,tracker_id):
    if provider=='apple':return delete_device(tracker_id)
    if provider not in {'google','samsung'}:return jsonify(status='error',message='Quelle nicht unterstützt.'),400
    devices=state.get(provider+'_devices',{})
    if tracker_id not in devices:return jsonify(status='error',message='Tracker nicht gefunden.'),404
    metadata, metadata_file, metadata_key = tracker_detail_store(provider, tracker_id)
    metadata.update(hidden=True, archived=True, enabled=False)
    save_json(metadata_file, metadata_key)
    for name,link in list(state.get(provider+'_links',{}).items()):
        if link.get(provider+'_id')==tracker_id:
            state[provider+'_links'].pop(name,None);sync_fusion_profile(name)
    files={'google':(GOOGLE_DEVICES_FILE,GOOGLE_LINKS_FILE),'samsung':(SAMSUNG_DEVICES_FILE,SAMSUNG_LINKS_FILE)}
    save_json(files[provider][0],provider+'_devices');save_json(files[provider][1],provider+'_links')
    return jsonify(status='ok',message='Quelle archiviert und aus Fusionen entfernt; Historie bleibt erhalten.')

